import type { GuideSection } from './guide';

/**
 * Le pagine e i pannelli fuori dalle Impostazioni (barra in alto, pagina Stazione, Log, mappe, Contest, Fox, QMAP, Rotore, Satelliti, telecomando):
 * dove sta ogni pulsante, cosa fa e quando usarlo. I nomi si citano con la chiave della stringa d'interfaccia tra doppie quadre. Tabella di copertura:
 * docs/copertura-parti/pagine.md.
 */
export const GUIDE_PAGINE: readonly GuideSection[] = [
  {
    id: 'p-nav',
    title: ['La barra in alto: i modi', 'The top bar: modes', 'Die obere Leiste: die Betriebsarten', 'La barre du haut : les modes', 'La barra superior: los modos', 'A barra de cima: os modos'],
    text: ['In cima alla finestra, a sinistra, ci sono le pillole dei modi; a destra le pagine (vedi «Le pagine della barra in alto»). Il marchio «AURORA» a sinistra riporta sempre alla pagina [[nav.station]]. La pillola accesa è il posto dove ti trovi.', 'At the top of the window, on the left, are the mode pills; on the right are the pages (see “The pages in the top bar”). The “AURORA” logo on the left always takes you back to the [[nav.station]] page. The lit pill is where you are now.', 'Oben im Fenster, links, sitzen die Schaltflächen der Betriebsarten; rechts die Seiten (siehe „Die Seiten der oberen Leiste“). Das Logo „AURORA“ links führt immer zurück zur Seite [[nav.station]]. Die leuchtende Schaltfläche zeigt, wo du gerade bist.', 'Tout en haut de la fenêtre, à gauche, il y a les pastilles des modes ; à droite, les pages (voir « Les pages de la barre du haut »). La marque « AURORA » à gauche ramène toujours à la page [[nav.station]]. La pastille allumée est l’endroit où tu te trouves.', 'Arriba, a la izquierda de la ventana, están las píldoras de los modos; a la derecha las páginas (mira «Las páginas de la barra superior»). La marca «AURORA» de la izquierda siempre te lleva a la página [[nav.station]]. La píldora encendida es el lugar donde estás.', 'No topo da janela, à esquerda, estão as pílulas dos modos; à direita as páginas (vê «As páginas da barra de cima»). A marca «AURORA» à esquerda leva sempre à página [[nav.station]]. A pílula acesa é o sítio onde estás.'],
    steps: [
      ['«FT8»: il gruppo dei modi HF. Il suo menu del modo (vedi «Modo, sottomodo e frequenza») offre FT8, FT4, JT9, JT65, FST4, FST4W e WSPR. Un clic torna alla pagina [[nav.station]] e rimette l’ultimo modo usato in questo gruppo (di fabbrica FT8). Se la radio non è su una frequenza di quel modo, Aurora la porta sulla prima banda dove esiste.', '“FT8”: the group of HF modes. Its mode menu (see “Mode, submode and frequency”) offers FT8, FT4, JT9, JT65, FST4, FST4W and WSPR. One click takes you back to the [[nav.station]] page and restores the last mode you used in this group (FT8 by default). If the radio is not on a frequency of that mode, Aurora moves it to the first band where the mode exists.', '„FT8“: die Gruppe der KW-Betriebsarten. Ihr Betriebsartmenü (siehe „Betriebsart, Untermodus und Frequenz“) bietet FT8, FT4, JT9, JT65, FST4, FST4W und WSPR. Ein Klick führt zurück zur Seite [[nav.station]] und stellt die zuletzt benutzte Betriebsart dieser Gruppe wieder ein (ab Werk FT8). Steht das Funkgerät nicht auf einer Frequenz dieser Betriebsart, stellt Aurora es auf das erste Band, auf dem sie existiert.', '« FT8 » : le groupe des modes HF. Son menu du mode (voir « Mode, sous-mode et fréquence ») propose FT8, FT4, JT9, JT65, FST4, FST4W et WSPR. Un clic te ramène à la page [[nav.station]] et remet le dernier mode utilisé dans ce groupe (FT8 par défaut). Si la radio n’est pas sur une fréquence de ce mode, Aurora la place sur la première bande où il existe.', '«FT8»: el grupo de los modos HF. Su menú del modo (mira «Modo, submodo y frecuencia») ofrece FT8, FT4, JT9, JT65, FST4, FST4W y WSPR. Un clic vuelve a la página [[nav.station]] y recupera el último modo usado en este grupo (de serie FT8). Si la radio no está en una frecuencia de ese modo, Aurora la lleva a la primera banda donde existe.', '«FT8»: o grupo dos modos HF. O seu menu do modo (vê «Modo, submodo e frequência») oferece FT8, FT4, JT9, JT65, FST4, FST4W e WSPR. Um clique volta à página [[nav.station]] e repõe o último modo usado neste grupo (de origem FT8). Se o rádio não estiver numa frequência desse modo, a Aurora leva-o para a primeira banda onde ele existe.'],
      ['«VHF»: il gruppo dei modi per VHF, microonde ed EME. Il suo menu offre JT65, JT4, Q65 e MSK144; il modo di partenza è MSK144. Funziona come «FT8»: ricorda l’ultimo modo scelto e sposta la radio se serve.', '“VHF”: the group of modes for VHF, microwaves and EME. Its menu offers JT65, JT4, Q65 and MSK144; the starting mode is MSK144. It works like “FT8”: it remembers the last mode you chose and moves the radio if needed.', '„VHF“: die Gruppe der Betriebsarten für VHF, Mikrowellen und EME. Ihr Menü bietet JT65, JT4, Q65 und MSK144; die Startbetriebsart ist MSK144. Es funktioniert wie „FT8“: Es merkt sich die zuletzt gewählte Betriebsart und stellt bei Bedarf das Funkgerät um.', '« VHF » : le groupe des modes pour la VHF, les micro-ondes et l’EME. Son menu propose JT65, JT4, Q65 et MSK144 ; le mode de départ est MSK144. Il fonctionne comme « FT8 » : il retient le dernier mode choisi et déplace la radio si besoin.', '«VHF»: el grupo de los modos para VHF, microondas y EME. Su menú ofrece JT65, JT4, Q65 y MSK144; el modo de partida es MSK144. Funciona como «FT8»: recuerda el último modo elegido y mueve la radio si hace falta.', '«VHF»: o grupo dos modos para VHF, micro-ondas e EME. O seu menu oferece JT65, JT4, Q65 e MSK144; o modo de partida é MSK144. Funciona como «FT8»: lembra-se do último modo escolhido e muda o rádio se for preciso.'],
      ['Durante la trasmissione le pillole «FT8» e «VHF» non cambiano gruppo: passandoci sopra leggi «[[mode.locked]]». Aspetta la fine del periodo oppure ferma la trasmissione con STOP TX.', 'While you transmit, the “FT8” and “VHF” pills do not switch group: hover over them and you read “[[mode.locked]]”. Wait for the end of the period or stop the transmission with STOP TX.', 'Während des Sendens wechseln die Schaltflächen „FT8“ und „VHF“ die Gruppe nicht: Fährst du mit der Maus darüber, liest du „[[mode.locked]]“. Warte das Ende des Durchgangs ab oder stoppe das Senden mit STOP TX.', 'Pendant l’émission, les pastilles « FT8 » et « VHF » ne changent pas de groupe : en passant dessus tu lis « [[mode.locked]] ». Attends la fin de la période ou arrête l’émission avec STOP TX.', 'Durante la transmisión las píldoras «FT8» y «VHF» no cambian de grupo: al pasar el ratón por encima lees «[[mode.locked]]». Espera al final del periodo o detén la transmisión con STOP TX.', 'Durante a transmissão as pílulas «FT8» e «VHF» não mudam de grupo: ao passares por cima lês «[[mode.locked]]». Espera pelo fim do período ou pára a transmissão com STOP TX.'],
      ['[[nav.textModes]]: PSK31, PSK63, RTTY, CW e SSTV stanno nella stessa pagina; il modo si sceglie dal menu «Modo» della pagina. Entrandoci da un’altra pagina Aurora porta la radio sulla banda del piano IARU di quel modo (e, se la banda di adesso non ce l’ha, sulla prima). Non lo fa mentre trasmetti.', '[[nav.textModes]]: PSK31, PSK63, RTTY, CW and SSTV are on the same page; you choose the mode from the “Mode” menu of the page. When you enter from another page, Aurora moves the radio to the IARU band-plan band of that mode (and, if the current band doesn’t have it, to the first one). It does not do this while you transmit.', '[[nav.textModes]]: PSK31, PSK63, RTTY, CW und SSTV liegen auf derselben Seite; die Betriebsart wählst du im Menü „Modus“ der Seite. Wenn du von einer anderen Seite hineingehst, stellt Aurora das Funkgerät auf das Band aus dem IARU-Bandplan dieser Betriebsart (und, falls das aktuelle Band sie nicht hat, auf das erste). Während du sendest, tut es das nicht.', '[[nav.textModes]] : PSK31, PSK63, RTTY, CW et SSTV sont dans la même page ; le mode se choisit dans le menu « Mode » de la page. Quand tu y arrives depuis une autre page, Aurora place la radio sur la bande du plan IARU de ce mode (et, si la bande actuelle ne l’a pas, sur la première). Elle ne le fait pas pendant que tu émets.', '[[nav.textModes]]: PSK31, PSK63, RTTY, CW y SSTV están en la misma página; el modo se elige en el menú «Modo» de la página. Si entras desde otra página, Aurora lleva la radio a la banda del plan IARU de ese modo (y, si la banda actual no la tiene, a la primera). No lo hace mientras transmites.', '[[nav.textModes]]: PSK31, PSK63, RTTY, CW e SSTV estão na mesma página; o modo escolhe-se no menu «Modo» da página. Ao entrares a partir de outra página, a Aurora leva o rádio para a banda do plano IARU desse modo (e, se a banda atual não o tiver, para a primeira). Não o faz enquanto transmites.'],
      ['[[nav.sat]]: la pagina dei satelliti (vedi «Satelliti: la pagina riquadro per riquadro»).', '[[nav.sat]]: the satellites page (see “Satellites: the page, panel by panel”).', '[[nav.sat]]: die Satellitenseite (siehe „Satelliten: die Seite Feld für Feld“).', '[[nav.sat]] : la page des satellites (voir « Satellites : la page encadré par encadré »).', '[[nav.sat]]: la página de los satélites (mira «Satélites: la página recuadro a recuadro»).', '[[nav.sat]]: a página dos satélites (vê «Satélites: a página quadro a quadro»).'],
      ['Se ti trovi su una pagina che non è di un modo (per esempio [[nav.log]] o [[nav.dxmap]]) nessuna pillola è accesa; un clic su «FT8» o «VHF» ti riporta alla Stazione.', 'If you are on a page that is not a mode page (for example [[nav.log]] or [[nav.dxmap]]), no pill is lit; a click on “FT8” or “VHF” takes you back to the Station.', 'Bist du auf einer Seite, die zu keiner Betriebsart gehört (zum Beispiel [[nav.log]] oder [[nav.dxmap]]), leuchtet keine Schaltfläche; ein Klick auf „FT8“ oder „VHF“ bringt dich zurück zur Station.', 'Si tu es sur une page qui n’est pas celle d’un mode (par exemple [[nav.log]] ou [[nav.dxmap]]), aucune pastille n’est allumée ; un clic sur « FT8 » ou « VHF » te ramène à la Station.', 'Si estás en una página que no es de un modo (por ejemplo [[nav.log]] o [[nav.dxmap]]) no hay ninguna píldora encendida; un clic en «FT8» o «VHF» te devuelve a la Estación.', 'Se estás numa página que não é de um modo (por exemplo [[nav.log]] ou [[nav.dxmap]]) nenhuma pílula está acesa; um clique em «FT8» ou «VHF» leva-te de volta à Estação.'],
    ],
    tip: ['I modi fuori da FT8 e VHF (PSK, RTTY, CW, SSTV, satelliti) hanno la loro pagina e la loro barra: lì mancano le pagine [[nav.fox]], [[nav.contest]] e [[nav.stats]].', 'The modes other than FT8 and VHF (PSK, RTTY, CW, SSTV, satellites) have their own page and their own bar: the [[nav.fox]], [[nav.contest]] and [[nav.stats]] pages are not there.', 'Die Betriebsarten außerhalb von FT8 und VHF (PSK, RTTY, CW, SSTV, Satelliten) haben ihre eigene Seite und ihre eigene Leiste: Dort fehlen die Seiten [[nav.fox]], [[nav.contest]] und [[nav.stats]].', 'Les modes hors FT8 et VHF (PSK, RTTY, CW, SSTV, satellites) ont leur page et leur barre : là, les pages [[nav.fox]], [[nav.contest]] et [[nav.stats]] n’existent pas.', 'Los modos que no son FT8 ni VHF (PSK, RTTY, CW, SSTV, satélites) tienen su página y su barra: ahí faltan las páginas [[nav.fox]], [[nav.contest]] y [[nav.stats]].', 'Os modos fora de FT8 e VHF (PSK, RTTY, CW, SSTV, satélites) têm a sua página e a sua barra: aí faltam as páginas [[nav.fox]], [[nav.contest]] e [[nav.stats]].'],
  },
  {
    id: 'p-navpages',
    title: ['Le pagine della barra in alto', 'The pages in the top bar', 'Die Seiten der oberen Leiste', 'Les pages de la barre du haut', 'Las páginas de la barra superior', 'As páginas da barra de cima'],
    text: ['A destra delle pillole dei modi ci sono le pagine. Prima quelle del gruppo in uso, poi un separatore e le pagine di tutti i modi, infine l’ingranaggio con il menu.', 'To the right of the mode pills are the pages. First the ones of the group in use, then a separator and the pages that work in every mode, and finally the gear with its menu.', 'Rechts von den Betriebsart-Schaltflächen stehen die Seiten. Zuerst die der aktuellen Gruppe, dann ein Trenner und die Seiten für alle Betriebsarten, am Ende das Zahnrad mit dem Menü.', 'À droite des pastilles des modes se trouvent les pages. D’abord celles du groupe en cours, puis un séparateur et les pages de tous les modes, enfin l’engrenage avec son menu.', 'A la derecha de las píldoras de los modos están las páginas. Primero las del grupo en uso, luego un separador y las páginas de todos los modos, y al final el engranaje con el menú.', 'À direita das pílulas dos modos estão as páginas. Primeiro as do grupo em uso, depois um separador e as páginas de todos os modos, por fim a roda dentada com o menu.'],
    steps: [
      ['[[nav.fox]]: compare solo nel gruppo «FT8». Serve a chi trasmette da una DXpedition (vedi «Pagina Fox: ogni comando»); per chiamare una DXpedition non serve, si usa Hound nella Stazione.', '[[nav.fox]]: appears only in the “FT8” group. It is for those who transmit from a DXpedition (see “Fox page: every command”); to call a DXpedition you don’t need it, you use Hound on the Station page.', '[[nav.fox]]: erscheint nur in der Gruppe „FT8“. Sie ist für alle, die von einer DXpedition aus senden (siehe „Fox-Seite: jeder Befehl“); um eine DXpedition zu rufen, brauchst du sie nicht, dafür nimmst du Hound auf der Station.', '[[nav.fox]] : n’apparaît que dans le groupe « FT8 ». Elle sert à qui émet depuis une DXpédition (voir « Page Fox : chaque commande ») ; pour appeler une DXpédition elle ne sert pas, on utilise Hound dans la Station.', '[[nav.fox]]: solo aparece en el grupo «FT8». Sirve a quien transmite desde una DXpedición (mira «Página Fox: cada comando»); para llamar a una DXpedición no hace falta, se usa Hound en la Estación.', '[[nav.fox]]: aparece só no grupo «FT8». Serve a quem transmite a partir de uma DXpedição (vê «Página Fox: cada comando»); para chamar uma DXpedição não é preciso, usa-se Hound na Estação.'],
      ['[[nav.contest]]: nei due gruppi, per fare i contest in FT8, FT4, MSK144 e Q65 (vedi «Contest: la barra e le schede»).', '[[nav.contest]]: in both groups, to run contests in FT8, FT4, MSK144 and Q65 (see “Contest: the bar and the tabs”).', '[[nav.contest]]: in beiden Gruppen, für Conteste in FT8, FT4, MSK144 und Q65 (siehe „Contest: Leiste und Karteireiter“).', '[[nav.contest]] : dans les deux groupes, pour faire les contests en FT8, FT4, MSK144 et Q65 (voir « Contest : la barre et les onglets »).', '[[nav.contest]]: en los dos grupos, para hacer concursos en FT8, FT4, MSK144 y Q65 (mira «Concurso: la barra y las fichas»).', '[[nav.contest]]: nos dois grupos, para fazer concursos em FT8, FT4, MSK144 e Q65 (vê «Concurso: a barra e os separadores»).'],
      ['[[nav.qmap]]: compare solo nel gruppo «VHF» e solo se hai acceso «Pagina QMAP nel menu» in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. Serve un ricevitore SDR (vedi «QMAP: ogni comando»).', '[[nav.qmap]]: appears only in the “VHF” group and only if you turned on “QMAP page in the menu” in [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. It needs an SDR receiver (see “QMAP: every command”).', '[[nav.qmap]]: erscheint nur in der Gruppe „VHF“ und nur, wenn du „QMAP-Seite im Menü“ unter [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]] eingeschaltet hast. Du brauchst einen SDR-Empfänger (siehe „QMAP: jeder Befehl“).', '[[nav.qmap]] : n’apparaît que dans le groupe « VHF » et seulement si tu as activé « Page QMAP dans le menu » dans [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. Il faut un récepteur SDR (voir « QMAP : chaque commande »).', '[[nav.qmap]]: solo aparece en el grupo «VHF» y solo si has activado «Página QMAP en el menú» en [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. Hace falta un receptor SDR (mira «QMAP: cada comando»).', '[[nav.qmap]]: aparece só no grupo «VHF» e só se tiveres ligado «Página QMAP no menu» em [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]]. É preciso um recetor SDR (vê «QMAP: cada comando»).'],
      ['[[nav.stats]]: i numeri del tuo log (vedi «Statistiche e scheda DXCC»).', '[[nav.stats]]: the numbers of your log (see “Statistics and the DXCC card”).', '[[nav.stats]]: die Zahlen deines Logs (siehe „Statistik und DXCC-Karte“).', '[[nav.stats]] : les chiffres de ton log (voir « Statistiques et onglet DXCC »).', '[[nav.stats]]: los números de tu log (mira «Estadísticas y ficha DXCC»).', '[[nav.stats]]: os números do teu log (vê «Estatísticas e separador DXCC»).'],
      ['[[nav.log]]: la pagina con tutti i QSO, la ricerca, l’esportazione e la correzione (vedi «Il Log: ricerca, selezione ed esportazione»).', '[[nav.log]]: the page with all your QSOs, search, export and correction (see “The Log: search, selection and export”).', '[[nav.log]]: die Seite mit allen QSOs, Suche, Export und Korrektur (siehe „Das Log: Suche, Auswahl und Export“).', '[[nav.log]] : la page avec tous les QSO, la recherche, l’export et la correction (voir « Le Journal : recherche, sélection et export »).', '[[nav.log]]: la página con todos los QSO, la búsqueda, la exportación y la corrección (mira «El Log: búsqueda, selección y exportación»).', '[[nav.log]]: a página com todos os QSO, a pesquisa, a exportação e a correção (vê «O Log: pesquisa, seleção e exportação»).'],
      ['[[nav.dxmap]]: il planisfero con le stazioni in onda (vedi «Mappa DX: la barra dei comandi e l’ingranaggio»). [[nav.propagation]]: sole, bande e chi ti ha ricevuto (vedi «Propagazione: ogni riquadro»). [[nav.rotator]]: il rotore d’antenna (vedi «Rotore: la pagina e la scheda»).', '[[nav.dxmap]]: the world map with the stations on the air (see “DX Map: the command bar and the gear”). [[nav.propagation]]: the sun, the bands and who has received you (see “Propagation: every panel”). [[nav.rotator]]: the antenna rotator (see “Rotator: the page and the card”).', '[[nav.dxmap]]: der Globus mit den aktiven Stationen (siehe „DX-Karte: Befehlsleiste und Zahnrad“). [[nav.propagation]]: Sonne, Bänder und wer dich empfangen hat (siehe „Ausbreitung: jedes Feld“). [[nav.rotator]]: der Antennenrotor (siehe „Rotor: Seite und Karteireiter“).', '[[nav.dxmap]] : le planisphère avec les stations en l’air (voir « Carte DX : la barre de commandes et l’engrenage »). [[nav.propagation]] : soleil, bandes et qui t’a reçu (voir « Propagation : chaque encadré »). [[nav.rotator]] : le rotor d’antenne (voir « Rotor : la page et l’onglet »).', '[[nav.dxmap]]: el planisferio con las estaciones en el aire (mira «Mapa DX: la barra de comandos y el engranaje»). [[nav.propagation]]: sol, bandas y quién te ha recibido (mira «Propagación: cada recuadro»). [[nav.rotator]]: el rotor de la antena (mira «Rotor: la página y la ficha»).', '[[nav.dxmap]]: o planisfério com as estações no ar (vê «Mapa DX: a barra de comandos e a roda dentada»). [[nav.propagation]]: sol, bandas e quem te recebeu (vê «Propagação: cada quadro»). [[nav.rotator]]: o rotor de antena (vê «Rotor: a página e o separador»).'],
      ['L’ingranaggio con la freccia (nome «[[nav.more]]») apre un piccolo menu: [[nav.settings]], [[nav.wiki]] e [[nav.news]]. [[nav.settings]] si apre già sulla pagina delle impostazioni che riguarda dove ti trovi (la pagina e il modo in uso); sul telefono o dal browser di un altro computer questa voce non c’è, le impostazioni si cambiano solo dal PC. Si chiude con Esc o con un clic fuori. L’ingranaggio è acceso quando sei in una di queste tre pagine.', 'The gear with the arrow (named “[[nav.more]]”) opens a small menu: [[nav.settings]], [[nav.wiki]] and [[nav.news]]. [[nav.settings]] opens directly on the settings page that matches where you are (the page and the mode in use); on the phone or from another computer’s browser this entry is not there, and settings can only be changed from the PC. Close it with Esc or with a click outside. The gear is lit when you are on one of these three pages.', 'Das Zahnrad mit dem Pfeil (Name „[[nav.more]]“) öffnet ein kleines Menü: [[nav.settings]], [[nav.wiki]] und [[nav.news]]. [[nav.settings]] öffnet sich gleich auf der Einstellungsseite, die zu deinem aktuellen Ort passt (die Seite und die Betriebsart in Benutzung); auf dem Telefon oder im Browser eines anderen Computers fehlt dieser Eintrag, die Einstellungen änderst du nur am PC. Es schließt sich mit Esc oder mit einem Klick daneben. Das Zahnrad leuchtet, wenn du auf einer dieser drei Seiten bist.', 'L’engrenage avec la flèche (nom « [[nav.more]] ») ouvre un petit menu : [[nav.settings]], [[nav.wiki]] et [[nav.news]]. [[nav.settings]] s’ouvre déjà sur la page des réglages qui concerne l’endroit où tu te trouves (la page et le mode en cours) ; sur le téléphone ou depuis le navigateur d’un autre ordinateur cette entrée n’existe pas, les réglages se changent uniquement depuis le PC. Le menu se ferme avec Échap ou par un clic à l’extérieur. L’engrenage est allumé quand tu es dans l’une de ces trois pages.', 'El engranaje con la flecha (nombre «[[nav.more]]») abre un menú pequeño: [[nav.settings]], [[nav.wiki]] y [[nav.news]]. [[nav.settings]] se abre ya en la página de ajustes que corresponde a donde estás (la página y el modo en uso); en el teléfono o en el navegador de otro ordenador esta opción no está, los ajustes se cambian solo desde el PC. Se cierra con Esc o con un clic fuera. El engranaje está encendido cuando estás en una de estas tres páginas.', 'A roda dentada com a seta (nome «[[nav.more]]») abre um pequeno menu: [[nav.settings]], [[nav.wiki]] e [[nav.news]]. [[nav.settings]] abre logo na página de definições que diz respeito ao sítio onde estás (a página e o modo em uso); no telemóvel ou no navegador de outro computador esta entrada não existe, as definições mudam-se só a partir do PC. Fecha-se com Esc ou com um clique fora. A roda dentada está acesa quando estás numa destas três páginas.'],
      ['Quando Aurora riparte torna all’ultima pagina in cui ti eri fermato, se era una tra [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], le Impostazioni o la Guida. Dalla Stazione, dai gruppi di modi e dalle altre pagine si riparte sempre dalla Stazione.', 'When Aurora starts again, it goes back to the last page you were on, if it was one of [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], Settings or the Guide. From the Station, from the mode groups and from the other pages it always starts again from the Station.', 'Wenn Aurora neu startet, kehrt es zur letzten Seite zurück, auf der du warst, sofern sie eine von [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], Einstellungen oder Hilfe war. Von der Station, von den Betriebsartgruppen und von den anderen Seiten aus startet es immer auf der Station.', 'Quand Aurora redémarre, elle revient à la dernière page où tu t’étais arrêté, si c’était l’une de [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], les Réglages ou le Guide. Depuis la Station, les groupes de modes et les autres pages, on repart toujours de la Station.', 'Cuando Aurora arranca vuelve a la última página en la que te quedaste, si era una de estas: [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], los Ajustes o la Guía. Desde la Estación, desde los grupos de modos y desde las demás páginas se arranca siempre en la Estación.', 'Quando a Aurora volta a arrancar regressa à última página onde tinhas ficado, se era uma entre [[nav.stats]], [[nav.dxmap]], [[nav.propagation]], as Definições ou o Guia. A partir da Estação, dos grupos de modos e das outras páginas arranca-se sempre na Estação.'],
      ['A destra della barra compaiono due cose solo quando servono: l’icona della versione nuova (vedi «L’aggiornamento nella barra») e il pulsante ⤓ che rimette nella finestra principale tutte le finestre staccate (vedi «Finestre a parte e disposizione»).', 'On the right of the bar two things appear only when needed: the icon of the new version (see “The update notice in the bar”) and the ⤓ button that puts all the detached windows back in the main window (see “Separate windows and layout”).', 'Rechts in der Leiste erscheinen zwei Dinge nur, wenn sie gebraucht werden: das Symbol der neuen Version (siehe „Das Update in der Leiste“) und die Schaltfläche ⤓, die alle abgelösten Fenster zurück ins Hauptfenster holt (siehe „Eigene Fenster und Anordnung“).', 'À droite de la barre apparaissent deux choses seulement quand elles servent : l’icône de la nouvelle version (voir « La mise à jour dans la barre ») et le bouton ⤓ qui remet dans la fenêtre principale toutes les fenêtres détachées (voir « Fenêtres détachées et disposition »).', 'A la derecha de la barra aparecen dos cosas solo cuando hacen falta: el icono de la versión nueva (mira «La actualización en la barra») y el botón ⤓ que devuelve a la ventana principal todas las ventanas separadas (mira «Ventanas aparte y disposición»).', 'À direita da barra aparecem duas coisas só quando são precisas: o ícone da versão nova (vê «A atualização na barra») e o botão ⤓ que repõe na janela principal todas as janelas destacadas (vê «Janelas à parte e disposição»).'],
    ],
  },
  {
    id: 'p-modefreq',
    title: ['Modo, sottomodo e frequenza', 'Mode, submode and frequency', 'Betriebsart, Untermodus und Frequenz', 'Mode, sous-mode et fréquence', 'Modo, submodo y frecuencia', 'Modo, submodo e frequência'],
    text: ['In alto a sinistra della pagina [[nav.station]], sopra la cascata, stanno il selettore del modo e quello delle frequenze. Funzionano se la radio è comandata con il CAT; senza il CAT il modo si cambia dalla radio (o dalla pagina) e Aurora decodifica lo stesso.', 'At the top left of the [[nav.station]] page, above the waterfall, are the mode selector and the frequency selector. They work if the radio is controlled with CAT; without CAT you change the mode from the radio (or from the page) and Aurora still decodes.', 'Oben links auf der Seite [[nav.station]], über dem Wasserfall, sitzen die Betriebsartauswahl und die Frequenzauswahl. Sie funktionieren, wenn das Funkgerät über CAT gesteuert wird; ohne CAT änderst du die Betriebsart am Funkgerät (oder auf der Seite), und Aurora dekodiert trotzdem.', 'En haut à gauche de la page [[nav.station]], au-dessus de la cascade, se trouvent le sélecteur du mode et celui des fréquences. Ils fonctionnent si la radio est pilotée par le CAT ; sans CAT, le mode se change depuis la radio (ou depuis la page) et Aurora décode quand même.', 'Arriba a la izquierda de la página [[nav.station]], encima de la cascada, están el selector del modo y el de las frecuencias. Funcionan si la radio se controla con el CAT; sin el CAT el modo se cambia desde la radio (o desde la página) y Aurora decodifica igualmente.', 'Em cima, à esquerda da página [[nav.station]], por cima da cascata, estão o seletor do modo e o das frequências. Funcionam se o rádio for comandado com o CAT; sem o CAT o modo muda-se no rádio (ou na página) e a Aurora descodifica na mesma.'],
    steps: [
      ['Il pulsante con il nome del modo e la freccia ▾ apre il menu dei modi del gruppo scelto in alto («FT8» o «VHF»). Scegli un modo e Aurora lo imposta; mentre trasmetti il pulsante non reagisce («[[mode.locked]]»). È grigio solo se né la radio (CAT) né il motore proprio possono cambiare modo: il suggerimento dice come ([[band.noRig]]).', 'The button with the name of the mode and the ▾ arrow opens the menu of the modes of the group chosen at the top (“FT8” or “VHF”). Choose a mode and Aurora sets it; while you transmit the button does not react (“[[mode.locked]]”). It is grey only if neither the radio (CAT) nor Aurora’s own engine can change mode: the hint tells you how ([[band.noRig]]).', 'Die Schaltfläche mit dem Namen der Betriebsart und dem Pfeil ▾ öffnet das Betriebsartmenü der oben gewählten Gruppe („FT8“ oder „VHF“). Wähle eine Betriebsart, und Aurora stellt sie ein; während du sendest, reagiert die Schaltfläche nicht („[[mode.locked]]“). Sie ist nur grau, wenn weder das Funkgerät (CAT) noch der eigene Motor die Betriebsart wechseln kann: Der Hinweis sagt, wie ([[band.noRig]]).', 'Le bouton avec le nom du mode et la flèche ▾ ouvre le menu des modes du groupe choisi en haut (« FT8 » ou « VHF »). Choisis un mode et Aurora le règle ; pendant l’émission le bouton ne réagit pas (« [[mode.locked]] »). Il est gris seulement si ni la radio (CAT) ni le moteur interne ne peuvent changer de mode : l’info-bulle dit comment ([[band.noRig]]).', 'El botón con el nombre del modo y la flecha ▾ abre el menú de los modos del grupo elegido arriba («FT8» o «VHF»). Elige un modo y Aurora lo ajusta; mientras transmites el botón no reacciona («[[mode.locked]]»). Está gris solo si ni la radio (CAT) ni el motor propio pueden cambiar de modo: la sugerencia dice cómo ([[band.noRig]]).', 'O botão com o nome do modo e a seta ▾ abre o menu dos modos do grupo escolhido em cima («FT8» ou «VHF»). Escolhe um modo e a Aurora define-o; enquanto transmites o botão não reage («[[mode.locked]]»). Fica cinzento só se nem o rádio (CAT) nem o motor próprio puderem mudar de modo: a sugestão diz como ([[band.noRig]]).'],
      ['Accanto al modo compaiono i suoi sottomodi, tutte tendine piccole. JT4: [[mode.jt4sub]] da A a G. JT65: [[mode.jt65sub]] A, B o C. Q65: [[mode.q65period]] (15, 30, 60, 120 o 300 secondi) e [[mode.q65sub]] da A a E. FST4 e FST4W: [[mode.fst4period]] (FST4 da 15 s a 30 minuti, FST4W da 2 a 30 minuti). Il periodo e il sottomodo devono essere uguali a quelli del corrispondente.', 'Next to the mode appear its submodes, all small drop-downs. JT4: [[mode.jt4sub]] from A to G. JT65: [[mode.jt65sub]] A, B or C. Q65: [[mode.q65period]] (15, 30, 60, 120 or 300 seconds) and [[mode.q65sub]] from A to E. FST4 and FST4W: [[mode.fst4period]] (FST4 from 15 s to 30 minutes, FST4W from 2 to 30 minutes). The period and the submode must be the same as those of the station you are working.', 'Neben der Betriebsart erscheinen ihre Untermodi, alles kleine Auswahllisten. JT4: [[mode.jt4sub]] von A bis G. JT65: [[mode.jt65sub]] A, B oder C. Q65: [[mode.q65period]] (15, 30, 60, 120 oder 300 Sekunden) und [[mode.q65sub]] von A bis E. FST4 und FST4W: [[mode.fst4period]] (FST4 von 15 s bis 30 Minuten, FST4W von 2 bis 30 Minuten). Durchgang und Untermodus müssen mit denen der Gegenstation übereinstimmen.', 'À côté du mode apparaissent ses sous-modes, toutes de petites listes. JT4 : [[mode.jt4sub]] de A à G. JT65 : [[mode.jt65sub]] A, B ou C. Q65 : [[mode.q65period]] (15, 30, 60, 120 ou 300 secondes) et [[mode.q65sub]] de A à E. FST4 et FST4W : [[mode.fst4period]] (FST4 de 15 s à 30 minutes, FST4W de 2 à 30 minutes). La période et le sous-mode doivent être les mêmes que ceux de ton correspondant.', 'Junto al modo aparecen sus submodos, todos en pequeñas listas desplegables. JT4: [[mode.jt4sub]] de A a G. JT65: [[mode.jt65sub]] A, B o C. Q65: [[mode.q65period]] (15, 30, 60, 120 o 300 segundos) y [[mode.q65sub]] de A a E. FST4 y FST4W: [[mode.fst4period]] (FST4 de 15 s a 30 minutos, FST4W de 2 a 30 minutos). El periodo y el submodo deben ser iguales a los de tu corresponsal.', 'Ao lado do modo aparecem os seus submodos, todos listas pequenas. JT4: [[mode.jt4sub]] de A a G. JT65: [[mode.jt65sub]] A, B ou C. Q65: [[mode.q65period]] (15, 30, 60, 120 ou 300 segundos) e [[mode.q65sub]] de A a E. FST4 e FST4W: [[mode.fst4period]] (FST4 de 15 s a 30 minutos, FST4W de 2 a 30 minutos). O período e o submodo têm de ser iguais aos do correspondente.'],
      ['Q65 ha in più: «[[mode.q65lor]]» o «[[mode.q65gau]]» ([[mode.q65fading]]), «[[mode.q65drift]]» da 0 a 50 (0 = spenta), gli interruttori «[[mode.q65eme]]» (ritardo dell’eco dalla Luna) e «[[mode.q65contest]]» (lista dei contest Q65), «[[dec.short.IncludeAveraging]]» e «[[dec.short.AutoClearAvg]]» (media dei periodi) e il pulsante ⟲ ([[mode.q65clearAvg]]). Il «?» di ogni voce (passa il mouse) spiega cosa fa.', 'Q65 also has: “[[mode.q65lor]]” or “[[mode.q65gau]]” ([[mode.q65fading]]), “[[mode.q65drift]]” from 0 to 50 (0 = off), the switches “[[mode.q65eme]]” (echo delay from the Moon) and “[[mode.q65contest]]” (list of Q65 contests), “[[dec.short.IncludeAveraging]]” and “[[dec.short.AutoClearAvg]]” (averaging of periods) and the ⟲ button ([[mode.q65clearAvg]]). The “?” next to each item (hover over it) explains what it does.', 'Q65 hat zusätzlich: „[[mode.q65lor]]“ oder „[[mode.q65gau]]“ ([[mode.q65fading]]), „[[mode.q65drift]]“ von 0 bis 50 (0 = aus), die Schalter „[[mode.q65eme]]“ (Echoverzögerung vom Mond) und „[[mode.q65contest]]“ (Liste der Q65-Conteste), „[[dec.short.IncludeAveraging]]“ und „[[dec.short.AutoClearAvg]]“ (Mittelung der Durchgänge) und die Schaltfläche ⟲ ([[mode.q65clearAvg]]). Das „?“ bei jedem Eintrag (Maus darüberhalten) erklärt, was er tut.', 'Q65 a en plus : « [[mode.q65lor]] » ou « [[mode.q65gau]] » ([[mode.q65fading]]), « [[mode.q65drift]] » de 0 à 50 (0 = désactivée), les interrupteurs « [[mode.q65eme]] » (retard de l’écho de la Lune) et « [[mode.q65contest]] » (liste des contests Q65), « [[dec.short.IncludeAveraging]] » et « [[dec.short.AutoClearAvg]] » (moyenne des périodes) et le bouton ⟲ ([[mode.q65clearAvg]]). Le « ? » de chaque entrée (passe la souris) explique ce qu’elle fait.', 'Q65 tiene además: «[[mode.q65lor]]» o «[[mode.q65gau]]» ([[mode.q65fading]]), «[[mode.q65drift]]» de 0 a 50 (0 = apagada), los interruptores «[[mode.q65eme]]» (retardo del eco de la Luna) y «[[mode.q65contest]]» (lista de los concursos Q65), «[[dec.short.IncludeAveraging]]» y «[[dec.short.AutoClearAvg]]» (promedio de los periodos) y el botón ⟲ ([[mode.q65clearAvg]]). El «?» de cada opción (pasa el ratón) explica qué hace.', 'O Q65 tem a mais: «[[mode.q65lor]]» ou «[[mode.q65gau]]» ([[mode.q65fading]]), «[[mode.q65drift]]» de 0 a 50 (0 = desligada), os interruptores «[[mode.q65eme]]» (atraso do eco da Lua) e «[[mode.q65contest]]» (lista dos concursos Q65), «[[dec.short.IncludeAveraging]]» e «[[dec.short.AutoClearAvg]]» (média dos períodos) e o botão ⟲ ([[mode.q65clearAvg]]). O «?» de cada entrada (passa o rato) explica o que faz.'],
      ['JT65 ha in più «[[dec.short.JT65AP]]» (decodifica a priori), «[[dec.short.IncludeCorrelation]]» (ricerca profonda) e il pulsante ⟲ ([[mode.jt65clearAvg]]). MSK144 ha la tendina [[mode.mskperiod]] (5, 10, 15 o 30 secondi) e «[[mode.mskSh]]» (messaggi brevi). WSPR e FST4W hanno [[mode.wsprPower]], «[[mode.wsprPct]]» (percentuale dei periodi in cui il radiofaro trasmette) e «[[mode.wsprType1]]». Valori di fabbrica: potenza 37 dBm (5 W), Tx Pct 20%.', 'JT65 also has “[[dec.short.JT65AP]]” (a priori decoding), “[[dec.short.IncludeCorrelation]]” (deep search) and the ⟲ button ([[mode.jt65clearAvg]]). MSK144 has the [[mode.mskperiod]] drop-down (5, 10, 15 or 30 seconds) and “[[mode.mskSh]]” (short messages). WSPR and FST4W have [[mode.wsprPower]], “[[mode.wsprPct]]” (the percentage of periods in which the beacon transmits) and “[[mode.wsprType1]]”. Factory values: power 37 dBm (5 W), Tx Pct 20%.', 'JT65 hat zusätzlich „[[dec.short.JT65AP]]“ (A-priori-Dekodierung), „[[dec.short.IncludeCorrelation]]“ (Tiefensuche) und die Schaltfläche ⟲ ([[mode.jt65clearAvg]]). MSK144 hat die Auswahlliste [[mode.mskperiod]] (5, 10, 15 oder 30 Sekunden) und „[[mode.mskSh]]“ (Kurznachrichten). WSPR und FST4W haben [[mode.wsprPower]], „[[mode.wsprPct]]“ (Prozentsatz der Durchgänge, in denen die Bake sendet) und „[[mode.wsprType1]]“. Werkseinstellungen: Leistung 37 dBm (5 W), Tx Pct 20 %.', 'JT65 a en plus « [[dec.short.JT65AP]] » (décodage a priori), « [[dec.short.IncludeCorrelation]] » (recherche profonde) et le bouton ⟲ ([[mode.jt65clearAvg]]). MSK144 a la liste [[mode.mskperiod]] (5, 10, 15 ou 30 secondes) et « [[mode.mskSh]] » (messages courts). WSPR et FST4W ont [[mode.wsprPower]], « [[mode.wsprPct]] » (pourcentage des périodes pendant lesquelles la balise émet) et « [[mode.wsprType1]] ». Valeurs d’usine : puissance 37 dBm (5 W), Tx Pct 20 %.', 'JT65 tiene además «[[dec.short.JT65AP]]» (decodificación a priori), «[[dec.short.IncludeCorrelation]]» (búsqueda profunda) y el botón ⟲ ([[mode.jt65clearAvg]]). MSK144 tiene la lista [[mode.mskperiod]] (5, 10, 15 o 30 segundos) y «[[mode.mskSh]]» (mensajes cortos). WSPR y FST4W tienen [[mode.wsprPower]], «[[mode.wsprPct]]» (porcentaje de los periodos en que la baliza transmite) y «[[mode.wsprType1]]». Valores de serie: potencia 37 dBm (5 W), Tx Pct 20%.', 'O JT65 tem a mais «[[dec.short.JT65AP]]» (descodificação a priori), «[[dec.short.IncludeCorrelation]]» (pesquisa profunda) e o botão ⟲ ([[mode.jt65clearAvg]]). O MSK144 tem a lista [[mode.mskperiod]] (5, 10, 15 ou 30 segundos) e «[[mode.mskSh]]» (mensagens curtas). WSPR e FST4W têm [[mode.wsprPower]], «[[mode.wsprPct]]» (percentagem dos períodos em que o farol transmite) e «[[mode.wsprType1]]». Valores de origem: potência 37 dBm (5 W), Tx Pct 20%.'],
      ['Il pulsante grande accanto, con la banda, i MHz e ▾, è la tendina delle frequenze ([[band.freqs]]): clic per aprirla. Per ogni banda mostra le frequenze del modo in uso: quella principale (pallino colorato, legenda «[[band.main]]») e le alternative, più tenui; alcune valgono solo in una regione IARU (la sigla in apice). Un clic su una frequenza porta lì la radio. Un clic sul nome della banda porta sulla sua frequenza principale. La riga della banda dove sei è evidenziata.', 'The big button next to it, with the band, the MHz and ▾, is the frequency drop-down ([[band.freqs]]): click it to open it. For each band it shows the frequencies of the mode in use: the main one (coloured dot, legend “[[band.main]]”) and the alternatives, fainter; some are valid only in one IARU region (the abbreviation in superscript). A click on a frequency moves the radio there. A click on the name of the band moves it to its main frequency. The row of the band you are on is highlighted.', 'Die große Schaltfläche daneben, mit Band, MHz und ▾, ist die Frequenzliste ([[band.freqs]]): Klicke, um sie zu öffnen. Für jedes Band zeigt sie die Frequenzen der benutzten Betriebsart: die Hauptfrequenz (farbiger Punkt, Legende „[[band.main]]“) und die Alternativen, blasser; manche gelten nur in einer IARU-Region (das Kürzel hochgestellt). Ein Klick auf eine Frequenz stellt das Funkgerät dort ein. Ein Klick auf den Bandnamen führt zur Hauptfrequenz des Bandes. Die Zeile des aktuellen Bandes ist hervorgehoben.', 'Le grand bouton à côté, avec la bande, les MHz et ▾, est la liste des fréquences ([[band.freqs]]) : clique pour l’ouvrir. Pour chaque bande, il montre les fréquences du mode en cours : la principale (pastille colorée, légende « [[band.main]] ») et les alternatives, plus pâles ; certaines ne valent que dans une région IARU (le sigle en exposant). Un clic sur une fréquence y place la radio. Un clic sur le nom de la bande la place sur sa fréquence principale. La ligne de la bande où tu es est surlignée.', 'El botón grande de al lado, con la banda, los MHz y ▾, es la lista de las frecuencias ([[band.freqs]]): haz clic para abrirla. Para cada banda muestra las frecuencias del modo en uso: la principal (punto de color, leyenda «[[band.main]]») y las alternativas, más tenues; algunas valen solo en una región IARU (la sigla en superíndice). Un clic en una frecuencia lleva la radio allí. Un clic en el nombre de la banda lleva a su frecuencia principal. La fila de la banda donde estás aparece resaltada.', 'O botão grande ao lado, com a banda, os MHz e ▾, é a lista das frequências ([[band.freqs]]): clica para a abrir. Para cada banda mostra as frequências do modo em uso: a principal (bolinha colorida, legenda «[[band.main]]») e as alternativas, mais ténues; algumas valem só numa região IARU (a sigla em expoente). Um clique numa frequência leva lá o rádio. Um clique no nome da banda leva-o para a sua frequência principal. A linha da banda onde estás fica realçada.'],
      ['Tasto destro sul pulsante delle frequenze: salta subito alla frequenza successiva dell’elenco del Band Hopping (serve la radio comandata; l’elenco si scrive in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Con un contest acceso la tendina mostra solo le bande ammesse dal regolamento.', 'Right-click the frequency button: it jumps straight to the next frequency in the Band Hopping list (the radio must be controlled; the list is written in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). With a contest on, the drop-down shows only the bands allowed by the rules.', 'Rechtsklick auf die Frequenzschaltfläche: springt sofort zur nächsten Frequenz der Band-Hopping-Liste (das Funkgerät muss gesteuert werden; die Liste schreibst du unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Bei eingeschaltetem Contest zeigt die Liste nur die Bänder, die das Regelwerk erlaubt.', 'Clic droit sur le bouton des fréquences : saute tout de suite à la fréquence suivante de la liste du Band Hopping (il faut la radio pilotée ; la liste s’écrit dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Avec un contest actif, la liste n’affiche que les bandes admises par le règlement.', 'Clic derecho en el botón de las frecuencias: salta enseguida a la frecuencia siguiente de la lista del Band Hopping (hace falta la radio controlada; la lista se escribe en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Con un concurso activo la lista muestra solo las bandas que admite el reglamento.', 'Botão direito no botão das frequências: salta logo para a frequência seguinte da lista do Band Hopping (é preciso o rádio comandado; a lista escreve-se em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]). Com um concurso ligado a lista mostra só as bandas permitidas pelo regulamento.'],
      ['Quali bande compaiono nella tendina si sceglie in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (la banda in uso si vede sempre); le frequenze stesse si cambiano in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].', 'Which bands appear in the drop-down is chosen in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (the band in use is always shown); the frequencies themselves are changed in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].', 'Welche Bänder in der Liste erscheinen, wählst du unter [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (das aktuelle Band siehst du immer); die Frequenzen selbst änderst du unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].', 'Les bandes qui apparaissent dans la liste se choisissent dans [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (la bande en cours se voit toujours) ; les fréquences elles-mêmes se changent dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].', 'Qué bandas aparecen en la lista se elige en [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (la banda en uso se ve siempre); las frecuencias en sí se cambian en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].', 'Quais as bandas que aparecem na lista escolhe-se em [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.bands]] (a banda em uso vê-se sempre); as próprias frequências mudam-se em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.common]] › [[sw.tab.freq]].'],
    ],
    tip: ['Il modo e la frequenza non cambiano mentre trasmetti, ma il pulsante non si spegne di colore: si ignora solo il clic.', 'The mode and the frequency do not change while you transmit, but the button does not change colour: the click is simply ignored.', 'Betriebsart und Frequenz ändern sich nicht, während du sendest, aber die Schaltfläche wird nicht farblos: Nur der Klick wird ignoriert.', 'Le mode et la fréquence ne changent pas pendant que tu émets, mais le bouton ne change pas de couleur : seul le clic est ignoré.', 'El modo y la frecuencia no cambian mientras transmites, pero el botón no cambia de color: solo se ignora el clic.', 'O modo e a frequência não mudam enquanto transmites, mas o botão não muda de cor: ignora-se só o clique.'],
  },
  {
    id: 'p-rxrow',
    title: ['La riga dei comandi di ricezione', 'The receive controls row', 'Die Empfangsbefehlsleiste', 'La rangée des commandes de réception', 'La fila de comandos de recepción', 'A linha de comandos de receção'],
    text: ['Sotto il selettore del modo c’è una barra a segmenti: ogni segmento è un interruttore (acceso = verde) o un pulsante. Passa il mouse su una voce per leggerne la spiegazione. Se i comandi di Aurora non sono raggiungibili i segmenti sono grigi.', 'Below the mode selector is a bar made of segments: each segment is a switch (on = green) or a button. Hover over an item to read its explanation. If Aurora’s controls cannot be reached, the segments are grey.', 'Unter der Betriebsartauswahl sitzt eine Leiste aus Segmenten: Jedes Segment ist ein Schalter (an = grün) oder eine Schaltfläche. Halte die Maus über einen Eintrag, um die Erklärung zu lesen. Sind die Befehle von Aurora nicht erreichbar, sind die Segmente grau.', 'Sous le sélecteur du mode, il y a une barre à segments : chaque segment est un interrupteur (allumé = vert) ou un bouton. Passe la souris sur une entrée pour lire son explication. Si les commandes d’Aurora ne sont pas joignables, les segments sont gris.', 'Debajo del selector del modo hay una barra de segmentos: cada segmento es un interruptor (encendido = verde) o un botón. Pasa el ratón por una opción para leer su explicación. Si los comandos de Aurora no están al alcance, los segmentos están grises.', 'Por baixo do seletor do modo há uma barra de segmentos: cada segmento é um interruptor (aceso = verde) ou um botão. Passa o rato por cima de uma entrada para ler a explicação. Se os comandos da Aurora não estiverem acessíveis os segmentos ficam cinzentos.'],
    steps: [
      ['[[ctl.monitor]]: ascolto acceso o spento. Spento, Aurora non decodifica niente: è il primo interruttore da guardare se la lista dei messaggi resta vuota.', '[[ctl.monitor]]: listening on or off. When off, Aurora decodes nothing: it is the first switch to check if the message list stays empty.', '[[ctl.monitor]]: Hören an oder aus. Aus dekodiert Aurora nichts: Das ist der erste Schalter, den du ansehen solltest, wenn die Nachrichtenliste leer bleibt.', '[[ctl.monitor]] : écoute allumée ou éteinte. Éteinte, Aurora ne décode rien : c’est le premier interrupteur à regarder si la liste des messages reste vide.', '[[ctl.monitor]]: escucha encendida o apagada. Apagada, Aurora no decodifica nada: es el primer interruptor que hay que mirar si la lista de mensajes se queda vacía.', '[[ctl.monitor]]: escuta ligada ou desligada. Desligada, a Aurora não descodifica nada: é o primeiro interruptor a ver se a lista de mensagens fica vazia.'],
      ['[[ctl.hound]]: il modo Hound, per chiamare una DXpedition in Fox/Hound (di solito si accende da solo, vedi «Collegare una DXpedition in Hound»). [[ctl.swl]]: solo ascolto, il decodificatore cerca più a fondo.', '[[ctl.hound]]: Hound mode, to call a DXpedition in Fox/Hound (it usually turns on by itself, see “Working a DXpedition as a Hound”). [[ctl.swl]]: listen only, the decoder searches deeper.', '[[ctl.hound]]: die Betriebsart Hound, um eine DXpedition im Fox/Hound-Betrieb zu rufen (schaltet sich meist von selbst ein, siehe „Eine DXpedition als Hound arbeiten“). [[ctl.swl]]: nur Hören, der Dekoder sucht tiefer.', '[[ctl.hound]] : le mode Hound, pour appeler une DXpédition en Fox/Hound (en général il s’allume tout seul, voir « Contacter une DXpédition en Hound »). [[ctl.swl]] : écoute seule, le décodeur cherche plus en profondeur.', '[[ctl.hound]]: el modo Hound, para llamar a una DXpedición en Fox/Hound (normalmente se enciende solo, mira «Contactar una DXpedición como Hound»). [[ctl.swl]]: solo escucha, el decodificador busca más a fondo.', '[[ctl.hound]]: o modo Hound, para chamar uma DXpedição em Fox/Hound (normalmente liga-se sozinho, vê «Contactar uma DXpedição como Hound»). [[ctl.swl]]: só escuta, o descodificador procura mais a fundo.'],
      ['[[ctl.jt_both]]: compare solo con JT65 o JT9; acceso decodifica nello stesso minuto anche l’altro dei due. [[ctl.agc]]: compensa le variazioni dell’AGC della radio (vedi «[[ctl.agc]]: segnali deboli vicino a stazioni forti»).', '[[ctl.jt_both]]: appears only with JT65 or JT9; when on, it also decodes the other of the two in the same minute. [[ctl.agc]]: compensates for the radio’s AGC variations (see “[[ctl.agc]]: weak signals near strong stations”).', '[[ctl.jt_both]]: erscheint nur bei JT65 oder JT9; eingeschaltet dekodiert er in derselben Minute auch die andere der beiden Betriebsarten. [[ctl.agc]]: gleicht die Schwankungen der AGC des Funkgeräts aus (siehe „[[ctl.agc]]: schwache Signale neben starken Stationen“).', '[[ctl.jt_both]] : n’apparaît qu’avec JT65 ou JT9 ; allumé, il décode dans la même minute aussi l’autre des deux. [[ctl.agc]] : compense les variations de l’AGC de la radio (voir « [[ctl.agc]] : signaux faibles près de stations fortes »).', '[[ctl.jt_both]]: solo aparece con JT65 o JT9; encendido decodifica en el mismo minuto también el otro de los dos. [[ctl.agc]]: compensa las variaciones del AGC de la radio (mira «[[ctl.agc]]: señales débiles cerca de estaciones fuertes»).', '[[ctl.jt_both]]: aparece só com JT65 ou JT9; ligado, descodifica no mesmo minuto também o outro dos dois. [[ctl.agc]]: compensa as variações do AGC do rádio (vê «[[ctl.agc]]: sinais fracos perto de estações fortes»).'],
      ['[[ctl.filter]]: decodifica solo ±60 Hz intorno alla frequenza Rx (±290 Hz in Hound). Acceso diventa giallo e lo dice nel suggerimento: tutti gli altri segnali della cascata vengono ignorati. Serve su una banda molto affollata quando segui solo il tuo corrispondente.', '[[ctl.filter]]: decodes only ±60 Hz around the Rx frequency (±290 Hz in Hound). When on, it turns yellow and says so in the hint: all the other signals in the waterfall are ignored. It is useful on a very crowded band when you follow only your partner.', '[[ctl.filter]]: dekodiert nur ±60 Hz um die Rx-Frequenz (±290 Hz bei Hound). Eingeschaltet wird er gelb und sagt es im Hinweis: Alle anderen Signale im Wasserfall werden ignoriert. Er hilft auf einem sehr vollen Band, wenn du nur deiner Gegenstation folgst.', '[[ctl.filter]] : décode seulement ±60 Hz autour de la fréquence Rx (±290 Hz en Hound). Allumé, il devient jaune et le dit dans l’info-bulle : tous les autres signaux de la cascade sont ignorés. Utile sur une bande très encombrée quand tu ne suis que ton correspondant.', '[[ctl.filter]]: decodifica solo ±60 Hz alrededor de la frecuencia Rx (±290 Hz en Hound). Encendido se pone amarillo y lo dice en la sugerencia: todas las demás señales de la cascada se ignoran. Sirve en una banda muy concurrida cuando sigues solo a tu corresponsal.', '[[ctl.filter]]: descodifica só ±60 Hz à volta da frequência Rx (±290 Hz em Hound). Ligado fica amarelo e di-lo na sugestão: todos os outros sinais da cascata são ignorados. Serve numa banda muito concorrida quando segues só o teu correspondente.'],
      ['[[ctl.ap_list]] e [[ctl.mtd]]: compaiono solo in FT8. «a7/a8» è la decodifica a liste (trova segnali fino a circa −24 dB; i messaggi trovati così hanno un asterisco); «Multithread» decodifica su tutti i processori del PC: gli stessi messaggi in meno tempo sulle bande affollate.', '[[ctl.ap_list]] and [[ctl.mtd]]: appear only in FT8. “a7/a8” is list decoding (it finds signals down to about −24 dB; messages found this way have an asterisk); “Multithread” decodes on all the processors of the PC: the same messages in less time on crowded bands.', '[[ctl.ap_list]] und [[ctl.mtd]]: erscheinen nur in FT8. „a7/a8“ ist die Listendekodierung (findet Signale bis etwa −24 dB; so gefundene Nachrichten haben ein Sternchen); „Multithread“ dekodiert auf allen Prozessoren des PCs: dieselben Nachrichten in kürzerer Zeit auf vollen Bändern.', '[[ctl.ap_list]] et [[ctl.mtd]] : n’apparaissent qu’en FT8. « a7/a8 » est le décodage par listes (trouve des signaux jusqu’à environ −24 dB ; les messages trouvés ainsi ont un astérisque) ; « Multithread » décode sur tous les processeurs du PC : les mêmes messages en moins de temps sur les bandes encombrées.', '[[ctl.ap_list]] y [[ctl.mtd]]: solo aparecen en FT8. «a7/a8» es la decodificación por listas (encuentra señales hasta unos −24 dB; los mensajes encontrados así llevan un asterisco); «Multithread» decodifica en todos los procesadores del PC: los mismos mensajes en menos tiempo en las bandas concurridas.', '[[ctl.ap_list]] e [[ctl.mtd]]: aparecem só em FT8. «a7/a8» é a descodificação por listas (encontra sinais até cerca de −24 dB; as mensagens encontradas assim têm um asterisco); «Multithread» descodifica em todos os processadores do PC: as mesmas mensagens em menos tempo nas bandas concorridas.'],
      ['[[ctl.stop_rx]]: ferma la ricezione e la decodifica in corso (non la trasmissione). [[ctl.decode]]: decodifica subito l’ultimo periodo registrato.', '[[ctl.stop_rx]]: stops reception and the decoding in progress (not transmission). [[ctl.decode]]: decodes the last recorded period right away.', '[[ctl.stop_rx]]: stoppt den Empfang und die laufende Dekodierung (nicht das Senden). [[ctl.decode]]: dekodiert sofort den zuletzt aufgenommenen Durchgang.', '[[ctl.stop_rx]] : arrête la réception et le décodage en cours (pas l’émission). [[ctl.decode]] : décode tout de suite la dernière période enregistrée.', '[[ctl.stop_rx]]: detiene la recepción y la decodificación en curso (no la transmisión). [[ctl.decode]]: decodifica enseguida el último periodo grabado.', '[[ctl.stop_rx]]: pára a receção e a descodificação em curso (não a transmissão). [[ctl.decode]]: descodifica logo o último período gravado.'],
      ['L’ultimo segmento, «[[autoSwitch.off]]», accende o spegne le Automazioni senza aprire le Impostazioni. Verde: Automazioni in modo reale (rispondono da sole e Abilita Tx si accende). Arancio: prova a vuoto (decidono e scrivono nel registro ma non trasmettono). Grigio: spente. Da spente, se la trasmissione è consentita, un clic ti chiede se passare al modo reale (Sì = reale, No = prova a vuoto); dopo la conferma i clic seguenti accendono e spengono senza domande. Le regole stanno in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (vedi «Risposte automatiche»).', 'The last segment, “[[autoSwitch.off]]”, turns the Automations on or off without opening the Settings. Green: Automations in live mode (they reply by themselves and Enable Tx turns on). Orange: dry run (they decide and write to the log but do not transmit). Grey: off. When off, if transmission is allowed, a click asks you whether to switch to live mode (Yes = live, No = dry run); after you confirm, the next clicks turn them on and off without questions. The rules are in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (see “Automatic replies”).', 'Das letzte Segment, „[[autoSwitch.off]]“, schaltet die Automatiken ein oder aus, ohne die Einstellungen zu öffnen. Grün: Automatiken im Echtbetrieb (antworten selbst und „Tx an“ schaltet sich ein). Orange: Probelauf (entscheiden und schreiben ins Protokoll, senden aber nicht). Grau: aus. Ist es aus und Senden erlaubt, fragt dich ein Klick, ob in den Echtbetrieb gewechselt werden soll (Ja = echt, Nein = Probelauf); nach der Bestätigung schalten die folgenden Klicks ohne Fragen ein und aus. Die Regeln stehen unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (siehe „Automatische Antworten“).', 'Le dernier segment, « [[autoSwitch.off]] », allume ou éteint les Automatisations sans ouvrir les Réglages. Vert : Automatisations en mode réel (elles répondent seules et Activer Tx s’allume). Orange : essai à blanc (elles décident et écrivent dans le journal mais n’émettent pas). Gris : éteintes. Quand elles sont éteintes, si l’émission est autorisée, un clic te demande de passer au mode réel (Oui = réel, Non = essai à blanc) ; après la confirmation, les clics suivants allument et éteignent sans question. Les règles sont dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (voir « Réponses automatiques »).', 'El último segmento, «[[autoSwitch.off]]», enciende o apaga las Automatizaciones sin abrir los Ajustes. Verde: Automatizaciones en modo real (responden solas y Habilitar Tx se enciende). Naranja: prueba en vacío (deciden y escriben en el registro pero no transmiten). Gris: apagadas. Estando apagadas, si la transmisión está permitida, un clic te pregunta si pasar al modo real (Sí = real, No = prueba en vacío); tras la confirmación, los clics siguientes encienden y apagan sin preguntar. Las reglas están en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (mira «Respuestas automáticas»).', 'O último segmento, «[[autoSwitch.off]]», liga ou desliga as Automações sem abrir as Definições. Verde: Automações em modo real (respondem sozinhas e Ativar Tx acende-se). Laranja: ensaio em vazio (decidem e escrevem no registo mas não transmitem). Cinzento: desligadas. Estando desligadas, se a transmissão for permitida, um clique pergunta-te se queres passar ao modo real (Sim = real, Não = ensaio em vazio); depois da confirmação os cliques seguintes ligam e desligam sem perguntas. As regras estão em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] (vê «Respostas automáticas»).'],
    ],
    tip: ['Il pulsante «Cancella» non c’è più qui: per svuotare gli elenchi usa «[[list.clear]]» nella barra del titolo di Attività di banda e della Finestra RX.', 'The “Clear” button is no longer here: to empty the lists use “[[list.clear]]” in the title bar of Band activity and of the RX window.', 'Die Schaltfläche „Löschen“ gibt es hier nicht mehr: Um die Listen zu leeren, nimm „[[list.clear]]“ in der Titelleiste von Bandaktivität und RX-Fenster.', 'Le bouton « Effacer » n’est plus ici : pour vider les listes, utilise « [[list.clear]] » dans la barre de titre d’Activité de bande et de la Fenêtre RX.', 'El botón «Borrar» ya no está aquí: para vaciar las listas usa «[[list.clear]]» en la barra del título de Actividad de banda y de la Ventana RX.', 'O botão «Apagar» já não existe aqui: para esvaziar as listas usa «[[list.clear]]» na barra do título da Atividade da banda e da Janela RX.'],
  },
  {
    id: 'p-status',
    title: ['Collegamento, frequenza e orologio in alto a sinistra', 'Connection, frequency and clock at the top left', 'Verbindung, Frequenz und Uhr oben links', 'Connexion, fréquence et horloge en haut à gauche', 'Conexión, frecuencia y reloj arriba a la izquierda', 'Ligação, frequência e relógio em cima à esquerda'],
    text: ['Accanto ai selettori compare una piccola striscia di stato. Di norma è quasi vuota: ti dice qualcosa solo quando c’è un problema.', 'Next to the selectors there is a small status strip. Usually it is almost empty: it tells you something only when there is a problem.', 'Neben den Auswahlfeldern erscheint ein kleiner Statusstreifen. Normalerweise ist er fast leer: Er sagt dir nur etwas, wenn es ein Problem gibt.', 'À côté des sélecteurs apparaît une petite bande d’état. En général elle est presque vide : elle ne te dit quelque chose que quand il y a un problème.', 'Junto a los selectores aparece una pequeña franja de estado. Normalmente está casi vacía: solo te dice algo cuando hay un problema.', 'Ao lado dos seletores aparece uma pequena faixa de estado. Em regra está quase vazia: só te diz alguma coisa quando há um problema.'],
    steps: [
      ['Pillola del collegamento: non c’è finché tutto va bene. Se la pagina perde il contatto con Aurora sul PC compare «[[conn.connecting]]» (sta riprovando) oppure «[[conn.closed]]» (il contatto è caduto). Controlla che Aurora sia aperta sul PC e che la rete funzioni.', 'Connection pill: it is not there while everything works. If the page loses contact with Aurora on the PC, “[[conn.connecting]]” appears (it is trying again) or “[[conn.closed]]” (the contact has dropped). Check that Aurora is open on the PC and that the network works.', 'Verbindungsanzeige: Es gibt sie nicht, solange alles gut läuft. Verliert die Seite den Kontakt zu Aurora auf dem PC, erscheint „[[conn.connecting]]“ (es versucht es erneut) oder „[[conn.closed]]“ (der Kontakt ist abgebrochen). Prüfe, ob Aurora am PC offen ist und das Netz funktioniert.', 'Pastille de la connexion : elle n’existe pas tant que tout va bien. Si la page perd le contact avec Aurora sur le PC, « [[conn.connecting]] » apparaît (elle réessaie) ou « [[conn.closed]] » (le contact est tombé). Vérifie qu’Aurora est ouverte sur le PC et que le réseau fonctionne.', 'Píldora de la conexión: no está mientras todo va bien. Si la página pierde el contacto con Aurora en el PC aparece «[[conn.connecting]]» (está reintentando) o «[[conn.closed]]» (el contacto se ha cortado). Comprueba que Aurora esté abierta en el PC y que la red funcione.', 'Pílula da ligação: não existe enquanto tudo corre bem. Se a página perde o contacto com a Aurora no PC aparece «[[conn.connecting]]» (está a tentar de novo) ou «[[conn.closed]]» (o contacto caiu). Verifica se a Aurora está aberta no PC e se a rede funciona.'],
      ['Frequenza della radio in MHz: si vede solo se il display della radio è nascosto (altrimenti la leggi già lì).', 'Radio frequency in MHz: you see it only if the radio display is hidden (otherwise you already read it there).', 'Frequenz des Funkgeräts in MHz: Du siehst sie nur, wenn die Anzeige des Funkgeräts ausgeblendet ist (sonst liest du sie schon dort).', 'Fréquence de la radio en MHz : elle ne se voit que si l’afficheur de la radio est masqué (sinon tu la lis déjà là).', 'Frecuencia de la radio en MHz: solo se ve si la pantalla de la radio está oculta (si no, ya la lees ahí).', 'Frequência do rádio em MHz: vê-se só se o visor do rádio estiver escondido (senão já a lês lá).'],
      ['Avviso giallo dell’orologio (con ⚠): compare solo se l’ora del PC è fuori tolleranza rispetto ai server NTP, o se non si riesce a controllare da più di un giorno. Un clic prova subito a correggere l’ora di Windows; se Windows non lo permette si apre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] con la prova sui server NTP (vedi «L’orologio»).', 'Yellow clock warning (with ⚠): it appears only if the PC time is out of tolerance compared with the NTP servers, or if it could not be checked for more than a day. A click tries to correct Windows time right away; if Windows does not allow it, [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] opens with the test on the NTP servers (see “The clock”).', 'Gelber Uhrhinweis (mit ⚠): erscheint nur, wenn die PC-Uhr gegenüber den NTP-Servern außerhalb der Toleranz liegt oder wenn sie seit mehr als einem Tag nicht geprüft werden konnte. Ein Klick versucht sofort, die Windows-Zeit zu korrigieren; erlaubt Windows das nicht, öffnet sich [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] mit dem Test an den NTP-Servern (siehe „Die Uhr“).', 'Alerte jaune de l’horloge (avec ⚠) : elle n’apparaît que si l’heure du PC est hors tolérance par rapport aux serveurs NTP, ou si on n’arrive pas à la contrôler depuis plus d’un jour. Un clic essaie tout de suite de corriger l’heure de Windows ; si Windows ne le permet pas, [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] s’ouvre avec l’essai sur les serveurs NTP (voir « L’horloge »).', 'Aviso amarillo del reloj (con ⚠): aparece solo si la hora del PC está fuera de tolerancia respecto a los servidores NTP, o si no se puede comprobar desde hace más de un día. Un clic intenta corregir enseguida la hora de Windows; si Windows no lo permite se abre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] con la prueba en los servidores NTP (mira «El reloj»).', 'Aviso amarelo do relógio (com ⚠): aparece só se a hora do PC estiver fora da tolerância em relação aos servidores NTP, ou se não for possível verificá-la há mais de um dia. Um clique tenta logo corrigir a hora do Windows; se o Windows não o permitir abre-se [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] com o teste aos servidores NTP (vê «O relógio»).'],
    ],
  },
  {
    id: 'p-footer',
    title: ['La barra in basso', 'The bottom bar', 'Die untere Leiste', 'La barre du bas', 'La barra inferior', 'A barra de baixo'],
    text: ['In fondo alla finestra una barra stretta mostra lo stato del periodo e tiene a portata di mano avvisi sonori, tema e ora UTC.', 'At the bottom of the window a narrow bar shows the state of the period and keeps sound alerts, theme and UTC time within reach.', 'Ganz unten im Fenster zeigt eine schmale Leiste den Zustand des Durchgangs und hält Tonhinweise, Design und UTC-Zeit griffbereit.', 'Tout en bas de la fenêtre, une barre étroite montre l’état de la période et garde à portée de main les alertes sonores, le thème et l’heure UTC.', 'Al fondo de la ventana una barra estrecha muestra el estado del periodo y tiene a mano los avisos sonoros, el tema y la hora UTC.', 'No fundo da janela uma barra estreita mostra o estado do período e mantém à mão os avisos sonoros, o tema e a hora UTC.'],
    steps: [
      ['[[bar.decodes]]: quante decodifiche ha dato l’ultimo periodo. A fianco una barra mostra a che punto del periodo sei (diventa rossa mentre trasmetti) e un contatore «secondo/durata» (per esempio 7/15). Nelle pagine PSK·RTTY·SSTV e satelliti questa parte non c’è.', '[[bar.decodes]]: how many decodes the last period gave. Next to it a bar shows where you are in the period (it turns red while you transmit) and a “second/length” counter (for example 7/15). On the PSK·RTTY·SSTV and satellite pages this part is not there.', '[[bar.decodes]]: wie viele Dekodierungen der letzte Durchgang ergeben hat. Daneben zeigt ein Balken, wo im Durchgang du gerade bist (er wird rot, während du sendest), und ein Zähler „Sekunde/Dauer“ (zum Beispiel 7/15). Auf den Seiten PSK·RTTY·SSTV und Satelliten fehlt dieser Teil.', '[[bar.decodes]] : combien de décodages la dernière période a donnés. À côté, une barre montre où tu en es dans la période (elle devient rouge pendant que tu émets) et un compteur « seconde/durée » (par exemple 7/15). Dans les pages PSK·RTTY·SSTV et satellites cette partie n’existe pas.', '[[bar.decodes]]: cuántas decodificaciones ha dado el último periodo. Al lado una barra muestra en qué punto del periodo estás (se pone roja mientras transmites) y un contador «segundo/duración» (por ejemplo 7/15). En las páginas PSK·RTTY·SSTV y satélites esta parte no está.', '[[bar.decodes]]: quantas descodificações deu o último período. Ao lado uma barra mostra em que ponto do período estás (fica vermelha enquanto transmites) e um contador «segundo/duração» (por exemplo 7/15). Nas páginas PSK·RTTY·SSTV e satélites esta parte não existe.'],
      ['[[bar.profile]]: il nome del profilo della radio in uso, se hai più profili ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).', '[[bar.profile]]: the name of the radio profile in use, if you have more than one profile ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).', '[[bar.profile]]: der Name des benutzten Funkgeräteprofils, wenn du mehrere Profile hast ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).', '[[bar.profile]] : le nom du profil de la radio en cours, si tu as plusieurs profils ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).', '[[bar.profile]]: el nombre del perfil de la radio en uso, si tienes varios perfiles ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).', '[[bar.profile]]: o nome do perfil do rádio em uso, se tiveres mais perfis ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.profiles]]).'],
      ['[[bar.watchdog]] con i minuti, per esempio «WD 6m»: il watchdog di trasmissione. Dopo quei minuti senza un QSO la trasmissione si ferma da sola; passando il mouse lo leggi. Compare solo se il watchdog è acceso (non zero).', '[[bar.watchdog]] with the minutes, for example “WD 6m”: the transmit watchdog. After that many minutes without a QSO, transmission stops by itself; hover over it to read it. It appears only if the watchdog is on (not zero).', '[[bar.watchdog]] mit den Minuten, zum Beispiel „WD 6m“: der Sende-Watchdog. Nach diesen Minuten ohne QSO stoppt das Senden von selbst; wenn du die Maus darüberhältst, liest du es. Er erscheint nur, wenn der Watchdog eingeschaltet ist (nicht null).', '[[bar.watchdog]] avec les minutes, par exemple « WD 6m » : le watchdog d’émission. Après ces minutes sans QSO, l’émission s’arrête toute seule ; en passant la souris dessus tu le lis. N’apparaît que si le watchdog est actif (pas à zéro).', '[[bar.watchdog]] con los minutos, por ejemplo «WD 6m»: el watchdog de transmisión. Pasados esos minutos sin un QSO la transmisión se detiene sola; al pasar el ratón lo lees. Solo aparece si el watchdog está encendido (no es cero).', '[[bar.watchdog]] com os minutos, por exemplo «WD 6m»: o watchdog de transmissão. Passados esses minutos sem um QSO a transmissão pára sozinha; passando o rato por cima lês isso. Aparece só se o watchdog estiver ligado (não zero).'],
      ['L’icona dell’altoparlante e il cursore del volume: gli avvisi sonori (vedi «Lingua, tema e volume dalla barra»). Accanto la luna, il sole o il cerchio mezzo pieno: il tema.', 'The speaker icon and the volume slider: the sound alerts (see “Language, theme and volume from the bar”). Next to it the moon, the sun or the half-filled circle: the theme.', 'Das Lautsprechersymbol und der Lautstärkeregler: die Tonhinweise (siehe „Sprache, Design und Lautstärke in der Leiste“). Daneben der Mond, die Sonne oder der halb gefüllte Kreis: das Design.', 'L’icône du haut-parleur et le curseur du volume : les alertes sonores (voir « Langue, thème et volume depuis la barre »). À côté, la lune, le soleil ou le cercle à moitié plein : le thème.', 'El icono del altavoz y el cursor del volumen: los avisos sonoros (mira «Idioma, tema y volumen desde la barra»). Al lado la luna, el sol o el círculo medio lleno: el tema.', 'O ícone do altifalante e o cursor do volume: os avisos sonoros (vê «Idioma, tema e volume a partir da barra»). Ao lado a lua, o sol ou o círculo meio cheio: o tema.'],
      ['L’orario UTC con i secondi, e a destra il nome e la versione di Aurora. Se il programma non risponde la versione è sostituita da una scritta che lo dice.', 'The UTC time with seconds, and on the right the name and version of Aurora. If the program does not answer, the version is replaced by a text saying so.', 'Die UTC-Uhrzeit mit Sekunden, und rechts der Name und die Version von Aurora. Antwortet das Programm nicht, wird die Version durch einen Text ersetzt, der das sagt.', 'L’heure UTC avec les secondes, et à droite le nom et la version d’Aurora. Si le programme ne répond pas, la version est remplacée par un texte qui le dit.', 'La hora UTC con los segundos, y a la derecha el nombre y la versión de Aurora. Si el programa no responde, la versión se sustituye por un texto que lo dice.', 'A hora UTC com os segundos e, à direita, o nome e a versão da Aurora. Se o programa não responder a versão é substituída por um texto que o diz.'],
    ],
  },
  {
    id: 'p-langtheme',
    title: ['Lingua, tema e volume dalla barra', 'Language, theme and volume from the bar', 'Sprache, Design und Lautstärke in der Leiste', 'Langue, thème et volume depuis la barre', 'Idioma, tema y volumen desde la barra', 'Idioma, tema e volume a partir da barra'],
    text: ['Sono le tre domande più frequenti. Lingua, tema e volume non stanno tutti nello stesso posto: la lingua è nelle Impostazioni, volume e tema sono nella barra in basso.', 'These are the three most frequent questions. Language, theme and volume are not all in the same place: the language is in the Settings, volume and theme are in the bottom bar.', 'Das sind die drei häufigsten Fragen. Sprache, Design und Lautstärke sitzen nicht alle am selben Ort: Die Sprache ist in den Einstellungen, Lautstärke und Design sind in der unteren Leiste.', 'Ce sont les trois questions les plus fréquentes. La langue, le thème et le volume ne sont pas tous au même endroit : la langue est dans les Réglages, le volume et le thème sont dans la barre du bas.', 'Son las tres preguntas más frecuentes. El idioma, el tema y el volumen no están todos en el mismo sitio: el idioma está en los Ajustes, el volumen y el tema están en la barra inferior.', 'São as três perguntas mais frequentes. Idioma, tema e volume não estão todos no mesmo sítio: o idioma está nas Definições, volume e tema estão na barra de baixo.'],
    steps: [
      ['Cambiare la lingua: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], riquadro «[[ap.theme]]», voce «[[gen.language]]». Il menu ha le bandiere delle sette lingue (italiano, inglese, tedesco, francese, spagnolo, portoghese, olandese); con la tastiera: frecce per aprire e spostarsi, Invio o spazio per scegliere, Esc per chiudere, Home e Fine per il primo e l’ultimo. Il cambio vale subito per tutta l’interfaccia, Guida compresa, e resta su questo dispositivo (il telefono ha la sua scelta).', 'Change the language: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], box “[[ap.theme]]”, item “[[gen.language]]”. The menu has the flags of the seven languages (Italian, English, German, French, Spanish, Portuguese, Dutch); with the keyboard: arrows to open and move, Enter or space to choose, Esc to close, Home and End for the first and the last. The change applies at once to the whole interface, the Guide included, and stays on this device (the phone has its own choice).', 'Sprache wechseln: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], Feld „[[ap.theme]]“, Eintrag „[[gen.language]]“. Das Menü hat die Flaggen der sieben Sprachen (Italienisch, Englisch, Deutsch, Französisch, Spanisch, Portugiesisch, Niederländisch); mit der Tastatur: Pfeiltasten zum Öffnen und Bewegen, Enter oder Leertaste zum Wählen, Esc zum Schließen, Pos1 und Ende für den ersten und den letzten Eintrag. Der Wechsel gilt sofort für die ganze Oberfläche, die Hilfe eingeschlossen, und bleibt auf diesem Gerät gespeichert (das Telefon hat seine eigene Wahl).', 'Changer la langue : [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], encadré « [[ap.theme]] », entrée « [[gen.language]] ». Le menu a les drapeaux des sept langues (italien, anglais, allemand, français, espagnol, portugais, néerlandais) ; au clavier : flèches pour ouvrir et se déplacer, Entrée ou espace pour choisir, Échap pour fermer, Début et Fin pour le premier et le dernier. Le changement vaut tout de suite pour toute l’interface, Guide compris, et reste sur cet appareil (le téléphone a son propre choix).', 'Cambiar el idioma: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], recuadro «[[ap.theme]]», opción «[[gen.language]]». El menú tiene las banderas de los siete idiomas (italiano, inglés, alemán, francés, español, portugués, neerlandés); con el teclado: flechas para abrir y moverte, Intro o espacio para elegir, Esc para cerrar, Inicio y Fin para el primero y el último. El cambio vale enseguida para toda la interfaz, Guía incluida, y se queda en este dispositivo (el teléfono tiene su propia elección).', 'Mudar o idioma: [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]], quadro «[[ap.theme]]», entrada «[[gen.language]]». O menu tem as bandeiras dos sete idiomas (italiano, inglês, alemão, francês, espanhol, português, neerlandês); com o teclado: setas para abrir e mover, Enter ou espaço para escolher, Esc para fechar, Home e End para o primeiro e o último. A mudança vale logo para toda a interface, Guia incluído, e fica neste dispositivo (o telemóvel tem a sua escolha).'],
      ['Cambiare il tema: nella barra in basso, a destra, l’icona del tema (luna = scuro, sole = chiaro, cerchio mezzo pieno = automatico). Ogni clic passa al successivo, nell’ordine scuro, chiaro, automatico; «automatico» segue il tema di Windows e cambia con lui. Di fabbrica è scuro. La stessa scelta c’è in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (voce «[[ap.theme]]»), dove trovi anche «[[ap.contrast]]» e le dimensioni del testo. Sul telefono il tema sta in alto, a destra, nella barra del telecomando.', 'Change the theme: in the bottom bar, on the right, the theme icon (moon = dark, sun = light, half-filled circle = automatic). Each click moves to the next one, in the order dark, light, automatic; “automatic” follows the Windows theme and changes with it. By default it is dark. The same choice is in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (item “[[ap.theme]]”), where you also find “[[ap.contrast]]” and the text sizes. On the phone the theme is at the top right, in the remote-control bar.', 'Design wechseln: in der unteren Leiste, rechts, das Design-Symbol (Mond = dunkel, Sonne = hell, halb gefüllter Kreis = automatisch). Jeder Klick springt zum nächsten, in der Reihenfolge dunkel, hell, automatisch; „automatisch“ folgt dem Windows-Design und wechselt mit ihm. Ab Werk ist es dunkel. Dieselbe Wahl gibt es unter [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (Eintrag „[[ap.theme]]“), wo du auch „[[ap.contrast]]“ und die Textgrößen findest. Auf dem Telefon sitzt das Design oben rechts in der Fernbedienungsleiste.', 'Changer le thème : dans la barre du bas, à droite, l’icône du thème (lune = sombre, soleil = clair, cercle à moitié plein = automatique). Chaque clic passe au suivant, dans l’ordre sombre, clair, automatique ; « automatique » suit le thème de Windows et change avec lui. Par défaut c’est sombre. Le même choix existe dans [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (entrée « [[ap.theme]] »), où tu trouves aussi « [[ap.contrast]] » et les tailles du texte. Sur le téléphone, le thème est en haut à droite, dans la barre de la télécommande.', 'Cambiar el tema: en la barra inferior, a la derecha, el icono del tema (luna = oscuro, sol = claro, círculo medio lleno = automático). Cada clic pasa al siguiente, en el orden oscuro, claro, automático; «automático» sigue el tema de Windows y cambia con él. De serie es oscuro. La misma elección está en [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (opción «[[ap.theme]]»), donde también encuentras «[[ap.contrast]]» y el tamaño del texto. En el teléfono el tema está arriba, a la derecha, en la barra del mando a distancia.', 'Mudar o tema: na barra de baixo, à direita, o ícone do tema (lua = escuro, sol = claro, círculo meio cheio = automático). Cada clique passa ao seguinte, pela ordem escuro, claro, automático; «automático» segue o tema do Windows e muda com ele. De origem é escuro. A mesma escolha existe em [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] (entrada «[[ap.theme]]»), onde encontras também «[[ap.contrast]]» e os tamanhos do texto. No telemóvel o tema está em cima, à direita, na barra do telecomando.'],
      ['Accendere gli avvisi sonori: nella barra in basso clicca l’altoparlante. Barrato = spento (di fabbrica); con le onde = acceso. Appena acceso, il cursore accanto regola il volume generale (da 0 a 100%, di fabbrica 50%); da spento il cursore è bloccato. Il primo clic serve anche a far sbloccare l’audio al browser.', 'Turn on the sound alerts: in the bottom bar click the speaker. Crossed out = off (the default); with waves = on. As soon as it is on, the slider next to it sets the general volume (from 0 to 100%, 50% by default); when off the slider is locked. The first click also lets the browser unlock the audio.', 'Tonhinweise einschalten: Klicke in der unteren Leiste auf den Lautsprecher. Durchgestrichen = aus (ab Werk); mit Wellen = an. Sobald er an ist, regelt der Regler daneben die Gesamtlautstärke (von 0 bis 100 %, ab Werk 50 %); ist er aus, ist der Regler gesperrt. Der erste Klick dient auch dazu, dass der Browser den Ton freigibt.', 'Activer les alertes sonores : dans la barre du bas, clique sur le haut-parleur. Barré = éteint (par défaut) ; avec des ondes = allumé. Dès qu’il est allumé, le curseur à côté règle le volume général (de 0 à 100 %, 50 % par défaut) ; éteint, le curseur est bloqué. Le premier clic sert aussi à faire débloquer l’audio par le navigateur.', 'Activar los avisos sonoros: en la barra inferior haz clic en el altavoz. Tachado = apagado (de serie); con ondas = encendido. Nada más encenderlo, el cursor de al lado regula el volumen general (de 0 a 100%, de serie 50%); apagado el cursor está bloqueado. El primer clic sirve también para que el navegador desbloquee el audio.', 'Ligar os avisos sonoros: na barra de baixo clica no altifalante. Riscado = desligado (de origem); com ondas = ligado. Assim que o ligas, o cursor ao lado regula o volume geral (de 0 a 100%, de origem 50%); desligado o cursor fica bloqueado. O primeiro clique serve também para o navegador desbloquear o áudio.'],
      ['Quale suono per quale evento (chiamata verso di me, DXCC nuovo, QSO a log…), la voce e i tuoi file WAV o MP3, il silenzio mentre trasmetti: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (vedi «Suoni» e «Voce e file propri per gli avvisi»). Gli avvisi a comparsa sono in «Messaggi a comparsa».', 'Which sound for which event (call to me, new DXCC, QSO logged…), the voice and your own WAV or MP3 files, silence while you transmit: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (see “Sounds” and “Voice and your own files for alerts”). The pop-up alerts are in “Pop-up messages”.', 'Welcher Ton für welches Ereignis (Anruf an mich, neues DXCC, QSO im Log …), die Stimme und deine eigenen WAV- oder MP3-Dateien, die Stille während des Sendens: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (siehe „Töne“ und „Stimme und eigene Dateien für Hinweise“). Die Hinweise, die von selbst erscheinen, stehen unter „Einblendungen“.', 'Quel son pour quel événement (appel vers moi, nouveau DXCC, QSO enregistré…), la voix et tes fichiers WAV ou MP3, le silence pendant que tu émets : [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (voir « Sons » et « Voix et fichiers perso pour les alertes »). Les alertes qui s’affichent sont dans « Messages éphémères ».', 'Qué sonido para qué evento (llamada hacia mí, DXCC nuevo, QSO al log…), la voz y tus archivos WAV o MP3, el silencio mientras transmites: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (mira «Sonidos» y «Voz y archivos propios para los avisos»). Los avisos emergentes están en «Mensajes emergentes».', 'Que som para que evento (chamada para mim, DXCC novo, QSO no log…), a voz e os teus ficheiros WAV ou MP3, o silêncio enquanto transmites: [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] (vê «Sons» e «Voz e ficheiros próprios para os alertas»). Os avisos temporários estão em «Mensagens temporárias».'],
    ],
  },
  {
    id: 'p-diag',
    title: ['Gli avvisi di diagnosi in basso a destra', 'The diagnostic alerts at the bottom right', 'Die Diagnosehinweise unten rechts', 'Les alertes de diagnostic en bas à droite', 'Los avisos de diagnóstico abajo a la derecha', 'Os avisos de diagnóstico em baixo à direita'],
    text: ['Quando qualcosa nella stazione non va compaiono piccole schede in basso a destra, dalla più grave (rosso) alla più lieve (azzurro, solo informazione). Spariscono da sole quando il problema passa. Nei primi 20 secondi dopo l’apertura non si mostra niente: la radio e l’audio si stanno ancora accendendo. Ogni scheda ha la × per chiuderla (resta chiusa finché non cambia il problema) e, dove serve, il pulsante «[[diag.fix]]» che apre la pagina delle impostazioni giusta.', 'When something in the station is wrong, small cards appear at the bottom right, from the most serious (red) to the mildest (light blue, information only). They disappear by themselves when the problem goes away. In the first 20 seconds after opening nothing is shown: the radio and the audio are still starting up. Each card has a × to close it (it stays closed until the problem changes) and, where needed, the “[[diag.fix]]” button that opens the right settings page.', 'Wenn in der Station etwas nicht stimmt, erscheinen unten rechts kleine Karten, vom schwersten (rot) bis zum leichtesten (hellblau, nur Information). Sie verschwinden von selbst, wenn das Problem vorbei ist. In den ersten 20 Sekunden nach dem Öffnen wird nichts angezeigt: Funkgerät und Audio fahren noch hoch. Jede Karte hat das × zum Schließen (sie bleibt zu, bis sich das Problem ändert) und, wo es nötig ist, die Schaltfläche „[[diag.fix]]“, die die richtige Einstellungsseite öffnet.', 'Quand quelque chose ne va pas dans la station, de petites cartes apparaissent en bas à droite, de la plus grave (rouge) à la plus légère (bleu clair, simple information). Elles disparaissent toutes seules quand le problème passe. Pendant les 20 premières secondes après l’ouverture, rien ne s’affiche : la radio et l’audio sont encore en train de démarrer. Chaque carte a la × pour la fermer (elle reste fermée tant que le problème ne change pas) et, quand il le faut, le bouton « [[diag.fix]] » qui ouvre la bonne page des réglages.', 'Cuando algo de la estación no va bien aparecen pequeñas fichas abajo a la derecha, de la más grave (rojo) a la más leve (azul, solo información). Desaparecen solas cuando el problema pasa. En los primeros 20 segundos tras la apertura no se muestra nada: la radio y el audio aún se están encendiendo. Cada ficha tiene la × para cerrarla (se queda cerrada hasta que cambia el problema) y, donde hace falta, el botón «[[diag.fix]]» que abre la página de ajustes correcta.', 'Quando algo na estação não está bem aparecem pequenos cartões em baixo à direita, do mais grave (vermelho) ao mais leve (azul, só informação). Desaparecem sozinhos quando o problema passa. Nos primeiros 20 segundos depois da abertura não se mostra nada: o rádio e o áudio ainda estão a arrancar. Cada cartão tem o × para o fechar (fica fechado até o problema mudar) e, onde é preciso, o botão «[[diag.fix]]» que abre a página de definições certa.'],
    steps: [
      ['Orologio del PC fuori di tot millisecondi: giallo sopra il 4% del periodo (600 ms in FT8), rosso sopra l’8%. «[[diag.fix]]» apre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].', 'PC clock off by so many milliseconds: yellow above 4% of the period (600 ms in FT8), red above 8%. “[[diag.fix]]” opens [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].', 'PC-Uhr um so viele Millisekunden daneben: gelb über 4 % des Durchgangs (600 ms in FT8), rot über 8 %. „[[diag.fix]]“ öffnet [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].', 'Horloge du PC décalée de tant de millisecondes : jaune au-dessus de 4 % de la période (600 ms en FT8), rouge au-dessus de 8 %. « [[diag.fix]] » ouvre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].', 'Reloj del PC desfasado tantos milisegundos: amarillo por encima del 4% del periodo (600 ms en FT8), rojo por encima del 8%. «[[diag.fix]]» abre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].', 'Relógio do PC fora por tantos milissegundos: amarelo acima de 4% do período (600 ms em FT8), vermelho acima de 8%. «[[diag.fix]]» abre [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]].'],
      ['Manca il tuo nominativo: senza, Aurora non sa quali messaggi sono per te. «[[diag.fix]]» apre [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].', 'Your callsign is missing: without it, Aurora does not know which messages are for you. “[[diag.fix]]” opens [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].', 'Dein Rufzeichen fehlt: Ohne es weiß Aurora nicht, welche Nachrichten für dich sind. „[[diag.fix]]“ öffnet [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].', 'Ton indicatif manque : sans lui, Aurora ne sait pas quels messages sont pour toi. « [[diag.fix]] » ouvre [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].', 'Falta tu indicativo: sin él, Aurora no sabe qué mensajes son para ti. «[[diag.fix]]» abre [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].', 'Falta o teu indicativo: sem ele, a Aurora não sabe que mensagens são para ti. «[[diag.fix]]» abre [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].'],
      ['Ingresso audio saturo (rosso), muto (giallo) o debole (azzurro): sistema il volume di registrazione di Windows, il cavo o il dispositivo scelto; accanto al cursore «Rx» c’è anche «[[rxl.auto]]» che regola da solo (vedi «I livelli Rx e Pwr»).', 'Audio input saturated (red), silent (yellow) or weak (light blue): fix the Windows recording volume, the cable or the chosen device; next to the “Rx” slider there is also “[[rxl.auto]]” which adjusts it by itself (see “The Rx and Pwr levels”).', 'Audioeingang übersteuert (rot), stumm (gelb) oder schwach (hellblau): Stelle die Aufnahmelautstärke von Windows, das Kabel oder das gewählte Gerät ein; neben dem Regler „Rx“ gibt es auch „[[rxl.auto]]“, das von selbst regelt (siehe „Die Pegel Rx und Pwr“).', 'Entrée audio saturée (rouge), muette (jaune) ou faible (bleu clair) : règle le volume d’enregistrement de Windows, le câble ou l’appareil choisi ; à côté du curseur « Rx » il y a aussi « [[rxl.auto]] » qui règle tout seul (voir « Les niveaux Rx et Pwr »).', 'Entrada de audio saturada (rojo), muda (amarillo) o débil (azul): arregla el volumen de grabación de Windows, el cable o el dispositivo elegido; junto al cursor «Rx» también está «[[rxl.auto]]», que regula solo (mira «Los niveles Rx y Pwr»).', 'Entrada de áudio saturada (vermelho), muda (amarelo) ou fraca (azul): acerta o volume de gravação do Windows, o cabo ou o dispositivo escolhido; ao lado do cursor «Rx» há também «[[rxl.auto]]» que regula sozinho (vê «Os níveis Rx e Pwr»).'],
      ['L’audio perde blocchi: il pulsante «[[diag.howto]]» apre una scheda con i controlli da fare in ordine (cavo USB, risparmio energetico USB, programmi pesanti). «[[diag.fix]]» porta alla pagina [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].', 'The audio drops blocks: the “[[diag.howto]]” button opens a card with the checks to make in order (USB cable, USB power saving, heavy programs). “[[diag.fix]]” takes you to the [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]] page.', 'Das Audio verliert Blöcke: Die Schaltfläche „[[diag.howto]]“ öffnet eine Karte mit den Prüfungen in der richtigen Reihenfolge (USB-Kabel, USB-Energiesparen, schwere Programme). „[[diag.fix]]“ führt zur Seite [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].', 'L’audio perd des blocs : le bouton « [[diag.howto]] » ouvre une carte avec les contrôles à faire dans l’ordre (câble USB, économie d’énergie USB, programmes lourds). « [[diag.fix]] » mène à la page [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].', 'El audio pierde bloques: el botón «[[diag.howto]]» abre una ficha con las comprobaciones que hay que hacer en orden (cable USB, ahorro de energía USB, programas pesados). «[[diag.fix]]» lleva a la página [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].', 'O áudio perde blocos: o botão «[[diag.howto]]» abre um cartão com as verificações a fazer por ordem (cabo USB, poupança de energia USB, programas pesados). «[[diag.fix]]» leva à página [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.audio]].'],
      ['La scheda audio scelta o l’uscita audio per trasmettere non ci sono più (radio spenta, cavo USB staccato): accendi la radio, Aurora la riprende da sola.', 'The chosen sound card or the audio output for transmitting is gone (radio off, USB cable unplugged): turn the radio on, Aurora picks it up again by itself.', 'Die gewählte Soundkarte oder der Audioausgang zum Senden ist nicht mehr da (Funkgerät aus, USB-Kabel abgezogen): Schalte das Funkgerät ein, Aurora nimmt es von selbst wieder auf.', 'La carte son choisie ou la sortie audio pour émettre n’existent plus (radio éteinte, câble USB débranché) : allume la radio, Aurora la reprend toute seule.', 'La tarjeta de sonido elegida o la salida de audio para transmitir ya no están (radio apagada, cable USB desconectado): enciende la radio, Aurora la recupera sola.', 'A placa de som escolhida ou a saída de áudio para transmitir já não existem (rádio desligado, cabo USB desligado): liga o rádio, a Aurora retoma-a sozinha.'],
      ['Nessun messaggio decodificato da alcuni minuti (dopo 3 di silenzio, azzurro): banda chiusa oppure ricezione ferma, controlla [[ctl.monitor]] e l’audio.', 'No message decoded for a few minutes (after 3 of silence, light blue): the band is closed or reception is stopped, check [[ctl.monitor]] and the audio.', 'Seit einigen Minuten keine Nachricht dekodiert (nach 3 Minuten Stille, hellblau): Das Band ist zu oder der Empfang steht, prüfe [[ctl.monitor]] und das Audio.', 'Aucun message décodé depuis quelques minutes (après 3 de silence, bleu clair) : bande fermée ou réception arrêtée, vérifie [[ctl.monitor]] et l’audio.', 'Ningún mensaje decodificado desde hace algunos minutos (tras 3 de silencio, azul): banda cerrada o recepción parada, comprueba [[ctl.monitor]] y el audio.', 'Nenhuma mensagem descodificada há alguns minutos (depois de 3 de silêncio, azul): banda fechada ou receção parada, verifica [[ctl.monitor]] e o áudio.'],
      ['Problemi di trasmissione: «non puoi trasmettere perché la radio non è collegata» (CAT non configurato), «stai trasmettendo senza una radio» (il PTT non viene comandato, va bene solo con il VOX), «la radio non è andata in trasmissione» (con il motivo; vedi «Il PTT non parte»), «la radio è ripartita con la potenza al tot%» (su alcune radio si regola solo con la manopola RF PWR), «OmniRig non risponde», «la radio non si collega» (porta occupata). I pulsanti «[[diag.fix]]» portano a [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].', 'Transmission problems: “you can’t transmit because the radio is not connected” (CAT not set up), “you are transmitting without a radio” (the PTT is not controlled, fine only with VOX), “the radio did not go into transmit” (with the reason; see “The PTT does not key”), “the radio restarted with power at x%” (on some radios it is set only with the RF PWR knob), “OmniRig is not answering”, “the radio does not connect” (port busy). The “[[diag.fix]]” buttons lead to [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].', 'Sendeprobleme: „Du kannst nicht senden, weil das Funkgerät nicht verbunden ist“ (CAT nicht eingerichtet), „Du sendest ohne verbundenes Funkgerät“ (das PTT wird nicht geschaltet, nur mit VOX in Ordnung), „Das Funkgerät ist nicht auf Senden gegangen“ (mit dem Grund; siehe „Das PTT schaltet nicht“), „Das Funkgerät startete mit x % Leistung“ (bei manchen Funkgeräten lässt sie sich nur mit dem Knopf RF PWR einstellen), „OmniRig antwortet nicht“, „Das Funkgerät verbindet sich nicht“ (Anschluss belegt). Die Schaltflächen „[[diag.fix]]“ führen zu [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].', 'Problèmes d’émission : « tu ne peux pas émettre parce que la radio n’est pas connectée » (CAT non configuré), « tu émets sans radio » (le PTT n’est pas piloté, ça va seulement avec le VOX), « la radio n’est pas passée en émission » (avec le motif ; voir « Le PTT ne part pas »), « la radio est repartie avec la puissance à tant % » (sur certaines radios elle se règle seulement avec le bouton RF PWR), « OmniRig ne répond pas », « la radio ne se connecte pas » (port occupé). Les boutons « [[diag.fix]] » mènent à [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].', 'Problemas de transmisión: «no puedes transmitir porque la radio no está conectada» (CAT sin configurar), «estás transmitiendo sin radio» (el PTT no se controla, solo vale con el VOX), «la radio no ha pasado a transmisión» (con el motivo; mira «El PTT no sale»), «la radio ha vuelto a arrancar con la potencia al tot%» (en algunas radios solo se regula con la rueda RF PWR), «OmniRig no responde», «la radio no se conecta» (puerto ocupado). Los botones «[[diag.fix]]» llevan a [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].', 'Problemas de transmissão: «não podes transmitir porque o rádio não está ligado» (CAT não configurado), «estás a transmitir sem um rádio» (o PTT não é comandado, só serve com o VOX), «o rádio não passou a transmitir» (com o motivo; vê «O PTT não arranca»), «o rádio voltou a arrancar com a potência a tanto%» (em alguns rádios regula-se só com o botão RF PWR), «o OmniRig não responde», «o rádio não se liga» (porta ocupada). Os botões «[[diag.fix]]» levam a [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].'],
      ['Il PC decodifica troppo lentamente: la scheda dice quanti secondi per periodo e propone due pulsanti, «[[diag.slow_pc.to2]]» o «[[diag.slow_pc.to1]]», che cambiano subito la profondità di decodifica (vale dal periodo dopo), più «[[diag.slow_pc.setting]]» per aprire l’impostazione. Se succede spesso il PC è sotto i requisiti (vedi «Che computer serve»).', 'The PC decodes too slowly: the card says how many seconds per period and offers two buttons, “[[diag.slow_pc.to2]]” or “[[diag.slow_pc.to1]]”, which change the decoding depth right away (it applies from the next period), plus “[[diag.slow_pc.setting]]” to open the setting. If it happens often, the PC is below the requirements (see “Which computer you need”).', 'Der PC dekodiert zu langsam: Die Karte sagt, wie viele Sekunden pro Durchgang, und bietet zwei Schaltflächen an, „[[diag.slow_pc.to2]]“ oder „[[diag.slow_pc.to1]]“, die sofort die Dekodiertiefe ändern (gilt ab dem nächsten Durchgang), dazu „[[diag.slow_pc.setting]]“, um die Einstellung zu öffnen. Passiert es oft, liegt der PC unter den Anforderungen (siehe „Welcher Computer nötig ist“).', 'Le PC décode trop lentement : la carte dit combien de secondes par période et propose deux boutons, « [[diag.slow_pc.to2]] » ou « [[diag.slow_pc.to1]] », qui changent tout de suite la profondeur de décodage (valable à partir de la période suivante), plus « [[diag.slow_pc.setting]] » pour ouvrir le réglage. Si cela arrive souvent, le PC est en dessous de la configuration requise (voir « Quel ordinateur faut-il »).', 'El PC decodifica demasiado despacio: la ficha dice cuántos segundos por periodo y propone dos botones, «[[diag.slow_pc.to2]]» o «[[diag.slow_pc.to1]]», que cambian al momento la profundidad de decodificación (vale desde el periodo siguiente), más «[[diag.slow_pc.setting]]» para abrir el ajuste. Si ocurre a menudo, el PC está por debajo de los requisitos (mira «Qué ordenador hace falta»).', 'O PC descodifica devagar demais: o cartão diz quantos segundos por período e propõe dois botões, «[[diag.slow_pc.to2]]» ou «[[diag.slow_pc.to1]]», que mudam logo a profundidade de descodificação (vale a partir do período seguinte), mais «[[diag.slow_pc.setting]]» para abrir a definição. Se acontecer com frequência o PC está abaixo dos requisitos (vê «Que computador é preciso»).'],
      ['Contest: la banda o il modo non sono ammessi dal regolamento, oppure un nominativo composto non permette i messaggi di contest. Il link porta alla pagina [[nav.contest]].', 'Contest: the band or the mode is not allowed by the rules, or a compound callsign does not allow contest messages. The link leads to the [[nav.contest]] page.', 'Contest: Band oder Betriebsart sind laut Regelwerk nicht erlaubt, oder ein zusammengesetztes Rufzeichen lässt keine Contest-Nachrichten zu. Der Link führt zur Seite [[nav.contest]].', 'Contest : la bande ou le mode ne sont pas admis par le règlement, ou un indicatif composé ne permet pas les messages de contest. Le lien mène à la page [[nav.contest]].', 'Concurso: la banda o el modo no los admite el reglamento, o un indicativo compuesto no permite los mensajes de concurso. El enlace lleva a la página [[nav.contest]].', 'Concurso: a banda ou o modo não são permitidos pelo regulamento, ou um indicativo composto não permite as mensagens de concurso. A ligação leva à página [[nav.contest]].'],
    ],
    tip: ['Gli avvisi di diagnosi restano al massimo 10 minuti dalla loro ultima conferma; se li chiudi e il problema è lo stesso non tornano.', 'Diagnostic alerts stay at most 10 minutes from their last confirmation; if you close them and the problem is the same, they do not come back.', 'Diagnosehinweise bleiben höchstens 10 Minuten ab ihrer letzten Bestätigung; schließt du sie und das Problem ist dasselbe, kommen sie nicht zurück.', 'Les alertes de diagnostic restent au maximum 10 minutes depuis leur dernière confirmation ; si tu les fermes et que le problème est le même, elles ne reviennent pas.', 'Los avisos de diagnóstico se quedan como máximo 10 minutos desde su última confirmación; si los cierras y el problema es el mismo, no vuelven.', 'Os avisos de diagnóstico ficam no máximo 10 minutos desde a sua última confirmação; se os fechares e o problema for o mesmo não voltam.'],
  },
  {
    id: 'p-newdx',
    title: ['DXCC nuovo e stazione desiderata: gli avvisi in evidenza', 'New DXCC and wanted station: the highlighted alerts', 'Neues DXCC und Wunschstation: die auffälligen Hinweise', 'Nouveau DXCC et station recherchée : les alertes bien visibles', 'DXCC nuevo y estación deseada: los avisos destacados', 'DXCC novo e estação desejada: os avisos em destaque'],
    text: ['Due avvisi si fanno notare più degli altri: la scheda del DXCC nuovo, che lampeggia in alto a destra, e la barra della lista dei desiderati, in cima alla pagina.', 'Two alerts stand out more than the others: the new-DXCC card, which flashes at the top right, and the wanted-list bar, at the top of the page.', 'Zwei Hinweise fallen mehr auf als die anderen: die Karte für ein neues DXCC, die oben rechts blinkt, und die Leiste der Wunschliste, ganz oben auf der Seite.', 'Deux alertes se font remarquer plus que les autres : la carte du nouveau DXCC, qui clignote en haut à droite, et la barre de la liste des recherchées, en haut de la page.', 'Dos avisos destacan más que los demás: la ficha del DXCC nuevo, que parpadea arriba a la derecha, y la barra de la lista de deseadas, en lo alto de la página.', 'Dois avisos fazem-se notar mais do que os outros: o cartão do DXCC novo, que pisca em cima à direita, e a barra da lista dos desejados, no topo da página.'],
    steps: [
      ['La scheda lampeggiante in alto a destra mostra la bandiera, il nominativo, il paese e l’ora UTC dell’ultima ricezione («[[newdx.last]]», con il segnale in dB) di una stazione che è un paese nuovo («[[newdx.dxcc]]») o nuovo sulla banda («[[newdx.band]]»). L’ora si aggiorna a ogni sua trasmissione; la scheda sparisce 10 minuti dopo l’ultima volta che la senti. Si vedono al massimo 4 schede.', 'The flashing card at the top right shows the flag, the callsign, the country and the UTC time of the last reception (“[[newdx.last]]”, with the signal in dB) of a station that is a new country (“[[newdx.dxcc]]”) or new on the band (“[[newdx.band]]”). The time updates at each of its transmissions; the card disappears 10 minutes after the last time you hear it. At most 4 cards are shown.', 'Die blinkende Karte oben rechts zeigt die Flagge, das Rufzeichen, das Land und die UTC-Zeit des letzten Empfangs („[[newdx.last]]“, mit dem Signal in dB) einer Station, die ein neues Land („[[newdx.dxcc]]“) oder neu auf dem Band („[[newdx.band]]“) ist. Die Zeit aktualisiert sich bei jeder ihrer Sendungen; die Karte verschwindet 10 Minuten nach dem letzten Mal, dass du sie hörst. Es sind höchstens 4 Karten zu sehen.', 'La carte clignotante en haut à droite montre le drapeau, l’indicatif, le pays et l’heure UTC de la dernière réception (« [[newdx.last]] », avec le signal en dB) d’une station qui est un nouveau pays (« [[newdx.dxcc]] ») ou nouveau sur la bande (« [[newdx.band]] »). L’heure se met à jour à chacune de ses émissions ; la carte disparaît 10 minutes après la dernière fois que tu l’entends. On voit au maximum 4 cartes.', 'La ficha parpadeante de arriba a la derecha muestra la bandera, el indicativo, el país y la hora UTC de la última recepción («[[newdx.last]]», con la señal en dB) de una estación que es un país nuevo («[[newdx.dxcc]]») o nuevo en la banda («[[newdx.band]]»). La hora se actualiza en cada transmisión suya; la ficha desaparece 10 minutos después de la última vez que la oyes. Se ven como máximo 4 fichas.', 'O cartão intermitente em cima à direita mostra a bandeira, o indicativo, o país e a hora UTC da última receção («[[newdx.last]]», com o sinal em dB) de uma estação que é um país novo («[[newdx.dxcc]]») ou novo na banda («[[newdx.band]]»). A hora atualiza-se a cada transmissão dela; o cartão desaparece 10 minutos depois da última vez que a ouves. Veem-se no máximo 4 cartões.'],
      ['Doppio clic sulla scheda: rispondi a quella stazione. La × la chiude (non torna finché Aurora resta aperta); ogni stazione compare una sola volta, con il suo suono.', 'Double-click the card: you reply to that station. The × closes it (it does not come back while Aurora stays open); each station appears only once, with its sound.', 'Doppelklick auf die Karte: Du antwortest dieser Station. Das × schließt sie (sie kommt nicht wieder, solange Aurora offen bleibt); jede Station erscheint nur einmal, mit ihrem Ton.', 'Double-clic sur la carte : tu réponds à cette station. La × la ferme (elle ne revient pas tant qu’Aurora reste ouverte) ; chaque station n’apparaît qu’une seule fois, avec son son.', 'Doble clic en la ficha: respondes a esa estación. La × la cierra (no vuelve mientras Aurora siga abierta); cada estación aparece una sola vez, con su sonido.', 'Duplo clique no cartão: respondes a essa estação. O × fecha-o (não volta enquanto a Aurora estiver aberta); cada estação aparece uma só vez, com o seu som.'],
      ['Come spegnerla (la domanda più frequente): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], riquadro «[[not2.grpAlerts]]». «[[not2.popNew]]» accende e spegne la scheda per un paese nuovo, «[[not2.popNewBand]]» quella per un paese nuovo sulla banda: togli la spunta a tutte e due e la scheda non compare più. «[[not2.popPos]]» sceglie l’angolo o il bordo dello schermo dove compare; il suo suono si sceglie in «[[not2.popSound]]».', 'How to turn it off (the most frequent question): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], box “[[not2.grpAlerts]]”. “[[not2.popNew]]” turns the card for a new country on and off, “[[not2.popNewBand]]” the one for a new country on the band: clear both check marks and the card no longer appears. “[[not2.popPos]]” chooses the corner or edge of the screen where it appears; its sound is chosen in “[[not2.popSound]]”.', 'So schaltest du sie aus (die häufigste Frage): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], Feld „[[not2.grpAlerts]]“. „[[not2.popNew]]“ schaltet die Karte für ein neues Land ein und aus, „[[not2.popNewBand]]“ die für ein neues Land auf dem Band: Nimm bei beiden das Häkchen weg, und die Karte erscheint nicht mehr. „[[not2.popPos]]“ wählt die Ecke oder den Rand des Bildschirms, wo sie erscheint; ihr Ton wird in „[[not2.popSound]]“ gewählt.', 'Comment l’éteindre (la question la plus fréquente) : [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], encadré « [[not2.grpAlerts]] ». « [[not2.popNew]] » allume et éteint la carte pour un nouveau pays, « [[not2.popNewBand]] » celle pour un nouveau pays sur la bande : décoche les deux et la carte n’apparaît plus. « [[not2.popPos]] » choisit le coin ou le bord de l’écran où elle apparaît ; son son se choisit dans « [[not2.popSound]] ».', 'Cómo apagarla (la pregunta más frecuente): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], recuadro «[[not2.grpAlerts]]». «[[not2.popNew]]» enciende y apaga la ficha de un país nuevo, «[[not2.popNewBand]]» la de un país nuevo en la banda: quita la marca a las dos y la ficha no aparece más. «[[not2.popPos]]» elige la esquina o el borde de la pantalla donde aparece; su sonido se elige en «[[not2.popSound]]».', 'Como o desligar (a pergunta mais frequente): [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]], quadro «[[not2.grpAlerts]]». «[[not2.popNew]]» liga e desliga o cartão para um país novo, «[[not2.popNewBand]]» o do país novo na banda: tira o visto a ambas e o cartão deixa de aparecer. «[[not2.popPos]]» escolhe o canto ou a margem do ecrã onde aparece; o seu som escolhe-se em «[[not2.popSound]]».'],
      ['La barra della lista dei desiderati (stella ★): una striscia in cima alla pagina con «nominativo desiderata (motivo)» [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] o [[wish.reason.grid]], la sorgente ([[wish.source.decode]] o [[wish.source.cluster]]), il messaggio, la banda e il segnale. Con uno spot del cluster c’è anche «[[wish.tune]]» che porta la radio sulla frequenza dello spot; «[[wish.close]]» la chiude. Si toglie da sola dopo 90 secondi e suona se gli avvisi sonori sono accesi (e, se il browser lo consente, manda una notifica).', 'The wanted-list bar (star ★): a strip at the top of the page with “callsign wanted (reason)” [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] or [[wish.reason.grid]], the source ([[wish.source.decode]] or [[wish.source.cluster]]), the message, the band and the signal. With a cluster spot there is also “[[wish.tune]]” which moves the radio to the spot frequency; “[[wish.close]]” closes it. It goes away by itself after 90 seconds and plays a sound if the sound alerts are on (and, if the browser allows it, sends a notification).', 'Die Leiste der Wunschliste (Stern ★): ein Streifen oben auf der Seite mit „Rufzeichen Wunschstation (Grund)“ [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] oder [[wish.reason.grid]], der Quelle ([[wish.source.decode]] oder [[wish.source.cluster]]), der Nachricht, dem Band und dem Signal. Bei einem Cluster-Spot gibt es auch „[[wish.tune]]“, das das Funkgerät auf die Frequenz des Spots stellt; „[[wish.close]]“ schließt sie. Sie verschwindet nach 90 Sekunden von selbst und spielt einen Ton, wenn die Tonhinweise an sind (und, wenn der Browser es erlaubt, schickt sie eine Benachrichtigung).', 'La barre de la liste des recherchées (étoile ★) : une bande en haut de la page avec « indicatif recherchée (motif) » [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] ou [[wish.reason.grid]], la source ([[wish.source.decode]] ou [[wish.source.cluster]]), le message, la bande et le signal. Avec un spot du cluster il y a aussi « [[wish.tune]] » qui place la radio sur la fréquence du spot ; « [[wish.close]] » la ferme. Elle s’enlève toute seule après 90 secondes et sonne si les alertes sonores sont allumées (et, si le navigateur l’autorise, envoie une notification).', 'La barra de la lista de deseadas (estrella ★): una franja en lo alto de la página con «indicativo deseada (motivo)» [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] o [[wish.reason.grid]], la fuente ([[wish.source.decode]] o [[wish.source.cluster]]), el mensaje, la banda y la señal. Con un spot del cluster también está «[[wish.tune]]», que lleva la radio a la frecuencia del spot; «[[wish.close]]» la cierra. Se quita sola a los 90 segundos y suena si los avisos sonoros están encendidos (y, si el navegador lo permite, manda una notificación).', 'A barra da lista dos desejados (estrela ★): uma faixa no topo da página com «indicativo desejado (motivo)» [[wish.reason.call]], [[wish.reason.prefix]], [[wish.reason.country]] ou [[wish.reason.grid]], a origem ([[wish.source.decode]] ou [[wish.source.cluster]]), a mensagem, a banda e o sinal. Com um spot do cluster há também «[[wish.tune]]» que leva o rádio para a frequência do spot; «[[wish.close]]» fecha-a. Retira-se sozinha ao fim de 90 segundos e toca se os avisos sonoros estiverem ligados (e, se o navegador o permitir, envia uma notificação).'],
      ['Cosa è «desiderata» si scrive in [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (nominativi, prefissi, paesi, griglie, bande, pausa tra due avvisi per la stessa stazione, avviso sul telefono).', 'What counts as “wanted” is written in [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (callsigns, prefixes, countries, grid squares, bands, pause between two alerts for the same station, alert on the phone).', 'Was als Wunschstation gilt, schreibst du unter [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (Rufzeichen, Präfixe, Länder, Locator, Bänder, Pause zwischen zwei Hinweisen für dieselbe Station, Hinweis auf dem Telefon).', 'Ce qui est « recherché » s’écrit dans [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (indicatifs, préfixes, pays, grilles, bandes, pause entre deux alertes pour la même station, alerte sur le téléphone).', 'Qué es «deseada» se escribe en [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (indicativos, prefijos, países, cuadrículas, bandas, pausa entre dos avisos de la misma estación, aviso en el teléfono).', 'O que é «desejado» escreve-se em [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]] (indicativos, prefixos, países, quadrículas, bandas, pausa entre dois avisos para a mesma estação, aviso no telemóvel).'],
    ],
  },
  {
    id: 'p-updbar',
    title: ['L’aggiornamento nella barra', 'The update notice in the bar', 'Das Update in der Leiste', 'La mise à jour dans la barre', 'La actualización en la barra', 'A atualização na barra'],
    text: ['Quando esce una versione nuova di Aurora, a destra della barra in alto compare una piccola icona (freccia verso il basso con un pallino). Sul PC Aurora scarica la versione in sottofondo e ne controlla la firma.', 'When a new version of Aurora comes out, a small icon appears on the right of the top bar (a down arrow with a dot). On the PC, Aurora downloads the version in the background and checks its signature.', 'Wenn eine neue Version von Aurora erscheint, taucht rechts in der oberen Leiste ein kleines Symbol auf (Pfeil nach unten mit einem Punkt). Auf dem PC lädt Aurora die Version im Hintergrund herunter und prüft ihre Signatur.', 'Quand une nouvelle version d’Aurora sort, à droite de la barre du haut apparaît une petite icône (flèche vers le bas avec un point). Sur le PC, Aurora télécharge la version en arrière-plan et en contrôle la signature.', 'Cuando sale una versión nueva de Aurora, a la derecha de la barra superior aparece un pequeño icono (flecha hacia abajo con un punto). En el PC Aurora descarga la versión en segundo plano y comprueba su firma.', 'Quando sai uma versão nova da Aurora, à direita da barra de cima aparece um pequeno ícone (seta para baixo com uma bolinha). No PC a Aurora transfere a versão em segundo plano e verifica a assinatura.'],
    steps: [
      ['Clic sull’icona: si apre un riquadro con «Nuova versione di Aurora: X (in uso Y)». Il pulsante «[[upd.install]]» scarica (se serve) e installa: Aurora si chiude e si riapre da sola. «[[upd.open]]» apre le note e il download sul sito. «[[upd.later]]» nasconde l’avviso fino alla versione dopo.', 'Click the icon: a box opens with “New Aurora version: X (in use Y)”. The “[[upd.install]]” button downloads (if needed) and installs: Aurora closes and reopens by itself. “[[upd.open]]” opens the notes and the download on the website. “[[upd.later]]” hides the notice until the next version.', 'Klick auf das Symbol: Es öffnet sich ein Feld mit „Neue Aurora-Version: X (verwendet Y)“. Die Schaltfläche „[[upd.install]]“ lädt (falls nötig) herunter und installiert: Aurora schließt sich und öffnet sich von selbst wieder. „[[upd.open]]“ öffnet die Hinweise und den Download auf der Website. „[[upd.later]]“ blendet den Hinweis bis zur nächsten Version aus.', 'Clic sur l’icône : un encadré s’ouvre avec « Nouvelle version d’Aurora : X (utilisée Y) ». Le bouton « [[upd.install]] » télécharge (si besoin) et installe : Aurora se ferme et se rouvre toute seule. « [[upd.open]] » ouvre les notes et le téléchargement sur le site. « [[upd.later]] » masque l’alerte jusqu’à la version suivante.', 'Clic en el icono: se abre un recuadro con «Nueva versión de Aurora: X (en uso Y)». El botón «[[upd.install]]» descarga (si hace falta) e instala: Aurora se cierra y se vuelve a abrir sola. «[[upd.open]]» abre las notas y la descarga en el sitio. «[[upd.later]]» oculta el aviso hasta la versión siguiente.', 'Clica no ícone: abre-se um quadro com «Nova versão da Aurora: X (em uso Y)». O botão «[[upd.install]]» transfere (se for preciso) e instala: a Aurora fecha-se e volta a abrir-se sozinha. «[[upd.open]]» abre as notas e a transferência no site. «[[upd.later]]» esconde o aviso até à versão seguinte.'],
      ['Quando il PC ha già scaricato la versione, al posto dell’icona c’è una barretta arancio con l’avanzamento («Controllo…», «Installo…»); a fine scarico dice «[[upd.strip.ready]]» con il pulsante «[[upd.strip.install]]» (un clic e installa). Se il download non riesce compare «[[upd.strip.failed]]» con «[[upd.strip.retry]]».', 'When the PC has already downloaded the version, instead of the icon there is a small orange bar with the progress (“Checking…”, “Installing…”); when the download ends it says “[[upd.strip.ready]]” with the “[[upd.strip.install]]” button (one click and it installs). If the download fails, “[[upd.strip.failed]]” appears with “[[upd.strip.retry]]”.', 'Hat der PC die Version schon heruntergeladen, steht anstelle des Symbols ein kleiner oranger Balken mit dem Fortschritt („Prüfung…“, „Installiere…“); am Ende des Downloads zeigt er „[[upd.strip.ready]]“ mit der Schaltfläche „[[upd.strip.install]]“ (ein Klick und es installiert). Schlägt der Download fehl, erscheint „[[upd.strip.failed]]“ mit „[[upd.strip.retry]]“.', 'Quand le PC a déjà téléchargé la version, à la place de l’icône il y a une petite barre orange avec l’avancement (« Contrôle… », « Installation… ») ; à la fin du téléchargement elle dit « [[upd.strip.ready]] » avec le bouton « [[upd.strip.install]] » (un clic et elle s’installe). Si le téléchargement échoue, « [[upd.strip.failed]] » apparaît avec « [[upd.strip.retry]] ».', 'Cuando el PC ya ha descargado la versión, en lugar del icono hay una barrita naranja con el avance («Comprobando…», «Instalando…»); al terminar la descarga dice «[[upd.strip.ready]]» con el botón «[[upd.strip.install]]» (un clic e instala). Si la descarga falla aparece «[[upd.strip.failed]]» con «[[upd.strip.retry]]».', 'Quando o PC já transferiu a versão, no lugar do ícone há uma barrinha laranja com o progresso («A verificar…», «A instalar…»); no fim da transferência diz «[[upd.strip.ready]]» com o botão «[[upd.strip.install]]» (um clique e instala). Se a transferência falhar aparece «[[upd.strip.failed]]» com «[[upd.strip.retry]]».'],
      ['Se l’installazione non parte compare un messaggio con il motivo e il link per scaricare l’installatore a mano.', 'If the installation does not start, a message appears with the reason and the link to download the installer by hand.', 'Startet die Installation nicht, erscheint eine Meldung mit dem Grund und dem Link, um den Installer von Hand herunterzuladen.', 'Si l’installation ne démarre pas, un message apparaît avec le motif et le lien pour télécharger l’installateur à la main.', 'Si la instalación no arranca aparece un mensaje con el motivo y el enlace para descargar el instalador a mano.', 'Se a instalação não arrancar aparece uma mensagem com o motivo e a ligação para transferires o instalador à mão.'],
      ['Al primo avvio dopo un aggiornamento, o con una versione molto vecchia, può comparire la locandina «[[upd.poster.available]]»: «[[upd.poster.install]]» aggiorna subito (parte da sola dopo pochi secondi, «[[upd.poster.cancel]]» la ferma), «[[upd.later]]» la rimanda, «[[upd.poster.news]]» apre le novità.', 'At the first start after an update, or with a very old version, the “[[upd.poster.available]]” poster may appear: “[[upd.poster.install]]” updates right away (it starts by itself after a few seconds, “[[upd.poster.cancel]]” stops it), “[[upd.later]]” postpones it, “[[upd.poster.news]]” opens the news.', 'Beim ersten Start nach einem Update oder mit einer sehr alten Version kann das Plakat „[[upd.poster.available]]“ erscheinen: „[[upd.poster.install]]“ aktualisiert sofort (startet nach wenigen Sekunden von selbst, „[[upd.poster.cancel]]“ stoppt es), „[[upd.later]]“ verschiebt es, „[[upd.poster.news]]“ öffnet die Neuigkeiten.', 'Au premier démarrage après une mise à jour, ou avec une version très ancienne, l’affiche « [[upd.poster.available]] » peut apparaître : « [[upd.poster.install]] » met à jour tout de suite (elle démarre toute seule après quelques secondes, « [[upd.poster.cancel]] » l’arrête), « [[upd.later]] » la remet à plus tard, « [[upd.poster.news]] » ouvre les nouveautés.', 'En el primer arranque tras una actualización, o con una versión muy antigua, puede aparecer el cartel «[[upd.poster.available]]»: «[[upd.poster.install]]» actualiza al momento (arranca sola tras unos segundos, «[[upd.poster.cancel]]» la detiene), «[[upd.later]]» la pospone, «[[upd.poster.news]]» abre las novedades.', 'No primeiro arranque depois de uma atualização, ou com uma versão muito antiga, pode aparecer o cartaz «[[upd.poster.available]]»: «[[upd.poster.install]]» atualiza logo (arranca sozinho passados poucos segundos, «[[upd.poster.cancel]]» pára-o), «[[upd.later]]» adia-o, «[[upd.poster.news]]» abre as novidades.'],
      ['Controllo, intervallo, versioni di prova e repository si impostano in [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].', 'Checking, interval, test versions and repository are set in [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].', 'Prüfung, Intervall, Testversionen und Repository stellst du unter [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]] ein.', 'Le contrôle, l’intervalle, les versions d’essai et le dépôt se règlent dans [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].', 'La comprobación, el intervalo, las versiones de prueba y el repositorio se ajustan en [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].', 'Verificação, intervalo, versões de teste e repositório definem-se em [[nav.settings]] › [[sw.sec.access]] › [[tab.updates]].'],
    ],
  },
  {
    id: 'p-notices',
    title: ['Avvisi e cartoline che compaiono da soli', 'Alerts and cards that pop up on their own', 'Hinweise und Karten, die von selbst erscheinen', 'Alertes et cartes qui apparaissent toutes seules', 'Avisos y tarjetas que aparecen solos', 'Avisos e cartões que aparecem sozinhos'],
    text: ['Oltre agli avvisi di diagnosi (vedi «Gli avvisi di diagnosi in basso a destra») Aurora mostra pochi altri avvisi, quasi sempre una volta sola.', 'Besides the diagnostic alerts (see “The diagnostic alerts at the bottom right”), Aurora shows a few other notices, almost always only once.', 'Neben den Diagnosehinweisen (siehe „Die Diagnosehinweise unten rechts“) zeigt Aurora wenige weitere Hinweise, fast immer nur einmal.', 'En plus des alertes de diagnostic (voir « Les alertes de diagnostic en bas à droite »), Aurora montre quelques autres alertes, presque toujours une seule fois.', 'Además de los avisos de diagnóstico (mira «Los avisos de diagnóstico abajo a la derecha») Aurora muestra pocos avisos más, casi siempre una sola vez.', 'Além dos avisos de diagnóstico (vê «Os avisos de diagnóstico em baixo à direita») a Aurora mostra poucos outros avisos, quase sempre uma só vez.'],
    steps: [
      ['Al primo avvio una striscia dice che gli errori anonimi vengono mandati a chi sviluppa Aurora, senza nominativo, locatore, messaggi né password, e che puoi spegnerlo quando vuoi. Il collegamento «[[rep.notice.open]]» porta alla pagina giusta; «[[rep.notice.ok]]» chiude la striscia per sempre. Gli interruttori sono in [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (vedi «Rapporti degli errori»).', 'At the first start a strip says that anonymous errors are sent to the people who develop Aurora, without callsign, locator, messages or passwords, and that you can turn it off whenever you like. The “[[rep.notice.open]]” link leads to the right page; “[[rep.notice.ok]]” closes the strip for good. The switches are in [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (see “Error reports”).', 'Beim ersten Start sagt ein Streifen, dass anonyme Fehler an die Entwickler von Aurora geschickt werden, ohne Rufzeichen, Locator, Nachrichten und Passwörter, und dass du es jederzeit ausschalten kannst. Der Link „[[rep.notice.open]]“ führt zur richtigen Seite; „[[rep.notice.ok]]“ schließt den Streifen für immer. Die Schalter stehen unter [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (siehe „Fehlerberichte“).', 'Au premier démarrage, une bande dit que les erreurs anonymes sont envoyées à qui développe Aurora, sans indicatif, locator, messages ni mots de passe, et que tu peux le désactiver quand tu veux. Le lien « [[rep.notice.open]] » mène à la bonne page ; « [[rep.notice.ok]] » ferme la bande pour toujours. Les interrupteurs sont dans [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (voir « Rapports d’erreurs »).', 'En el primer arranque una franja dice que los errores anónimos se mandan a quien desarrolla Aurora, sin indicativo, localizador, mensajes ni contraseñas, y que puedes apagarlo cuando quieras. El enlace «[[rep.notice.open]]» lleva a la página correcta; «[[rep.notice.ok]]» cierra la franja para siempre. Los interruptores están en [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (mira «Informes de errores»).', 'No primeiro arranque uma faixa diz que os erros anónimos são enviados a quem desenvolve a Aurora, sem indicativo, locator, mensagens nem palavras-passe, e que o podes desligar quando quiseres. A ligação «[[rep.notice.open]]» leva à página certa; «[[rep.notice.ok]]» fecha a faixa para sempre. Os interruptores estão em [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] (vê «Relatórios de erros»).'],
      ['Se Aurora si era chiusa da sola e hai chiesto di essere avvisato, al riavvio compare la finestra «[[rep.crashTitle]]» con tre pulsanti: «[[rep.crashSend]]» (manda il rapporto), «[[rep.show]]» (mostra cosa verrebbe mandato prima di decidere) e «[[rep.no]]».', 'If Aurora closed by itself and you asked to be notified, at restart the “[[rep.crashTitle]]” window appears with three buttons: “[[rep.crashSend]]” (sends the report), “[[rep.show]]” (shows what would be sent before you decide) and “[[rep.no]]”.', 'Hat sich Aurora von selbst geschlossen und du hast darum gebeten, benachrichtigt zu werden, erscheint beim Neustart das Fenster „[[rep.crashTitle]]“ mit drei Schaltflächen: „[[rep.crashSend]]“ (sendet den Bericht), „[[rep.show]]“ (zeigt, was gesendet würde, bevor du entscheidest) und „[[rep.no]]“.', 'Si Aurora s’était fermée toute seule et que tu as demandé à être prévenu, au redémarrage la fenêtre « [[rep.crashTitle]] » apparaît avec trois boutons : « [[rep.crashSend]] » (envoie le rapport), « [[rep.show]] » (montre ce qui serait envoyé avant de décider) et « [[rep.no]] ».', 'Si Aurora se había cerrado sola y has pedido que te avisen, al reiniciar aparece la ventana «[[rep.crashTitle]]» con tres botones: «[[rep.crashSend]]» (manda el informe), «[[rep.show]]» (muestra qué se mandaría antes de decidir) y «[[rep.no]]».', 'Se a Aurora se tinha fechado sozinha e pediste para seres avisado, no reinício aparece a janela «[[rep.crashTitle]]» com três botões: «[[rep.crashSend]]» (envia o relatório), «[[rep.show]]» (mostra o que seria enviado antes de decidires) e «[[rep.no]]».'],
      ['Di tanto in tanto arriva una cartolina in basso a destra, con un suono, scritta da chi sviluppa Aurora (auguri, avvisi di servizio, aggiornamenti importanti). Arriva una volta sola per messaggio, nella lingua di Aurora, anche con Aurora chiusa tramite l’agente nel tray; il pulsante «[[agent.msg.open]]» apre il collegamento del messaggio, se c’è. Non si può spegnere.', 'From time to time a card arrives at the bottom right, with a sound, written by the people who develop Aurora (greetings, service notices, important updates). It arrives only once per message, in Aurora’s language, even with Aurora closed through the agent in the tray; the “[[agent.msg.open]]” button opens the message link, if there is one. It cannot be turned off.', 'Von Zeit zu Zeit kommt eine Karte unten rechts, mit einem Ton, geschrieben von den Entwicklern von Aurora (Glückwünsche, Dienstmitteilungen, wichtige Updates). Sie kommt nur einmal pro Nachricht, in der Sprache von Aurora, auch bei geschlossenem Aurora über den Agenten im Tray; die Schaltfläche „[[agent.msg.open]]“ öffnet den Link der Nachricht, falls es einen gibt. Sie lässt sich nicht ausschalten.', 'De temps en temps arrive une carte en bas à droite, avec un son, écrite par qui développe Aurora (vœux, avis de service, mises à jour importantes). Elle arrive une seule fois par message, dans la langue d’Aurora, même avec Aurora fermée grâce à l’agent dans la zone de notification ; le bouton « [[agent.msg.open]] » ouvre le lien du message, s’il y en a un. On ne peut pas la désactiver.', 'De vez en cuando llega una tarjeta abajo a la derecha, con un sonido, escrita por quien desarrolla Aurora (felicitaciones, avisos de servicio, actualizaciones importantes). Llega una sola vez por mensaje, en el idioma de Aurora, incluso con Aurora cerrada gracias al agente de la bandeja del sistema; el botón «[[agent.msg.open]]» abre el enlace del mensaje, si lo hay. No se puede apagar.', 'De vez em quando chega um cartão em baixo à direita, com um som, escrito por quem desenvolve a Aurora (votos, avisos de serviço, atualizações importantes). Chega uma só vez por mensagem, no idioma da Aurora, mesmo com a Aurora fechada através do agente na área de notificação; o botão «[[agent.msg.open]]» abre a ligação da mensagem, se existir. Não se pode desligar.'],
      ['Quando esce una versione nuova compare l’icona nella barra o la locandina (vedi «L’aggiornamento nella barra»). Prima del primo QSO, se il log è vuoto, il pannello Log propone di importarne uno o di collegare un log esterno.', 'When a new version comes out, the icon appears in the bar or the poster (see “The update notice in the bar”). Before the first QSO, if the log is empty, the Log panel offers to import one or to connect an external log.', 'Erscheint eine neue Version, kommt das Symbol in der Leiste oder das Plakat (siehe „Das Update in der Leiste“). Vor dem ersten QSO, wenn das Log leer ist, schlägt das Log-Feld vor, eines zu importieren oder ein externes Log zu verbinden.', 'Quand une nouvelle version sort, l’icône dans la barre ou l’affiche apparaît (voir « La mise à jour dans la barre »). Avant le premier QSO, si le log est vide, le panneau Journal propose d’en importer un ou de connecter un log externe.', 'Cuando sale una versión nueva aparece el icono en la barra o el cartel (mira «La actualización en la barra»). Antes del primer QSO, si el log está vacío, el panel Log propone importar uno o conectar un log externo.', 'Quando sai uma versão nova aparece o ícone na barra ou o cartaz (vê «A atualização na barra»). Antes do primeiro QSO, se o log estiver vazio, o painel Log propõe importar um ou ligar um log externo.'],
    ],
  },
  {
    id: 'p-bandsopen',
    title: ['Il blocco «Bande aperte»', 'The “Open bands” block', 'Der Block „Offene Bänder“', 'Le bloc « Bandes ouvertes »', 'El bloque «Bandas abiertas»', 'O bloco «Bandas abertas»'],
    text: ['Il blocco [[bands.title]] della pagina Stazione dice quali bande sono aperte e chi ti sente. Servono i servizi online: spenti, il blocco lo dice e il pulsante «[[prop.settings]]» porta a [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], dove si accendono la propagazione e PSK Reporter.', 'The [[bands.title]] block of the Station page tells you which bands are open and who hears you. It needs the online services: when off, the block says so and the “[[prop.settings]]” button leads to [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], where propagation and PSK Reporter are turned on.', 'Der Block [[bands.title]] der Seite Station sagt, welche Bänder offen sind und wer dich hört. Du brauchst die Online-Dienste: Sind sie aus, sagt es der Block, und die Schaltfläche „[[prop.settings]]“ führt zu [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], wo Ausbreitung und PSK Reporter eingeschaltet werden.', 'Le bloc [[bands.title]] de la page Station dit quelles bandes sont ouvertes et qui t’entend. Il faut les services en ligne : éteints, le bloc le dit et le bouton « [[prop.settings]] » mène à [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], où l’on active la propagation et PSK Reporter.', 'El bloque [[bands.title]] de la página Estación dice qué bandas están abiertas y quién te oye. Hacen falta los servicios en línea: apagados, el bloque lo dice y el botón «[[prop.settings]]» lleva a [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], donde se encienden la propagación y PSK Reporter.', 'O bloco [[bands.title]] da página Estação diz que bandas estão abertas e quem te ouve. São precisos os serviços online: desligados, o bloco di-lo e o botão «[[prop.settings]]» leva a [[nav.settings]] › [[sw.fam.log]] › [[tab.online]], onde se ligam a propagação e o PSK Reporter.'],
    steps: [
      ['In alto la tabella delle condizioni, la stessa della pagina [[nav.propagation]]: quattro gruppi di bande (80-40 m, 30-20 m, 17-15 m, 12-10 m), una colonna per il giorno e una per la notte, con tre barrette e il giudizio («[[prop.cond.Good]]», «[[prop.cond.Fair]]», «[[prop.cond.Poor]]»). La colonna di adesso è segnata «[[prop.here]]» e il gruppo su cui è la radio «[[prop.tuned]]».', 'At the top the table of conditions, the same as on the [[nav.propagation]] page: four band groups (80-40 m, 30-20 m, 17-15 m, 12-10 m), a column for day and one for night, with three small bars and the verdict (“[[prop.cond.Good]]”, “[[prop.cond.Fair]]”, “[[prop.cond.Poor]]”). The current column is marked “[[prop.here]]” and the group the radio is on “[[prop.tuned]]”.', 'Oben die Tabelle der Bedingungen, dieselbe wie auf der Seite [[nav.propagation]]: vier Bandgruppen (80-40 m, 30-20 m, 17-15 m, 12-10 m), eine Spalte für den Tag und eine für die Nacht, mit drei Balken und der Beurteilung („[[prop.cond.Good]]“, „[[prop.cond.Fair]]“, „[[prop.cond.Poor]]“). Die aktuelle Spalte ist mit „[[prop.here]]“ markiert und die Gruppe, auf der das Funkgerät steht, mit „[[prop.tuned]]“.', 'En haut le tableau des conditions, le même que dans la page [[nav.propagation]] : quatre groupes de bandes (80-40 m, 30-20 m, 17-15 m, 12-10 m), une colonne pour le jour et une pour la nuit, avec trois petites barres et le jugement (« [[prop.cond.Good]] », « [[prop.cond.Fair]] », « [[prop.cond.Poor]] »). La colonne de maintenant est marquée « [[prop.here]] » et le groupe sur lequel est la radio « [[prop.tuned]] ».', 'Arriba la tabla de las condiciones, la misma de la página [[nav.propagation]]: cuatro grupos de bandas (80-40 m, 30-20 m, 17-15 m, 12-10 m), una columna para el día y otra para la noche, con tres barritas y el juicio («[[prop.cond.Good]]», «[[prop.cond.Fair]]», «[[prop.cond.Poor]]»). La columna de ahora está marcada «[[prop.here]]» y el grupo en que está la radio «[[prop.tuned]]».', 'Em cima a tabela das condições, a mesma da página [[nav.propagation]]: quatro grupos de bandas (80-40 m, 30-20 m, 17-15 m, 12-10 m), uma coluna para o dia e uma para a noite, com três barrinhas e o juízo («[[prop.cond.Good]]», «[[prop.cond.Fair]]», «[[prop.cond.Poor]]»). A coluna de agora está assinalada «[[prop.here]]» e o grupo em que está o rádio «[[prop.tuned]]».'],
      ['Sotto, «[[bands.far3]]»: le stazioni più lontane che hanno ricevuto il tuo segnale (PSK Reporter), una per riga, con bandiera, nominativo, paese, banda, distanza e segnale in dB. Ne compaiono tre; la quarta e la quinta solo se c’è posto. Senza ricezioni la riga dice «[[bands.noPsk]]».', 'Below, “[[bands.far3]]”: the farthest stations that have received your signal (PSK Reporter), one per row, with flag, callsign, country, band, distance and signal in dB. Three appear; the fourth and the fifth only if there is room. With no receptions the row says “[[bands.noPsk]]”.', 'Darunter „[[bands.far3]]“: die am weitesten entfernten Stationen, die dein Signal empfangen haben (PSK Reporter), eine pro Zeile, mit Flagge, Rufzeichen, Land, Band, Entfernung und Signal in dB. Drei erscheinen; die vierte und fünfte nur, wenn Platz ist. Ohne Empfänge sagt die Zeile „[[bands.noPsk]]“.', 'Dessous, « [[bands.far3]] » : les stations les plus lointaines qui ont reçu ton signal (PSK Reporter), une par ligne, avec drapeau, indicatif, pays, bande, distance et signal en dB. Trois apparaissent ; la quatrième et la cinquième seulement s’il y a de la place. Sans réceptions, la ligne dit « [[bands.noPsk]] ».', 'Debajo, «[[bands.far3]]»: las estaciones más lejanas que han recibido tu señal (PSK Reporter), una por fila, con bandera, indicativo, país, banda, distancia y señal en dB. Aparecen tres; la cuarta y la quinta solo si hay sitio. Sin recepciones la fila dice «[[bands.noPsk]]».', 'Por baixo, «[[bands.far3]]»: as estações mais distantes que receberam o teu sinal (PSK Reporter), uma por linha, com bandeira, indicativo, país, banda, distância e sinal em dB. Aparecem três; a quarta e a quinta só se houver lugar. Sem receções a linha diz «[[bands.noPsk]]».'],
      ['La distanza è in km o in miglia secondo le preferenze. Il blocco si aggiorna da solo ogni 10 secondi; le condizioni arrivano da N0NBH (hamqsl.com).', 'The distance is in km or in miles according to the preferences. The block updates by itself every 10 seconds; the conditions come from N0NBH (hamqsl.com).', 'Die Entfernung ist in km oder Meilen je nach Einstellung. Der Block aktualisiert sich alle 10 Sekunden von selbst; die Bedingungen kommen von N0NBH (hamqsl.com).', 'La distance est en km ou en miles selon les préférences. Le bloc se met à jour tout seul toutes les 10 secondes ; les conditions viennent de N0NBH (hamqsl.com).', 'La distancia está en km o en millas según las preferencias. El bloque se actualiza solo cada 10 segundos; las condiciones llegan de N0NBH (hamqsl.com).', 'A distância é em km ou em milhas conforme as preferências. O bloco atualiza-se sozinho a cada 10 segundos; as condições vêm do N0NBH (hamqsl.com).'],
    ],
  },
  {
    id: 'p-actband',
    title: ['Attività di banda: la barra del titolo e il Filtro', 'Band activity: the title bar and the Filter', 'Bandaktivität: Titelleiste und Filter', 'Activité de bande : la barre de titre et le Filtre', 'Actividad de banda: la barra del título y el Filtro', 'Atividade da banda: a barra do título e o Filtro'],
    text: ['Il pannello [[panel.all]] elenca tutti i messaggi decodificati sulla banda, i più recenti in cima. Nella barra del titolo ci sono tre pulsanti piccoli, poi il pulsante ⧉ per staccare il pannello (vedi «Finestre a parte e disposizione»).', 'The [[panel.all]] panel lists all the messages decoded on the band, the most recent on top. In the title bar there are three small buttons, then the ⧉ button to detach the panel (see “Separate windows and layout”).', 'Das Feld [[panel.all]] listet alle auf dem Band dekodierten Nachrichten auf, die neuesten oben. In der Titelleiste gibt es drei kleine Schaltflächen, dann die Schaltfläche ⧉, um das Feld abzulösen (siehe „Eigene Fenster und Anordnung“).', 'Le panneau [[panel.all]] liste tous les messages décodés sur la bande, les plus récents en haut. Dans la barre de titre il y a trois petits boutons, puis le bouton ⧉ pour détacher le panneau (voir « Fenêtres détachées et disposition »).', 'El panel [[panel.all]] lista todos los mensajes decodificados en la banda, los más recientes arriba. En la barra del título hay tres botones pequeños, y después el botón ⧉ para separar el panel (mira «Ventanas aparte y disposición»).', 'O painel [[panel.all]] lista todas as mensagens descodificadas na banda, as mais recentes em cima. Na barra do título há três botões pequenos, depois o botão ⧉ para destacar o painel (vê «Janelas à parte e disposição»).'],
    steps: [
      ['«[[bfl.button]]»: apre una fila di pillole sotto la barra del titolo, con cui scegli quali novità vedere. Quando ne hai scelte alcune, il pulsante si accende e porta il loro numero (per esempio «Filtro 3»). Un secondo clic chiude la fila senza togliere la scelta.', '“[[bfl.button]]”: opens a row of pills below the title bar, with which you choose which news items to see. When you have chosen some, the button lights up and shows their number (for example “Filter 3”). A second click closes the row without removing your choice.', '„[[bfl.button]]“: öffnet unter der Titelleiste eine Reihe von Schaltflächen, mit denen du wählst, welche Neuheiten du sehen willst. Hast du einige gewählt, leuchtet die Schaltfläche und zeigt ihre Anzahl (zum Beispiel „Filter 3“). Ein zweiter Klick schließt die Reihe, ohne die Auswahl aufzuheben.', '« [[bfl.button]] » : ouvre une rangée de pastilles sous la barre de titre, avec lesquelles tu choisis quelles nouveautés voir. Quand tu en as choisi quelques-unes, le bouton s’allume et porte leur nombre (par exemple « Filtre 3 »). Un deuxième clic ferme la rangée sans enlever le choix.', '«[[bfl.button]]»: abre una fila de píldoras bajo la barra del título, con las que eliges qué novedades ver. Cuando has elegido algunas, el botón se enciende y lleva su número (por ejemplo «Filtro 3»). Un segundo clic cierra la fila sin quitar la elección.', '«[[bfl.button]]»: abre uma fila de pílulas por baixo da barra do título, com que escolhes que novidades ver. Quando escolheste algumas, o botão acende-se e mostra o número delas (por exemplo «Filtro 3»). Um segundo clique fecha a fila sem tirar a escolha.'],
      ['La pillola «[[bfl.all]]» toglie il filtro (si vede tutto). Le altre sono i tipi di messaggio, con gli stessi nomi delle etichette colorate: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] e [[kind.new_state_band]] (gli stati degli USA). Più pillole accese = un messaggio passa se ha almeno una di quelle novità (logica «o»).', 'The “[[bfl.all]]” pill removes the filter (you see everything). The others are the message types, with the same names as the coloured labels: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] and [[kind.new_state_band]] (the US states). Several pills lit = a message passes if it has at least one of those news items (“or” logic).', 'Die Schaltfläche „[[bfl.all]]“ hebt den Filter auf (alles wird gezeigt). Die anderen sind die Nachrichtentypen, mit denselben Namen wie die farbigen Etiketten: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] und [[kind.new_state_band]] (die US-Staaten). Mehrere eingeschaltete Schaltflächen = eine Nachricht kommt durch, wenn sie mindestens eine dieser Neuheiten hat (Logik „oder“).', 'La pastille « [[bfl.all]] » enlève le filtre (on voit tout). Les autres sont les types de message, avec les mêmes noms que les étiquettes colorées : [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] et [[kind.new_state_band]] (les États des USA). Plusieurs pastilles allumées = un message passe s’il a au moins une de ces nouveautés (logique « ou »).', 'La píldora «[[bfl.all]]» quita el filtro (se ve todo). Las demás son los tipos de mensaje, con los mismos nombres que las etiquetas de colores: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] y [[kind.new_state_band]] (los estados de EE. UU.). Más píldoras encendidas = un mensaje pasa si tiene al menos una de esas novedades (lógica «o»).', 'A pílula «[[bfl.all]]» tira o filtro (vê-se tudo). As outras são os tipos de mensagem, com os mesmos nomes das etiquetas coloridas: [[kind.cq]], [[kind.new_dxcc]], [[kind.new_dxcc_band]], [[kind.new_zone]], [[kind.new_zone_band]], [[kind.new_itu]], [[kind.new_itu_band]], [[kind.new_grid]], [[kind.new_grid_band]], [[kind.new_px]], [[kind.new_px_band]], [[kind.new_call]], [[kind.new_call_band]], [[kind.worked_call]], [[kind.new_state]] e [[kind.new_state_band]] (os estados dos EUA). Mais pílulas acesas = uma mensagem passa se tiver pelo menos uma dessas novidades (lógica «ou»).'],
      ['Dopo il gruppo «[[bfl.except]]» ci sono quattro pillole che restringono quello che resta: «[[bfl.cqOnly]]» (solo i messaggi di chi chiama CQ), «[[bfl.rr73AsCq]]» (conta come CQ anche chi manda RR73), «[[bfl.hasGrid]]» (solo chi ha mandato il locatore) e «[[bfl.notMyCont]]» (nasconde le stazioni del tuo continente).', 'After the “[[bfl.except]]” group there are four pills that narrow down what is left: “[[bfl.cqOnly]]” (only messages from stations calling CQ), “[[bfl.rr73AsCq]]” (a station sending RR73 also counts as CQ), “[[bfl.hasGrid]]” (only stations that sent their locator) and “[[bfl.notMyCont]]” (hides the stations of your continent).', 'Nach der Gruppe „[[bfl.except]]“ gibt es vier Schaltflächen, die einschränken, was übrig bleibt: „[[bfl.cqOnly]]“ (nur die Nachrichten von Stationen, die CQ rufen), „[[bfl.rr73AsCq]]“ (auch wer RR73 sendet, zählt als CQ), „[[bfl.hasGrid]]“ (nur wer den Locator gesendet hat) und „[[bfl.notMyCont]]“ (blendet die Stationen deines Kontinents aus).', 'Après le groupe « [[bfl.except]] » il y a quatre pastilles qui restreignent ce qui reste : « [[bfl.cqOnly]] » (seulement les messages de ceux qui appellent CQ), « [[bfl.rr73AsCq]] » (compte comme CQ aussi celui qui envoie RR73), « [[bfl.hasGrid]] » (seulement ceux qui ont envoyé le locator) et « [[bfl.notMyCont]] » (cache les stations de ton continent).', 'Después del grupo «[[bfl.except]]» hay cuatro píldoras que restringen lo que queda: «[[bfl.cqOnly]]» (solo los mensajes de quien llama CQ), «[[bfl.rr73AsCq]]» (cuenta como CQ también quien manda RR73), «[[bfl.hasGrid]]» (solo quien ha mandado el localizador) y «[[bfl.notMyCont]]» (oculta las estaciones de tu continente).', 'Depois do grupo «[[bfl.except]]» há quatro pílulas que restringem o que sobra: «[[bfl.cqOnly]]» (só as mensagens de quem chama CQ), «[[bfl.rr73AsCq]]» (conta como CQ também quem envia RR73), «[[bfl.hasGrid]]» (só quem enviou o locator) e «[[bfl.notMyCont]]» (esconde as estações do teu continente).'],
      ['La scelta si salva da sola, vale anche per «[[panel.cq]]» e per le Automazioni (che rispondono solo alle stazioni che passano il filtro). Non cambia la decodifica: nasconde solo le righe.', 'Your choice is saved by itself, and it also applies to “[[panel.cq]]” and to the Automations (which reply only to the stations that pass the filter). It does not change the decoding: it only hides rows.', 'Die Auswahl speichert sich von selbst, gilt auch für „[[panel.cq]]“ und für die Automatiken (die nur Stationen antworten, die den Filter passieren). Sie ändert die Dekodierung nicht: Sie blendet nur die Zeilen aus.', 'Le choix s’enregistre tout seul, il vaut aussi pour « [[panel.cq]] » et pour les Automatisations (qui répondent seulement aux stations qui passent le filtre). Il ne change pas le décodage : il cache seulement les lignes.', 'La elección se guarda sola, vale también para «[[panel.cq]]» y para las Automatizaciones (que responden solo a las estaciones que pasan el filtro). No cambia la decodificación: solo oculta las filas.', 'A escolha guarda-se sozinha, vale também para «[[panel.cq]]» e para as Automações (que respondem só às estações que passam o filtro). Não muda a descodificação: esconde só as linhas.'],
      ['«[[list.clear]]»: svuota solo questo elenco; i messaggi che arrivano dopo compaiono di nuovo. L’altro elenco (Finestra RX) non cambia.', '“[[list.clear]]”: empties only this list; messages that arrive afterwards appear again. The other list (RX window) does not change.', '„[[list.clear]]“: leert nur diese Liste; Nachrichten, die danach eintreffen, erscheinen wieder. Die andere Liste (RX-Fenster) ändert sich nicht.', '« [[list.clear]] » : vide seulement cette liste ; les messages qui arrivent ensuite apparaissent de nouveau. L’autre liste (Fenêtre RX) ne change pas.', '«[[list.clear]]»: vacía solo esta lista; los mensajes que llegan después aparecen de nuevo. La otra lista (Ventana RX) no cambia.', '«[[list.clear]]»: esvazia só esta lista; as mensagens que chegam depois aparecem de novo. A outra lista (Janela RX) não muda.'],
      ['«[[list.bottom.off]]» / «[[list.bottom.on]]»: dove compaiono i messaggi nuovi. Con la freccia ↑ il più recente è in cima e l’elenco scorre verso il basso; con ↓ il più recente è l’ultima riga. Ogni elenco ricorda la sua scelta.', '“[[list.bottom.off]]” / “[[list.bottom.on]]”: where new messages appear. With the ↑ arrow the most recent is on top and the list scrolls downwards; with ↓ the most recent is the last row. Each list remembers its own choice.', '„[[list.bottom.off]]“ / „[[list.bottom.on]]“: wo die neuen Nachrichten erscheinen. Mit dem Pfeil ↑ steht die neueste oben und die Liste läuft nach unten; mit ↓ ist die neueste die letzte Zeile. Jede Liste merkt sich ihre Wahl.', '« [[list.bottom.off]] » / « [[list.bottom.on]] » : l’endroit où apparaissent les nouveaux messages. Avec la flèche ↑ le plus récent est en haut et la liste défile vers le bas ; avec ↓ le plus récent est la dernière ligne. Chaque liste retient son choix.', '«[[list.bottom.off]]» / «[[list.bottom.on]]»: dónde aparecen los mensajes nuevos. Con la flecha ↑ el más reciente está arriba y la lista se desplaza hacia abajo; con ↓ el más reciente es la última fila. Cada lista recuerda su elección.', '«[[list.bottom.off]]» / «[[list.bottom.on]]»: onde aparecem as mensagens novas. Com a seta ↑ a mais recente fica em cima e a lista desce para baixo; com ↓ a mais recente é a última linha. Cada lista lembra-se da sua escolha.'],
      ['Gli altri filtri di questo pannello (segnale minimo, distanza minima e massima, nascondi i messaggi a me, nascondi le mie trasmissioni, solo certe bande) sono nel riquadro «[[bfl.title]]» di [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; lì scrivi anche i nominativi sempre o mai mostrati e il bypass che mostra tutto per un momento (vedi «Filtri per nominativo, prefisso e già collegati»).', 'The other filters of this panel (minimum signal, minimum and maximum distance, hide messages to me, hide my transmissions, only certain bands) are in the “[[bfl.title]]” box of [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; there you also write the callsigns to always or never show and the bypass that shows everything for a moment (see “Filters by callsign, prefix and already worked”).', 'Die anderen Filter dieses Feldes (Mindestsignal, Mindest- und Höchstentfernung, Nachrichten an mich ausblenden, eigene Sendungen ausblenden, nur bestimmte Bänder) sind im Feld „[[bfl.title]]“ unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; dort schreibst du auch die Rufzeichen, die immer oder nie gezeigt werden, und den Bypass, der für einen Moment alles zeigt (siehe „Filter nach Rufzeichen, Präfix und schon gearbeitet“).', 'Les autres filtres de ce panneau (signal minimum, distance minimale et maximale, cacher les messages pour moi, cacher mes émissions, seulement certaines bandes) sont dans l’encadré « [[bfl.title]] » de [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] ; là tu écris aussi les indicatifs toujours ou jamais montrés et le bypass qui montre tout un instant (voir « Filtres par indicatif, préfixe et déjà contactés »).', 'Los demás filtros de este panel (señal mínima, distancia mínima y máxima, ocultar los mensajes para mí, ocultar mis transmisiones, solo ciertas bandas) están en el recuadro «[[bfl.title]]» de [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; ahí escribes también los indicativos siempre o nunca mostrados y el bypass que lo muestra todo por un momento (mira «Filtros por indicativo, prefijo y ya contactados»).', 'Os outros filtros deste painel (sinal mínimo, distância mínima e máxima, esconder as mensagens para mim, esconder as minhas transmissões, só certas bandas) estão no quadro «[[bfl.title]]» de [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; aí escreves também os indicativos sempre ou nunca mostrados e o bypass que mostra tudo por um momento (vê «Filtros por indicativo, prefixo e já contactados»).'],
    ],
    tip: ['Se «Attività di banda» sembra vuota controlla subito la pillola «[[bfl.button]]»: con un numero accanto è attivo un filtro. Il messaggio «[[bfl.empty]]» lo conferma.', 'If “Band activity” seems empty, check the “[[bfl.button]]” pill right away: with a number next to it, a filter is active. The message “[[bfl.empty]]” confirms it.', 'Wirkt „Bandaktivität“ leer, prüfe gleich die Schaltfläche „[[bfl.button]]“: Mit einer Zahl daneben ist ein Filter aktiv. Die Meldung „[[bfl.empty]]“ bestätigt es.', 'Si « Activité de bande » semble vide, regarde d’abord la pastille « [[bfl.button]] » : avec un nombre à côté, un filtre est actif. Le message « [[bfl.empty]] » le confirme.', 'Si «Actividad de banda» parece vacía, comprueba enseguida la píldora «[[bfl.button]]»: con un número al lado hay un filtro activo. El mensaje «[[bfl.empty]]» lo confirma.', 'Se a «Atividade da banda» parecer vazia verifica logo a pílula «[[bfl.button]]»: com um número ao lado há um filtro ativo. A mensagem «[[bfl.empty]]» confirma-o.'],
  },
  {
    id: 'p-rows',
    title: ['Come si legge una riga dei messaggi', 'How to read a message row', 'So liest du eine Nachrichtenzeile', 'Comment lire une ligne de messages', 'Cómo se lee una fila de los mensajes', 'Como se lê uma linha das mensagens'],
    text: ['Le righe di Attività di banda e della Finestra RX hanno gli stessi segni. Quasi ogni colore ha un suggerimento: passa il mouse sulla riga.', 'The rows of Band activity and of the RX window have the same marks. Almost every colour has a hint: hover over the row.', 'Die Zeilen von Bandaktivität und RX-Fenster haben dieselben Zeichen. Fast jede Farbe hat einen Hinweis: Halte die Maus über die Zeile.', 'Les lignes d’Activité de bande et de la Fenêtre RX ont les mêmes signes. Presque chaque couleur a une info-bulle : passe la souris sur la ligne.', 'Las filas de Actividad de banda y de la Ventana RX tienen las mismas marcas. Casi cada color tiene una sugerencia: pasa el ratón por la fila.', 'As linhas da Atividade da banda e da Janela RX têm os mesmos sinais. Quase cada cor tem uma sugestão: passa o rato por cima da linha.'],
    steps: [
      ['Colonne, da sinistra: l’ora UTC (o l’età del messaggio, se la attivi in [[sw.pg.messages]]), il rapporto in dB, DT (lo scarto di tempo in secondi dal tuo orologio: vicino a zero va bene), la frequenza audio in Hz (solo in Attività di banda), il messaggio, la bandiera e il paese con distanza e azimut (se li accendi tra le preferenze), e infine l’etichetta colorata. Le righe Tx (le tue trasmissioni) hanno «Tx» al posto del rapporto e, se ripetute uguali, una sola riga con «×N».', 'Columns, from the left: the UTC time (or the age of the message, if you turn it on in [[sw.pg.messages]]), the report in dB, DT (the time offset in seconds from your clock: close to zero is fine), the audio frequency in Hz (only in Band activity), the message, the flag and the country with distance and bearing (if you turn them on in the preferences), and finally the coloured label. Tx rows (your own transmissions) have “Tx” in place of the report and, if repeated identically, a single row with “×N”.', 'Spalten, von links: die UTC-Zeit (oder das Alter der Nachricht, wenn du es in [[sw.pg.messages]] einschaltest), der Rapport in dB, DT (die Zeitabweichung in Sekunden zu deiner Uhr: nahe null ist gut), die Audiofrequenz in Hz (nur in Bandaktivität), die Nachricht, die Flagge und das Land mit Entfernung und Azimut (wenn du sie in den Einstellungen einschaltest), und schließlich das farbige Etikett. Die Tx-Zeilen (deine Sendungen) haben „Tx“ statt des Rapports und, wenn sie sich gleich wiederholen, nur eine Zeile mit „×N“.', 'Colonnes, de gauche à droite : l’heure UTC (ou l’âge du message, si tu l’actives dans [[sw.pg.messages]]), le report en dB, DT (l’écart de temps en secondes par rapport à ton horloge : près de zéro, c’est bon), la fréquence audio en Hz (seulement dans Activité de bande), le message, le drapeau et le pays avec la distance et l’azimut (si tu les actives dans les préférences), et enfin l’étiquette colorée. Les lignes Tx (tes émissions) ont « Tx » à la place du report et, si elles se répètent à l’identique, une seule ligne avec « ×N ».', 'Columnas, de izquierda a derecha: la hora UTC (o la edad del mensaje, si la activas en [[sw.pg.messages]]), el informe en dB, DT (el desfase de tiempo en segundos respecto a tu reloj: cerca de cero va bien), la frecuencia de audio en Hz (solo en Actividad de banda), el mensaje, la bandera y el país con distancia y acimut (si los enciendes en las preferencias), y por último la etiqueta de color. Las filas Tx (tus transmisiones) tienen «Tx» en lugar del informe y, si se repiten iguales, una sola fila con «×N».', 'Colunas, da esquerda: a hora UTC (ou a idade da mensagem, se a ativares em [[sw.pg.messages]]), o relatório em dB, DT (o desvio de tempo em segundos em relação ao teu relógio: perto de zero está bem), a frequência de áudio em Hz (só na Atividade da banda), a mensagem, a bandeira e o país com distância e azimute (se os ligares nas preferências) e, por fim, a etiqueta colorida. As linhas Tx (as tuas transmissões) têm «Tx» no lugar do relatório e, se repetidas iguais, uma só linha com «×N».'],
      ['In Attività di banda le colonne hanno i titoli e linee ben visibili, come nel DX Cluster: trascina un titolo per spostare la colonna, il suo bordo destro per allargarla (doppio clic sul bordo: si adatta al contenuto); tasto destro sui titoli: «[[cluster.cols.reset]]». Ordine e larghezze restano ricordati.', 'In Band activity the columns have headings and clearly visible lines, as in the DX Cluster: drag a heading to move the column, its right edge to widen it (double-click the edge: it fits the content); right-click the headings: “[[cluster.cols.reset]]”. Order and widths are remembered.', 'In Bandaktivität haben die Spalten Überschriften und gut sichtbare Linien, wie im DX-Cluster: Zieh eine Überschrift, um die Spalte zu verschieben, ihren rechten Rand, um sie zu verbreitern (Doppelklick auf den Rand: passt sich dem Inhalt an); Rechtsklick auf die Überschriften: „[[cluster.cols.reset]]“. Reihenfolge und Breiten bleiben gespeichert.', 'Dans Activité de bande les colonnes ont des titres et des lignes bien visibles, comme dans le DX Cluster : fais glisser un titre pour déplacer la colonne, son bord droit pour l’élargir (double-clic sur le bord : elle s’adapte au contenu) ; clic droit sur les titres : « [[cluster.cols.reset]] ». L’ordre et les largeurs sont mémorisés.', 'En Actividad de banda las columnas tienen títulos y líneas bien visibles, como en el DX Cluster: arrastra un título para mover la columna, su borde derecho para ensancharla (doble clic en el borde: se ajusta al contenido); clic derecho en los títulos: «[[cluster.cols.reset]]». El orden y los anchos se recuerdan.', 'Na Atividade da banda as colunas têm títulos e linhas bem visíveis, como no DX Cluster: arrasta um título para mover a coluna, o seu bordo direito para a alargar (duplo clique no bordo: ajusta-se ao conteúdo); clique direito nos títulos: «[[cluster.cols.reset]]». A ordem e as larguras ficam memorizadas.'],
      ['Etichetta colorata a destra: «[[tag.new_dxcc]]», «[[tag.new_dxcc_band]]», «[[tag.new_zone]]», «[[tag.new_zone_band]]», «[[tag.new_itu]]», «[[tag.new_itu_band]]», «[[tag.new_grid]]», «[[tag.new_grid_band]]», «[[tag.new_px]]», «[[tag.new_px_band]]», «[[tag.new_call]]», «[[tag.new_call_band]]», «[[tag.worked_call]]» e «[[tag.auto]]». Dicono cosa ha di speciale quella stazione per il tuo log; la barra colorata a sinistra della riga ha lo stesso colore. Il colore di ogni tipo si cambia in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Un colore più chiaro e a righe vuol dire «lavorato ma non confermato» (se hai acceso quella opzione).', 'Coloured label on the right: “[[tag.new_dxcc]]”, “[[tag.new_dxcc_band]]”, “[[tag.new_zone]]”, “[[tag.new_zone_band]]”, “[[tag.new_itu]]”, “[[tag.new_itu_band]]”, “[[tag.new_grid]]”, “[[tag.new_grid_band]]”, “[[tag.new_px]]”, “[[tag.new_px_band]]”, “[[tag.new_call]]”, “[[tag.new_call_band]]”, “[[tag.worked_call]]” and “[[tag.auto]]”. They tell you what is special about that station for your log; the coloured bar on the left of the row has the same colour. The colour of each type is changed in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. A lighter, striped colour means “worked but not confirmed” (if you turned that option on).', 'Farbiges Etikett rechts: „[[tag.new_dxcc]]“, „[[tag.new_dxcc_band]]“, „[[tag.new_zone]]“, „[[tag.new_zone_band]]“, „[[tag.new_itu]]“, „[[tag.new_itu_band]]“, „[[tag.new_grid]]“, „[[tag.new_grid_band]]“, „[[tag.new_px]]“, „[[tag.new_px_band]]“, „[[tag.new_call]]“, „[[tag.new_call_band]]“, „[[tag.worked_call]]“ und „[[tag.auto]]“. Sie sagen, was diese Station für dein Log Besonderes hat; der farbige Balken links in der Zeile hat dieselbe Farbe. Die Farbe jedes Typs änderst du unter [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Eine hellere, gestreifte Farbe bedeutet „gearbeitet, aber nicht bestätigt“ (wenn du diese Option eingeschaltet hast).', 'Étiquette colorée à droite : « [[tag.new_dxcc]] », « [[tag.new_dxcc_band]] », « [[tag.new_zone]] », « [[tag.new_zone_band]] », « [[tag.new_itu]] », « [[tag.new_itu_band]] », « [[tag.new_grid]] », « [[tag.new_grid_band]] », « [[tag.new_px]] », « [[tag.new_px_band]] », « [[tag.new_call]] », « [[tag.new_call_band]] », « [[tag.worked_call]] » et « [[tag.auto]] ». Elles disent ce que cette station a de spécial pour ton log ; la barre colorée à gauche de la ligne a la même couleur. La couleur de chaque type se change dans [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Une couleur plus claire et rayée veut dire « contacté mais non confirmé » (si tu as activé cette option).', 'Etiqueta de color a la derecha: «[[tag.new_dxcc]]», «[[tag.new_dxcc_band]]», «[[tag.new_zone]]», «[[tag.new_zone_band]]», «[[tag.new_itu]]», «[[tag.new_itu_band]]», «[[tag.new_grid]]», «[[tag.new_grid_band]]», «[[tag.new_px]]», «[[tag.new_px_band]]», «[[tag.new_call]]», «[[tag.new_call_band]]», «[[tag.worked_call]]» y «[[tag.auto]]». Dicen qué tiene de especial esa estación para tu log; la barra de color a la izquierda de la fila tiene el mismo color. El color de cada tipo se cambia en [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Un color más claro y a rayas vacías quiere decir «contactada pero no confirmada» (si has activado esa opción).', 'Etiqueta colorida à direita: «[[tag.new_dxcc]]», «[[tag.new_dxcc_band]]», «[[tag.new_zone]]», «[[tag.new_zone_band]]», «[[tag.new_itu]]», «[[tag.new_itu_band]]», «[[tag.new_grid]]», «[[tag.new_grid_band]]», «[[tag.new_px]]», «[[tag.new_px_band]]», «[[tag.new_call]]», «[[tag.new_call_band]]», «[[tag.worked_call]]» e «[[tag.auto]]». Dizem o que essa estação tem de especial para o teu log; a barra colorida à esquerda da linha tem a mesma cor. A cor de cada tipo muda-se em [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]]. Uma cor mais clara e às riscas quer dizer «contactado mas não confirmado» (se ligaste essa opção).'],
      ['Altre etichette: «IN CODA» seguito da un numero (la stazione è in coda, il numero è il suo posto) e «FOX» (una DXpedition in modo Fox/Hound).', 'Other labels: “Queue” followed by a number (the station is in the queue, the number is its place) and “Fox” (a DXpedition in Fox/Hound mode).', 'Weitere Etiketten: „WARTET“ gefolgt von einer Zahl (die Station ist in der Warteschlange, die Zahl ist ihr Platz) und „FOX“ (eine DXpedition im Fox/Hound-Betrieb).', 'Autres étiquettes : « FILE » suivie d’un nombre (la station est en file, le nombre est sa place) et « FOX » (une DXpédition en mode Fox/Hound).', 'Otras etiquetas: «EN COLA» seguido de un número (la estación está en cola, el número es su puesto) y «FOX» (una DXpedición en modo Fox/Hound).', 'Outras etiquetas: «NA FILA» seguido de um número (a estação está na fila, o número é o seu lugar) e «FOX» (uma DXpedição em modo Fox/Hound).'],
      ['Segni sulla riga: una striscia rossa sul bordo destro (il «segnalino») e il fondo evidenziato = quella stazione ti sta chiamando; la striscia (e il nominativo) diventa viola = ti ha risposto; riga barrata = stazione già collegata su questa banda e in questo modo (il modo di segnarla — barrato, sottolineato, colorato, nascosto — si sceglie in [[sw.tab.colors]]); la stazione che stai chiamando è evidenziata e resta ferma in cima, con il colore che cambia a ogni sua risposta (rapporto, R+rapporto, chiusura); la riga viola dei filtri = nominativo, prefisso o paese scelti in «[[fil.highlight]]»; un fondo particolare = stazione della tua lista dei desiderati; il pallino blu con un numero = in coda.', 'Marks on the row: a red strip on the right edge (the marker) and a highlighted background = that station is calling you; the strip (and the callsign) turns purple = it has answered you; struck-through row = station already worked on this band and in this mode (how to mark it — struck through, underlined, coloured, hidden — is chosen in [[sw.tab.colors]]); the station you are calling is highlighted and stays fixed at the top, with the colour changing at each of its replies (report, R+report, closing); the purple filter row = callsign, prefix or country chosen in “[[fil.highlight]]”; a special background = station of your wanted list; the blue dot with a number = in the queue.', 'Zeichen in der Zeile: ein roter Streifen am rechten Rand (die „Markierung“) und der hervorgehobene Hintergrund = diese Station ruft dich; der Streifen (und das Rufzeichen) wird violett = sie hat dir geantwortet; durchgestrichene Zeile = Station schon auf diesem Band und in dieser Betriebsart gearbeitet (die Art der Kennzeichnung — durchgestrichen, unterstrichen, farbig, ausgeblendet — wählst du unter [[sw.tab.colors]]); die Station, die du rufst, ist hervorgehoben und bleibt oben stehen, mit einer Farbe, die sich bei jeder ihrer Antworten ändert (Rapport, R+Rapport, Abschluss); die violette Zeile der Filter = Rufzeichen, Präfix oder Land, die du in „[[fil.highlight]]“ gewählt hast; ein besonderer Hintergrund = Station deiner Wunschliste; der blaue Punkt mit einer Zahl = in der Warteschlange.', 'Signes sur la ligne : une bande rouge sur le bord droit (le « repère ») et le fond surligné = cette station t’appelle ; la bande (et l’indicatif) devient violette = elle t’a répondu ; ligne barrée = station déjà contactée sur cette bande et dans ce mode (la façon de la marquer — barrée, soulignée, colorée, cachée — se choisit dans [[sw.tab.colors]]) ; la station que tu appelles est surlignée et reste fixe en haut, avec la couleur qui change à chacune de ses réponses (report, R+report, clôture) ; la ligne violette des filtres = indicatif, préfixe ou pays choisis dans « [[fil.highlight]] » ; un fond particulier = station de ta liste des recherchées ; la pastille bleue avec un nombre = en file.', 'Marcas en la fila: una franja roja en el borde derecho (el «marcador») y el fondo resaltado = esa estación te está llamando; la franja (y el indicativo) se vuelve violeta = te ha respondido; fila tachada = estación ya contactada en esta banda y en este modo (la forma de marcarla — tachado, subrayado, coloreado, oculto — se elige en [[sw.tab.colors]]); la estación que estás llamando aparece resaltada y se queda fija arriba, con el color que cambia en cada respuesta suya (informe, R+informe, cierre); la fila violeta de los filtros = indicativo, prefijo o país elegidos en «[[fil.highlight]]»; un fondo especial = estación de tu lista de deseadas; el punto azul con un número = en cola.', 'Sinais na linha: uma faixa vermelha na margem direita (o «marcador») e o fundo realçado = essa estação está a chamar-te; a faixa (e o indicativo) fica violeta = respondeu-te; linha riscada = estação já contactada nesta banda e neste modo (o modo de a assinalar — riscado, sublinhado, colorido, escondido — escolhe-se em [[sw.tab.colors]]); a estação que estás a chamar fica realçada e parada no topo, com a cor a mudar a cada resposta dela (relatório, R+relatório, fecho); a linha violeta dos filtros = indicativo, prefixo ou país escolhidos em «[[fil.highlight]]»; um fundo especial = estação da tua lista dos desejados; a bolinha azul com um número = na fila.'],
      ['Nel messaggio il nominativo di chi trasmette è in grassetto (con una sottolineatura colorata se usa LoTW); il nominativo del DX che stai chiamando è evidenziato. Passando il mouse sul nominativo compare il riquadro della stazione: paese, continente, nome, città, azimut e distanza dalla tua stazione (se si conosce il locatore) e come conferma i QSO (LoTW, eQSL, QSL diretta, bureau, QSL via). I dati vengono da QRZ.com o HamQTH se li hai attivati ([[nav.settings]] › [[sw.fam.log]]).', 'In the message, the callsign of the transmitting station is in bold (with a coloured underline if it uses LoTW); the callsign of the DX you are calling is highlighted. Hover over the callsign and the station card appears: country, continent, name, city, azimuth and distance from your station (if the locator is known) and how it confirms QSOs (LoTW, eQSL, direct QSL, bureau, QSL via). The data comes from QRZ.com or HamQTH if you have turned them on ([[nav.settings]] › [[sw.fam.log]]).', 'In der Nachricht steht das Rufzeichen des Senders fett (mit einer farbigen Unterstreichung, wenn er LoTW nutzt); das Rufzeichen des DX, den du rufst, ist hervorgehoben. Hältst du die Maus über das Rufzeichen, erscheint das Feld der Station: Land, Kontinent, Name, Ort, Azimut und Entfernung von deiner Station (wenn der Locator bekannt ist) und wie sie QSOs bestätigt (LoTW, eQSL, Direkt-QSL, Büro, QSL via). Die Daten kommen von QRZ.com oder HamQTH, wenn du sie aktiviert hast ([[nav.settings]] › [[sw.fam.log]]).', 'Dans le message, l’indicatif de celui qui émet est en gras (avec un soulignement coloré s’il utilise LoTW) ; l’indicatif du DX que tu appelles est surligné. En passant la souris sur l’indicatif, l’encadré de la station apparaît : pays, continent, nom, ville, azimut et distance depuis ta station (si le locator est connu) et comment elle confirme les QSO (LoTW, eQSL, QSL directe, bureau, QSL via). Les données viennent de QRZ.com ou HamQTH si tu les as activés ([[nav.settings]] › [[sw.fam.log]]).', 'En el mensaje el indicativo de quien transmite va en negrita (con un subrayado de color si usa LoTW); el indicativo del DX que estás llamando aparece resaltado. Al pasar el ratón por el indicativo aparece el recuadro de la estación: país, continente, nombre, ciudad, acimut y distancia desde tu estación (si se conoce el locator) y cómo confirma los QSO (LoTW, eQSL, QSL directa, buró, QSL vía). Los datos vienen de QRZ.com o HamQTH si los has activado ([[nav.settings]] › [[sw.fam.log]]).', 'Na mensagem o indicativo de quem transmite está a negrito (com um sublinhado colorido se usa o LoTW); o indicativo do DX que estás a chamar fica realçado. Passando o rato por cima do indicativo aparece o quadro da estação: país, continente, nome, cidade, azimute e distância desde a tua estação (se o locator for conhecido) e como confirma os QSO (LoTW, eQSL, QSL direta, bureau, QSL via). Os dados vêm do QRZ.com ou do HamQTH se os tiveres ativado ([[nav.settings]] › [[sw.fam.log]]).'],
      ['Un clic su una riga la seleziona. Doppio clic: rispondi a quella stazione (vedi «Rispondere a un CQ»); serve la spunta «[[gen.dblReply]]». Tasto destro sulla riga: la stazione va in coda per il prossimo QSO; di nuovo tasto destro la toglie (vedi «La coda e [[ctl.answer_all]]»). Tasto destro sul nominativo: un menu con «Apri su QRZ.com» e «Metti in coda» (o «Togli dalla coda»); Esc o un clic fuori lo chiudono.', 'One click on a row selects it. Double-click: you reply to that station (see “Answering a CQ”); the “[[gen.dblReply]]” check mark is needed. Right-click on the row: the station goes into the queue for the next QSO; right-click again removes it (see “The queue and [[ctl.answer_all]]”). Right-click on the callsign: a menu with “Open on QRZ.com” and “Add to queue” (or “Remove from queue”); Esc or a click outside closes it.', 'Ein Klick auf eine Zeile wählt sie aus. Doppelklick: Du antwortest dieser Station (siehe „Auf einen CQ antworten“); dafür muss das Häkchen „[[gen.dblReply]]“ gesetzt sein. Rechtsklick auf die Zeile: Die Station kommt für das nächste QSO in die Warteschlange; noch einmal Rechtsklick nimmt sie heraus (siehe „Die Warteschlange und [[ctl.answer_all]]“). Rechtsklick auf das Rufzeichen: ein Menü mit „Auf QRZ.com öffnen“ und „Einreihen“ (oder „Aus der Warteschlange nehmen“); Esc oder ein Klick daneben schließen es.', 'Un clic sur une ligne la sélectionne. Double-clic : tu réponds à cette station (voir « Répondre à un CQ ») ; la case « [[gen.dblReply]] » est nécessaire. Clic droit sur la ligne : la station va en file pour le prochain QSO ; encore un clic droit la retire (voir « La file d’attente et [[ctl.answer_all]] »). Clic droit sur l’indicatif : un menu avec « Ouvrir sur QRZ.com » et « Mettre en file » (ou « Retirer de la file ») ; Échap ou un clic à l’extérieur le ferment.', 'Un clic en una fila la selecciona. Doble clic: respondes a esa estación (mira «Responder a un CQ»); hace falta la marca «[[gen.dblReply]]». Clic derecho en la fila: la estación pasa a la cola para el próximo QSO; otro clic derecho la quita (mira «La cola y [[ctl.answer_all]]»). Clic derecho en el indicativo: un menú con «Abrir en QRZ.com» y «Poner en cola» (o «Quitar de la cola»); Esc o un clic fuera lo cierran.', 'Um clique numa linha seleciona-a. Duplo clique: respondes a essa estação (vê «Responder a um CQ»); é preciso o visto em «[[gen.dblReply]]». Botão direito na linha: a estação vai para a fila do próximo QSO; outra vez botão direito tira-a (vê «A fila e [[ctl.answer_all]]»). Botão direito no indicativo: um menu com «Abrir no QRZ.com» e «Pôr na fila» (ou «Tirar da fila»); Esc ou um clique fora fecham-no.'],
      ['Sul telefono un solo tocco su una riga risponde subito.', 'On the phone a single tap on a row replies right away.', 'Auf dem Telefon antwortet ein einziges Tippen auf eine Zeile sofort.', 'Sur le téléphone, un seul toucher sur une ligne répond tout de suite.', 'En el teléfono un solo toque en una fila responde al momento.', 'No telemóvel um só toque numa linha responde logo.'],
      ['Bandiera, paese, distanza, azimut, DT, età al posto dell’ora, le tue trasmissioni nell’elenco e la riga vuota tra due periodi si accendono e si spengono in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Lo stato vuoto dice «[[decode.empty]]» (o, in JT65 e JT9, che i messaggi arrivano a fine minuto).', 'Flag, country, distance, bearing, DT, age in place of the time, your own transmissions in the list and the empty row between two periods are turned on and off in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. The empty state says “[[decode.empty]]” (or, in JT65 and JT9, that messages arrive at the end of the minute).', 'Flagge, Land, Entfernung, Azimut, DT, Alter anstelle der Uhrzeit, deine Sendungen in der Liste und die Leerzeile zwischen zwei Durchgängen schaltest du unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] ein und aus. Der leere Zustand sagt „[[decode.empty]]“ (oder, in JT65 und JT9, dass die Nachrichten am Ende der Minute kommen).', 'Drapeau, pays, distance, azimut, DT, âge à la place de l’heure, tes émissions dans la liste et la ligne vide entre deux périodes s’activent et se désactivent dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. L’état vide dit « [[decode.empty]] » (ou, en JT65 et JT9, que les messages arrivent en fin de minute).', 'La bandera, el país, la distancia, el acimut, DT, la edad en lugar de la hora, tus transmisiones en la lista y la fila vacía entre dos periodos se encienden y se apagan en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. El estado vacío dice «[[decode.empty]]» (o, en JT65 y JT9, que los mensajes llegan al final del minuto).', 'Bandeira, país, distância, azimute, DT, idade no lugar da hora, as tuas transmissões na lista e a linha vazia entre dois períodos ligam-se e desligam-se em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. O estado vazio diz «[[decode.empty]]» (ou, em JT65 e JT9, que as mensagens chegam no fim do minuto).'],
    ],
  },
  {
    id: 'p-rxwin',
    title: ['La Finestra RX', 'The RX window', 'Das RX-Fenster', 'La Fenêtre RX', 'La ventana RX', 'A Janela RX'],
    text: ['La Finestra RX sta sopra il pannello Log (è accesa di fabbrica) e mostra solo quello che riguarda la tua frequenza di ricezione: le stazioni che trasmettono dove sta la barretta verde Rx (±50 Hz; ±100 Hz in MSK144), i messaggi diretti a te e le tue trasmissioni. È la «Rx Frequency» di WSJT-X. Per seguire solo il DX metti la barretta Rx su di lui.', 'The RX window sits above the Log panel (it is on by default) and shows only what concerns your receive frequency: the stations transmitting where the green Rx marker is (±50 Hz; ±100 Hz in MSK144), the messages addressed to you and your own transmissions. It is the “Rx Frequency” window of WSJT-X. To follow only the DX, put the Rx marker on him.', 'Das RX-Fenster sitzt über dem Log-Feld (ab Werk eingeschaltet) und zeigt nur, was deine Empfangsfrequenz betrifft: die Stationen, die dort senden, wo der grüne Rx-Balken steht (±50 Hz; ±100 Hz in MSK144), die an dich gerichteten Nachrichten und deine Sendungen. Es ist die „Rx Frequency“ von WSJT-X. Um nur dem DX zu folgen, setze den Rx-Balken auf ihn.', 'La Fenêtre RX se trouve au-dessus du panneau Journal (elle est activée par défaut) et ne montre que ce qui concerne ta fréquence de réception : les stations qui émettent là où se trouve la petite barre verte Rx (±50 Hz ; ±100 Hz en MSK144), les messages qui te sont adressés et tes émissions. C’est la « Rx Frequency » de WSJT-X. Pour suivre seulement le DX, place la petite barre Rx sur lui.', 'La Ventana RX está encima del panel Log (viene encendida de serie) y muestra solo lo que afecta a tu frecuencia de recepción: las estaciones que transmiten donde está la barrita verde Rx (±50 Hz; ±100 Hz en MSK144), los mensajes dirigidos a ti y tus transmisiones. Es la «Rx Frequency» de WSJT-X. Para seguir solo al DX pon la barrita Rx sobre él.', 'A Janela RX fica por cima do painel Log (está ligada de origem) e mostra só o que diz respeito à tua frequência de receção: as estações que transmitem onde está a barrinha verde Rx (±50 Hz; ±100 Hz em MSK144), as mensagens dirigidas a ti e as tuas transmissões. É a «Rx Frequency» do WSJT-X. Para seguires só o DX põe a barrinha Rx em cima dele.'],
    steps: [
      ['Barra del titolo: «[[rxw.title]]», a destra la frequenza Rx con la tolleranza (per esempio «1500 Hz ±50»), poi «[[list.clear]]» e «[[list.bottom.off]]» / «[[list.bottom.on]]», che funzionano come in Attività di banda ma valgono solo qui.', 'Title bar: “[[rxw.title]]”, on the right the Rx frequency with its tolerance (for example “1500 Hz ±50”), then “[[list.clear]]” and “[[list.bottom.off]]” / “[[list.bottom.on]]”, which work as in Band activity but apply only here.', 'Titelleiste: „[[rxw.title]]“, rechts die Rx-Frequenz mit der Toleranz (zum Beispiel „1500 Hz ±50“), dann „[[list.clear]]“ und „[[list.bottom.off]]“ / „[[list.bottom.on]]“, die wie in Bandaktivität funktionieren, aber nur hier gelten.', 'Barre de titre : « [[rxw.title]] », à droite la fréquence Rx avec la tolérance (par exemple « 1500 Hz ±50 »), puis « [[list.clear]] » et « [[list.bottom.off]] » / « [[list.bottom.on]] », qui fonctionnent comme dans Activité de bande mais ne valent qu’ici.', 'Barra del título: «[[rxw.title]]», a la derecha la frecuencia Rx con la tolerancia (por ejemplo «1500 Hz ±50»), luego «[[list.clear]]» y «[[list.bottom.off]]» / «[[list.bottom.on]]», que funcionan como en Actividad de banda pero valen solo aquí.', 'Barra do título: «[[rxw.title]]», à direita a frequência Rx com a tolerância (por exemplo «1500 Hz ±50»), depois «[[list.clear]]» e «[[list.bottom.off]]» / «[[list.bottom.on]]», que funcionam como na Atividade da banda mas valem só aqui.'],
      ['Il pulsante «RX» nelle linguette del pannello Log (vicino a «[[log.tab.log]]» e «[[log.tab.map]]») accende e spegne la Finestra RX: spenta, il pannello Log occupa tutto il posto. La scelta resta.', 'The “RX” button in the tabs of the Log panel (next to “[[log.tab.log]]” and “[[log.tab.map]]”) turns the RX window on and off: when off, the Log panel takes all the space. Your choice is kept.', 'Die Schaltfläche „RX“ in den Reitern des Log-Feldes (neben „[[log.tab.log]]“ und „[[log.tab.map]]“) schaltet das RX-Fenster ein und aus: Ist es aus, nimmt das Log-Feld den ganzen Platz ein. Die Wahl bleibt gespeichert.', 'Le bouton « RX » dans les onglets du panneau Journal (près de « [[log.tab.log]] » et « [[log.tab.map]] ») allume et éteint la Fenêtre RX : éteinte, le panneau Journal occupe toute la place. Le choix est conservé.', 'El botón «RX» de las pestañas del panel Log (junto a «[[log.tab.log]]» y «[[log.tab.map]]») enciende y apaga la Ventana RX: apagada, el panel Log ocupa todo el sitio. La elección se queda.', 'O botão «RX» nos separadores do painel Log (perto de «[[log.tab.log]]» e «[[log.tab.map]]») liga e desliga a Janela RX: desligada, o painel Log ocupa todo o espaço. A escolha mantém-se.'],
      ['Le colonne hanno un titolo — l’ora (o «[[rxw.col.age]]»), dB, DT, «[[rxw.col.msg]]», «[[rxw.col.country]]» — che si trascina per cambiare l’ordine delle colonne; trascinando il bordo destro di un titolo cambi la larghezza, con il doppio clic sul bordo la colonna si adatta al contenuto. Tasto destro sul titolo: «Ripristina colonne». Anche Alt + frecce sposta la colonna scelta.', 'The columns have a heading — the time (or “[[rxw.col.age]]”), dB, DT, “[[rxw.col.msg]]”, “[[rxw.col.country]]” — which you drag to change the order of the columns; dragging the right edge of a heading changes the width, and double-clicking the edge fits the column to its content. Right-click on the heading: “Reset columns”. Alt + arrows also move the chosen column.', 'Die Spalten haben einen Titel — die Uhrzeit (oder „[[rxw.col.age]]“), dB, DT, „[[rxw.col.msg]]“, „[[rxw.col.country]]“ —, den du ziehst, um die Reihenfolge der Spalten zu ändern; ziehst du den rechten Rand eines Titels, änderst du die Breite, mit Doppelklick auf den Rand passt sich die Spalte dem Inhalt an. Rechtsklick auf den Titel: „Spalten zurücksetzen“. Auch Alt + Pfeiltasten verschiebt die gewählte Spalte.', 'Les colonnes ont un titre — l’heure (ou « [[rxw.col.age]] »), dB, DT, « [[rxw.col.msg]] », « [[rxw.col.country]] » — qu’on glisse pour changer l’ordre des colonnes ; en glissant le bord droit d’un titre tu changes la largeur, avec le double-clic sur le bord la colonne s’adapte au contenu. Clic droit sur le titre : « Réinitialiser les colonnes ». Alt + flèches déplace aussi la colonne choisie.', 'Las columnas tienen un título — la hora (o «[[rxw.col.age]]»), dB, DT, «[[rxw.col.msg]]», «[[rxw.col.country]]» — que se arrastra para cambiar el orden de las columnas; si arrastras el borde derecho de un título cambias la anchura, y con un doble clic en el borde la columna se ajusta al contenido. Clic derecho en el título: «Restablecer columnas». También Alt + flechas mueve la columna elegida.', 'As colunas têm um título — a hora (ou «[[rxw.col.age]]»), dB, DT, «[[rxw.col.msg]]», «[[rxw.col.country]]» — que se arrasta para mudar a ordem das colunas; arrastando a margem direita de um título mudas a largura, com o duplo clique na margem a coluna ajusta-se ao conteúdo. Botão direito no título: «Repor colunas». Também Alt + setas move a coluna escolhida.'],
      ['Se in Attività di banda non vuoi vedere i messaggi del tuo QSO (sono già qui) accendi «[[rxw.exclusive]]» in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; di fabbrica si vedono in tutte e due.', 'If you don’t want to see the messages of your QSO in Band activity (they are already here), turn on “[[rxw.exclusive]]” in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; by default they appear in both.', 'Willst du in Bandaktivität die Nachrichten deines QSOs nicht sehen (sie stehen schon hier), schalte „[[rxw.exclusive]]“ unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] ein; ab Werk sieht man sie in beiden.', 'Si dans Activité de bande tu ne veux pas voir les messages de ton QSO (ils sont déjà ici), active « [[rxw.exclusive]] » dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] ; par défaut ils se voient dans les deux.', 'Si en Actividad de banda no quieres ver los mensajes de tu QSO (ya están aquí) enciende «[[rxw.exclusive]]» en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; de serie se ven en las dos.', 'Se na Atividade da banda não queres ver as mensagens do teu QSO (já estão aqui) liga «[[rxw.exclusive]]» em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]; de origem veem-se nas duas.'],
      ['Se non ci sono messaggi vicino alla frequenza Rx la finestra dice «[[rxw.empty]]».', 'If there are no messages near the Rx frequency, the window says “[[rxw.empty]]”.', 'Gibt es keine Nachrichten nahe der Rx-Frequenz, sagt das Fenster „[[rxw.empty]]“.', 'S’il n’y a pas de messages près de la fréquence Rx, la fenêtre dit « [[rxw.empty]] ».', 'Si no hay mensajes cerca de la frecuencia Rx, la ventana dice «[[rxw.empty]]».', 'Se não houver mensagens perto da frequência Rx a janela diz «[[rxw.empty]]».'],
    ],
  },
  {
    id: 'p-wfbar',
    title: ['La barra sopra la cascata', 'The bar above the waterfall', 'Die Leiste über dem Wasserfall', 'La barre au-dessus de la cascade', 'La barra sobre la cascada', 'A barra por cima da cascata'],
    text: ['Sopra la cascata c’è una barra di comandi, con le stesse opzioni di [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: cambiare qui o là è la stessa cosa e la modifica si vede subito. Ogni voce ha il suo suggerimento (passa il mouse).', 'Above the waterfall there is a command bar, with the same options as [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: changing here or there is the same thing and the change shows at once. Each item has its hint (hover over it).', 'Über dem Wasserfall sitzt eine Befehlsleiste mit denselben Optionen wie [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: Hier oder dort zu ändern ist dasselbe, und die Änderung ist sofort zu sehen. Jeder Eintrag hat seinen Hinweis (Maus darüberhalten).', 'Au-dessus de la cascade il y a une barre de commandes, avec les mêmes options que [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]] : changer ici ou là, c’est pareil et la modification se voit tout de suite. Chaque entrée a son info-bulle (passe la souris).', 'Sobre la cascada hay una barra de comandos, con las mismas opciones de [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: cambiar aquí o allí es lo mismo y el cambio se ve enseguida. Cada opción tiene su sugerencia (pasa el ratón).', 'Por cima da cascata há uma barra de comandos, com as mesmas opções de [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]]: mudar aqui ou ali é a mesma coisa e a alteração vê-se logo. Cada entrada tem a sua sugestão (passa o rato).'],
    steps: [
      ['«[[wft.bins]]» (di fabbrica 5): quanti canali dello spettro si sommano in un pixel; meno canali = più dettaglio e più rumore. «[[wft.start]]»: da che frequenza audio parte il bordo sinistro (0-4900 Hz, di fabbrica 0); alzarla taglia via la parte bassa e ingrandisce il resto.', '“[[wft.bins]]” (5 by default): how many spectrum channels are added into one pixel; fewer channels = more detail and more noise. “[[wft.start]]”: the audio frequency where the left edge starts (0-4900 Hz, 0 by default); raising it cuts off the low part and enlarges the rest.', '„[[wft.bins]]“ (ab Werk 5): wie viele Kanäle des Spektrums zu einem Pixel addiert werden; weniger Kanäle = mehr Detail und mehr Rauschen. „[[wft.start]]“: bei welcher Audiofrequenz der linke Rand beginnt (0-4900 Hz, ab Werk 0); erhöhst du sie, wird der untere Teil abgeschnitten und der Rest vergrößert.', '« [[wft.bins]] » (5 par défaut) : combien de canaux du spectre s’additionnent dans un pixel ; moins de canaux = plus de détail et plus de bruit. « [[wft.start]] » : à partir de quelle fréquence audio part le bord gauche (0-4900 Hz, 0 par défaut) ; l’augmenter coupe la partie basse et agrandit le reste.', '«[[wft.bins]]» (de serie 5): cuántos canales del espectro se suman en un píxel; menos canales = más detalle y más ruido. «[[wft.start]]»: desde qué frecuencia de audio parte el borde izquierdo (0-4900 Hz, de serie 0); subirla corta la parte baja y agranda el resto.', '«[[wft.bins]]» (de origem 5): quantos canais do espetro se somam num pixel; menos canais = mais detalhe e mais ruído. «[[wft.start]]»: de que frequência de áudio parte a margem esquerda (0-4900 Hz, de origem 0); aumentá-la corta a parte baixa e amplia o resto.'],
      ['«[[wft.palette]]»: i colori (30 tavolozze più la tua). «[[wft.gain]]» e «[[wft.zero]]»: due cursori da -50 a 50 (di fabbrica 0); Gain rende i segnali più vivi, Zero schiarisce o scurisce anche il fondo.', '“[[wft.palette]]”: the colours (30 palettes plus your own). “[[wft.gain]]” and “[[wft.zero]]”: two sliders from -50 to 50 (0 by default); Gain makes the signals more vivid, Zero lightens or darkens the background too.', '„[[wft.palette]]“: die Farben (30 Farbpaletten plus deine eigene). „[[wft.gain]]“ und „[[wft.zero]]“: zwei Regler von -50 bis 50 (ab Werk 0); Gain macht die Signale lebhafter, Zero hellt auch den Hintergrund auf oder dunkelt ihn ab.', '« [[wft.palette]] » : les couleurs (30 palettes plus la tienne). « [[wft.gain]] » et « [[wft.zero]] » : deux curseurs de -50 à 50 (0 par défaut) ; Gain rend les signaux plus vifs, Zero éclaircit ou assombrit aussi le fond.', '«[[wft.palette]]»: los colores (30 paletas más la tuya). «[[wft.gain]]» y «[[wft.zero]]»: dos cursores de -50 a 50 (de serie 0); Gain hace las señales más vivas, Zero aclara u oscurece también el fondo.', '«[[wft.palette]]»: as cores (30 paletas mais a tua). «[[wft.gain]]» e «[[wft.zero]]»: dois cursores de -50 a 50 (de origem 0); o Gain torna os sinais mais vivos, o Zero clareia ou escurece também o fundo.'],
      ['«[[wft.navg]]»: quante righe si mediano prima di disegnarne una (da 1 a 50, di fabbrica 1): più alto = cascata più lenta e meno rumorosa.', '“[[wft.navg]]”: how many rows are averaged before one is drawn (from 1 to 50, 1 by default): higher = slower and less noisy waterfall.', '„[[wft.navg]]“: wie viele Zeilen gemittelt werden, bevor eine gezeichnet wird (von 1 bis 50, ab Werk 1): höher = langsamerer und rauschärmerer Wasserfall.', '« [[wft.navg]] » : combien de lignes sont moyennées avant d’en dessiner une (de 1 à 50, 1 par défaut) : plus haut = cascade plus lente et moins bruyante.', '«[[wft.navg]]»: cuántas filas se promedian antes de dibujar una (de 1 a 50, de serie 1): más alto = cascada más lenta y con menos ruido.', '«[[wft.navg]]»: quantas linhas se calculam em média antes de desenhar uma (de 1 a 50, de origem 1): mais alto = cascata mais lenta e menos ruidosa.'],
      ['«[[wft.spec]]»: la tendina dello spettro sotto la cascata: «[[wfs.specOff]]» lo nasconde, «[[wfs.current]]» mostra l’ultimo spettro, «[[wfs.cumulative]]» la media di tutto il periodo. L’altezza si cambia trascinando la barretta grigia sopra lo spettro («[[wf.specHeight]]»).', '“[[wft.spec]]”: the drop-down for the spectrum under the waterfall: “[[wfs.specOff]]” hides it, “[[wfs.current]]” shows the latest spectrum, “[[wfs.cumulative]]” the average of the whole period. The height is changed by dragging the grey handle above the spectrum (“[[wf.specHeight]]”).', '„[[wft.spec]]“: die Auswahlliste des Spektrums unter dem Wasserfall: „[[wfs.specOff]]“ blendet es aus, „[[wfs.current]]“ zeigt das letzte Spektrum, „[[wfs.cumulative]]“ den Mittelwert des ganzen Durchgangs. Die Höhe änderst du, indem du den grauen Balken über dem Spektrum ziehst („[[wf.specHeight]]“).', '« [[wft.spec]] » : la liste du spectre sous la cascade : « [[wfs.specOff]] » le masque, « [[wfs.current]] » montre le dernier spectre, « [[wfs.cumulative]] » la moyenne de toute la période. La hauteur se change en glissant la petite barre grise au-dessus du spectre (« [[wf.specHeight]] »).', '«[[wft.spec]]»: la lista desplegable del espectro bajo la cascada: «[[wfs.specOff]]» lo oculta, «[[wfs.current]]» muestra el último espectro, «[[wfs.cumulative]]» el promedio de todo el periodo. La altura se cambia arrastrando la barrita gris sobre el espectro («[[wf.specHeight]]»).', '«[[wft.spec]]»: a lista do espetro por baixo da cascata: «[[wfs.specOff]]» esconde-o, «[[wfs.current]]» mostra o último espetro, «[[wfs.cumulative]]» a média de todo o período. A altura muda-se arrastando a barrinha cinzenta por cima do espetro («[[wf.specHeight]]»).'],
      ['«[[wft.flatten]]» toglie la curva del rumore di fondo (utile se il filtro della radio inclina il fondo). «[[wft.stamp]]» scrive sulla cascata l’ora UTC e la banda a ogni inizio di periodo.', '“[[wft.flatten]]” removes the background noise curve (useful if the radio filter tilts the background). “[[wft.stamp]]” writes the UTC time and the band on the waterfall at the start of each period.', '„[[wft.flatten]]“ nimmt die Kurve des Grundrauschens weg (nützlich, wenn das Filter des Funkgeräts den Hintergrund neigt). „[[wft.stamp]]“ schreibt bei jedem Beginn eines Durchgangs die UTC-Zeit und das Band in den Wasserfall.', '« [[wft.flatten]] » enlève la courbe du bruit de fond (utile si le filtre de la radio incline le fond). « [[wft.stamp]] » écrit sur la cascade l’heure UTC et la bande à chaque début de période.', '«[[wft.flatten]]» quita la curva del ruido de fondo (útil si el filtro de la radio inclina el fondo). «[[wft.stamp]]» escribe en la cascada la hora UTC y la banda al comienzo de cada periodo.', '«[[wft.flatten]]» tira a curva do ruído de fundo (útil se o filtro do rádio inclina o fundo). «[[wft.stamp]]» escreve na cascata a hora UTC e a banda no início de cada período.'],
      ['L’ultimo dato, in piccolo, è il tratto di audio mostrato (per esempio «0–3000 Hz»); la cascata è larga quanto il filtro della radio letto con il CAT (0-3000 Hz se la radio non lo dice).', 'The last item, in small type, is the stretch of audio shown (for example “0–3000 Hz”); the waterfall is as wide as the radio filter read through CAT (0-3000 Hz if the radio doesn’t say).', 'Die letzte Angabe, klein, ist der gezeigte Audiobereich (zum Beispiel „0–3000 Hz“); der Wasserfall ist so breit wie das über CAT gelesene Filter des Funkgeräts (0-3000 Hz, wenn das Funkgerät es nicht sagt).', 'La dernière donnée, en petit, est le tronçon d’audio affiché (par exemple « 0–3000 Hz ») ; la cascade est aussi large que le filtre de la radio lu avec le CAT (0-3000 Hz si la radio ne le dit pas).', 'El último dato, en pequeño, es el tramo de audio mostrado (por ejemplo «0–3000 Hz»); la cascada es tan ancha como el filtro de la radio leído con el CAT (0-3000 Hz si la radio no lo dice).', 'O último dado, em pequeno, é o troço de áudio mostrado (por exemplo «0–3000 Hz»); a cascata tem a largura do filtro do rádio lido com o CAT (0-3000 Hz se o rádio não o disser).'],
    ],
  },
  {
    id: 'p-wfmarks',
    title: ['La cascata: barre, frecce e nominativi', 'The waterfall: bars, arrows and callsigns', 'Der Wasserfall: Balken, Pfeile und Rufzeichen', 'La cascade : barres, flèches et indicatifs', 'La cascada: barras, flechas e indicativos', 'A cascata: barras, setas e indicativos'],
    text: ['Sulla cascata si lavora con il mouse. I gesti principali sono in «La cascata»; qui il resto.', 'On the waterfall you work with the mouse. The main gestures are in “The waterfall”; here is the rest.', 'Am Wasserfall arbeitest du mit der Maus. Die wichtigsten Gesten stehen unter „Der Wasserfall“; hier der Rest.', 'Sur la cascade, on travaille à la souris. Les gestes principaux sont dans « La cascade » ; ici le reste.', 'Sobre la cascada se trabaja con el ratón. Los gestos principales están en «La cascada»; aquí, el resto.', 'Na cascata trabalha-se com o rato. Os gestos principais estão em «A cascata»; aqui o resto.'],
    steps: [
      ['Le due barre verticali sono Rx (verde) e Tx (rossa), con la loro frequenza scritta in alto («Rx 1500»). Si trascinano con il mouse; oppure ci si porta il focus con Tab e si usano le frecce sinistra e destra: 10 Hz alla volta, 50 Hz tenendo premuto Maiusc.', 'The two vertical bars are Rx (green) and Tx (red), with their frequency written at the top (“Rx 1500”). You drag them with the mouse; or you move the focus to them with Tab and use the left and right arrows: 10 Hz at a time, 50 Hz while holding Shift.', 'Die beiden senkrechten Balken sind Rx (grün) und Tx (rot), mit ihrer Frequenz oben angeschrieben („Rx 1500“). Man zieht sie mit der Maus; oder man setzt mit Tab den Fokus darauf und benutzt die Pfeile links und rechts: 10 Hz auf einmal, 50 Hz bei gedrückter Umschalttaste.', 'Les deux barres verticales sont Rx (verte) et Tx (rouge), avec leur fréquence écrite en haut (« Rx 1500 »). On les glisse à la souris ; ou bien on y place le focus avec Tab et on utilise les flèches gauche et droite : 10 Hz à la fois, 50 Hz en gardant Maj appuyée.', 'Las dos barras verticales son Rx (verde) y Tx (roja), con su frecuencia escrita arriba («Rx 1500»). Se arrastran con el ratón; o bien llevas el foco con Tab y usas las flechas izquierda y derecha: 10 Hz cada vez, 50 Hz manteniendo pulsado Mayús.', 'As duas barras verticais são Rx (verde) e Tx (vermelha), com a sua frequência escrita em cima («Rx 1500»). Arrastam-se com o rato; ou leva-se o foco até elas com Tab e usam-se as setas esquerda e direita: 10 Hz de cada vez, 50 Hz com Shift premido.'],
      ['Passando il mouse sulla cascata due linee bianche mostrano la larghezza di un segnale; con «[[wfs.freqOn]]» acceso compare anche la frequenza in Hz sotto il puntatore. Le linee e le barre si spengono con «[[wfs.barsOn]]» (restano le etichette).', 'When you hover over the waterfall, two white lines show the width of a signal; with “[[wfs.freqOn]]” on, the frequency in Hz under the pointer also appears. The lines and the bars are turned off with “[[wfs.barsOn]]” (the labels stay).', 'Fährst du mit der Maus über den Wasserfall, zeigen zwei weiße Linien die Breite eines Signals; ist „[[wfs.freqOn]]“ eingeschaltet, erscheint auch die Frequenz in Hz unter dem Zeiger. Die Linien und die Balken schaltest du mit „[[wfs.barsOn]]“ aus (die Beschriftungen bleiben).', 'En passant la souris sur la cascade, deux lignes blanches montrent la largeur d’un signal ; avec « [[wfs.freqOn]] » allumé, la fréquence en Hz apparaît aussi sous le pointeur. Les lignes et les barres s’éteignent avec « [[wfs.barsOn]] » (les étiquettes restent).', 'Al pasar el ratón por la cascada dos líneas blancas muestran la anchura de una señal; con «[[wfs.freqOn]]» encendido aparece también la frecuencia en Hz bajo el puntero. Las líneas y las barras se apagan con «[[wfs.barsOn]]» (quedan las etiquetas).', 'Passando o rato pela cascata duas linhas brancas mostram a largura de um sinal; com «[[wfs.freqOn]]» ligado aparece também a frequência em Hz por baixo do ponteiro. As linhas e as barras desligam-se com «[[wfs.barsOn]]» (ficam as etiquetas).'],
      ['Con [[ctl.filter]] acceso, due zone scure ai lati della barra Rx mostrano la parte di banda che Aurora ignora.', 'With [[ctl.filter]] on, two dark areas at the sides of the Rx bar show the part of the band that Aurora ignores.', 'Ist [[ctl.filter]] eingeschaltet, zeigen zwei dunkle Zonen an den Seiten des Rx-Balkens den Teil des Bandes, den Aurora ignoriert.', 'Avec [[ctl.filter]] allumé, deux zones sombres de chaque côté de la barre Rx montrent la partie de la bande qu’Aurora ignore.', 'Con [[ctl.filter]] encendido, dos zonas oscuras a los lados de la barra Rx muestran la parte de banda que Aurora ignora.', 'Com [[ctl.filter]] ligado, duas zonas escuras dos lados da barra Rx mostram a parte da banda que a Aurora ignora.'],
      ['Sopra la cascata compaiono le etichette degli spot del DX Cluster che cadono nella banda audio che vedi: nominativo e tacca sulla frequenza dello spot. Se non c’è posto, gli spot si raccolgono in una etichetta «+N» (passa il mouse per l’elenco). Un clic su uno spot porta la frequenza di ricezione lì (solo la ricezione: non trasmette).', 'Above the waterfall appear the labels of the DX Cluster spots that fall in the audio band you see: callsign and a mark on the spot frequency. If there is no room, the spots are gathered into one “+N” label (hover over it for the list). A click on a spot moves the receive frequency there (reception only: it does not transmit).', 'Über dem Wasserfall erscheinen die Beschriftungen der DX-Cluster-Spots, die in den sichtbaren Audiobereich fallen: Rufzeichen und Strich auf der Frequenz des Spots. Ist kein Platz, sammeln sich die Spots in einer Beschriftung „+N“ (Maus darüberhalten für die Liste). Ein Klick auf einen Spot stellt die Empfangsfrequenz dorthin (nur den Empfang: Er sendet nicht).', 'Au-dessus de la cascade apparaissent les étiquettes des spots du DX Cluster qui tombent dans la bande audio que tu vois : indicatif et repère sur la fréquence du spot. S’il n’y a pas de place, les spots se regroupent dans une étiquette « +N » (passe la souris pour la liste). Un clic sur un spot place la fréquence de réception là (seulement la réception : il n’émet pas).', 'Sobre la cascada aparecen las etiquetas de los spots del DX Cluster que caen en la banda de audio que ves: indicativo y marca en la frecuencia del spot. Si no hay sitio, los spots se reúnen en una etiqueta «+N» (pasa el ratón para ver la lista). Un clic en un spot lleva allí la frecuencia de recepción (solo la recepción: no transmite).', 'Por cima da cascata aparecem as etiquetas dos spots do DX Cluster que caem na banda de áudio que vês: indicativo e marca na frequência do spot. Se não houver lugar, os spots reúnem-se numa etiqueta «+N» (passa o rato para a lista). Um clique num spot leva a frequência de receção para lá (só a receção: não transmite).'],
      ['Sotto la cascata il righello stretto ha una tacca ogni 100 Hz (numero ogni 500), due parentesi per Tx (arancio) e Rx (verde) e un segno per ogni messaggio dell’ultimo periodo.', 'Under the waterfall, the narrow ruler has a mark every 100 Hz (a number every 500), two brackets for Tx (orange) and Rx (green) and a sign for every message of the last period.', 'Unter dem Wasserfall hat das schmale Lineal alle 100 Hz einen Strich (alle 500 eine Zahl), zwei Klammern für Tx (orange) und Rx (grün) und ein Zeichen für jede Nachricht des letzten Durchgangs.', 'Sous la cascade, la règle étroite a un repère tous les 100 Hz (un nombre tous les 500), deux crochets pour Tx (orange) et Rx (vert) et un signe pour chaque message de la dernière période.', 'Bajo la cascada la regla estrecha tiene una marca cada 100 Hz (número cada 500), dos corchetes para Tx (naranja) y Rx (verde) y una señal por cada mensaje del último periodo.', 'Por baixo da cascata a régua estreita tem uma marca a cada 100 Hz (número a cada 500), dois parênteses para Tx (laranja) e Rx (verde) e um sinal por cada mensagem do último período.'],
      ['Mentre trasmetti la cascata si ferma (dalla radio non arriva audio) e una riga gialla segna la pausa; riparte alla fine della trasmissione.', 'While you transmit the waterfall stops (no audio comes from the radio) and a yellow line marks the pause; it starts again at the end of the transmission.', 'Während du sendest, steht der Wasserfall still (vom Funkgerät kommt kein Audio), und eine gelbe Linie markiert die Pause; er läuft am Ende der Sendung weiter.', 'Pendant que tu émets, la cascade s’arrête (la radio n’envoie pas d’audio) et une ligne jaune marque la pause ; elle repart à la fin de l’émission.', 'Mientras transmites la cascada se detiene (de la radio no llega audio) y una fila amarilla marca la pausa; vuelve a arrancar al final de la transmisión.', 'Enquanto transmites a cascata pára (do rádio não chega áudio) e uma linha amarela assinala a pausa; recomeça no fim da transmissão.'],
    ],
    tip: ['La barra Tx si sposta anche mentre trasmetti: il tono cambia subito. Scegli per trasmettere un punto libero della cascata.', 'The Tx bar can also be moved while you transmit: the tone changes at once. Choose a free spot on the waterfall to transmit.', 'Der Tx-Balken lässt sich auch während des Sendens verschieben: Der Ton ändert sich sofort. Wähle zum Senden eine freie Stelle im Wasserfall.', 'La barre Tx se déplace aussi pendant que tu émets : la tonalité change tout de suite. Pour émettre, choisis un endroit libre de la cascade.', 'La barra Tx también se mueve mientras transmites: el tono cambia al instante. Elige para transmitir un punto libre de la cascada.', 'A barra Tx move-se também enquanto transmites: o tom muda logo. Para transmitir escolhe um ponto livre da cascata.'],
  },
  {
    id: 'p-txpanel',
    title: ['Il pannello Trasmissione', 'The Transmit panel', 'Das Feld Senden', 'Le panneau Émission', 'El panel Transmisión', 'O painel Transmissão'],
    text: ['Il pannello [[panel.tx]] mostra con chi sei in contatto e a che punto è il QSO, e contiene gli interruttori del QSO (vedi «Gli interruttori del QSO») e i livelli audio (vedi «I livelli Rx e Pwr»).', 'The [[panel.tx]] panel shows who you are in contact with and how far the QSO has got, and contains the QSO switches (see “The QSO switches”) and the audio levels (see “The Rx and Pwr levels”).', 'Das Feld [[panel.tx]] zeigt, mit wem du in Kontakt bist und wie weit das QSO ist, und enthält die QSO-Schalter (siehe „Die QSO-Schalter“) und die Audiopegel (siehe „Die Pegel Rx und Pwr“).', 'Le panneau [[panel.tx]] montre avec qui tu es en contact et où en est le QSO, et contient les interrupteurs du QSO (voir « Les interrupteurs du QSO ») et les niveaux audio (voir « Les niveaux Rx et Pwr »).', 'El panel [[panel.tx]] muestra con quién estás en contacto y en qué punto está el QSO, y contiene los interruptores del QSO (mira «Los interruptores del QSO») y los niveles de audio (mira «Los niveles Rx y Pwr»).', 'O painel [[panel.tx]] mostra com quem estás em contacto e em que ponto está o QSO, e contém os interruptores do QSO (vê «Os interruptores do QSO») e os níveis de áudio (vê «Os níveis Rx e Pwr»).'],
    steps: [
      ['L’etichetta gialla «DX» con nominativo, locatore, bandiera e paese è la stazione che stai chiamando; senza stazione c’è un trattino.', 'The yellow “DX” label with callsign, locator, flag and country is the station you are calling; with no station there is a dash.', 'Das gelbe Etikett „DX“ mit Rufzeichen, Locator, Flagge und Land ist die Station, die du rufst; ohne Station steht ein Strich.', 'L’étiquette jaune « DX » avec indicatif, locator, drapeau et pays est la station que tu appelles ; sans station, il y a un tiret.', 'La etiqueta amarilla «DX» con indicativo, localizador, bandera y país es la estación que estás llamando; sin estación hay un guion.', 'A etiqueta amarela «DX» com indicativo, locator, bandeira e país é a estação que estás a chamar; sem estação há um traço.'],
      ['Accanto, le stazioni in coda, fino a 4, una per riga con il pallino del posto: un clic su un nominativo lascia subito il QSO in corso e risponde a lui (vedi «Passare subito a chi è in coda»). La freccia «Prossimo della coda» chiama la prima.', 'Next to it, the queued stations, up to 4, one per row with the dot of the place: a click on a callsign leaves the current QSO at once and replies to that station (see “Jump to a queued station”). The “Next in queue” arrow calls the first one.', 'Daneben die Stationen in der Warteschlange, bis zu 4, eine pro Zeile mit dem Punkt des Platzes: Ein Klick auf ein Rufzeichen verlässt sofort das laufende QSO und antwortet ihm (siehe „Sofort zu einer Station in der Warteschlange“). Der Pfeil „Nächster in der Warteschlange“ ruft die erste.', 'À côté, les stations en file, jusqu’à 4, une par ligne avec la pastille de la place : un clic sur un indicatif quitte tout de suite le QSO en cours et répond à lui (voir « Passer tout de suite à une station en file »). La flèche « Suivant dans la file » appelle la première.', 'Al lado, las estaciones en cola, hasta 4, una por fila con el punto del puesto: un clic en un indicativo deja enseguida el QSO en curso y responde a esa estación (mira «Pasar ya a quien está en cola»). La flecha «Siguiente en la cola» llama a la primera.', 'Ao lado, as estações na fila, até 4, uma por linha com a bolinha do lugar: um clique num indicativo deixa logo o QSO em curso e responde a essa estação (vê «Passar já a quem está na fila»). A seta «Próximo na fila» chama a primeira.'],
      ['Il riquadro RX/STOP: verde «RX» in ascolto; mentre trasmetti diventa il pulsante rosso «[[stop.button]] (Esc)», un clic ferma subito la trasmissione. Doppio clic su «RX» fa quello che fa «[[ctl.clear_dx]]»: libera la stazione e cancella i messaggi del QSO.', 'The RX/STOP box: green “RX” when listening; while you transmit it becomes the red “[[stop.button]] (Esc)” button, and a click stops the transmission at once. A double-click on “RX” does what “[[ctl.clear_dx]]” does: it frees the station and clears the QSO messages.', 'Das Feld RX/STOP: grünes „RX“ beim Hören; während du sendest, wird es zur roten Schaltfläche „[[stop.button]] (Esc)“, ein Klick stoppt das Senden sofort. Doppelklick auf „RX“ macht, was „[[ctl.clear_dx]]“ macht: Es gibt die Station frei und löscht die Nachrichten des QSOs.', 'Le cadre RX/STOP : « RX » vert en écoute ; pendant que tu émets il devient le bouton rouge « [[stop.button]] (Échap) », un clic arrête tout de suite l’émission. Double-clic sur « RX » fait ce que fait « [[ctl.clear_dx]] » : libère la station et efface les messages du QSO.', 'El recuadro RX/STOP: «RX» verde en escucha; mientras transmites se convierte en el botón rojo «[[stop.button]] (Esc)», un clic detiene enseguida la transmisión. Doble clic en «RX» hace lo que hace «[[ctl.clear_dx]]»: libera la estación y borra los mensajes del QSO.', 'O quadro RX/STOP: verde «RX» a ouvir; enquanto transmites passa a ser o botão vermelho «[[stop.button]] (Esc)», um clique pára logo a transmissão. Duplo clique em «RX» faz o que faz «[[ctl.clear_dx]]»: liberta a estação e apaga as mensagens do QSO.'],
      ['Accanto compare «Hound» (o «Super Hound») se il modo Hound è acceso: verde quando il Fox ha mandato un codice OTP e il servizio l’ha confermato, rosso se non è ancora verificato. Sotto una riga dice «Fox … verificato» o «NON valido».', 'Next to it “Hound” (or “Super Hound”) appears if Hound mode is on: green when the Fox has sent an OTP code and the service has confirmed it, red if it is not yet verified. Below, a line says “Fox … verified” or “NOT valid”.', 'Daneben erscheint „Hound“ (oder „Super Hound“), wenn der Hound-Modus an ist: grün, wenn der Fox einen OTP-Code gesendet hat und der Dienst ihn bestätigt hat, rot, wenn er noch nicht geprüft ist. Darunter sagt eine Zeile „Fox … geprüft“ oder „NICHT gültig“.', 'À côté apparaît « Hound » (ou « Super Hound ») si le mode Hound est actif : vert quand le Fox a envoyé un code OTP et que le service l’a confirmé, rouge s’il n’est pas encore vérifié. Dessous, une ligne dit « Fox … vérifié » ou « NON valide ».', 'Al lado aparece «Hound» (o «Super Hound») si el modo Hound está encendido: verde cuando el Fox ha mandado un código OTP y el servicio lo ha confirmado, rojo si todavía no está verificado. Debajo una fila dice «Fox … verificado» o «NO válido».', 'Ao lado aparece «Hound» (ou «Super Hound») se o modo Hound estiver ligado: verde quando o Fox enviou um código OTP e o serviço o confirmou, vermelho se ainda não está verificado. Por baixo uma linha diz «Fox … verificado» ou «NÃO válido».'],
      ['Gli avvisi di sicurezza della trasmissione (ROS alto, messaggio non trasmissibile, Tx bloccata da un programma esterno, Hound acceso o spento da solo) compaiono in rosso sotto la riga del DX e spariscono dopo due minuti.', 'The transmit safety alerts (high SWR, message that cannot be sent, Tx blocked by an external program, Hound turned on or off by itself) appear in red under the DX row and disappear after two minutes.', 'Die Sicherheitshinweise zum Senden (hohes SWR, nicht sendbare Nachricht, Tx von einem externen Programm gesperrt, Hound von selbst ein- oder ausgeschaltet) erscheinen rot unter der DX-Zeile und verschwinden nach zwei Minuten.', 'Les alertes de sécurité de l’émission (TOS élevé, message non transmissible, Tx bloquée par un programme externe, Hound allumé ou éteint tout seul) apparaissent en rouge sous la ligne du DX et disparaissent au bout de deux minutes.', 'Los avisos de seguridad de la transmisión (ROE alta, mensaje no transmisible, Tx bloqueada por un programa externo, Hound encendido o apagado solo) aparecen en rojo bajo la fila del DX y desaparecen a los dos minutos.', 'Os avisos de segurança da transmissão (ROE alta, mensagem não transmissível, Tx bloqueada por um programa externo, Hound ligado ou desligado sozinho) aparecem a vermelho por baixo da linha do DX e desaparecem passados dois minutos.'],
      ['I sei messaggi Tx1-Tx6 (il nome di ciascuno: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): il pallino acceso è quello che Aurora trasmette o trasmetterà nel prossimo periodo. Un clic su una riga sceglie da quale messaggio parte il motore. Il testo si può scrivere sul posto (fino a 37 caratteri): Invio o l’uscita dal campo lo confermano, Esc annulla, svuotato torna il messaggio standard.', 'The six messages Tx1-Tx6 (the name of each: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): the lit dot is the one Aurora transmits or will transmit in the next period. A click on a row chooses which message the engine starts from. The text can be written in place (up to 37 characters): Enter or leaving the field confirms it, Esc cancels, and if you empty it the standard message comes back.', 'Die sechs Nachrichten Tx1-Tx6 (der Name jeder einzelnen: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): Der leuchtende Punkt ist die Nachricht, die Aurora im nächsten Durchgang sendet oder senden wird. Ein Klick auf eine Zeile wählt, von welcher Nachricht der Motor ausgeht. Der Text lässt sich direkt schreiben (bis zu 37 Zeichen): Enter oder das Verlassen des Feldes bestätigt ihn, Esc bricht ab, leer geräumt kehrt die Standardnachricht zurück.', 'Les six messages Tx1-Tx6 (le nom de chacun : [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]) : la pastille allumée est celle qu’Aurora émet ou émettra à la prochaine période. Un clic sur une ligne choisit à partir de quel message part le moteur. Le texte peut s’écrire sur place (jusqu’à 37 caractères) : Entrée ou la sortie du champ le confirment, Échap annule, vidé, le message standard revient.', 'Los seis mensajes Tx1-Tx6 (el nombre de cada uno: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): el punto encendido es el que Aurora transmite o transmitirá en el próximo periodo. Un clic en una fila elige desde qué mensaje parte el motor. El texto se puede escribir en el sitio (hasta 37 caracteres): Intro o salir del campo lo confirman, Esc cancela, vaciado vuelve el mensaje estándar.', 'As seis mensagens Tx1-Tx6 (o nome de cada uma: [[tx.step.1]], [[tx.step.2]], [[tx.step.3]], [[tx.step.4]], [[tx.step.5]], [[tx.step.6]]): a bolinha acesa é a que a Aurora transmite ou vai transmitir no próximo período. Um clique numa linha escolhe de que mensagem parte o motor. O texto pode escrever-se no próprio sítio (até 37 carateres): Enter ou a saída do campo confirmam-no, Esc cancela, esvaziado volta a mensagem padrão.'],
      ['La riga di «[[ctl.skip_tx1]]» attivo ha il Tx1 barrato; in Hound il Tx6 (CQ) è spento. Sotto i messaggi può comparire un breve avviso se un comando non è riuscito.', 'The row of “[[ctl.skip_tx1]]” when active has Tx1 struck through; in Hound, Tx6 (CQ) is off. Below the messages a short notice may appear if a command failed.', 'Die Zeile bei aktivem „[[ctl.skip_tx1]]“ hat Tx1 durchgestrichen; bei Hound ist Tx6 (CQ) aus. Unter den Nachrichten kann ein kurzer Hinweis erscheinen, wenn ein Befehl nicht gelungen ist.', 'La ligne de « [[ctl.skip_tx1]] » actif a le Tx1 barré ; en Hound le Tx6 (CQ) est éteint. Sous les messages, une courte alerte peut apparaître si une commande n’a pas réussi.', 'La fila de «[[ctl.skip_tx1]]» activo tiene el Tx1 tachado; en Hound el Tx6 (CQ) está apagado. Bajo los mensajes puede aparecer un breve aviso si un comando no ha funcionado.', 'A linha de «[[ctl.skip_tx1]]» ativo tem o Tx1 riscado; em Hound o Tx6 (CQ) está desligado. Por baixo das mensagens pode aparecer um breve aviso se um comando não tiver resultado.'],
    ],
  },
  {
    id: 'p-qsosw',
    title: ['Gli interruttori del QSO', 'The QSO switches', 'Die QSO-Schalter', 'Les interrupteurs du QSO', 'Los interruptores del QSO', 'Os interruptores do QSO'],
    text: ['Nel pannello [[panel.tx]], sotto i sei messaggi, il riquadro «[[ctl.sec.qso]]» ha due colonne di pulsanti. Passa il mouse su ognuno per la spiegazione; acceso = verde con il led. Spegnere è sempre permesso; accendere quelli che fanno trasmettere richiede la trasmissione aperta sul PC.', 'In the [[panel.tx]] panel, under the six messages, the “[[ctl.sec.qso]]” box has two columns of buttons. Hover over each for the explanation; on = green with the LED. Turning off is always allowed; turning on the ones that make you transmit requires transmission to be open on the PC.', 'Im Feld [[panel.tx]], unter den sechs Nachrichten, hat das Feld „[[ctl.sec.qso]]“ zwei Spalten mit Schaltflächen. Halte die Maus über jede für die Erklärung; an = grün mit der LED. Ausschalten ist immer erlaubt; Einschalten der Schalter, die zum Senden führen, verlangt, dass das Senden am PC freigegeben ist.', 'Dans le panneau [[panel.tx]], sous les six messages, l’encadré « [[ctl.sec.qso]] » a deux colonnes de boutons. Passe la souris sur chacun pour l’explication ; allumé = vert avec la led. Éteindre est toujours permis ; allumer ceux qui font émettre demande l’émission ouverte sur le PC.', 'En el panel [[panel.tx]], bajo los seis mensajes, el recuadro «[[ctl.sec.qso]]» tiene dos columnas de botones. Pasa el ratón por cada uno para ver la explicación; encendido = verde con el led. Apagar siempre está permitido; encender los que hacen transmitir exige la transmisión abierta en el PC.', 'No painel [[panel.tx]], por baixo das seis mensagens, o quadro «[[ctl.sec.qso]]» tem duas colunas de botões. Passa o rato por cima de cada um para a explicação; aceso = verde com o led. Desligar é sempre permitido; ligar os que fazem transmitir exige a transmissão aberta no PC.'],
    steps: [
      ['Colonna «[[ctl.grp.seq]]»: [[ctl.autoseq]] (la sequenza va avanti da sola: rapporto, R+rapporto, RR73, 73, e a fine QSO va a log); [[ctl.single_qso]] (dopo un QSO completato Aurora smette di trasmettere); [[ctl.answer_all]] (ogni stazione che ti chiama va in coda); [[ctl.answer_b4]] (risponde anche a chi hai già collegato); [[ctl.bypass]] (salta la verifica sui messaggi di stazioni non in lista); [[ctl.skip_tx1]] (rispondendo a un CQ parte da Tx2 invece che da Tx1; spento in Hound); [[ctl.rrr]] (la chiusura è RRR invece di RR73); [[ctl.tx_period]] (un clic passa tra i due periodi di trasmissione: «Tx 00/30» o «Tx 15/45»; rispondendo a una stazione si imposta da solo quello giusto).', '“[[ctl.grp.seq]]” column: [[ctl.autoseq]] (the sequence goes on by itself: report, R+report, RR73, 73, and at the end of the QSO it goes to the log); [[ctl.single_qso]] (after a completed QSO Aurora stops transmitting); [[ctl.answer_all]] (every station that calls you goes into the queue); [[ctl.answer_b4]] (it also replies to those you have already worked); [[ctl.bypass]] (skips the check on messages from stations not in the list); [[ctl.skip_tx1]] (when replying to a CQ it starts from Tx2 instead of Tx1; off in Hound); [[ctl.rrr]] (the closing is RRR instead of RR73); [[ctl.tx_period]] (one click switches between the two transmit periods: “Tx 00/30” or “Tx 15/45”; when you reply to a station the right one is set by itself).', 'Spalte „[[ctl.grp.seq]]“: [[ctl.autoseq]] (die Sequenz läuft von selbst weiter: Rapport, R+Rapport, RR73, 73, und am Ende des QSOs kommt es ins Log); [[ctl.single_qso]] (nach einem abgeschlossenen QSO hört Aurora auf zu senden); [[ctl.answer_all]] (jede Station, die dich ruft, kommt in die Warteschlange); [[ctl.answer_b4]] (antwortet auch denen, die du schon gearbeitet hast); [[ctl.bypass]] (überspringt die Prüfung bei Nachrichten von Stationen, die nicht auf der Liste stehen); [[ctl.skip_tx1]] (beim Antworten auf einen CQ beginnt es bei Tx2 statt bei Tx1; bei Hound aus); [[ctl.rrr]] (der Abschluss ist RRR statt RR73); [[ctl.tx_period]] (ein Klick wechselt zwischen den beiden Sendedurchgängen: „Tx 00/30“ oder „Tx 15/45“; beim Antworten auf eine Station stellt sich der richtige von selbst ein).', 'Colonne « [[ctl.grp.seq]] » : [[ctl.autoseq]] (la séquence avance toute seule : report, R+report, RR73, 73, et en fin de QSO va au log) ; [[ctl.single_qso]] (après un QSO terminé, Aurora arrête d’émettre) ; [[ctl.answer_all]] (chaque station qui t’appelle va en file) ; [[ctl.answer_b4]] (répond aussi à ceux que tu as déjà contactés) ; [[ctl.bypass]] (saute la vérification sur les messages des stations hors liste) ; [[ctl.skip_tx1]] (en répondant à un CQ, on part de Tx2 au lieu de Tx1 ; éteint en Hound) ; [[ctl.rrr]] (la clôture est RRR au lieu de RR73) ; [[ctl.tx_period]] (un clic passe d’une période d’émission à l’autre : « Tx 00/30 » ou « Tx 15/45 » ; en répondant à une station, la bonne se règle toute seule).', 'Columna «[[ctl.grp.seq]]»: [[ctl.autoseq]] (la secuencia avanza sola: informe, R+informe, RR73, 73, y al final del QSO va al log); [[ctl.single_qso]] (tras un QSO completado Aurora deja de transmitir); [[ctl.answer_all]] (cada estación que te llama pasa a la cola); [[ctl.answer_b4]] (responde también a quien ya has contactado); [[ctl.bypass]] (salta la verificación de los mensajes de estaciones que no están en la lista); [[ctl.skip_tx1]] (al responder a un CQ se parte de Tx2 en lugar de Tx1; apagado en Hound); [[ctl.rrr]] (el cierre es RRR en lugar de RR73); [[ctl.tx_period]] (un clic cambia entre los dos periodos de transmisión: «Tx 00/30» o «Tx 15/45»; al responder a una estación se ajusta solo el correcto).', 'Coluna «[[ctl.grp.seq]]»: [[ctl.autoseq]] (a sequência avança sozinha: relatório, R+relatório, RR73, 73, e no fim do QSO vai para o log); [[ctl.single_qso]] (depois de um QSO completo a Aurora deixa de transmitir); [[ctl.answer_all]] (cada estação que te chama vai para a fila); [[ctl.answer_b4]] (responde também a quem já contactaste); [[ctl.bypass]] (salta a verificação nas mensagens de estações que não estão na lista); [[ctl.skip_tx1]] (ao responder a um CQ parte do Tx2 em vez do Tx1; desligado em Hound); [[ctl.rrr]] (o fecho é RRR em vez de RR73); [[ctl.tx_period]] (um clique passa entre os dois períodos de transmissão: «Tx 00/30» ou «Tx 15/45»; ao responder a uma estação define-se sozinho o certo).'],
      ['Colonna «[[ctl.grp.tx]]»: [[ctl.enable_tx]] (al prossimo periodo Aurora trasmette); [[ctl.auto_tx]] (la trasmissione automatica: il QSO e il CQ ripartono da soli); [[ctl.wait_call]] (aspetta che il DX sia libero e poi lo chiama); [[ctl.pounce]] (con Abilita Tx spento, risponde da sola al CQ scelto). Da accesi questi quattro interruttori diventano rossi: vuol dire che Aurora può trasmettere da sola.', '“[[ctl.grp.tx]]” column: [[ctl.enable_tx]] (at the next period Aurora transmits); [[ctl.auto_tx]] (automatic transmission: the QSO and the CQ start again by themselves); [[ctl.wait_call]] (waits until the DX is free and then calls him); [[ctl.pounce]] (with Enable Tx off, it replies by itself to the chosen CQ). When on, these four switches turn red: it means Aurora may transmit by itself.', 'Spalte „[[ctl.grp.tx]]“: [[ctl.enable_tx]] (im nächsten Durchgang sendet Aurora); [[ctl.auto_tx]] (das automatische Senden: QSO und CQ starten von selbst neu); [[ctl.wait_call]] (wartet, bis der DX frei ist, und ruft ihn dann); [[ctl.pounce]] (bei ausgeschaltetem „Tx an“ antwortet es von selbst auf den gewählten CQ). Eingeschaltet werden diese vier Schalter rot: Das heißt, Aurora kann von selbst senden.', 'Colonne « [[ctl.grp.tx]] » : [[ctl.enable_tx]] (à la prochaine période Aurora émet) ; [[ctl.auto_tx]] (l’émission automatique : le QSO et le CQ repartent tout seuls) ; [[ctl.wait_call]] (attend que le DX soit libre puis l’appelle) ; [[ctl.pounce]] (avec Activer Tx éteint, répond toute seule au CQ choisi). Allumés, ces quatre interrupteurs deviennent rouges : cela veut dire qu’Aurora peut émettre toute seule.', 'Columna «[[ctl.grp.tx]]»: [[ctl.enable_tx]] (en el próximo periodo Aurora transmite); [[ctl.auto_tx]] (la transmisión automática: el QSO y el CQ vuelven a arrancar solos); [[ctl.wait_call]] (espera a que el DX esté libre y luego lo llama); [[ctl.pounce]] (con Habilitar Tx apagado, responde sola al CQ elegido). Encendidos, estos cuatro interruptores se ponen rojos: quiere decir que Aurora puede transmitir sola.', 'Coluna «[[ctl.grp.tx]]»: [[ctl.enable_tx]] (no próximo período a Aurora transmite); [[ctl.auto_tx]] (a transmissão automática: o QSO e o CQ recomeçam sozinhos); [[ctl.wait_call]] (espera que o DX esteja livre e depois chama-o); [[ctl.pounce]] (com Ativar Tx desligado, responde sozinha ao CQ escolhido). Ligados, estes quatro interruptores ficam vermelhos: quer dizer que a Aurora pode transmitir sozinha.'],
      ['Se la trasmissione è chiusa (Aurora avviata con AURORA_ALLOW_TX=0) i quattro interruttori che fanno trasmettere sono grigi e una riga lo dice: si apre solo dal PC, all’avvio. [[ctl.pounce]] si arma solo con [[ctl.enable_tx]] spento.', 'If transmission is closed (Aurora started with AURORA_ALLOW_TX=0), the four switches that make you transmit are grey and a line says so: it can only be opened from the PC, at start-up. [[ctl.pounce]] arms only with [[ctl.enable_tx]] off.', 'Ist das Senden gesperrt (Aurora mit AURORA_ALLOW_TX=0 gestartet), sind die vier Schalter, die zum Senden führen, grau, und eine Zeile sagt es: Es wird nur am PC beim Start freigegeben. [[ctl.pounce]] lässt sich nur bei ausgeschaltetem [[ctl.enable_tx]] scharf stellen.', 'Si l’émission est fermée (Aurora lancée avec AURORA_ALLOW_TX=0), les quatre interrupteurs qui font émettre sont gris et une ligne le dit : elle ne s’ouvre que depuis le PC, au démarrage. [[ctl.pounce]] ne s’arme qu’avec [[ctl.enable_tx]] éteint.', 'Si la transmisión está cerrada (Aurora iniciada con AURORA_ALLOW_TX=0) los cuatro interruptores que hacen transmitir están grises y una fila lo dice: solo se abre desde el PC, al iniciar. [[ctl.pounce]] se arma solo con [[ctl.enable_tx]] apagado.', 'Se a transmissão estiver fechada (Aurora iniciada com AURORA_ALLOW_TX=0) os quatro interruptores que fazem transmitir ficam cinzentos e uma linha di-lo: só se abre a partir do PC, no arranque. [[ctl.pounce]] arma-se só com [[ctl.enable_tx]] desligado.'],
      ['Il led dell’AutoSeq porta il livello nel testo («AutoSeq 3»). Dettagli di «[[ctl.wait_call]]» e «[[ctl.pounce]]» in «Wait and Reply e [[ctl.wait_call]]».', 'The AutoSeq LED carries the level in its text (“AutoSeq 3”). Details of “[[ctl.wait_call]]” and “[[ctl.pounce]]” are in “Wait and Reply and [[ctl.wait_call]]”.', 'Die LED des AutoSeq trägt die Stufe im Text („AutoSeq 3“). Einzelheiten zu „[[ctl.wait_call]]“ und „[[ctl.pounce]]“ unter „Wait and Reply und [[ctl.wait_call]]“.', 'La led de l’AutoSeq porte le niveau dans le texte (« AutoSeq 3 »). Détails de « [[ctl.wait_call]] » et « [[ctl.pounce]] » dans « Wait and Reply et [[ctl.wait_call]] ».', 'El led del AutoSeq lleva el nivel en el texto («AutoSeq 3»). Los detalles de «[[ctl.wait_call]]» y «[[ctl.pounce]]» están en «Wait and Reply y [[ctl.wait_call]]».', 'O led do AutoSeq leva o nível no texto («AutoSeq 3»). Detalhes de «[[ctl.wait_call]]» e «[[ctl.pounce]]» em «Wait and Reply e [[ctl.wait_call]]».'],
    ],
    tip: ['Se non parte nessuna trasmissione guarda subito [[ctl.enable_tx]]: è l’unico che deve essere acceso per trasmettere un messaggio; gli altri decidono come continua il QSO.', 'If no transmission starts, look at [[ctl.enable_tx]] first: it is the only one that must be on to send a message; the others decide how the QSO continues.', 'Startet keine Sendung, sieh sofort auf [[ctl.enable_tx]]: Das ist der einzige, der an sein muss, um eine Nachricht zu senden; die anderen bestimmen, wie das QSO weitergeht.', 'Si aucune émission ne part, regarde d’abord [[ctl.enable_tx]] : c’est le seul qui doit être allumé pour émettre un message ; les autres décident comment le QSO continue.', 'Si no sale ninguna transmisión, mira enseguida [[ctl.enable_tx]]: es el único que debe estar encendido para transmitir un mensaje; los demás deciden cómo sigue el QSO.', 'Se não arrancar nenhuma transmissão olha logo para [[ctl.enable_tx]]: é o único que tem de estar ligado para transmitir uma mensagem; os outros decidem como continua o QSO.'],
  },
  {
    id: 'p-levels',
    title: ['I livelli Rx e Pwr', 'The Rx and Pwr levels', 'Die Pegel Rx und Pwr', 'Les niveaux Rx et Pwr', 'Los niveles Rx y Pwr', 'Os níveis Rx e Pwr'],
    text: ['In fondo al pannello [[panel.tx]] (o in una riga sola, nella pagina a blocchi) ci sono due livelli audio: «Rx», l’ingresso, e «Pwr», l’uscita verso la radio.', 'At the bottom of the [[panel.tx]] panel (or in a single row, on the block-based page) there are two audio levels: “Rx”, the input, and “Pwr”, the output to the radio.', 'Unten im Feld [[panel.tx]] (oder in einer einzigen Zeile auf der Blockseite) gibt es zwei Audiopegel: „Rx“, den Eingang, und „Pwr“, den Ausgang zum Funkgerät.', 'En bas du panneau [[panel.tx]] (ou sur une seule ligne, dans la page en blocs) il y a deux niveaux audio : « Rx », l’entrée, et « Pwr », la sortie vers la radio.', 'Al fondo del panel [[panel.tx]] (o en una sola fila, en la página de bloques) hay dos niveles de audio: «Rx», la entrada, y «Pwr», la salida hacia la radio.', 'No fundo do painel [[panel.tx]] (ou numa só linha, na página em blocos) há dois níveis de áudio: «Rx», a entrada, e «Pwr», a saída para o rádio.'],
    steps: [
      ['«Rx»: un indicatore del livello dell’audio che entra (picco e livello medio in dB, passando il mouse) con un giudizio — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] o [[rxl.state.overdrive]] — e il suggerimento su cosa fare. Il livello giusto è quello «Giusto».', '“Rx”: an indicator of the level of the incoming audio (peak and average level in dB, by hovering over it) with a verdict — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] or [[rxl.state.overdrive]] — and the hint on what to do. The right level is “Good”.', '„Rx“: eine Anzeige für den Pegel des eingehenden Audios (Spitze und Mittelwert in dB, wenn du die Maus darüberhältst) mit einer Beurteilung — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] oder [[rxl.state.overdrive]] — und dem Hinweis, was zu tun ist. Der richtige Pegel ist „Gut“.', '« Rx » : un indicateur du niveau de l’audio qui entre (crête et niveau moyen en dB, en passant la souris) avec un jugement — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] ou [[rxl.state.overdrive]] — et la suggestion sur quoi faire. Le bon niveau est « Bon ».', '«Rx»: un indicador del nivel del audio que entra (pico y nivel medio en dB, al pasar el ratón) con un juicio — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] o [[rxl.state.overdrive]] — y la sugerencia de qué hacer. El nivel correcto es el «Correcto».', '«Rx»: um indicador do nível do áudio que entra (pico e nível médio em dB, passando o rato) com um juízo — [[rxl.state.silent]], [[rxl.state.low]], [[rxl.state.good]], [[rxl.state.high]] ou [[rxl.state.overdrive]] — e a sugestão do que fazer. O nível certo é o «Bom».'],
      ['Il cursore «Rx» regola il volume di registrazione di Windows e accanto ne scrive la percentuale. «[[rxl.auto]]» lo regola da solo: scende subito se il segnale satura, sale piano se resta debole; si ferma mentre trasmetti e si spegne se muovi il cursore.', 'The “Rx” slider sets the Windows recording volume and writes its percentage next to it. “[[rxl.auto]]” sets it by itself: it goes down at once if the signal saturates, goes up slowly if it stays weak; it pauses while you transmit and turns off if you move the slider.', 'Der Regler „Rx“ stellt die Aufnahmelautstärke von Windows ein und schreibt daneben den Prozentwert. „[[rxl.auto]]“ regelt ihn von selbst: Er sinkt sofort, wenn das Signal übersteuert, und steigt langsam, wenn es schwach bleibt; er pausiert, während du sendest, und schaltet sich aus, wenn du den Regler bewegst.', 'Le curseur « Rx » règle le volume d’enregistrement de Windows et écrit à côté son pourcentage. « [[rxl.auto]] » le règle tout seul : il descend tout de suite si le signal sature, monte doucement s’il reste faible ; il s’arrête pendant que tu émets et s’éteint si tu bouges le curseur.', 'El cursor «Rx» regula el volumen de grabación de Windows y al lado escribe su porcentaje. «[[rxl.auto]]» lo regula solo: baja enseguida si la señal satura, sube despacio si se queda débil; se detiene mientras transmites y se apaga si mueves el cursor.', 'O cursor «Rx» regula o volume de gravação do Windows e ao lado escreve a percentagem. «[[rxl.auto]]» regula-o sozinho: desce logo se o sinal satura, sobe devagar se continua fraco; pára enquanto transmites e desliga-se se moveres o cursor.'],
      ['«Pwr»: il livello audio di uscita (volume del mixer di Windows verso la radio, 100% sul cursore = 100% nel mixer). Se la radio va fuori ALC abbassa questo livello; per un’emissione pulita l’ALC deve restare a 0. Si regola anche a trasmissione ferma. Passando il mouse leggi percentuale e attenuazione in dB. Senza il comando radio e Aurora acceso compare «Pwr –» (vedi «Il cursore Pwr»).', '“Pwr”: the output audio level (Windows mixer volume towards the radio, 100% on the slider = 100% in the mixer). If the radio goes beyond ALC, lower this level; for a clean signal the ALC must stay at 0. It can also be set while transmission is stopped. Hovering over it you read the percentage and the attenuation in dB. Without radio control and with Aurora on, “Pwr –” appears (see “The Pwr slider”).', '„Pwr“: der Audio-Ausgangspegel (Lautstärke des Windows-Mixers zum Funkgerät, 100 % am Regler = 100 % im Mixer). Geht das Funkgerät über ALC hinaus, senke diesen Pegel; für ein sauberes Signal muss der ALC bei 0 bleiben. Er lässt sich auch bei stehendem Senden einstellen. Hältst du die Maus darüber, liest du Prozentwert und Dämpfung in dB. Ohne Funkgerätsteuerung und bei laufendem Aurora erscheint „Pwr –“ (siehe „Der Pwr-Regler“).', '« Pwr » : le niveau audio de sortie (volume du mélangeur de Windows vers la radio, 100 % sur le curseur = 100 % dans le mélangeur). Si la radio sort de l’ALC, baisse ce niveau ; pour une émission propre, l’ALC doit rester à 0. Il se règle aussi quand l’émission est arrêtée. En passant la souris tu lis le pourcentage et l’atténuation en dB. Sans la commande de la radio et avec Aurora allumé, « Pwr – » apparaît (voir « Le curseur Pwr »).', '«Pwr»: el nivel de audio de salida (volumen del mezclador de Windows hacia la radio, 100% en el cursor = 100% en el mezclador). Si la radio se sale del ALC, baja este nivel; para una emisión limpia el ALC debe quedarse en 0. También se regula con la transmisión parada. Al pasar el ratón lees el porcentaje y la atenuación en dB. Sin el mando de la radio y con Aurora encendido aparece «Pwr –» (mira «El cursor Pwr»).', '«Pwr»: o nível de áudio de saída (volume do misturador do Windows para o rádio, 100% no cursor = 100% no misturador). Se o rádio sai fora do ALC baixa este nível; para uma emissão limpa o ALC tem de ficar a 0. Regula-se também com a transmissão parada. Passando o rato lês percentagem e atenuação em dB. Sem o comando do rádio e com a Aurora ligada aparece «Pwr –» (vê «O cursor Pwr»).'],
    ],
  },
  {
    id: 'p-cmds',
    title: ['Il pannello Comandi: ogni campo e pulsante', 'The Commands panel: every field and button', 'Das Feld Befehle: jedes Feld und jede Schaltfläche', 'Le panneau Commandes : chaque champ et bouton', 'El panel Comandos: cada campo y botón', 'O painel Comandos: cada campo e botão'],
    text: ['Il pannello [[panel.station]] ha in alto tre campi numerici in grande e sotto una riga di pulsanti. È la versione completa di «Il pannello Comandi».', 'The [[panel.station]] panel has three large numeric fields at the top and a row of buttons below. It is the complete version of “The Commands panel”.', 'Das Feld [[panel.station]] hat oben drei große Zahlenfelder und darunter eine Reihe von Schaltflächen. Es ist die vollständige Version von „Das Feld Befehle“.', 'Le panneau [[panel.station]] a en haut trois champs numériques en grand et dessous une rangée de boutons. C’est la version complète de « Le panneau Commandes ».', 'El panel [[panel.station]] tiene arriba tres campos numéricos grandes y debajo una fila de botones. Es la versión completa de «El panel Comandos».', 'O painel [[panel.station]] tem em cima três campos numéricos grandes e por baixo uma linha de botões. É a versão completa de «O painel Comandos».'],
    steps: [
      ['«Tx» (200-3000 Hz) e «Rx» (100-3000 Hz): le frequenze audio. Scrivi e premi Invio, o esci dal campo, per applicarle; i campi seguono anche la cascata. Il campo Tx diventa rosso se la frequenza è fuori da 200-2700 Hz: molte radio lì tagliano la potenza (vedi «Frequenza Tx fuori da 200-2700 Hz»).', '“Tx” (200-3000 Hz) and “Rx” (100-3000 Hz): the audio frequencies. Type and press Enter, or leave the field, to apply them; the fields also follow the waterfall. The Tx field turns red if the frequency is outside 200-2700 Hz: many radios cut the power there (see “Tx frequency outside 200-2700 Hz”).', '„Tx“ (200-3000 Hz) und „Rx“ (100-3000 Hz): die Audiofrequenzen. Schreibe und drücke Enter, oder verlasse das Feld, um sie anzuwenden; die Felder folgen auch dem Wasserfall. Das Feld Tx wird rot, wenn die Frequenz außerhalb von 200-2700 Hz liegt: Viele Funkgeräte kappen dort die Leistung (siehe „Tx-Frequenz außerhalb von 200-2700 Hz“).', '« Tx » (200-3000 Hz) et « Rx » (100-3000 Hz) : les fréquences audio. Écris et appuie sur Entrée, ou sors du champ, pour les appliquer ; les champs suivent aussi la cascade. Le champ Tx devient rouge si la fréquence est hors de 200-2700 Hz : beaucoup de radios y coupent la puissance (voir « Fréquence Tx hors de 200-2700 Hz »).', '«Tx» (200-3000 Hz) y «Rx» (100-3000 Hz): las frecuencias de audio. Escribe y pulsa Intro, o sal del campo, para aplicarlas; los campos siguen también a la cascada. El campo Tx se pone rojo si la frecuencia está fuera de 200-2700 Hz: muchas radios ahí recortan la potencia (mira «Frecuencia Tx fuera de 200-2700 Hz»).', '«Tx» (200-3000 Hz) e «Rx» (100-3000 Hz): as frequências de áudio. Escreve e carrega em Enter, ou sai do campo, para as aplicar; os campos seguem também a cascata. O campo Tx fica vermelho se a frequência estiver fora de 200-2700 Hz: muitos rádios aí cortam a potência (vê «Frequência Tx fora de 200-2700 Hz»).'],
      ['La freccia ▲ accanto a Tx copia la frequenza Rx sulla Tx («[[ctl.rx_to_tx]]»); la freccia ▼ accanto a Rx copia la Tx sulla Rx («[[ctl.tx_to_rx]]»).', 'The ▲ arrow next to Tx copies the Rx frequency to Tx (“[[ctl.rx_to_tx]]”); the ▼ arrow next to Rx copies Tx to Rx (“[[ctl.tx_to_rx]]”).', 'Der Pfeil ▲ neben Tx kopiert die Rx-Frequenz auf die Tx („[[ctl.rx_to_tx]]“); der Pfeil ▼ neben Rx kopiert die Tx auf die Rx („[[ctl.tx_to_rx]]“).', 'La flèche ▲ à côté de Tx copie la fréquence Rx sur la Tx (« [[ctl.rx_to_tx]] ») ; la flèche ▼ à côté de Rx copie la Tx sur la Rx (« [[ctl.tx_to_rx]] »).', 'La flecha ▲ junto a Tx copia la frecuencia Rx en la Tx («[[ctl.rx_to_tx]]»); la flecha ▼ junto a Rx copia la Tx en la Rx («[[ctl.tx_to_rx]]»).', 'A seta ▲ ao lado de Tx copia a frequência Rx para a Tx («[[ctl.rx_to_tx]]»); a seta ▼ ao lado de Rx copia a Tx para a Rx («[[ctl.tx_to_rx]]»).'],
      ['«[[cmd.report]]» (da -50 a +49 dB): il rapporto che mandi (Tx2 e Tx3). Aurora lo mette dal segnale della stazione; scritto a mano vale subito e resta finché non arriva un altro rapporto dal motore.', '“[[cmd.report]]” (from -50 to +49 dB): the report you send (Tx2 and Tx3). Aurora sets it from the station’s signal; written by hand it applies at once and stays until another report comes from the engine.', '„[[cmd.report]]“ (von -50 bis +49 dB): der Rapport, den du sendest (Tx2 und Tx3). Aurora setzt ihn aus dem Signal der Station; von Hand geschrieben gilt er sofort und bleibt, bis vom Motor ein anderer Rapport kommt.', '« [[cmd.report]] » (de -50 à +49 dB) : le report que tu envoies (Tx2 et Tx3). Aurora le règle d’après le signal de la station ; écrit à la main, il vaut tout de suite et reste tant qu’un autre report n’arrive pas du moteur.', '«[[cmd.report]]» (de -50 a +49 dB): el informe que mandas (Tx2 y Tx3). Aurora lo pone a partir de la señal de la estación; escrito a mano vale enseguida y se queda hasta que llega otro informe del motor.', '«[[cmd.report]]» (de -50 a +49 dB): o relatório que envias (Tx2 e Tx3). A Aurora põe-no a partir do sinal da estação; escrito à mão vale logo e fica até chegar outro relatório do motor.'],
      ['«[[ctl.hold_tx]]»: tiene ferma la frequenza di trasmissione; rispondendo a una stazione si sposta solo la ricezione. Serve per restare su un punto libero.', '“[[ctl.hold_tx]]”: keeps the transmit frequency fixed; when you reply to a station only the reception moves. It is for staying on a free spot.', '„[[ctl.hold_tx]]“: hält die Sendefrequenz fest; beim Antworten auf eine Station verschiebt sich nur der Empfang. Praktisch, um auf einer freien Stelle zu bleiben.', '« [[ctl.hold_tx]] » : garde fixe la fréquence d’émission ; en répondant à une station, seule la réception se déplace. Utile pour rester sur un endroit libre.', '«[[ctl.hold_tx]]»: mantiene fija la frecuencia de transmisión; al responder a una estación solo se mueve la recepción. Sirve para quedarte en un punto libre.', '«[[ctl.hold_tx]]»: mantém parada a frequência de transmissão; ao responder a uma estação muda-se só a receção. Serve para ficar num ponto livre.'],
      ['«[[cmd.tune]]»: compare solo se lo accendi in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Trasmette una portante per accordare l’antenna; ripremuto la ferma; dura al massimo 2 minuti e serve la trasmissione aperta.', '“[[cmd.tune]]”: appears only if you turn it on in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. It transmits a carrier to tune the antenna; pressed again it stops it; it lasts at most 2 minutes and transmission must be open.', '„[[cmd.tune]]“: erscheint nur, wenn du ihn unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] einschaltest. Sendet einen Träger, um die Antenne abzustimmen; erneutes Drücken stoppt ihn; er dauert höchstens 2 Minuten, und das Senden muss freigegeben sein.', '« [[cmd.tune]] » : n’apparaît que si tu l’actives dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Il émet une porteuse pour accorder l’antenne ; un nouvel appui l’arrête ; il dure au maximum 2 minutes et demande l’émission ouverte.', '«[[cmd.tune]]»: solo aparece si lo enciendes en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Transmite una portadora para sintonizar la antena; si lo pulsas de nuevo la detiene; dura como máximo 2 minutos y hace falta la transmisión abierta.', '«[[cmd.tune]]»: aparece só se o ligares em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Transmite uma portadora para sintonizar a antena; carregado de novo pára-a; dura no máximo 2 minutos e exige a transmissão aberta.'],
      ['«[[ctl.split]]»: tiene separata la frequenza di trasmissione da quella di ricezione (split della radio). «[[cmd.logQso]]»: compare solo se acceso nello stesso posto; registra subito il QSO con il DX, per quando la sequenza non l’ha fatto da sola. «[[ctl.clear_dx]]»: libera la stazione da chiamare e i messaggi preparati.', '“[[ctl.split]]”: keeps the transmit frequency separate from the receive one (the radio’s split). “[[cmd.logQso]]”: appears only if turned on in the same place; it logs the QSO with the DX right away, for when the sequence didn’t do it by itself. “[[ctl.clear_dx]]”: frees the station to call and the prepared messages.', '„[[ctl.split]]“: hält die Sendefrequenz getrennt von der Empfangsfrequenz (Split des Funkgeräts). „[[cmd.logQso]]“: erscheint nur, wenn am selben Ort eingeschaltet; loggt sofort das QSO mit dem DX, für den Fall, dass die Sequenz es nicht von selbst getan hat. „[[ctl.clear_dx]]“: gibt die zu rufende Station und die vorbereiteten Nachrichten frei.', '« [[ctl.split]] » : garde séparées la fréquence d’émission et celle de réception (split de la radio). « [[cmd.logQso]] » : n’apparaît que s’il est activé au même endroit ; enregistre tout de suite le QSO avec le DX, pour quand la séquence ne l’a pas fait toute seule. « [[ctl.clear_dx]] » : libère la station à appeler et les messages préparés.', '«[[ctl.split]]»: mantiene separada la frecuencia de transmisión de la de recepción (split de la radio). «[[cmd.logQso]]»: solo aparece si está encendido en el mismo sitio; registra enseguida el QSO con el DX, para cuando la secuencia no lo ha hecho sola. «[[ctl.clear_dx]]»: libera la estación que hay que llamar y los mensajes preparados.', '«[[ctl.split]]»: mantém separada a frequência de transmissão da de receção (split do rádio). «[[cmd.logQso]]»: aparece só se ligado no mesmo sítio; regista logo o QSO com o DX, para quando a sequência não o fez sozinha. «[[ctl.clear_dx]]»: liberta a estação a chamar e as mensagens preparadas.'],
      ['Se compare «[[ctl.unavailable]]» i comandi di Aurora non sono raggiungibili: controlla che Aurora sia aperta sul PC.', 'If “[[ctl.unavailable]]” appears, Aurora’s controls cannot be reached: check that Aurora is open on the PC.', 'Erscheint „[[ctl.unavailable]]“, sind die Befehle von Aurora nicht erreichbar: Prüfe, ob Aurora am PC offen ist.', 'Si « [[ctl.unavailable]] » apparaît, les commandes d’Aurora ne sont pas joignables : vérifie qu’Aurora est ouverte sur le PC.', 'Si aparece «[[ctl.unavailable]]» los comandos de Aurora no están al alcance: comprueba que Aurora esté abierta en el PC.', 'Se aparecer «[[ctl.unavailable]]» os comandos da Aurora não estão acessíveis: verifica se a Aurora está aberta no PC.'],
    ],
  },
  {
    id: 'p-cqhow',
    title: ['Chiamare CQ dalla pagina Stazione', 'Calling CQ from the Station page', 'CQ rufen von der Seite Station', 'Lancer CQ depuis la page Station', 'Llamar CQ desde la página Estación', 'Chamar CQ a partir da página Estação'],
    text: ['Sul PC non c’è un pulsante «CQ»: il CQ è il sesto messaggio del pannello [[panel.tx]]. Sul telefono il pulsante «[[phone.cq]]» fa tutto in un tocco.', 'On the PC there is no “CQ” button: CQ is the sixth message of the [[panel.tx]] panel. On the phone the “[[phone.cq]]” button does everything in one tap.', 'Am PC gibt es keine Schaltfläche „CQ“: Das CQ ist die sechste Nachricht im Feld [[panel.tx]]. Auf dem Telefon macht die Schaltfläche „[[phone.cq]]“ alles mit einem Tippen.', 'Sur le PC il n’y a pas de bouton « CQ » : le CQ est le sixième message du panneau [[panel.tx]]. Sur le téléphone, le bouton « [[phone.cq]] » fait tout en un toucher.', 'En el PC no hay un botón «CQ»: el CQ es el sexto mensaje del panel [[panel.tx]]. En el teléfono el botón «[[phone.cq]]» lo hace todo con un toque.', 'No PC não há um botão «CQ»: o CQ é a sexta mensagem do painel [[panel.tx]]. No telemóvel o botão «[[phone.cq]]» faz tudo num toque.'],
    steps: [
      ['Scegli un punto libero della cascata con il tasto destro: la barra rossa Tx va lì.', 'Choose a free spot on the waterfall with the right button: the red Tx bar goes there.', 'Wähle mit der rechten Maustaste eine freie Stelle im Wasserfall: Der rote Tx-Balken geht dorthin.', 'Choisis un endroit libre de la cascade avec le clic droit : la barre rouge Tx va là.', 'Elige un punto libre de la cascada con el botón derecho: la barra roja Tx va allí.', 'Escolhe um ponto livre da cascata com o botão direito: a barra vermelha Tx vai para lá.'],
      ['Nel pannello [[panel.tx]] clicca la sesta riga («[[tx.step.6]]»): il pallino indica che Aurora parte da quel messaggio. Il testo si può scrivere sul posto (per esempio «CQ DX» o «CQ EU»); in Hound il CQ non si trasmette.', 'In the [[panel.tx]] panel click the sixth row (“[[tx.step.6]]”): the dot shows that Aurora starts from that message. The text can be written in place (for example “CQ DX” or “CQ EU”); in Hound the CQ is not transmitted.', 'Klicke im Feld [[panel.tx]] die sechste Zeile an („[[tx.step.6]]“): Der Punkt zeigt, dass Aurora von dieser Nachricht ausgeht. Der Text lässt sich direkt schreiben (zum Beispiel „CQ DX“ oder „CQ EU“); bei Hound wird das CQ nicht gesendet.', 'Dans le panneau [[panel.tx]] clique la sixième ligne (« [[tx.step.6]] ») : la pastille indique qu’Aurora part de ce message. Le texte peut s’écrire sur place (par exemple « CQ DX » ou « CQ EU ») ; en Hound le CQ n’est pas émis.', 'En el panel [[panel.tx]] haz clic en la sexta fila («[[tx.step.6]]»): el punto indica que Aurora parte de ese mensaje. El texto se puede escribir en el sitio (por ejemplo «CQ DX» o «CQ EU»); en Hound el CQ no se transmite.', 'No painel [[panel.tx]] clica na sexta linha («[[tx.step.6]]»): a bolinha indica que a Aurora parte dessa mensagem. O texto pode escrever-se no próprio sítio (por exemplo «CQ DX» ou «CQ EU»); em Hound o CQ não se transmite.'],
      ['Accendi [[ctl.enable_tx]]: al prossimo periodo Aurora trasmette il CQ. Chi ti risponde viene servito in automatico se [[ctl.autoseq]] è acceso. A QSO finito il CQ riparte da solo solo se [[ctl.auto_tx]] è acceso; con [[ctl.single_qso]] acceso, dopo un QSO Aurora smette.', 'Turn on [[ctl.enable_tx]]: at the next period Aurora transmits the CQ. Whoever answers you is served automatically if [[ctl.autoseq]] is on. When the QSO is finished, the CQ starts again by itself only if [[ctl.auto_tx]] is on; with [[ctl.single_qso]] on, after one QSO Aurora stops.', 'Schalte [[ctl.enable_tx]] ein: Im nächsten Durchgang sendet Aurora das CQ. Wer dir antwortet, wird automatisch bedient, wenn [[ctl.autoseq]] an ist. Nach dem QSO startet das CQ nur dann von selbst neu, wenn [[ctl.auto_tx]] an ist; bei eingeschaltetem [[ctl.single_qso]] hört Aurora nach einem QSO auf.', 'Active [[ctl.enable_tx]] : à la prochaine période, Aurora émet le CQ. Celui qui te répond est servi automatiquement si [[ctl.autoseq]] est allumé. Une fois le QSO fini, le CQ ne repart tout seul que si [[ctl.auto_tx]] est allumé ; avec [[ctl.single_qso]] allumé, après un QSO Aurora s’arrête.', 'Enciende [[ctl.enable_tx]]: en el próximo periodo Aurora transmite el CQ. Quien te responde es atendido automáticamente si [[ctl.autoseq]] está encendido. Al terminar el QSO el CQ vuelve a salir solo únicamente si [[ctl.auto_tx]] está encendido; con [[ctl.single_qso]] encendido, después de un QSO Aurora se detiene.', 'Liga [[ctl.enable_tx]]: no próximo período a Aurora transmite o CQ. Quem te responde é servido automaticamente se [[ctl.autoseq]] estiver ligado. No fim do QSO o CQ recomeça sozinho só se [[ctl.auto_tx]] estiver ligado; com [[ctl.single_qso]] ligado, depois de um QSO a Aurora pára.'],
      ['Per fermarti: STOP TX o il tasto Esc (vedi «Fermare la trasmissione»). Nei contest il CQ ripetuto è «[[contest.autoCq]]» (F1); con le Automazioni c’è «[[auto.autoCqOn]]».', 'To stop: STOP TX or the Esc key (see “Stopping transmission”). In contests the repeated CQ is “[[contest.autoCq]]” (F1); with the Automations there is “[[auto.autoCqOn]]”.', 'Zum Anhalten: STOP TX oder die Taste Esc (siehe „Senden stoppen“). In Contesten ist das wiederholte CQ „[[contest.autoCq]]“ (F1); bei den Automatiken gibt es „[[auto.autoCqOn]]“.', 'Pour t’arrêter : STOP TX ou la touche Échap (voir « Arrêter l’émission »). Dans les contests, le CQ répété est « [[contest.autoCq]] » (F1) ; avec les Automatisations il y a « [[auto.autoCqOn]] ».', 'Para detenerte: STOP TX o la tecla Esc (mira «Detener la transmisión»). En los concursos el CQ repetido es «[[contest.autoCq]]» (F1); con las Automatizaciones está «[[auto.autoCqOn]]».', 'Para parar: STOP TX ou a tecla Esc (vê «Parar a transmissão»). Nos concursos o CQ repetido é «[[contest.autoCq]]» (F1); com as Automações há «[[auto.autoCqOn]]».'],
    ],
  },
  {
    id: 'p-cqdxped',
    title: ['Il pannello CQ e novità e le DXpedition', 'The CQ and news panel, and DXpeditions', 'Das Feld CQ und Neues und die DXpeditionen', 'Le panneau CQ et nouveautés et les DXpéditions', 'El panel CQ y novedades y las DXpediciones', 'O painel CQ e novidades e as DXpedições'],
    text: ['Il pannello [[panel.cq]] ha due parti: a sinistra le stazioni che chiamano CQ, a destra (se il calendario NG3K è acceso) l’elenco delle DXpedition, con il titolo «[[dxp.title]]». Il contenuto dei CQ si sceglie in «[[cqp.title]]» (vedi «[[panel.cq]] e DXpedition»).', 'The [[panel.cq]] panel has two parts: on the left the stations calling CQ, on the right (if the NG3K calendar is on) the list of DXpeditions, with the title “[[dxp.title]]”. The content of the CQs is chosen in “[[cqp.title]]” (see “[[panel.cq]] and DXpeditions”).', 'Das Feld [[panel.cq]] hat zwei Teile: links die Stationen, die CQ rufen, rechts (wenn der NG3K-Kalender an ist) die Liste der DXpeditionen, mit dem Titel „[[dxp.title]]“. Den Inhalt der CQs wählst du in „[[cqp.title]]“ (siehe „[[panel.cq]] und DXpeditionen“).', 'Le panneau [[panel.cq]] a deux parties : à gauche les stations qui appellent CQ, à droite (si le calendrier NG3K est activé) la liste des DXpéditions, avec le titre « [[dxp.title]] ». Le contenu des CQ se choisit dans « [[cqp.title]] » (voir « [[panel.cq]] et DXpéditions »).', 'El panel [[panel.cq]] tiene dos partes: a la izquierda las estaciones que llaman CQ, a la derecha (si el calendario NG3K está encendido) la lista de las DXpediciones, con el título «[[dxp.title]]». El contenido de los CQ se elige en «[[cqp.title]]» (mira «[[panel.cq]] y DXpediciones»).', 'O painel [[panel.cq]] tem duas partes: à esquerda as estações que chamam CQ, à direita (se o calendário NG3K estiver ligado) a lista das DXpedições, com o título «[[dxp.title]]». O conteúdo dos CQ escolhe-se em «[[cqp.title]]» (vê «[[panel.cq]] e DXpedições»).'],
    steps: [
      ['Le caselle dei CQ stanno su due righe e scorrono da sole avanti e indietro se sono troppe (si fermano con il mouse sopra): ogni casella ha bandierina, nominativo e paese; il messaggio, il rapporto e l’ora sono nel suggerimento. Il colore è quello della novità. Doppio clic: rispondi. Tasto destro: in coda. Una stazione che non si sente da 15 minuti sparisce.', 'The CQ boxes are on two rows and scroll back and forth by themselves if there are too many (they stop with the mouse over them): each box has a flag, a callsign and a country; the message, the report and the time are in the hint. The colour is that of the news item. Double-click: you reply. Right-click: into the queue. A station not heard for 15 minutes disappears.', 'Die CQ-Kästchen stehen in zwei Zeilen und laufen von selbst vor und zurück, wenn es zu viele sind (sie halten an, wenn die Maus darüber ist): Jedes Kästchen hat Flagge, Rufzeichen und Land; die Nachricht, der Rapport und die Uhrzeit stehen im Hinweis. Die Farbe ist die der Neuheit. Doppelklick: Du antwortest. Rechtsklick: in die Warteschlange. Eine Station, die seit 15 Minuten nicht gehört wird, verschwindet.', 'Les cases des CQ sont sur deux lignes et défilent toutes seules d’avant en arrière si elles sont trop nombreuses (elles s’arrêtent avec la souris dessus) : chaque case a un petit drapeau, l’indicatif et le pays ; le message, le report et l’heure sont dans l’info-bulle. La couleur est celle de la nouveauté. Double-clic : tu réponds. Clic droit : en file. Une station qu’on n’entend plus depuis 15 minutes disparaît.', 'Las casillas de los CQ están en dos filas y se desplazan solas hacia delante y hacia atrás si son demasiadas (se detienen con el ratón encima): cada casilla tiene banderita, indicativo y país; el mensaje, el informe y la hora están en la sugerencia. El color es el de la novedad. Doble clic: respondes. Clic derecho: a la cola. Una estación que no se oye desde hace 15 minutos desaparece.', 'As caixas dos CQ ficam em duas linhas e deslizam sozinhas para a frente e para trás se forem demasiadas (param com o rato por cima): cada caixa tem bandeirinha, indicativo e país; a mensagem, o relatório e a hora estão na sugestão. A cor é a da novidade. Duplo clique: respondes. Botão direito: na fila. Uma estação que não se ouve há 15 minutos desaparece.'],
      ['Una DXpedition ha una riga con nominativo, bandiera, paese, via QSL accorciata e la data: «fino al …» (in onda), «dal …» (in arrivo, fino a 120 giorni) o «finita …» (finita, per i giorni scelti in «[[onl.dxpedDays]]»). L’etichetta «Fox/Hound» dice che la spedizione la senti lavorare in Fox/Hound (serve Hound per collegarla).', 'A DXpedition has a row with callsign, flag, country, shortened QSL route and the date: “until …” (on the air), “from …” (coming, up to 120 days ahead) or “ended …” (finished, for the days chosen in “[[onl.dxpedDays]]”). The “Fox/Hound” label says that you hear the expedition working in Fox/Hound (you need Hound to work it).', 'Eine DXpedition hat eine Zeile mit Rufzeichen, Flagge, Land, gekürztem QSL-Weg und dem Datum: „bis …“ (aktiv), „ab …“ (kommend, bis zu 120 Tage) oder „beendet …“ (beendet, für die in „[[onl.dxpedDays]]“ gewählten Tage). Das Etikett „Fox/Hound“ sagt, dass du die Expedition im Fox/Hound-Betrieb arbeiten hörst (du brauchst Hound, um sie zu arbeiten).', 'Une DXpédition a une ligne avec indicatif, drapeau, pays, voie QSL abrégée et la date : « jusqu’au … » (en l’air), « dès le … » (à venir, jusqu’à 120 jours) ou « finie … » (terminée, pour le nombre de jours choisi dans « [[onl.dxpedDays]] »). L’étiquette « Fox/Hound » dit que tu entends l’expédition travailler en Fox/Hound (il faut Hound pour la contacter).', 'Una DXpedición tiene una fila con indicativo, bandera, país, vía QSL abreviada y la fecha: «hasta el …» (en el aire), «desde el …» (próxima, hasta 120 días) o «terminó …» (terminada, durante los días elegidos en «[[onl.dxpedDays]]»). La etiqueta «Fox/Hound» dice que a la expedición la oyes trabajar en Fox/Hound (hace falta Hound para contactarla).', 'Uma DXpedição tem uma linha com indicativo, bandeira, país, via QSL abreviada e a data: «até …» (no ar), «a partir de …» (a chegar, até 120 dias) ou «terminou …» (terminada, durante os dias escolhidos em «[[onl.dxpedDays]]»). A etiqueta «Fox/Hound» diz que ouves a expedição a trabalhar em Fox/Hound (é preciso Hound para a contactar).'],
      ['Sotto il nominativo una riga «[[dxp.onAir]]» dice che un cluster l’ha spottata adesso, con frequenza, modo e da quanti minuti; doppio clic sulla frequenza porta lì la radio. «[[dxp.heardByMe]]» = l’hai decodificata tu: frequenza, modo, segnale e ora.', 'Under the callsign a “[[dxp.onAir]]” row says that a cluster has spotted it just now, with frequency, mode and how many minutes ago; double-click the frequency to move the radio there. “[[dxp.heardByMe]]” = you decoded it yourself: frequency, mode, signal and time.', 'Unter dem Rufzeichen sagt eine Zeile „[[dxp.onAir]]“, dass ein Cluster sie gerade gespottet hat, mit Frequenz, Betriebsart und seit wie vielen Minuten; Doppelklick auf die Frequenz stellt das Funkgerät dorthin. „[[dxp.heardByMe]]“ = du hast sie dekodiert: Frequenz, Betriebsart, Signal und Uhrzeit.', 'Sous l’indicatif, une ligne « [[dxp.onAir]] » dit qu’un cluster l’a spottée à l’instant, avec fréquence, mode et depuis combien de minutes ; double-clic sur la fréquence place la radio là. « [[dxp.heardByMe]] » = tu l’as décodée : fréquence, mode, signal et heure.', 'Bajo el indicativo una fila «[[dxp.onAir]]» dice que un cluster la ha spotteado ahora, con frecuencia, modo y hace cuántos minutos; doble clic en la frecuencia lleva allí la radio. «[[dxp.heardByMe]]» = la has decodificado tú: frecuencia, modo, señal y hora.', 'Por baixo do indicativo uma linha «[[dxp.onAir]]» diz que um cluster a assinalou agora, com frequência, modo e há quantos minutos; duplo clique na frequência leva lá o rádio. «[[dxp.heardByMe]]» = descodificaste-a tu: frequência, modo, sinal e hora.'],
      ['Un clic sulla riga apre la scheda della spedizione: stato (in onda, in arrivo, finita), quanto manca, se la senti, l’ultimo spot, le date, le note di NG3K, la distanza e la direzione da te, la mappa del paese e il pulsante «Vai su … kHz» che porta la radio sull’ultimo spot. Doppio clic su una spedizione sentita la chiama senza aprire la scheda. «[[dxd.close]]» o Esc chiudono la scheda.', 'A click on the row opens the expedition card: status (on the air, coming, finished), how long to go, whether you hear it, the last spot, the dates, the NG3K notes, the distance and direction from you, the map of the country and the “Tune to … kHz” button that moves the radio to the last spot. A double-click on a heard expedition calls it without opening the card. “[[dxd.close]]” or Esc closes the card.', 'Ein Klick auf die Zeile öffnet die Karte der Expedition: Zustand (aktiv, kommend, beendet), wie lange es noch dauert, ob du sie hörst, der letzte Spot, die Daten, die Hinweise von NG3K, die Entfernung und Richtung von dir, die Karte des Landes und die Schaltfläche „Auf … kHz“, die das Funkgerät auf den letzten Spot stellt. Doppelklick auf eine gehörte Expedition ruft sie, ohne die Karte zu öffnen. „[[dxd.close]]“ oder Esc schließen die Karte.', 'Un clic sur la ligne ouvre la fiche de l’expédition : état (en l’air, à venir, terminée), le temps restant, si tu l’entends, le dernier spot, les dates, les notes de NG3K, la distance et la direction depuis chez toi, la carte du pays et le bouton « Aller sur … kHz » qui place la radio sur le dernier spot. Double-clic sur une expédition entendue l’appelle sans ouvrir la fiche. « [[dxd.close]] » ou Échap ferment la fiche.', 'Un clic en la fila abre la ficha de la expedición: estado (en el aire, próxima, terminada), cuánto falta, si la oyes, el último spot, las fechas, las notas de NG3K, la distancia y la dirección desde ti, el mapa del país y el botón «Ir a … kHz» que lleva la radio al último spot. Doble clic en una expedición oída la llama sin abrir la ficha. «[[dxd.close]]» o Esc cierran la ficha.', 'Um clique na linha abre o separador da expedição: estado (no ar, a chegar, terminada), quanto falta, se a ouves, o último spot, as datas, as notas do NG3K, a distância e a direção a partir de ti, o mapa do país e o botão «Ir para … kHz» que leva o rádio para o último spot. Duplo clique numa expedição ouvida chama-a sem abrir o separador. «[[dxd.close]]» ou Esc fecham o separador.'],
      ['Se scorri a mano l’elenco, dopo 15 secondi senza toccarlo torna in cima, dove stanno le spedizioni in onda. Si accende e si spegne con «[[onl.dxped]]» in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].', 'If you scroll the list by hand, after 15 seconds without touching it, it goes back to the top, where the expeditions on the air are. It is turned on and off with “[[onl.dxped]]” in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].', 'Scrollst du die Liste von Hand, springt sie nach 15 Sekunden ohne Berührung wieder nach oben, wo die aktiven Expeditionen stehen. Sie wird mit „[[onl.dxped]]“ unter [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] ein- und ausgeschaltet.', 'Si tu fais défiler la liste à la main, après 15 secondes sans y toucher elle revient en haut, où se trouvent les expéditions en l’air. Elle s’allume et s’éteint avec « [[onl.dxped]] » dans [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].', 'Si desplazas la lista a mano, tras 15 segundos sin tocarla vuelve arriba, donde están las expediciones en el aire. Se enciende y se apaga con «[[onl.dxped]]» en [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].', 'Se deslizas a lista à mão, passados 15 segundos sem lhe tocar volta ao topo, onde estão as expedições no ar. Liga-se e desliga-se com «[[onl.dxped]]» em [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].'],
    ],
  },
  {
    id: 'p-cluster',
    title: ['Il pannello DX Cluster: filtri e colonne', 'The DX Cluster panel: filters and columns', 'Das Feld DX-Cluster: Filter und Spalten', 'Le panneau DX Cluster : filtres et colonnes', 'El panel DX Cluster: filtros y columnas', 'O painel DX Cluster: filtros e colunas'],
    text: ['Il pannello [[panel.cluster]] mostra gli spot dei server a cui sei collegato. Se è vuoto vedi anche «Il DX Cluster è vuoto». Se il cluster è spento, il pannello lo dice con il pulsante «[[cluster.settings]]»; senza il tuo nominativo nei dati di stazione, anche.', 'The [[panel.cluster]] panel shows the spots from the servers you are connected to. If it is empty, see also “The DX Cluster is empty”. If the cluster is off, the panel says so with the “[[cluster.settings]]” button; the same happens without your callsign in the station data.', 'Das Feld [[panel.cluster]] zeigt die Spots der Server, mit denen du verbunden bist. Ist es leer, sieh auch „Der DX-Cluster ist leer“. Ist der Cluster aus, sagt das Feld es mit der Schaltfläche „[[cluster.settings]]“; ebenso, wenn dein Rufzeichen in den Stationsdaten fehlt.', 'Le panneau [[panel.cluster]] montre les spots des serveurs auxquels tu es connecté. S’il est vide, vois aussi « Le DX Cluster est vide ». Si le cluster est éteint, le panneau le dit avec le bouton « [[cluster.settings]] » ; sans ton indicatif dans les données de la station, aussi.', 'El panel [[panel.cluster]] muestra los spots de los servidores a los que estás conectado. Si está vacío mira también «El DX Cluster está vacío». Si el cluster está apagado, el panel lo dice con el botón «[[cluster.settings]]»; también si falta tu indicativo en los datos de la estación.', 'O painel [[panel.cluster]] mostra os spots dos servidores a que estás ligado. Se estiver vazio vê também «O DX Cluster está vazio». Se o cluster estiver desligado, o painel di-lo com o botão «[[cluster.settings]]»; sem o teu indicativo nos dados da estação, também.'],
    steps: [
      ['In alto la barra dei filtri, che cambiano solo cosa vedi (gli spot restano in memoria): «[[cluster.filter.band]]» («[[cluster.filter.bandNow]]» = la banda su cui è la radio, oppure una o più bande), «[[cluster.filter.mode]]», «[[cluster.filter.spotter]]» («[[cluster.filter.spotterMine]]» o i continenti scelti), il pulsante «[[cluster.filter.newOnly]]» (solo spot nuovi per la tua lista dei desideri: paese, griglia, banda), il campo «[[cluster.filter.search]]».', 'At the top is the filter bar, which changes only what you see (the spots stay in memory): “[[cluster.filter.band]]” (“[[cluster.filter.bandNow]]” = the band the radio is on, or one or more bands), “[[cluster.filter.mode]]”, “[[cluster.filter.spotter]]” (“[[cluster.filter.spotterMine]]” or the chosen continents), the “[[cluster.filter.newOnly]]” button (only spots that are new for your wanted list: country, grid square, band), the “[[cluster.filter.search]]” field.', 'Oben die Filterleiste, die nur ändern, was du siehst (die Spots bleiben im Speicher): „[[cluster.filter.band]]“ („[[cluster.filter.bandNow]]“ = das Band, auf dem das Funkgerät ist, oder ein oder mehrere Bänder), „[[cluster.filter.mode]]“, „[[cluster.filter.spotter]]“ („[[cluster.filter.spotterMine]]“ oder die gewählten Kontinente), die Schaltfläche „[[cluster.filter.newOnly]]“ (nur Spots, die für deine Wunschliste neu sind: Land, Locator, Band), das Feld „[[cluster.filter.search]]“.', 'En haut la barre des filtres, qui changent seulement ce que tu vois (les spots restent en mémoire) : « [[cluster.filter.band]] » (« [[cluster.filter.bandNow]] » = la bande sur laquelle est la radio, ou une ou plusieurs bandes), « [[cluster.filter.mode]] », « [[cluster.filter.spotter]] » (« [[cluster.filter.spotterMine]] » ou les continents choisis), le bouton « [[cluster.filter.newOnly]] » (seulement les spots nouveaux pour ta liste de souhaits : pays, grille, bande), le champ « [[cluster.filter.search]] ».', 'Arriba la barra de los filtros, que solo cambian lo que ves (los spots se quedan en memoria): «[[cluster.filter.band]]» («[[cluster.filter.bandNow]]» = la banda en que está la radio, o una o más bandas), «[[cluster.filter.mode]]», «[[cluster.filter.spotter]]» («[[cluster.filter.spotterMine]]» o los continentes elegidos), el botón «[[cluster.filter.newOnly]]» (solo spots nuevos para tu lista de deseos: país, cuadrícula, banda), el campo «[[cluster.filter.search]]».', 'Em cima a barra dos filtros, que mudam só o que vês (os spots ficam em memória): «[[cluster.filter.band]]» («[[cluster.filter.bandNow]]» = a banda em que está o rádio, ou uma ou mais bandas), «[[cluster.filter.mode]]», «[[cluster.filter.spotter]]» («[[cluster.filter.spotterMine]]» ou os continentes escolhidos), o botão «[[cluster.filter.newOnly]]» (só spots novos para a tua lista de desejos: país, quadrícula, banda), o campo «[[cluster.filter.search]]».'],
      ['Nella barra del titolo del pannello, a destra: «[[ctl.spot]]» apre la finestra per mandare uno spot a DXSummit con il DX in corso e la frequenza della radio (vedi «Il pannello Comandi»); la rotella apre «[[cop.title]]», le stesse della pagina PSK · RTTY · CW e valide anche qui: «[[cop.choose]]» (doppio clic, come di base, o clic singolo; il rotore che gira verso la stazione), «[[cop.spots]]» (dopo quanti minuti uno spot sparisce) e «[[cop.columns]]». Sul telefono e nella finestra staccata i due pulsanti stanno sopra il pannello. A destra della barra dei filtri si legge a quanti server sei collegato («Collegato a n su m») oppure «[[cluster.nobody]]» (nessun server collegato).', 'In the panel title bar, on the right: “[[ctl.spot]]” opens the window to send a spot to DXSummit with the current DX and the radio frequency (see “The Commands panel”); the wheel opens “[[cop.title]]”, the same as on the PSK · RTTY · CW page and valid here too: “[[cop.choose]]” (double-click, the default, or single click; the rotator turning towards the station), “[[cop.spots]]” (after how many minutes a spot disappears) and “[[cop.columns]]”. On the phone and in the detached window the two buttons sit above the panel. On the right of the filter bar you read how many servers you are connected to (“Connected to n of m”) or “[[cluster.nobody]]” (no server connected).', 'In der Titelleiste des Feldes, rechts: „[[ctl.spot]]“ öffnet das Fenster, um einen Spot an DXSummit zu senden, mit dem aktuellen DX und der Frequenz des Funkgeräts (siehe „Das Feld Befehle“); das Zahnrad öffnet „[[cop.title]]“, dieselben wie auf der Seite PSK · RTTY · CW und auch hier gültig: „[[cop.choose]]“ (Doppelklick, wie voreingestellt, oder Einzelklick; der Rotor dreht zur Station), „[[cop.spots]]“ (nach wie vielen Minuten ein Spot verschwindet) und „[[cop.columns]]“. Auf dem Telefon und im abgetrennten Fenster stehen die beiden Schaltflächen über dem Feld. Rechts in der Filterleiste steht, mit wie vielen Servern du verbunden bist („Verbunden mit n von m“), oder „[[cluster.nobody]]“ (kein Server verbunden).', 'Dans la barre de titre du panneau, à droite : « [[ctl.spot]] » ouvre la fenêtre pour envoyer un spot à DXSummit avec le DX en cours et la fréquence de la radio (voir « Le panneau Commandes ») ; la roue dentée ouvre « [[cop.title]] », les mêmes que dans la page PSK · RTTY · CW et valables ici aussi : « [[cop.choose]] » (double clic, par défaut, ou simple clic ; le rotor qui tourne vers la station), « [[cop.spots]] » (après combien de minutes un spot disparaît) et « [[cop.columns]] ». Sur le téléphone et dans la fenêtre détachée les deux boutons sont au-dessus du panneau. À droite de la barre des filtres on lit à combien de serveurs tu es connecté (« Connecté à n sur m ») ou « [[cluster.nobody]] » (aucun serveur connecté).', 'En la barra de título del panel, a la derecha: «[[ctl.spot]]» abre la ventana para mandar un spot a DXSummit con el DX en curso y la frecuencia de la radio (mira «El panel Comandos»); la rueda dentada abre «[[cop.title]]», las mismas de la página PSK · RTTY · CW y válidas también aquí: «[[cop.choose]]» (doble clic, por defecto, o clic sencillo; el rotor que gira hacia la estación), «[[cop.spots]]» (tras cuántos minutos desaparece un spot) y «[[cop.columns]]». En el teléfono y en la ventana separada los dos botones están encima del panel. A la derecha de la barra de filtros se lee a cuántos servidores estás conectado («Conectado a n de m») o «[[cluster.nobody]]» (ningún servidor conectado).', 'Na barra de título do painel, à direita: «[[ctl.spot]]» abre a janela para enviar um spot ao DXSummit com o DX em curso e a frequência do rádio (vê «O painel Comandos»); a roda dentada abre «[[cop.title]]», as mesmas da página PSK · RTTY · CW e válidas também aqui: «[[cop.choose]]» (duplo clique, por omissão, ou clique simples; o rotor que roda para a estação), «[[cop.spots]]» (ao fim de quantos minutos um spot desaparece) e «[[cop.columns]]». No telefone e na janela destacada os dois botões ficam por cima do painel. À direita da barra dos filtros lê-se a quantos servidores estás ligado («Ligado a n de m») ou «[[cluster.nobody]]» (nenhum servidor ligado).'],
      ['Da dove parte lo spot si sceglie in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › «[[cluster.spotVia]]»: «[[cluster.spotVia.dxsummit]]» (come JTDX: lo spot compare su dxsummit.fi ma non entra nella rete dei cluster telnet) oppure «[[cluster.spotVia.telnet]]» (Aurora lo manda dal cluster collegato con il comando DX e dice «riuscito» solo quando il cluster lo ripete; da lì arriva a tutta la rete). Molti cluster accettano gli spot solo con l’accesso: accanto a ogni server ci sono «[[cluster.access.user]]» (il nominativo, anche con SSID) e «[[cluster.access.password]]», che si manda solo quando il cluster la chiede e non si mostra più dopo il salvataggio.', 'Where the spot leaves from is chosen in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › “[[cluster.spotVia]]”: “[[cluster.spotVia.dxsummit]]” (like JTDX: the spot appears on dxsummit.fi but does not enter the telnet cluster network) or “[[cluster.spotVia.telnet]]” (Aurora sends it from the connected cluster with the DX command and says “done” only when the cluster repeats it; from there it reaches the whole network). Many clusters accept spots only with a login: next to each server there are “[[cluster.access.user]]” (the callsign, also with an SSID) and “[[cluster.access.password]]”, which is sent only when the cluster asks for it and is not shown again after saving.', 'Woher der Spot kommt, wählst du unter [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › „[[cluster.spotVia]]“: „[[cluster.spotVia.dxsummit]]“ (wie JTDX: der Spot erscheint auf dxsummit.fi, gelangt aber nicht ins Netz der Telnet-Cluster) oder „[[cluster.spotVia.telnet]]“ (Aurora sendet ihn über den verbundenen Cluster mit dem Befehl DX und meldet „erledigt“ erst, wenn der Cluster ihn wiederholt; von dort erreicht er das ganze Netz). Viele Cluster nehmen Spots nur mit Anmeldung an: neben jedem Server gibt es „[[cluster.access.user]]“ (das Rufzeichen, auch mit SSID) und „[[cluster.access.password]]“, das nur auf Anfrage des Clusters gesendet und nach dem Speichern nicht mehr angezeigt wird.', 'D’où part le spot se choisit dans [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › « [[cluster.spotVia]] » : « [[cluster.spotVia.dxsummit]] » (comme JTDX : le spot apparaît sur dxsummit.fi mais n’entre pas dans le réseau des clusters telnet) ou « [[cluster.spotVia.telnet]] » (Aurora l’envoie depuis le cluster connecté avec la commande DX et ne dit « réussi » que quand le cluster le répète ; de là il atteint tout le réseau). Beaucoup de clusters n’acceptent les spots qu’avec une connexion : à côté de chaque serveur il y a « [[cluster.access.user]] » (l’indicatif, aussi avec un SSID) et « [[cluster.access.password]] », envoyé seulement quand le cluster le demande et plus affiché après l’enregistrement.', 'Desde dónde sale el spot se elige en [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › «[[cluster.spotVia]]»: «[[cluster.spotVia.dxsummit]]» (como JTDX: el spot aparece en dxsummit.fi pero no entra en la red de clústeres telnet) o «[[cluster.spotVia.telnet]]» (Aurora lo envía desde el clúster conectado con el comando DX y dice «hecho» solo cuando el clúster lo repite; desde ahí llega a toda la red). Muchos clústeres solo aceptan spots con acceso: junto a cada servidor están «[[cluster.access.user]]» (el indicativo, también con SSID) y «[[cluster.access.password]]», que solo se envía cuando el clúster la pide y no se vuelve a mostrar tras guardar.', 'De onde sai o spot escolhe-se em [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] › «[[cluster.spotVia]]»: «[[cluster.spotVia.dxsummit]]» (como no JTDX: o spot aparece em dxsummit.fi mas não entra na rede de clusters telnet) ou «[[cluster.spotVia.telnet]]» (a Aurora envia-o a partir do cluster ligado com o comando DX e só diz «feito» quando o cluster o repete; daí chega a toda a rede). Muitos clusters só aceitam spots com acesso: ao lado de cada servidor há «[[cluster.access.user]]» (o indicativo, também com SSID) e «[[cluster.access.password]]», que só é enviada quando o cluster a pede e não volta a ser mostrada depois de guardar.'],
      ['La tabella ha sette colonne: «[[cluster.col.by]]» (chi ha mandato lo spot), «[[cluster.col.freq]]» (in kHz), «[[cluster.col.call]]» (il DX), «[[cluster.col.country]]», «[[cluster.col.mode]]», «[[cluster.col.comment]]» e «[[cluster.col.time]]». Si cambia l’ordine trascinando il titolo (oppure Alt + frecce), la larghezza trascinando il bordo destro (Alt + Maiusc + frecce); tasto destro sul titolo: «[[cluster.cols.reset]]».', 'The table has seven columns: “[[cluster.col.by]]” (who sent the spot), “[[cluster.col.freq]]” (in kHz), “[[cluster.col.call]]” (the DX), “[[cluster.col.country]]”, “[[cluster.col.mode]]”, “[[cluster.col.comment]]” and “[[cluster.col.time]]”. You change the order by dragging the heading (or Alt + arrows), the width by dragging the right edge (Alt + Shift + arrows); right-click on the heading: “[[cluster.cols.reset]]”.', 'Die Tabelle hat sieben Spalten: „[[cluster.col.by]]“ (wer den Spot gesendet hat), „[[cluster.col.freq]]“ (in kHz), „[[cluster.col.call]]“ (der DX), „[[cluster.col.country]]“, „[[cluster.col.mode]]“, „[[cluster.col.comment]]“ und „[[cluster.col.time]]“. Die Reihenfolge änderst du, indem du den Titel ziehst (oder Alt + Pfeiltasten), die Breite, indem du den rechten Rand ziehst (Alt + Umschalt + Pfeiltasten); Rechtsklick auf den Titel: „[[cluster.cols.reset]]“.', 'Le tableau a sept colonnes : « [[cluster.col.by]] » (qui a envoyé le spot), « [[cluster.col.freq]] » (en kHz), « [[cluster.col.call]] » (le DX), « [[cluster.col.country]] », « [[cluster.col.mode]] », « [[cluster.col.comment]] » et « [[cluster.col.time]] ». On change l’ordre en glissant le titre (ou Alt + flèches), la largeur en glissant le bord droit (Alt + Maj + flèches) ; clic droit sur le titre : « [[cluster.cols.reset]] ».', 'La tabla tiene siete columnas: «[[cluster.col.by]]» (quién ha mandado el spot), «[[cluster.col.freq]]» (en kHz), «[[cluster.col.call]]» (el DX), «[[cluster.col.country]]», «[[cluster.col.mode]]», «[[cluster.col.comment]]» y «[[cluster.col.time]]». El orden se cambia arrastrando el título (o con Alt + flechas), la anchura arrastrando el borde derecho (Alt + Mayús + flechas); clic derecho en el título: «[[cluster.cols.reset]]».', 'A tabela tem sete colunas: «[[cluster.col.by]]» (quem enviou o spot), «[[cluster.col.freq]]» (em kHz), «[[cluster.col.call]]» (o DX), «[[cluster.col.country]]», «[[cluster.col.mode]]», «[[cluster.col.comment]]» e «[[cluster.col.time]]». A ordem muda-se arrastando o título (ou Alt + setas), a largura arrastando a margem direita (Alt + Shift + setas); botão direito no título: «[[cluster.cols.reset]]».'],
      ['Colori delle righe: evidenziata la banda dove sei; fondo diverso per le stazioni della lista dei desiderati e per le DXpedition in onda secondo NG3K (il colore si sceglie in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).', 'Row colours: the band you are on is highlighted; a different background for the stations of the wanted list and for the DXpeditions on the air according to NG3K (the colour is chosen in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).', 'Farben der Zeilen: Das Band, auf dem du bist, ist hervorgehoben; ein anderer Hintergrund für die Stationen der Wunschliste und für die aktiven DXpeditionen laut NG3K (die Farbe wählst du unter [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).', 'Couleurs des lignes : la bande où tu es est surlignée ; fond différent pour les stations de la liste des recherchées et pour les DXpéditions en l’air selon NG3K (la couleur se choisit dans [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).', 'Colores de las filas: resaltada la banda donde estás; fondo distinto para las estaciones de la lista de deseadas y para las DXpediciones en el aire según NG3K (el color se elige en [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).', 'Cores das linhas: realçada a banda onde estás; fundo diferente para as estações da lista dos desejados e para as DXpedições no ar segundo o NG3K (a cor escolhe-se em [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]).'],
      ['Doppio clic su una riga: la radio va sulla frequenza dello spot, senza trasmettere. Basta un clic singolo se lo scegli nella rotella (sotto). Con «UP 5» nel commento e Split DX acceso la radio va anche in split (vedi «Split DX dal DX Cluster»). Passando il mouse sul nominativo compare il riquadro della stazione; tasto destro su DX o DE: «Apri su QRZ.com».', 'Double-click on a row: the radio goes to the spot frequency, without transmitting. A single click is enough if you choose it in the wheel (below). With “UP 5” in the comment and Split DX on, the radio also goes into split (see “DX split from the DX Cluster”). Hovering over the callsign shows the station card; right-click on DX or DE: “Open on QRZ.com”.', 'Doppelklick auf eine Zeile: Das Funkgerät geht auf die Frequenz des Spots, ohne zu senden. Ein einzelner Klick genügt, wenn du das im Zahnrad wählst (unten). Mit „UP 5“ im Kommentar und eingeschaltetem Split DX geht das Funkgerät auch in Split (siehe „Split DX aus dem DX-Cluster“). Hältst du die Maus über das Rufzeichen, erscheint das Feld der Station; Rechtsklick auf DX oder DE: „Auf QRZ.com öffnen“.', 'Double-clic sur une ligne : la radio va sur la fréquence du spot, sans émettre. Un simple clic suffit si tu le choisis dans la roue dentée (plus bas). Avec « UP 5 » dans le commentaire et Split DX actif, la radio passe aussi en split (voir « Split DX depuis le DX Cluster »). En passant la souris sur l’indicatif, l’encadré de la station apparaît ; clic droit sur DX ou DE : « Ouvrir sur QRZ.com ».', 'Doble clic en una fila: la radio va a la frecuencia del spot, sin transmitir. Basta un clic sencillo si lo eliges en la rueda dentada (abajo). Con «UP 5» en el comentario y Split DX encendido la radio también pasa a split (mira «Split DX desde el DX Cluster»). Al pasar el ratón por el indicativo aparece el recuadro de la estación; clic derecho en DX o DE: «Abrir en QRZ.com».', 'Duplo clique numa linha: o rádio vai para a frequência do spot, sem transmitir. Basta um clique simples se o escolheres na roda dentada (abaixo). Com «UP 5» no comentário e Split DX ligado o rádio vai também em split (vê «Split DX a partir do DX Cluster»). Passando o rato por cima do indicativo aparece o quadro da estação; botão direito em DX ou DE: «Abrir no QRZ.com».'],
      ['La colonna Modo viene dal commento o dalla frequenza (vedi «Il modo degli spot del DX Cluster»). Il commento intero si legge passando il mouse sulla cella.', 'The Mode column comes from the comment or from the frequency (see “The mode of DX Cluster spots”). The whole comment is read by hovering over the cell.', 'Die Spalte Modus kommt aus dem Kommentar oder aus der Frequenz (siehe „Die Betriebsart der DX-Cluster-Spots“). Den ganzen Kommentar liest du, wenn du die Maus über die Zelle hältst.', 'La colonne Mode vient du commentaire ou de la fréquence (voir « Le mode des spots du DX Cluster »). Le commentaire entier se lit en passant la souris sur la cellule.', 'La columna Modo viene del comentario o de la frecuencia (mira «El modo de los spots del DX Cluster»). El comentario entero se lee pasando el ratón por la celda.', 'A coluna Modo vem do comentário ou da frequência (vê «O modo dos spots do DX Cluster»). O comentário inteiro lê-se passando o rato por cima da célula.'],
    ],
  },
  {
    id: 'p-logpanel',
    title: ['Il pannello Log e la scheda DXCC', 'The Log panel and the DXCC card', 'Das Log-Feld und die DXCC-Karte', 'Le panneau Journal et l’onglet DXCC', 'El panel Log y la ficha DXCC', 'O painel Log e o separador DXCC'],
    text: ['Il pannello Log ha tre linguette nella barra del titolo: «[[log.tab.log]]» (o «[[log.tab.internal]]» se non c’è un log esterno), «[[log.tab.map]]» e «RX» (la Finestra RX). Nella barra, a destra, il totale dei QSO («n QSO»).', 'The Log panel has three tabs in the title bar: “[[log.tab.log]]” (or “[[log.tab.internal]]” if there is no external log), “[[log.tab.map]]” and “RX” (the RX window). In the bar, on the right, the total of QSOs (“n QSOs”).', 'Das Log-Feld hat drei Reiter in der Titelleiste: „[[log.tab.log]]“ (oder „[[log.tab.internal]]“, wenn es kein externes Log gibt), „[[log.tab.map]]“ und „RX“ (das RX-Fenster). In der Leiste rechts die Gesamtzahl der QSOs („n QSOs“).', 'Le panneau Journal a trois onglets dans la barre de titre : « [[log.tab.log]] » (ou « [[log.tab.internal]] » s’il n’y a pas de log externe), « [[log.tab.map]] » et « RX » (la Fenêtre RX). Dans la barre, à droite, le total des QSO (« n QSO »).', 'El panel Log tiene tres pestañas en la barra del título: «[[log.tab.log]]» (o «[[log.tab.internal]]» si no hay un log externo), «[[log.tab.map]]» y «RX» (la Ventana RX). En la barra, a la derecha, el total de los QSO («n QSO»).', 'O painel Log tem três separadores na barra do título: «[[log.tab.log]]» (ou «[[log.tab.internal]]» se não houver um log externo), «[[log.tab.map]]» e «RX» (a Janela RX). Na barra, à direita, o total dos QSO («n QSO»).'],
    steps: [
      ['Con la linguetta del log vedi gli ultimi QSO, quelli di Log4OM2 se Aurora legge il suo log (solo lettura) altrimenti quelli del log interno di Aurora. Colonne: «[[log.col.date]]», «[[log.col.call]]», «[[log.col.band]]», «[[log.col.mode]]», «[[log.col.rst]]» (inviato e ricevuto), «[[log.col.country]]». I titoli si trascinano e si ridimensionano come quelli del DX Cluster; tasto destro sul titolo ripristina.', 'With the log tab you see the latest QSOs, those of Log4OM2 if Aurora reads its log (read only), otherwise those of Aurora’s internal log. Columns: “[[log.col.date]]”, “[[log.col.call]]”, “[[log.col.band]]”, “[[log.col.mode]]”, “[[log.col.rst]]” (sent and received), “[[log.col.country]]”. The headings are dragged and resized like those of the DX Cluster; right-click on the heading resets them.', 'Mit dem Log-Reiter siehst du die letzten QSOs, die von Log4OM2, wenn Aurora dessen Log liest (nur lesend), sonst die des internen Logs von Aurora. Spalten: „[[log.col.date]]“, „[[log.col.call]]“, „[[log.col.band]]“, „[[log.col.mode]]“, „[[log.col.rst]]“ (gesendet und empfangen), „[[log.col.country]]“. Die Titel lassen sich wie die des DX-Clusters ziehen und in der Größe ändern; Rechtsklick auf den Titel setzt zurück.', 'Avec l’onglet du log tu vois les derniers QSO, ceux de Log4OM2 si Aurora lit son log (lecture seule), sinon ceux du log interne d’Aurora. Colonnes : « [[log.col.date]] », « [[log.col.call]] », « [[log.col.band]] », « [[log.col.mode]] », « [[log.col.rst]] » (envoyé et reçu), « [[log.col.country]] ». Les titres se glissent et se redimensionnent comme ceux du DX Cluster ; clic droit sur le titre pour réinitialiser.', 'Con la pestaña del log ves los últimos QSO, los de Log4OM2 si Aurora lee su log (solo lectura) y si no los del log interno de Aurora. Columnas: «[[log.col.date]]», «[[log.col.call]]», «[[log.col.band]]», «[[log.col.mode]]», «[[log.col.rst]]» (enviado y recibido), «[[log.col.country]]». Los títulos se arrastran y se redimensionan como los del DX Cluster; clic derecho en el título los restablece.', 'Com o separador do log vês os últimos QSO, os do Log4OM2 se a Aurora lê o seu log (só leitura), senão os do log interno da Aurora. Colunas: «[[log.col.date]]», «[[log.col.call]]», «[[log.col.band]]», «[[log.col.mode]]», «[[log.col.rst]]» (enviado e recebido), «[[log.col.country]]». Os títulos arrastam-se e redimensionam-se como os do DX Cluster; botão direito no título repõe.'],
      ['Un QSO appena registrato lampeggia in cima con l’etichetta «[[log.loggedBadge]]». Con la linguetta «[[log.tab.map]]» aperta, a ogni QSO a log il pannello passa un attimo al Log, fa vedere la riga nuova e poi torna alla mappa.', 'A QSO just logged flashes at the top with the “[[log.loggedBadge]]” label. With the “[[log.tab.map]]” tab open, at every QSO logged the panel switches for a moment to the Log, shows the new row and then goes back to the map.', 'Ein gerade gespeichertes QSO blinkt oben mit dem Etikett „[[log.loggedBadge]]“. Ist der Reiter „[[log.tab.map]]“ offen, wechselt das Feld bei jedem geloggten QSO kurz zum Log, zeigt die neue Zeile und kehrt dann zur Karte zurück.', 'Un QSO tout juste enregistré clignote en haut avec l’étiquette « [[log.loggedBadge]] ». Avec l’onglet « [[log.tab.map]] » ouvert, à chaque QSO enregistré, le panneau passe un instant au Journal, fait voir la nouvelle ligne puis revient à la carte.', 'Un QSO recién registrado parpadea arriba con la etiqueta «[[log.loggedBadge]]». Con la pestaña «[[log.tab.map]]» abierta, en cada QSO al log el panel pasa un momento al Log, muestra la fila nueva y luego vuelve al mapa.', 'Um QSO acabado de registar pisca no topo com a etiqueta «[[log.loggedBadge]]». Com o separador «[[log.tab.map]]» aberto, a cada QSO no log o painel passa um instante ao Log, mostra a linha nova e depois volta ao mapa.'],
      ['Doppio clic su una riga del log interno: si apre la finestra per correggere o cancellare il QSO (vedi «Correggere o cancellare un QSO»). Nel log di Log4OM2 si legge «[[log.readonly4om]]».', 'Double-click on a row of the internal log: the window to correct or delete the QSO opens (see “Correcting or deleting a QSO”). In the Log4OM2 log you read “[[log.readonly4om]]”.', 'Doppelklick auf eine Zeile des internen Logs: Es öffnet sich das Fenster, um das QSO zu korrigieren oder zu löschen (siehe „Ein QSO korrigieren oder löschen“). Im Log von Log4OM2 liest du „[[log.readonly4om]]“.', 'Double-clic sur une ligne du log interne : la fenêtre pour corriger ou supprimer le QSO s’ouvre (voir « Corriger ou supprimer un QSO »). Dans le log de Log4OM2 on lit « [[log.readonly4om]] ».', 'Doble clic en una fila del log interno: se abre la ventana para corregir o borrar el QSO (mira «Corregir o borrar un QSO»). En el log de Log4OM2 se lee «[[log.readonly4om]]».', 'Duplo clique numa linha do log interno: abre-se a janela para corrigir ou apagar o QSO (vê «Corrigir ou apagar um QSO»). No log do Log4OM2 lê-se «[[log.readonly4om]]».'],
      ['Se il log è vuoto compare «[[cta.log.none]]» con il pulsante «[[cta.log.go]]», che porta alle impostazioni dei log. Quanti QSO vedere si sceglie in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] («[[gen.log4omCount]]»).', 'If the log is empty, “[[cta.log.none]]” appears with the “[[cta.log.go]]” button, which leads to the log settings. How many QSOs to show is chosen in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] (“[[gen.log4omCount]]”).', 'Ist das Log leer, erscheint „[[cta.log.none]]“ mit der Schaltfläche „[[cta.log.go]]“, die zu den Log-Einstellungen führt. Wie viele QSOs du siehst, wählst du unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] („[[gen.log4omCount]]“).', 'Si le log est vide, « [[cta.log.none]] » apparaît avec le bouton « [[cta.log.go]] », qui mène aux réglages des logs. Combien de QSO voir se choisit dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] (« [[gen.log4omCount]] »).', 'Si el log está vacío aparece «[[cta.log.none]]» con el botón «[[cta.log.go]]», que lleva a los ajustes de los logs. Cuántos QSO ver se elige en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] («[[gen.log4omCount]]»).', 'Se o log estiver vazio aparece «[[cta.log.none]]» com o botão «[[cta.log.go]]», que leva às definições dos logs. Quantos QSO ver escolhe-se em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] («[[gen.log4omCount]]»).'],
      ['Sotto il log c’è la scheda DXCC della stazione che stai chiamando (vedi «La scheda DXCC»). La linguetta «[[log.tab.map]]» mostra la Mappa DX della banda in uso (vedi «La mappa nel pannello Log»).', 'Under the log is the DXCC card of the station you are calling (see “The DXCC card”). The “[[log.tab.map]]” tab shows the DX Map of the band in use (see “The map in the Log panel”).', 'Unter dem Log liegt die DXCC-Karte der Station, die du rufst (siehe „Die DXCC-Karte“). Der Reiter „[[log.tab.map]]“ zeigt die DX-Karte des benutzten Bandes (siehe „Die Karte im Log-Bereich“).', 'Sous le log il y a l’onglet DXCC de la station que tu appelles (voir « L’onglet DXCC »). L’onglet « [[log.tab.map]] » montre la Carte DX de la bande en cours (voir « La carte dans le panneau Journal »).', 'Bajo el log está la ficha DXCC de la estación que estás llamando (mira «La ficha DXCC»). La pestaña «[[log.tab.map]]» muestra el Mapa DX de la banda en uso (mira «El mapa en el panel Log»).', 'Por baixo do log está o separador DXCC da estação que estás a chamar (vê «O separador DXCC»). O separador «[[log.tab.map]]» mostra o Mapa DX da banda em uso (vê «O mapa no painel Log»).'],
    ],
  },
  {
    id: 'p-dxcc',
    title: ['La scheda DXCC', 'The DXCC card', 'Die DXCC-Karte', 'L’onglet DXCC', 'La ficha DXCC', 'O separador DXCC'],
    text: ['La scheda DXCC dice se la stazione che stai chiamando è un paese nuovo per te. Sta nel pannello Log, e per intero nella pagina [[nav.stats]]. Si regola in [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (quali righe e bande, il totale, il campo «Prova», le didascalie).', 'The DXCC card tells you whether the station you are calling is a new country for you. It is in the Log panel, and in full on the [[nav.stats]] page. It is adjusted in [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (which rows and bands, the total, the “Try” field, the captions).', 'Die DXCC-Karte sagt, ob die Station, die du rufst, ein neues Land für dich ist. Sie sitzt im Log-Feld und vollständig auf der Seite [[nav.stats]]. Eingestellt wird sie unter [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (welche Zeilen und Bänder, die Summe, das Feld „Testen“, die Beschriftungen).', 'L’onglet DXCC dit si la station que tu appelles est un nouveau pays pour toi. Il se trouve dans le panneau Journal, et en entier dans la page [[nav.stats]]. Il se règle dans [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (quelles lignes et bandes, le total, le champ « Essai », les légendes).', 'La ficha DXCC dice si la estación que estás llamando es un país nuevo para ti. Está en el panel Log, y entera en la página [[nav.stats]]. Se ajusta en [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (qué filas y bandas, el total, el campo «Prueba», los rótulos).', 'O separador DXCC diz se a estação que estás a chamar é um país novo para ti. Está no painel Log e, por inteiro, na página [[nav.stats]]. Regula-se em [[nav.settings]] › [[sw.fam.log]] › [[tab.dxcc]] (que linhas e bandas, o total, o campo «Testar», as legendas).'],
    steps: [
      ['Sopra, sei etichette: tre per il paese — «NEW ONE» (mai collegato su nessuna banda né modo), «NEW BAND» (mai su questa banda), «NEW MODE» (mai in questo modo) — e tre per il locatore: «NEW GRID», «GRID BAND» e «GRID MODE». Si accendono quando valgono per la stazione; passando il mouse leggi cosa vuol dire ognuna.', 'At the top, six labels: three for the country — “NEW ONE” (never worked on any band or mode), “NEW BAND” (never on this band), “NEW MODE” (never in this mode) — and three for the locator: “NEW GRID”, “GRID BAND” and “GRID MODE”. They light up when they apply to the station; hovering over them you read what each one means.', 'Oben sechs Etiketten: drei für das Land — „NEW ONE“ (nie gearbeitet, auf keinem Band und in keiner Betriebsart), „NEW BAND“ (nie auf diesem Band), „NEW MODE“ (nie in dieser Betriebsart) — und drei für den Locator: „NEW GRID“, „GRID BAND“ und „GRID MODE“. Sie leuchten, wenn sie für die Station gelten; wenn du die Maus darüberhältst, liest du, was jedes bedeutet.', 'En haut, six étiquettes : trois pour le pays — « NEW ONE » (jamais contacté sur aucune bande ni mode), « NEW BAND » (jamais sur cette bande), « NEW MODE » (jamais dans ce mode) — et trois pour le locator : « NEW GRID », « GRID BAND » et « GRID MODE ». Elles s’allument quand elles valent pour la station ; en passant la souris tu lis ce que veut dire chacune.', 'Arriba, seis etiquetas: tres para el país — «NEW ONE» (nunca contactado en ninguna banda ni modo), «NEW BAND» (nunca en esta banda), «NEW MODE» (nunca en este modo) — y tres para el localizador: «NEW GRID», «GRID BAND» y «GRID MODE». Se encienden cuando valen para la estación; al pasar el ratón lees qué quiere decir cada una.', 'Em cima, seis etiquetas: três para o país — «NEW ONE» (nunca contactado em nenhuma banda nem modo), «NEW BAND» (nunca nesta banda), «NEW MODE» (nunca neste modo) — e três para o locator: «NEW GRID», «GRID BAND» e «GRID MODE». Acendem-se quando valem para a estação; passando o rato lês o que quer dizer cada uma.'],
      ['La tabella ha una riga per modo (FT8, FT4 e DIG, cioè gli altri modi digitali) e una colonna per banda, da 160 m a 4 m più «U» (le bande più corte di 4 m). Con una stazione scelta mostra il suo paese: verde = lavorato (e confermato, o il log non dice niente sulle conferme), arancio = lavorato ma non confermato, grigio = mai. Senza stazione mostra quanti paesi hai lavorato per casella.', 'The table has a row for each mode (FT8, FT4 and DIG, meaning the other digital modes) and a column for each band, from 160 m to 4 m plus “U” (the bands shorter than 4 m). With a station chosen it shows its country: green = worked (and confirmed, or the log says nothing about confirmations), orange = worked but not confirmed, grey = never. With no station it shows how many countries you have worked per box.', 'Die Tabelle hat eine Zeile pro Betriebsart (FT8, FT4 und DIG, also die anderen digitalen Betriebsarten) und eine Spalte pro Band, von 160 m bis 4 m plus „U“ (die Bänder kürzer als 4 m). Mit gewählter Station zeigt sie deren Land: grün = gearbeitet (und bestätigt, oder das Log sagt nichts über Bestätigungen), orange = gearbeitet, aber nicht bestätigt, grau = nie. Ohne Station zeigt sie, wie viele Länder du pro Feld gearbeitet hast.', 'Le tableau a une ligne par mode (FT8, FT4 et DIG, c’est-à-dire les autres modes numériques) et une colonne par bande, de 160 m à 4 m plus « U » (les bandes plus courtes que 4 m). Avec une station choisie, il montre son pays : vert = contacté (et confirmé, ou le log ne dit rien sur les confirmations), orange = contacté mais non confirmé, gris = jamais. Sans station, il montre combien de pays tu as contactés par case.', 'La tabla tiene una fila por modo (FT8, FT4 y DIG, es decir los demás modos digitales) y una columna por banda, de 160 m a 4 m más «U» (las bandas más cortas de 4 m). Con una estación elegida muestra su país: verde = trabajado (y confirmado, o el log no dice nada sobre las confirmaciones), naranja = trabajado pero no confirmado, gris = nunca. Sin estación muestra cuántos países has trabajado por casilla.', 'A tabela tem uma linha por modo (FT8, FT4 e DIG, isto é, os outros modos digitais) e uma coluna por banda, de 160 m a 4 m mais «U» (as bandas mais curtas do que 4 m). Com uma estação escolhida mostra o país dela: verde = trabalhado (e confirmado, ou o log não diz nada sobre as confirmações), laranja = trabalhado mas não confirmado, cinzento = nunca. Sem estação mostra quantos países trabalhaste por casa.'],
      ['Il numero in alto a sinistra è il totale dei paesi lavorati; in basso quanti paesi hai lavorato su quanti ce ne sono, e il numero di QSO nel log.', 'The number at the top left is the total of countries worked; at the bottom, how many countries you have worked out of how many exist, and the number of QSOs in the log.', 'Die Zahl oben links ist die Summe der gearbeiteten Länder; unten, wie viele Länder du von wie vielen gearbeitet hast, und die Zahl der QSOs im Log.', 'Le nombre en haut à gauche est le total des pays contactés ; en bas, combien de pays tu as contactés sur combien il y en a, et le nombre de QSO dans le log.', 'El número de arriba a la izquierda es el total de los países trabajados; abajo cuántos países has trabajado de cuántos hay, y el número de QSO del log.', 'O número em cima à esquerda é o total dos países trabalhados; em baixo quantos países trabalhaste em quantos existem, e o número de QSO no log.'],
      ['Il campo «[[dxcc.tryCall]]» (solo se acceso nelle impostazioni): scrivi un nominativo per vedere di che paese è e se l’hai già lavorato, senza chiamarlo. Nella pagina [[nav.stats]] i pulsanti «[[dxcc.view.station]]» e «[[dxcc.view.totals]]» passano dal paese della stazione ai totali.', 'The “[[dxcc.tryCall]]” field (only if turned on in the settings): type a callsign to see which country it is and whether you have already worked it, without calling it. On the [[nav.stats]] page the “[[dxcc.view.station]]” and “[[dxcc.view.totals]]” buttons switch from the station’s country to the totals.', 'Das Feld „[[dxcc.tryCall]]“ (nur wenn in den Einstellungen eingeschaltet): Schreibe ein Rufzeichen, um zu sehen, aus welchem Land es ist und ob du es schon gearbeitet hast, ohne es zu rufen. Auf der Seite [[nav.stats]] wechseln die Schaltflächen „[[dxcc.view.station]]“ und „[[dxcc.view.totals]]“ vom Land der Station zu den Summen.', 'Le champ « [[dxcc.tryCall]] » (seulement s’il est activé dans les réglages) : écris un indicatif pour voir de quel pays il est et si tu l’as déjà contacté, sans l’appeler. Dans la page [[nav.stats]] les boutons « [[dxcc.view.station]] » et « [[dxcc.view.totals]] » passent du pays de la station aux totaux.', 'El campo «[[dxcc.tryCall]]» (solo si está encendido en los ajustes): escribe un indicativo para ver de qué país es y si ya lo has trabajado, sin llamarlo. En la página [[nav.stats]] los botones «[[dxcc.view.station]]» y «[[dxcc.view.totals]]» pasan del país de la estación a los totales.', 'O campo «[[dxcc.tryCall]]» (só se ligado nas definições): escreve um indicativo para ver de que país é e se já o trabalhaste, sem o chamar. Na página [[nav.stats]] os botões «[[dxcc.view.station]]» e «[[dxcc.view.totals]]» passam do país da estação para os totais.'],
      ['I dati vengono dal log interno di Aurora (e da Log4OM2 se è collegato) e dal file dei prefissi cty.dat; si aggiornano da soli a ogni QSO registrato. Se manca uno dei due la scheda dice «[[dxcc.unavailable]]».', 'The data comes from Aurora’s internal log (and from Log4OM2 if connected) and from the cty.dat prefix file; it updates by itself at every QSO logged. If one of the two is missing, the card says “[[dxcc.unavailable]]”.', 'Die Daten kommen aus dem internen Log von Aurora (und von Log4OM2, wenn es verbunden ist) und aus der Präfixdatei cty.dat; sie aktualisieren sich bei jedem gespeicherten QSO von selbst. Fehlt eines von beiden, sagt die Karte „[[dxcc.unavailable]]“.', 'Les données viennent du log interne d’Aurora (et de Log4OM2 s’il est connecté) et du fichier des préfixes cty.dat ; elles se mettent à jour toutes seules à chaque QSO enregistré. Si l’un des deux manque, l’onglet dit « [[dxcc.unavailable]] ».', 'Los datos vienen del log interno de Aurora (y de Log4OM2 si está conectado) y del archivo de prefijos cty.dat; se actualizan solos en cada QSO registrado. Si falta uno de los dos la ficha dice «[[dxcc.unavailable]]».', 'Os dados vêm do log interno da Aurora (e do Log4OM2 se estiver ligado) e do ficheiro dos prefixos cty.dat; atualizam-se sozinhos a cada QSO registado. Se faltar um dos dois o separador diz «[[dxcc.unavailable]]».'],
    ],
  },
  {
    id: 'p-detach',
    title: ['Finestre a parte e disposizione', 'Separate windows and layout', 'Eigene Fenster und Anordnung', 'Fenêtres détachées et disposition', 'Ventanas aparte y disposición', 'Janelas à parte e disposição'],
    text: ['Ogni pannello della pagina Stazione ha in alto a destra il pulsante ⧉ («[[win.detach]]»): serve per portare quel pannello su un secondo schermo. Le misure dei pannelli sono fisse; vedi anche «La pagina principale a blocchi».', 'Each panel of the Station page has the ⧉ button at the top right (“[[win.detach]]”): it is used to move that panel to a second screen. The panel sizes are fixed; see also “The block-based main page”.', 'Jedes Feld der Seite Station hat oben rechts die Schaltfläche ⧉ („[[win.detach]]“): Damit bringst du dieses Feld auf einen zweiten Bildschirm. Die Maße der Felder sind fest; siehe auch „Die Hauptseite aus Blöcken“.', 'Chaque panneau de la page Station a en haut à droite le bouton ⧉ (« [[win.detach]] ») : il sert à amener ce panneau sur un deuxième écran. Les dimensions des panneaux sont fixes ; voir aussi « La page principale en blocs ».', 'Cada panel de la página Estación tiene arriba a la derecha el botón ⧉ («[[win.detach]]»): sirve para llevar ese panel a una segunda pantalla. Las medidas de los paneles son fijas; mira también «La página principal en bloques».', 'Cada painel da página Estação tem em cima à direita o botão ⧉ («[[win.detach]]»): serve para levar esse painel para um segundo ecrã. As medidas dos painéis são fixas; vê também «A página principal em blocos».'],
    steps: [
      ['Clic su ⧉: si apre un piccolo menu con «[[win.new]]» (una finestra nuova con quel solo pannello), «[[win.dash]]» (la dashboard a blocchi, dove si raccolgono più pannelli) e, se c’è già una finestra a parte, «Accanto a: …» per affiancare il pannello a quelli di quella finestra.', 'Click ⧉: a small menu opens with “[[win.new]]” (a new window with only that panel), “[[win.dash]]” (the block dashboard, where several panels are gathered) and, if there is already a separate window, “Next to: …” to place the panel beside those of that window.', 'Klick auf ⧉: Es öffnet sich ein kleines Menü mit „[[win.new]]“ (ein neues Fenster mit nur diesem Feld), „[[win.dash]]“ (das Dashboard aus Blöcken, in dem mehrere Felder gesammelt werden) und, wenn es schon ein eigenes Fenster gibt, „Neben: …“, um das Feld neben die Felder dieses Fensters zu setzen.', 'Clic sur ⧉ : un petit menu s’ouvre avec « [[win.new]] » (une nouvelle fenêtre avec ce seul panneau), « [[win.dash]] » (le tableau de bord en blocs, où l’on rassemble plusieurs panneaux) et, s’il y a déjà une fenêtre détachée, « À côté de : … » pour placer le panneau à côté de ceux de cette fenêtre.', 'Clic en ⧉: se abre un pequeño menú con «[[win.new]]» (una ventana nueva con solo ese panel), «[[win.dash]]» (el dashboard de bloques, donde se reúnen varios paneles) y, si ya hay una ventana aparte, «Junto a: …» para poner el panel junto a los de esa ventana.', 'Clica em ⧉: abre-se um pequeno menu com «[[win.new]]» (uma janela nova com esse único painel), «[[win.dash]]» (a dashboard em blocos, onde se reúnem vários painéis) e, se já existir uma janela à parte, «Ao lado de: …» para pôr o painel junto aos dessa janela.'],
      ['Un pannello staccato non si vede più nella finestra principale; lì resta un avviso («[[win.elsewhere]]») dove serve, e i pannelli vicini si allargano da soli a riempire il posto. Quando li rimetti tutti a posto torna la pagina di sempre.', 'A detached panel is no longer seen in the main window; a notice stays there (“[[win.elsewhere]]”) where needed, and the neighbouring panels widen by themselves to fill the space. When you put them all back, the usual page returns.', 'Ein abgelöstes Feld ist im Hauptfenster nicht mehr zu sehen; dort bleibt, wo nötig, ein Hinweis („[[win.elsewhere]]“), und die Nachbarfelder werden von selbst breiter und füllen den Platz. Wenn du alle wieder zurückholst, kehrt die gewohnte Seite zurück.', 'Un panneau détaché ne se voit plus dans la fenêtre principale ; il y reste une alerte (« [[win.elsewhere]] ») là où il le faut, et les panneaux voisins s’élargissent tout seuls pour remplir la place. Quand tu les remets tous en place, la page habituelle revient.', 'Un panel separado ya no se ve en la ventana principal; ahí queda un aviso («[[win.elsewhere]]») donde hace falta, y los paneles vecinos se ensanchan solos para llenar el sitio. Cuando los vuelves a poner todos en su sitio, vuelve la página de siempre.', 'Um painel destacado já não se vê na janela principal; aí fica um aviso («[[win.elsewhere]]») onde é preciso, e os painéis vizinhos alargam-se sozinhos para encher o lugar. Quando os repões todos volta a página de sempre.'],
      ['Per rimettere tutto nella finestra principale: il pulsante ⤓ («[[win.attachAll]]»), che compare in alto a destra solo se c’è almeno una finestra a parte. Ogni finestra a parte ha anche il suo pulsante «[[win.attach]]».', 'To put everything back in the main window: the ⤓ button (“[[win.attachAll]]”), which appears at the top right only if there is at least one separate window. Each separate window also has its own “[[win.attach]]” button.', 'Um alles ins Hauptfenster zurückzuholen: die Schaltfläche ⤓ („[[win.attachAll]]“), die oben rechts nur erscheint, wenn es mindestens ein eigenes Fenster gibt. Jedes eigene Fenster hat auch seine Schaltfläche „[[win.attach]]“.', 'Pour tout remettre dans la fenêtre principale : le bouton ⤓ (« [[win.attachAll]] »), qui apparaît en haut à droite seulement s’il y a au moins une fenêtre détachée. Chaque fenêtre détachée a aussi son bouton « [[win.attach]] ».', 'Para volver a poner todo en la ventana principal: el botón ⤓ («[[win.attachAll]]»), que aparece arriba a la derecha solo si hay al menos una ventana aparte. Cada ventana aparte tiene también su botón «[[win.attach]]».', 'Para repor tudo na janela principal: o botão ⤓ («[[win.attachAll]]»), que aparece em cima à direita só se houver pelo menos uma janela à parte. Cada janela à parte tem também o seu botão «[[win.attach]]».'],
      ['Quali pannelli mostrare e dove stanno ora: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] («[[win.where]]», «[[win.shown]]», «[[win.reset]]»).', 'Which panels to show and where they are now: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] (“[[win.where]]”, “[[win.shown]]”, “[[win.reset]]”).', 'Welche Felder gezeigt werden und wo sie jetzt sind: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] („[[win.where]]“, „[[win.shown]]“, „[[win.reset]]“).', 'Quels panneaux montrer et où ils se trouvent maintenant : [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] (« [[win.where]] », « [[win.shown]] », « [[win.reset]] »).', 'Qué paneles mostrar y dónde están ahora: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] («[[win.where]]», «[[win.shown]]», «[[win.reset]]»).', 'Que painéis mostrar e onde estão agora: [[nav.settings]] › [[sw.sec.look]] › [[tab.windows]] («[[win.where]]», «[[win.shown]]», «[[win.reset]]»).'],
    ],
  },
  {
    id: 'p-logprompt',
    title: ['La finestra «Registrare il QSO con…»', 'The “Log the QSO with…” window', 'Das Fenster QSO loggen mit …', 'La fenêtre « Enregistrer le QSO avec… »', 'La ventana «Registrar el QSO con…»', 'A janela «Registar o QSO com…»'],
    text: ['A fine QSO, se hai acceso «[[jx.PromptToLog]]» (di fabbrica è spento), compare una finestra al centro dello schermo per controllare i dati prima di salvarli nel log. Spento, il QSO si salva da solo senza domande.', 'At the end of a QSO, if you have turned on “[[jx.PromptToLog]]” (it is off by default), a window appears in the middle of the screen so you can check the data before saving it to the log. When off, the QSO is saved by itself without questions.', 'Am Ende eines QSOs erscheint, wenn du „[[jx.PromptToLog]]“ eingeschaltet hast (ab Werk aus), mitten auf dem Bildschirm ein Fenster, um die Daten zu prüfen, bevor sie im Log gespeichert werden. Ist es aus, speichert sich das QSO von selbst ohne Nachfrage.', 'En fin de QSO, si tu as activé « [[jx.PromptToLog]] » (désactivé par défaut), une fenêtre apparaît au centre de l’écran pour contrôler les données avant de les enregistrer dans le log. Désactivée, le QSO s’enregistre tout seul sans question.', 'Al final de un QSO, si has activado «[[jx.PromptToLog]]» (de serie está apagado), aparece una ventana en el centro de la pantalla para comprobar los datos antes de guardarlos en el log. Apagado, el QSO se guarda solo sin preguntar.', 'No fim do QSO, se ligaste «[[jx.PromptToLog]]» (de origem está desligado), aparece uma janela ao centro do ecrã para verificares os dados antes de os guardar no log. Desligado, o QSO guarda-se sozinho sem perguntas.'],
    steps: [
      ['In alto il titolo «[[lp.title.lead]] NOMINATIVO?» e le etichette con banda, modo, frequenza e ora UTC del QSO. Se ci sono più QSO in attesa lo dice («n QSO in attesa»).', 'At the top the title “[[lp.title.lead]] CALLSIGN?” and the labels with the band, mode, frequency and UTC time of the QSO. If more QSOs are waiting, it says so (“n QSOs waiting”).', 'Oben der Titel „[[lp.title.lead]] RUFZEICHEN?“ und die Etiketten mit Band, Betriebsart, Frequenz und UTC-Zeit des QSOs. Warten mehrere QSOs, sagt es das („n QSOs warten“).', 'En haut, le titre « [[lp.title.lead]] INDICATIF ? » et les étiquettes avec bande, mode, fréquence et heure UTC du QSO. S’il y a plusieurs QSO en attente, elle le dit (« n QSO en attente »).', 'Arriba el título «[[lp.title.lead]] INDICATIVO?» y las etiquetas con banda, modo, frecuencia y hora UTC del QSO. Si hay varios QSO en espera lo dice («n QSO en espera»).', 'Em cima o título «[[lp.title.lead]] INDICATIVO?» e as etiquetas com banda, modo, frequência e hora UTC do QSO. Se houver mais QSO à espera di-lo («n QSO à espera»).'],
      ['I campi, tutti modificabili: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] e [[lp.f.comment]]. Se un valore non va compare «Controlla il campo …» e il QSO non si salva.', 'The fields, all editable: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] and [[lp.f.comment]]. If a value is not right, “Check the … field” appears and the QSO is not saved.', 'Die Felder, alle änderbar: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] und [[lp.f.comment]]. Stimmt ein Wert nicht, erscheint „Prüfe das Feld …“ und das QSO wird nicht gespeichert.', 'Les champs, tous modifiables : [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] et [[lp.f.comment]]. Si une valeur ne va pas, « Vérifie le champ … » apparaît et le QSO ne s’enregistre pas.', 'Los campos, todos modificables: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] y [[lp.f.comment]]. Si un valor no es válido aparece «Revisa el campo …» y el QSO no se guarda.', 'Os campos, todos editáveis: [[lp.f.call]], [[lp.f.grid]], [[lp.f.rst_sent]], [[lp.f.rst_rcvd]], [[lp.f.name]], [[lp.f.qth]] e [[lp.f.comment]]. Se um valor não estiver certo aparece «Verifica o campo …» e o QSO não se guarda.'],
      ['«[[lp.log]]» (o il tasto Invio) registra il QSO con le correzioni; «[[lp.discard]]» lo scarta senza salvarlo. Esc non chiude la finestra (resta a STOP TX).', '“[[lp.log]]” (or the Enter key) logs the QSO with your corrections; “[[lp.discard]]” discards it without saving. Esc does not close the window (it stays until STOP TX).', '„[[lp.log]]“ (oder die Enter-Taste) speichert das QSO mit den Korrekturen; „[[lp.discard]]“ verwirft es, ohne es zu speichern. Esc schließt das Fenster nicht (es bleibt bei STOP TX).', '« [[lp.log]] » (ou la touche Entrée) enregistre le QSO avec les corrections ; « [[lp.discard]] » l’écarte sans l’enregistrer. Échap ne ferme pas la fenêtre (il reste sur STOP TX).', '«[[lp.log]]» (o la tecla Intro) registra el QSO con las correcciones; «[[lp.discard]]» lo descarta sin guardarlo. Esc no cierra la ventana (se queda en STOP TX).', '«[[lp.log]]» (ou a tecla Enter) regista o QSO com as correções; «[[lp.discard]]» descarta-o sem o guardar. Esc não fecha a janela (fica em STOP TX).'],
      ['L’impostazione si cambia in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].', 'The setting is changed in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].', 'Die Einstellung änderst du unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].', 'Le réglage se change dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].', 'El ajuste se cambia en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].', 'A definição muda-se em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.qso]].'],
    ],
  },
  {
    id: 'p-logpage',
    title: ['Il Log: ricerca, selezione ed esportazione', 'The Log: search, selection and export', 'Das Log: Suche, Auswahl und Export', 'Le Journal : recherche, sélection et export', 'El Log: búsqueda, selección y exportación', 'O Log: pesquisa, seleção e exportação'],
    text: ['La pagina [[nav.log]] (titolo «[[exp.title]]») mostra tutti i QSO del log interno di Aurora. Serve per cercarli, correggerli, cancellarli, aggiungerne uno a mano e salvarli in un file ADIF o Cabrillo. In alto a destra: «＋ [[exp.add]]» e «[[exp.back]]» (torna alla Stazione).', 'The [[nav.log]] page (title “[[exp.title]]”) shows all the QSOs of Aurora’s internal log. It is used to search them, correct them, delete them, add one by hand and save them to an ADIF or Cabrillo file. At the top right: “＋ [[exp.add]]” and “[[exp.back]]” (back to the Station).', 'Die Seite [[nav.log]] (Titel „[[exp.title]]“) zeigt alle QSOs des internen Logs von Aurora. Du suchst sie, korrigierst sie, löschst sie, fügst eines von Hand hinzu und speicherst sie in einer ADIF- oder Cabrillo-Datei. Oben rechts: „＋ [[exp.add]]“ und „[[exp.back]]“ (zurück zur Station).', 'La page [[nav.log]] (titre « [[exp.title]] ») montre tous les QSO du log interne d’Aurora. Elle sert à les chercher, les corriger, les supprimer, en ajouter un à la main et les enregistrer dans un fichier ADIF ou Cabrillo. En haut à droite : « ＋ [[exp.add]] » et « [[exp.back]] » (retour à la Station).', 'La página [[nav.log]] (título «[[exp.title]]») muestra todos los QSO del log interno de Aurora. Sirve para buscarlos, corregirlos, borrarlos, añadir uno a mano y guardarlos en un archivo ADIF o Cabrillo. Arriba a la derecha: «＋ [[exp.add]]» y «[[exp.back]]» (vuelve a la Estación).', 'A página [[nav.log]] (título «[[exp.title]]») mostra todos os QSO do log interno da Aurora. Serve para os pesquisar, corrigir, apagar, juntar um à mão e guardá-los num ficheiro ADIF ou Cabrillo. Em cima à direita: «＋ [[exp.add]]» e «[[exp.back]]» (volta à Estação).'],
    steps: [
      ['Filtri, sulla stessa riga: il campo «[[exp.search]]» (filtra mentre scrivi), «[[exp.from]]» e «[[exp.to]]» (date UTC; si può mettere solo una delle due), «[[exp.band]]» e «[[exp.mode]]» (si riempiono con le bande e i modi che hai nel log). «[[exp.clear]]» compare solo quando c’è un filtro e li toglie tutti.', 'Filters, on the same row: the “[[exp.search]]” field (it filters as you type), “[[exp.from]]” and “[[exp.to]]” (UTC dates; you can set just one of the two), “[[exp.band]]” and “[[exp.mode]]” (they fill with the bands and modes you have in the log). “[[exp.clear]]” appears only when a filter is active and removes them all.', 'Filter, in derselben Zeile: das Feld „[[exp.search]]“ (filtert beim Schreiben), „[[exp.from]]“ und „[[exp.to]]“ (UTC-Daten; man kann auch nur eines setzen), „[[exp.band]]“ und „[[exp.mode]]“ (sie füllen sich mit den Bändern und Betriebsarten, die du im Log hast). „[[exp.clear]]“ erscheint nur, wenn ein Filter aktiv ist, und nimmt alle weg.', 'Filtres, sur la même ligne : le champ « [[exp.search]] » (filtre pendant que tu écris), « [[exp.from]] » et « [[exp.to]] » (dates UTC ; on peut n’en mettre qu’une des deux), « [[exp.band]] » et « [[exp.mode]] » (elles se remplissent avec les bandes et les modes que tu as dans le log). « [[exp.clear]] » n’apparaît que quand il y a un filtre et les enlève tous.', 'Filtros, en la misma fila: el campo «[[exp.search]]» (filtra mientras escribes), «[[exp.from]]» y «[[exp.to]]» (fechas UTC; se puede poner solo una de las dos), «[[exp.band]]» y «[[exp.mode]]» (se llenan con las bandas y los modos que tienes en el log). «[[exp.clear]]» aparece solo cuando hay un filtro y los quita todos.', 'Filtros, na mesma linha: o campo «[[exp.search]]» (filtra enquanto escreves), «[[exp.from]]» e «[[exp.to]]» (datas UTC; pode pôr-se só uma das duas), «[[exp.band]]» e «[[exp.mode]]» (preenchem-se com as bandas e os modos que tens no log). «[[exp.clear]]» aparece só quando há um filtro e tira-os todos.'],
      ['Selezione: la prima volta che si apre la pagina tutti i QSO sono selezionati (il caso più comune è esportare tutto). Ogni riga ha la sua casella; la casella in alto seleziona o toglie tutte le righe mostrate («[[exp.selectShown]]»). I pulsanti «[[exp.all]]» e «[[exp.none]]» fanno lo stesso solo sui QSO che i filtri mostrano. Una scritta dice quanti QSO sono selezionati, quanti sono mostrati e quanti ce ne sono nel log; i selezionati nascosti da un filtro vengono comunque salvati.', 'Selection: the first time the page opens, all the QSOs are selected (the most common case is exporting everything). Each row has its own check box; the box at the top selects or clears all the rows shown (“[[exp.selectShown]]”). The “[[exp.all]]” and “[[exp.none]]” buttons do the same only on the QSOs that the filters show. A line says how many QSOs are selected, how many are shown and how many there are in the log; selected QSOs hidden by a filter are saved anyway.', 'Auswahl: Beim ersten Öffnen der Seite sind alle QSOs ausgewählt (der häufigste Fall ist, alles zu exportieren). Jede Zeile hat ihr Kästchen; das Kästchen oben wählt alle gezeigten Zeilen aus oder ab („[[exp.selectShown]]“). Die Schaltflächen „[[exp.all]]“ und „[[exp.none]]“ tun dasselbe nur für die QSOs, die die Filter zeigen. Eine Zeile sagt, wie viele QSOs ausgewählt sind, wie viele gezeigt werden und wie viele es im Log gibt; ausgewählte QSOs, die ein Filter versteckt, werden trotzdem gespeichert.', 'Sélection : la première fois qu’on ouvre la page, tous les QSO sont sélectionnés (le cas le plus courant est d’exporter tout). Chaque ligne a sa case ; la case en haut sélectionne ou désélectionne toutes les lignes affichées (« [[exp.selectShown]] »). Les boutons « [[exp.all]] » et « [[exp.none]] » font la même chose seulement sur les QSO que les filtres affichent. Un texte dit combien de QSO sont sélectionnés, combien sont affichés et combien il y en a dans le log ; les sélectionnés cachés par un filtre sont quand même enregistrés.', 'Selección: la primera vez que se abre la página todos los QSO están seleccionados (el caso más común es exportarlo todo). Cada fila tiene su casilla; la casilla de arriba selecciona o quita todas las filas mostradas («[[exp.selectShown]]»). Los botones «[[exp.all]]» y «[[exp.none]]» hacen lo mismo solo con los QSO que muestran los filtros. Un texto dice cuántos QSO están seleccionados, cuántos se muestran y cuántos hay en el log; los seleccionados ocultos por un filtro se guardan igualmente.', 'Seleção: a primeira vez que se abre a página todos os QSO estão selecionados (o caso mais comum é exportar tudo). Cada linha tem a sua caixa; a caixa em cima seleciona ou tira todas as linhas mostradas («[[exp.selectShown]]»). Os botões «[[exp.all]]» e «[[exp.none]]» fazem o mesmo só nos QSO que os filtros mostram. Um texto diz quantos QSO estão selecionados, quantos são mostrados e quantos há no log; os selecionados escondidos por um filtro são guardados na mesma.'],
      ['Colonne: «[[exp.col.date]]», «[[exp.col.time]]», «[[exp.col.call]]», «[[exp.col.band]]», «[[exp.col.mode]]», «[[exp.col.sent]]» e «[[exp.col.rcvd]]» (i rapporti in dB che hai inviato e ricevuto), «[[exp.col.grid]]», «[[exp.col.country]]» e il pulsante «[[exp.edit.btn]]». Con log grandi si vedono 300 righe alla volta: scorri in fondo o premi «[[exp.more]]»; filtri, selezione ed esportazione valgono per tutto il log.', 'Columns: “[[exp.col.date]]”, “[[exp.col.time]]”, “[[exp.col.call]]”, “[[exp.col.band]]”, “[[exp.col.mode]]”, “[[exp.col.sent]]” and “[[exp.col.rcvd]]” (the reports in dB you sent and received), “[[exp.col.grid]]”, “[[exp.col.country]]” and the “[[exp.edit.btn]]” button. With large logs 300 rows are shown at a time: scroll to the bottom or press “[[exp.more]]”; filters, selection and export apply to the whole log.', 'Spalten: „[[exp.col.date]]“, „[[exp.col.time]]“, „[[exp.col.call]]“, „[[exp.col.band]]“, „[[exp.col.mode]]“, „[[exp.col.sent]]“ und „[[exp.col.rcvd]]“ (die Rapporte in dB, die du gesendet und empfangen hast), „[[exp.col.grid]]“, „[[exp.col.country]]“ und die Schaltfläche „[[exp.edit.btn]]“. Bei großen Logs siehst du 300 Zeilen auf einmal: Scrolle nach unten oder drücke „[[exp.more]]“; Filter, Auswahl und Export gelten für das ganze Log.', 'Colonnes : « [[exp.col.date]] », « [[exp.col.time]] », « [[exp.col.call]] », « [[exp.col.band]] », « [[exp.col.mode]] », « [[exp.col.sent]] » et « [[exp.col.rcvd]] » (les reports en dB que tu as envoyés et reçus), « [[exp.col.grid]] », « [[exp.col.country]] » et le bouton « [[exp.edit.btn]] ». Avec de gros logs on voit 300 lignes à la fois : fais défiler jusqu’en bas ou appuie sur « [[exp.more]] » ; filtres, sélection et export valent pour tout le log.', 'Columnas: «[[exp.col.date]]», «[[exp.col.time]]», «[[exp.col.call]]», «[[exp.col.band]]», «[[exp.col.mode]]», «[[exp.col.sent]]» y «[[exp.col.rcvd]]» (los informes en dB que has enviado y recibido), «[[exp.col.grid]]», «[[exp.col.country]]» y el botón «[[exp.edit.btn]]». Con logs grandes se ven 300 filas cada vez: baja hasta el final o pulsa «[[exp.more]]»; los filtros, la selección y la exportación valen para todo el log.', 'Colunas: «[[exp.col.date]]», «[[exp.col.time]]», «[[exp.col.call]]», «[[exp.col.band]]», «[[exp.col.mode]]», «[[exp.col.sent]]» e «[[exp.col.rcvd]]» (os relatórios em dB que enviaste e recebeste), «[[exp.col.grid]]», «[[exp.col.country]]» e o botão «[[exp.edit.btn]]». Com logs grandes veem-se 300 linhas de cada vez: desce até ao fim ou carrega em «[[exp.more]]»; filtros, seleção e exportação valem para todo o log.'],
      ['Doppio clic su una riga, oppure «[[exp.edit.btn]]»: apre la finestra per correggere o cancellare quel QSO (vedi «La finestra per correggere o cancellare un QSO»).', 'Double-click on a row, or “[[exp.edit.btn]]”: opens the window to correct or delete that QSO (see “The window to correct or delete a QSO”).', 'Doppelklick auf eine Zeile oder „[[exp.edit.btn]]“: öffnet das Fenster, um dieses QSO zu korrigieren oder zu löschen (siehe „Das Fenster zum Korrigieren oder Löschen eines QSO“).', 'Double-clic sur une ligne, ou « [[exp.edit.btn]] » : ouvre la fenêtre pour corriger ou supprimer ce QSO (voir « La fenêtre pour corriger ou supprimer un QSO »).', 'Doble clic en una fila, o «[[exp.edit.btn]]»: abre la ventana para corregir o borrar ese QSO (mira «La ventana para corregir o borrar un QSO»).', 'Duplo clique numa linha, ou «[[exp.edit.btn]]»: abre a janela para corrigir ou apagar esse QSO (vê «A janela para corrigir ou apagar um QSO»).'],
      ['«[[exp.save]]» (sul PC apre la finestra di Windows per scegliere cartella e nome del file ADIF) o «[[exp.download]]» (dal telefono o da un altro computer: scarica il file nella cartella dei download): salvano solo i QSO selezionati. «[[exp.saveCbr]]» salva gli stessi QSO in Cabrillo 3.0 (per un contest con le sue regole usa la pagina [[nav.contest]]). Senza nessun QSO selezionato i pulsanti sono grigi.', '“[[exp.save]]” (on the PC it opens the Windows window to choose the folder and the name of the ADIF file) or “[[exp.download]]” (from the phone or from another computer: it downloads the file to the downloads folder): they save only the selected QSOs. “[[exp.saveCbr]]” saves the same QSOs in Cabrillo 3.0 (for a contest with its own rules use the [[nav.contest]] page). With no QSO selected the buttons are grey.', '„[[exp.save]]“ (am PC öffnet das Windows-Fenster, um Ordner und Namen der ADIF-Datei zu wählen) oder „[[exp.download]]“ (vom Telefon oder von einem anderen Computer: lädt die Datei in den Download-Ordner): speichern nur die ausgewählten QSOs. „[[exp.saveCbr]]“ speichert dieselben QSOs in Cabrillo 3.0 (für einen Contest mit seinen Regeln nimm die Seite [[nav.contest]]). Ist kein QSO ausgewählt, sind die Schaltflächen grau.', '« [[exp.save]] » (sur le PC ouvre la fenêtre de Windows pour choisir dossier et nom du fichier ADIF) ou « [[exp.download]] » (depuis le téléphone ou un autre ordinateur : télécharge le fichier dans le dossier des téléchargements) : n’enregistrent que les QSO sélectionnés. « [[exp.saveCbr]] » enregistre les mêmes QSO en Cabrillo 3.0 (pour un contest avec son règlement, utilise la page [[nav.contest]]). Sans aucun QSO sélectionné, les boutons sont gris.', '«[[exp.save]]» (en el PC abre la ventana de Windows para elegir carpeta y nombre del archivo ADIF) o «[[exp.download]]» (desde el teléfono o desde otro ordenador: descarga el archivo en la carpeta de descargas): guardan solo los QSO seleccionados. «[[exp.saveCbr]]» guarda los mismos QSO en Cabrillo 3.0 (para un concurso con sus reglas usa la página [[nav.contest]]). Sin ningún QSO seleccionado los botones están grises.', '«[[exp.save]]» (no PC abre a janela do Windows para escolher pasta e nome do ficheiro ADIF) ou «[[exp.download]]» (a partir do telemóvel ou de outro computador: transfere o ficheiro para a pasta das transferências): guardam só os QSO selecionados. «[[exp.saveCbr]]» guarda os mesmos QSO em Cabrillo 3.0 (para um concurso com as suas regras usa a página [[nav.contest]]). Sem nenhum QSO selecionado os botões ficam cinzentos.'],
      ['«Elimina selezionati (n)» (con il numero dei selezionati) cancella i QSO selezionati dal log e dal file ADIF di Aurora, dopo una conferma; «[[exp.clearLog]]» toglie tutti i QSO per ripartire da un log vuoto (il vecchio file ADIF è messo da parte con la data), dopo una conferma. Non si può recuperare dal programma.', '“Delete selected (n)” (with the number of selected QSOs) removes the selected QSOs from Aurora’s log and ADIF file, after a confirmation; “[[exp.clearLog]]” removes all the QSOs to start again from an empty log (the old ADIF file is set aside with the date), after a confirmation. It cannot be recovered from the program.', '„Ausgewählte löschen (n)“ (mit der Zahl der ausgewählten) löscht die ausgewählten QSOs aus dem Log und aus der ADIF-Datei von Aurora, nach einer Bestätigung; „[[exp.clearLog]]“ entfernt alle QSOs, um mit einem leeren Log neu zu beginnen (die alte ADIF-Datei wird mit dem Datum beiseitegelegt), nach einer Bestätigung. Im Programm lässt es sich nicht wiederherstellen.', '« Supprimer la sélection (n) » (avec le nombre de QSO sélectionnés) supprime les QSO sélectionnés du log et du fichier ADIF d’Aurora, après une confirmation ; « [[exp.clearLog]] » enlève tous les QSO pour repartir d’un log vide (l’ancien fichier ADIF est mis de côté avec la date), après une confirmation. Impossible de les récupérer depuis le programme.', '«Eliminar seleccionados (n)» (con el número de seleccionados) borra los QSO seleccionados del log y del archivo ADIF de Aurora, tras una confirmación; «[[exp.clearLog]]» quita todos los QSO para empezar de nuevo con un log vacío (el archivo ADIF antiguo se aparta con la fecha), tras una confirmación. No se puede recuperar desde el programa.', '«Eliminar selecionados (n)» (com o número dos selecionados) apaga os QSO selecionados do log e do ficheiro ADIF da Aurora, depois de uma confirmação; «[[exp.clearLog]]» tira todos os QSO para recomeçares com um log vazio (o ficheiro ADIF antigo é posto de parte com a data), depois de uma confirmação. Não se pode recuperar a partir do programa.'],
      ['«＋ [[exp.add]]» apre un modulo per un QSO fatto fuori da Aurora: [[exp.f.call]], [[exp.f.date]] e [[exp.f.time]] (UTC), [[exp.f.band]] o [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] e [[exp.f.comment]]. «[[exp.addSave]]» lo registra come un QSO normale (log, file ADIF e programmi collegati); «[[exp.addCancel]]» chiude il modulo.', '“＋ [[exp.add]]” opens a form for a QSO made outside Aurora: [[exp.f.call]], [[exp.f.date]] and [[exp.f.time]] (UTC), [[exp.f.band]] or [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] and [[exp.f.comment]]. “[[exp.addSave]]” logs it like a normal QSO (log, ADIF file and connected programs); “[[exp.addCancel]]” closes the form.', '„＋ [[exp.add]]“ öffnet ein Formular für ein QSO, das außerhalb von Aurora gefahren wurde: [[exp.f.call]], [[exp.f.date]] und [[exp.f.time]] (UTC), [[exp.f.band]] oder [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] und [[exp.f.comment]]. „[[exp.addSave]]“ speichert es wie ein normales QSO (Log, ADIF-Datei und verbundene Programme); „[[exp.addCancel]]“ schließt das Formular.', '« ＋ [[exp.add]] » ouvre un formulaire pour un QSO fait en dehors d’Aurora : [[exp.f.call]], [[exp.f.date]] et [[exp.f.time]] (UTC), [[exp.f.band]] ou [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] et [[exp.f.comment]]. « [[exp.addSave]] » l’enregistre comme un QSO normal (log, fichier ADIF et programmes connectés) ; « [[exp.addCancel]] » ferme le formulaire.', '«＋ [[exp.add]]» abre un formulario para un QSO hecho fuera de Aurora: [[exp.f.call]], [[exp.f.date]] y [[exp.f.time]] (UTC), [[exp.f.band]] o [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] y [[exp.f.comment]]. «[[exp.addSave]]» lo registra como un QSO normal (log, archivo ADIF y programas conectados); «[[exp.addCancel]]» cierra el formulario.', '«＋ [[exp.add]]» abre um formulário para um QSO feito fora da Aurora: [[exp.f.call]], [[exp.f.date]] e [[exp.f.time]] (UTC), [[exp.f.band]] ou [[exp.f.freq]], [[exp.f.mode]], [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]], [[exp.f.name]] e [[exp.f.comment]]. «[[exp.addSave]]» regista-o como um QSO normal (log, ficheiro ADIF e programas ligados); «[[exp.addCancel]]» fecha o formulário.'],
      ['Cancellare, aggiungere e correggere si può fare solo dal PC o dalla rete di casa («[[exp.localOnly]]»). Con il log vuoto la pagina dice «[[exp.empty]]». Per importare un file ADIF (il tuo storico) vedi «Statistiche e scheda DXCC», riquadro «[[logio.title]]».', 'Deleting, adding and correcting can be done only from the PC or from the home network (“[[exp.localOnly]]”). With an empty log the page says “[[exp.empty]]”. To import an ADIF file (your history) see “Statistics and the DXCC card”, box “[[logio.title]]”.', 'Löschen, Hinzufügen und Korrigieren geht nur am PC oder im Heimnetz („[[exp.localOnly]]“). Bei leerem Log sagt die Seite „[[exp.empty]]“. Um eine ADIF-Datei (dein bisheriges Log) zu importieren, siehe „Statistik und DXCC-Karte“, Feld „[[logio.title]]“.', 'Supprimer, ajouter et corriger ne se fait que depuis le PC ou depuis le réseau de la maison (« [[exp.localOnly]] »). Avec le log vide, la page dit « [[exp.empty]] ». Pour importer un fichier ADIF (ton historique), voir « Statistiques et onglet DXCC », encadré « [[logio.title]] ».', 'Borrar, añadir y corregir solo se puede hacer desde el PC o desde la red de casa («[[exp.localOnly]]»). Con el log vacío la página dice «[[exp.empty]]». Para importar un archivo ADIF (tu historial) mira «Estadísticas y ficha DXCC», recuadro «[[logio.title]]».', 'Apagar, juntar e corrigir só se pode fazer a partir do PC ou da rede de casa («[[exp.localOnly]]»). Com o log vazio a página diz «[[exp.empty]]». Para importar um ficheiro ADIF (o teu histórico) vê «Estatísticas e separador DXCC», quadro «[[logio.title]]».'],
    ],
  },
  {
    id: 'p-logedit',
    title: ['La finestra per correggere o cancellare un QSO', 'The window to correct or delete a QSO', 'Das Fenster zum Korrigieren oder Löschen eines QSO', 'La fenêtre pour corriger ou supprimer un QSO', 'La ventana para corregir o borrar un QSO', 'A janela para corrigir ou apagar um QSO'],
    text: ['Si apre con un doppio clic su un QSO (nella pagina [[nav.log]] e nel pannello [[panel.log]] della Stazione) o con «[[exp.edit.btn]]». Cambia solo il log interno di Aurora e il suo file ADIF; i «già lavorati» si ricalcolano. Vedi anche «Correggere o cancellare un QSO».', 'It opens with a double-click on a QSO (on the [[nav.log]] page and in the [[panel.log]] panel of the Station) or with “[[exp.edit.btn]]”. It changes only Aurora’s internal log and its ADIF file; the “already worked” flags are recalculated. See also “Correcting or deleting a QSO”.', 'Es öffnet sich mit einem Doppelklick auf ein QSO (auf der Seite [[nav.log]] und im Feld [[panel.log]] der Station) oder mit „[[exp.edit.btn]]“. Es ändert nur das interne Log von Aurora und seine ADIF-Datei; die „schon gearbeitet“-Angaben werden neu berechnet. Siehe auch „Ein QSO korrigieren oder löschen“.', 'Elle s’ouvre par un double-clic sur un QSO (dans la page [[nav.log]] et dans le panneau [[panel.log]] de la Station) ou avec « [[exp.edit.btn]] ». Elle ne change que le log interne d’Aurora et son fichier ADIF ; les « déjà contactés » sont recalculés. Voir aussi « Corriger ou supprimer un QSO ».', 'Se abre con un doble clic en un QSO (en la página [[nav.log]] y en el panel [[panel.log]] de la Estación) o con «[[exp.edit.btn]]». Cambia solo el log interno de Aurora y su archivo ADIF; los «ya trabajados» se recalculan. Mira también «Corregir o borrar un QSO».', 'Abre-se com um duplo clique num QSO (na página [[nav.log]] e no painel [[panel.log]] da Estação) ou com «[[exp.edit.btn]]». Muda só o log interno da Aurora e o seu ficheiro ADIF; os «já trabalhados» recalculam-se. Vê também «Corrigir ou apagar um QSO».'],
    steps: [
      ['Campi: [[exp.f.call]] (da 3 a 13 lettere, cifre o «/»), [[exp.f.date]] e [[exp.f.time]] (in UTC), [[exp.f.band]] (tendina), [[exp.f.freq]] in MHz (per esempio 14.074, o vuota), [[exp.f.mode]] (tendina divisa in «[[exp.mg.digital]]», «[[exp.mg.voice]]», «[[exp.mg.cw]]» e «[[exp.mg.other]]»), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 o 8 caratteri, o vuoto), [[exp.f.name]], [[exp.f.qth]] e [[exp.f.comment]].', 'Fields: [[exp.f.call]] (from 3 to 13 letters, digits or “/”), [[exp.f.date]] and [[exp.f.time]] (in UTC), [[exp.f.band]] (drop-down), [[exp.f.freq]] in MHz (for example 14.074, or empty), [[exp.f.mode]] (drop-down divided into “[[exp.mg.digital]]”, “[[exp.mg.voice]]”, “[[exp.mg.cw]]” and “[[exp.mg.other]]”), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 or 8 characters, or empty), [[exp.f.name]], [[exp.f.qth]] and [[exp.f.comment]].', 'Felder: [[exp.f.call]] (3 bis 13 Buchstaben, Ziffern oder „/“), [[exp.f.date]] und [[exp.f.time]] (in UTC), [[exp.f.band]] (Auswahlliste), [[exp.f.freq]] in MHz (zum Beispiel 14.074, oder leer), [[exp.f.mode]] (Auswahlliste, unterteilt in „[[exp.mg.digital]]“, „[[exp.mg.voice]]“, „[[exp.mg.cw]]“ und „[[exp.mg.other]]“), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 oder 8 Zeichen, oder leer), [[exp.f.name]], [[exp.f.qth]] und [[exp.f.comment]].', 'Champs : [[exp.f.call]] (de 3 à 13 lettres, chiffres ou « / »), [[exp.f.date]] et [[exp.f.time]] (en UTC), [[exp.f.band]] (liste), [[exp.f.freq]] en MHz (par exemple 14.074, ou vide), [[exp.f.mode]] (liste divisée en « [[exp.mg.digital]] », « [[exp.mg.voice]] », « [[exp.mg.cw]] » et « [[exp.mg.other]] »), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 ou 8 caractères, ou vide), [[exp.f.name]], [[exp.f.qth]] et [[exp.f.comment]].', 'Campos: [[exp.f.call]] (de 3 a 13 letras, cifras o «/»), [[exp.f.date]] y [[exp.f.time]] (en UTC), [[exp.f.band]] (lista desplegable), [[exp.f.freq]] en MHz (por ejemplo 14.074, o vacía), [[exp.f.mode]] (lista desplegable dividida en «[[exp.mg.digital]]», «[[exp.mg.voice]]», «[[exp.mg.cw]]» y «[[exp.mg.other]]»), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 u 8 caracteres, o vacío), [[exp.f.name]], [[exp.f.qth]] y [[exp.f.comment]].', 'Campos: [[exp.f.call]] (de 3 a 13 letras, algarismos ou «/»), [[exp.f.date]] e [[exp.f.time]] (em UTC), [[exp.f.band]] (lista), [[exp.f.freq]] em MHz (por exemplo 14.074, ou vazia), [[exp.f.mode]] (lista dividida em «[[exp.mg.digital]]», «[[exp.mg.voice]]», «[[exp.mg.cw]]» e «[[exp.mg.other]]»), [[exp.f.sent]], [[exp.f.rcvd]], [[exp.f.grid]] (4, 6 ou 8 carateres, ou vazio), [[exp.f.name]], [[exp.f.qth]] e [[exp.f.comment]].'],
      ['Un valore sbagliato è segnato in rosso con il motivo sotto il campo e il QSO non si salva finché non lo correggi.', 'A wrong value is marked in red with the reason under the field, and the QSO is not saved until you correct it.', 'Ein falscher Wert ist rot markiert, mit dem Grund unter dem Feld, und das QSO wird nicht gespeichert, bis du ihn korrigierst.', 'Une valeur fausse est marquée en rouge avec le motif sous le champ et le QSO ne s’enregistre pas tant que tu ne l’as pas corrigée.', 'Un valor erróneo se marca en rojo con el motivo bajo el campo y el QSO no se guarda hasta que lo corriges.', 'Um valor errado é assinalado a vermelho com o motivo por baixo do campo e o QSO não se guarda enquanto não o corrigires.'],
      ['«[[exp.edit.save]]»: salva le correzioni (se non hai cambiato niente chiude e basta). «[[exp.edit.cancel]]», Esc o un clic fuori dalla finestra: chiudono senza cambiare nulla. «[[exp.edit.delete]]»: toglie il QSO dal log di Aurora e dal suo file ADIF, dopo una conferma; non si recupera dal programma.', '“[[exp.edit.save]]”: saves the corrections (if you changed nothing, it just closes). “[[exp.edit.cancel]]”, Esc or a click outside the window: they close without changing anything. “[[exp.edit.delete]]”: removes the QSO from Aurora’s log and from its ADIF file, after a confirmation; it cannot be recovered from the program.', '„[[exp.edit.save]]“: speichert die Korrekturen (hast du nichts geändert, schließt es nur). „[[exp.edit.cancel]]“, Esc oder ein Klick außerhalb des Fensters: schließen, ohne etwas zu ändern. „[[exp.edit.delete]]“: entfernt das QSO aus dem Log von Aurora und aus seiner ADIF-Datei, nach einer Bestätigung; im Programm lässt es sich nicht wiederherstellen.', '« [[exp.edit.save]] » : enregistre les corrections (si tu n’as rien changé, elle se ferme simplement). « [[exp.edit.cancel]] », Échap ou un clic à l’extérieur de la fenêtre : ferment sans rien changer. « [[exp.edit.delete]] » : enlève le QSO du log d’Aurora et de son fichier ADIF, après une confirmation ; impossible de le récupérer depuis le programme.', '«[[exp.edit.save]]»: guarda las correcciones (si no has cambiado nada, simplemente cierra). «[[exp.edit.cancel]]», Esc o un clic fuera de la ventana: cierran sin cambiar nada. «[[exp.edit.delete]]»: quita el QSO del log de Aurora y de su archivo ADIF, tras una confirmación; no se recupera desde el programa.', '«[[exp.edit.save]]»: guarda as correções (se não mudaste nada fecha e pronto). «[[exp.edit.cancel]]», Esc ou um clique fora da janela: fecham sem mudar nada. «[[exp.edit.delete]]»: tira o QSO do log da Aurora e do seu ficheiro ADIF, depois de uma confirmação; não se recupera a partir do programa.'],
      ['Nel pannello Log che mostra il log di Log4OM2 i QSO sono in sola lettura: si correggono in Log4OM2.', 'In the Log panel that shows the Log4OM2 log the QSOs are read only: you correct them in Log4OM2.', 'Im Log-Feld, das das Log von Log4OM2 zeigt, sind die QSOs nur lesbar: Sie werden in Log4OM2 korrigiert.', 'Dans le panneau Journal qui montre le log de Log4OM2, les QSO sont en lecture seule : on les corrige dans Log4OM2.', 'En el panel Log que muestra el log de Log4OM2 los QSO son de solo lectura: se corrigen en Log4OM2.', 'No painel Log que mostra o log do Log4OM2 os QSO são só de leitura: corrigem-se no Log4OM2.'],
    ],
    tip: ['Ai log esterni (programmi collegati via UDP, Wavelog, ClubLog, QRZ, LoTW) non si rimanda nessuna correzione né cancellazione: lì il QSO si corregge a mano.', 'No correction or deletion is sent on to external logs (programs connected via UDP, Wavelog, ClubLog, QRZ, LoTW): there you correct the QSO by hand.', 'An externe Logs (über UDP verbundene Programme, Wavelog, ClubLog, QRZ, LoTW) wird keine Korrektur und keine Löschung weitergegeben: Dort korrigierst du das QSO von Hand.', 'Aux logs externes (programmes connectés par UDP, Wavelog, ClubLog, QRZ, LoTW) aucune correction ni suppression n’est renvoyée : là, le QSO se corrige à la main.', 'A los logs externos (programas conectados por UDP, Wavelog, ClubLog, QRZ, LoTW) no se reenvía ninguna corrección ni borrado: allí el QSO se corrige a mano.', 'Aos logs externos (programas ligados por UDP, Wavelog, ClubLog, QRZ, LoTW) não se reenvia nenhuma correção nem eliminação: aí o QSO corrige-se à mão.'],
  },
  {
    id: 'p-extlog',
    title: ['Un QSO manca nel log esterno', 'A QSO is missing from the external log', 'Ein QSO fehlt im externen Log', 'Un QSO manque dans le log externe', 'Falta un QSO en el log externo', 'Falta um QSO no log externo'],
    text: ['Aurora manda ogni QSO ai programmi di log e ai servizi in rete una volta sola, nel momento in cui lo registra. Se il log era chiuso o la rete non c’era, il QSO può non arrivare. Non esiste un pulsante «rimanda» sui QSO già a log; ecco cosa si può fare.', 'Aurora sends each QSO to the log programs and to the online services only once, at the moment it logs it. If the log was closed or the network was down, the QSO may not arrive. There is no “resend” button on QSOs already in the log; here is what you can do.', 'Aurora sendet jedes QSO an die Logprogramme und an die Online-Dienste nur einmal, in dem Moment, in dem es gespeichert wird. War das Log zu oder das Netz nicht da, kann das QSO ausbleiben. Eine Schaltfläche „Nachsenden“ für QSOs, die schon im Log sind, gibt es nicht; das kannst du tun.', 'Aurora envoie chaque QSO aux programmes de log et aux services en ligne une seule fois, au moment où il l’enregistre. Si le log était fermé ou si le réseau n’était pas là, le QSO peut ne pas arriver. Il n’existe pas de bouton « renvoyer » sur les QSO déjà enregistrés ; voici ce qu’on peut faire.', 'Aurora manda cada QSO a los programas de log y a los servicios en línea una sola vez, en el momento en que lo registra. Si el log estaba cerrado o no había red, el QSO puede no llegar. No existe un botón «reenviar» en los QSO ya registrados; esto es lo que se puede hacer.', 'A Aurora envia cada QSO aos programas de log e aos serviços online uma só vez, no momento em que o regista. Se o log estava fechado ou não havia rede, o QSO pode não chegar. Não existe um botão «reenviar» nos QSO já no log; eis o que se pode fazer.'],
    steps: [
      ['Per i prossimi QSO: in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] accendi «[[int.resend]]» sul destinatario del tuo log (vedi «Log chiuso: i QSO arrivano dopo»). Aurora tiene da parte i QSO fatti a log chiuso e li manda da sola circa 15 secondi dopo che lo riapri, nell’ordine in cui li hai fatti. Vale per un log sullo stesso PC (indirizzo 127.0.0.1) con «[[int.adif]]» o «[[int.n1mm]]».', 'For the next QSOs: in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] turn on “[[int.resend]]” on the recipient of your log (see “Log closed: QSOs arrive later”). Aurora keeps aside the QSOs made while the log was closed and sends them by itself about 15 seconds after you reopen it, in the order you made them. It works for a log on the same PC (address 127.0.0.1) with “[[int.adif]]” or “[[int.n1mm]]”.', 'Für die nächsten QSOs: Schalte unter [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] „[[int.resend]]“ beim Empfänger deines Logs ein (siehe „Log geschlossen: QSOs kommen später an“). Aurora legt die QSOs, die bei geschlossenem Log gefahren wurden, beiseite und sendet sie von selbst etwa 15 Sekunden, nachdem du es wieder öffnest, in der Reihenfolge, in der du sie gefahren hast. Das gilt für ein Log auf demselben PC (Adresse 127.0.0.1) mit „[[int.adif]]“ oder „[[int.n1mm]]“.', 'Pour les prochains QSO : dans [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] active « [[int.resend]] » sur le destinataire de ton log (voir « Journal fermé : les QSO arrivent après »). Aurora garde de côté les QSO faits quand le log était fermé et les envoie toute seule environ 15 secondes après que tu le rouvres, dans l’ordre où tu les as faits. Cela vaut pour un log sur le même PC (adresse 127.0.0.1) avec « [[int.adif]] » ou « [[int.n1mm]] ».', 'Para los próximos QSO: en [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] enciende «[[int.resend]]» en el destinatario de tu log (mira «Log cerrado: los QSO llegan después»). Aurora guarda aparte los QSO hechos con el log cerrado y los manda sola unos 15 segundos después de que lo abras, en el orden en que los hiciste. Vale para un log en el mismo PC (dirección 127.0.0.1) con «[[int.adif]]» o «[[int.n1mm]]».', 'Para os próximos QSO: em [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] liga «[[int.resend]]» no destinatário do teu log (vê «Log fechado: os QSO chegam depois»). A Aurora guarda de parte os QSO feitos com o log fechado e envia-os sozinha cerca de 15 segundos depois de o reabrires, pela ordem em que os fizeste. Vale para um log no mesmo PC (endereço 127.0.0.1) com «[[int.adif]]» ou «[[int.n1mm]]».'],
      ['Per i QSO già persi: apri [[nav.log]], filtra per data i QSO che mancano e salvali con «[[exp.save]]» in un file ADIF; poi importa quel file nel programma di log (quasi tutti hanno «Importa ADIF»). In un servizio in rete (ClubLog, QRZ.com, eQSL, LoTW) si carica lo stesso file ADIF dal suo sito.', 'For QSOs already lost: open [[nav.log]], filter by date the QSOs that are missing and save them with “[[exp.save]]” to an ADIF file; then import that file into the log program (almost all have “Import ADIF”). For an online service (ClubLog, QRZ.com, eQSL, LoTW) you upload the same ADIF file from its website.', 'Für die schon verlorenen QSOs: Öffne [[nav.log]], filtere nach Datum die fehlenden QSOs und speichere sie mit „[[exp.save]]“ in einer ADIF-Datei; importiere dann diese Datei im Logprogramm (fast alle haben „ADIF importieren“). In einem Online-Dienst (ClubLog, QRZ.com, eQSL, LoTW) lädst du dieselbe ADIF-Datei auf dessen Website hoch.', 'Pour les QSO déjà perdus : ouvre [[nav.log]], filtre par date les QSO qui manquent et enregistre-les avec « [[exp.save]] » dans un fichier ADIF ; puis importe ce fichier dans le programme de log (presque tous ont « Importer ADIF »). Dans un service en ligne (ClubLog, QRZ.com, eQSL, LoTW) on charge le même fichier ADIF depuis son site.', 'Para los QSO ya perdidos: abre [[nav.log]], filtra por fecha los QSO que faltan y guárdalos con «[[exp.save]]» en un archivo ADIF; luego importa ese archivo en el programa de log (casi todos tienen «Importar ADIF»). En un servicio en línea (ClubLog, QRZ.com, eQSL, LoTW) se sube el mismo archivo ADIF desde su sitio.', 'Para os QSO já perdidos: abre [[nav.log]], filtra por data os QSO que faltam e guarda-os com «[[exp.save]]» num ficheiro ADIF; depois importa esse ficheiro no programa de log (quase todos têm «Importar ADIF»). Num serviço online (ClubLog, QRZ.com, eQSL, LoTW) carrega-se o mesmo ficheiro ADIF a partir do seu site.'],
      ['Per Wavelog, ClubLog, QRZ.com, HRDLOG.NET e LoTW l’invio diretto ha già la sua coda: i QSO non inviati restano in attesa e partono appena il servizio risponde (vedi «Servizi di log in rete e ricerca nominativi»).', 'For Wavelog, ClubLog, QRZ.com, HRDLOG.NET and LoTW the direct upload already has its own queue: QSOs not sent stay waiting and go out as soon as the service answers (see “Online log services and callsign lookup”).', 'Für Wavelog, ClubLog, QRZ.com, HRDLOG.NET und LoTW hat der direkte Versand schon seine Warteschlange: Nicht gesendete QSOs bleiben wartend und gehen los, sobald der Dienst antwortet (siehe „Online-Logdienste und Rufzeichensuche“).', 'Pour Wavelog, ClubLog, QRZ.com, HRDLOG.NET et LoTW, l’envoi direct a déjà sa file : les QSO non envoyés restent en attente et partent dès que le service répond (voir « Services de log en ligne et recherche d’indicatifs »).', 'Para Wavelog, ClubLog, QRZ.com, HRDLOG.NET y LoTW el envío directo ya tiene su cola: los QSO no enviados quedan en espera y salen en cuanto el servicio responde (mira «Servicios de log en línea y búsqueda de indicativos»).', 'Para Wavelog, ClubLog, QRZ.com, HRDLOG.NET e LoTW o envio direto já tem a sua fila: os QSO não enviados ficam à espera e partem assim que o serviço responder (vê «Serviços de log online e pesquisa de indicativos»).'],
      ['Un QSO che tu correggi o cancelli in Aurora non viene corretto né cancellato negli altri log: va fatto a mano anche lì.', 'A QSO that you correct or delete in Aurora is not corrected or deleted in the other logs: it must be done by hand there too.', 'Ein QSO, das du in Aurora korrigierst oder löschst, wird in den anderen Logs weder korrigiert noch gelöscht: Das musst du auch dort von Hand tun.', 'Un QSO que tu corriges ou supprimes dans Aurora n’est ni corrigé ni supprimé dans les autres logs : il faut le faire à la main là aussi.', 'Un QSO que corriges o borras en Aurora no se corrige ni se borra en los demás logs: hay que hacerlo a mano también allí.', 'Um QSO que corrijas ou apagues na Aurora não é corrigido nem apagado nos outros logs: tem de se fazer à mão também aí.'],
    ],
  },
  {
    id: 'p-history',
    title: ['Lo Storico dei messaggi', 'The message History', 'Der Nachrichtenverlauf', 'L’historique des messages', 'El Historial de mensajes', 'O Histórico das mensagens'],
    text: ['La pagina «[[hist.title]]» elenca tutti i messaggi che hai ricevuto, ricercabili. Non è il log dei QSO: qui ci sono le stazioni sentite, non i collegamenti fatti. Non ha una voce nei menu: si apre dall’indirizzo «#/storico» (per esempio nel browser, dopo l’indirizzo di Aurora). Aurora lo ricorda come ultima pagina aperta.', 'The “[[hist.title]]” page lists all the messages you have received, searchable. It is not the QSO log: here are the stations heard, not the contacts made. It has no entry in the menus: it opens from the address “#/storico” (for example in the browser, after the Aurora address). Aurora remembers it as the last page opened.', 'Die Seite „[[hist.title]]“ listet alle Nachrichten auf, die du empfangen hast, durchsuchbar. Es ist nicht das QSO-Log: Hier stehen die gehörten Stationen, nicht die gefahrenen Verbindungen. Sie hat keinen Eintrag in den Menüs: Sie öffnet sich über die Adresse „#/storico“ (zum Beispiel im Browser, hinter der Adresse von Aurora). Aurora merkt sie sich als zuletzt geöffnete Seite.', 'La page « [[hist.title]] » liste tous les messages que tu as reçus, avec recherche. Ce n’est pas le log des QSO : ici il y a les stations entendues, pas les contacts faits. Elle n’a pas d’entrée dans les menus : elle s’ouvre depuis l’adresse « #/storico » (par exemple dans le navigateur, après l’adresse d’Aurora). Aurora la retient comme dernière page ouverte.', 'La página «[[hist.title]]» lista todos los mensajes que has recibido, con búsqueda. No es el log de los QSO: aquí están las estaciones oídas, no los contactos hechos. No tiene una entrada en los menús: se abre desde la dirección «#/storico» (por ejemplo en el navegador, después de la dirección de Aurora). Aurora la recuerda como última página abierta.', 'A página «[[hist.title]]» lista todas as mensagens que recebeste, com pesquisa. Não é o log dos QSO: aqui estão as estações ouvidas, não os contactos feitos. Não tem uma entrada nos menus: abre-se a partir do endereço «#/storico» (por exemplo no navegador, a seguir ao endereço da Aurora). A Aurora lembra-se dela como última página aberta.'],
    steps: [
      ['Filtri: il campo «[[hist.search]]», le tendine «[[hist.band]]», «[[hist.mode]]» e «[[hist.period]]» («[[hist.p.1h]]», «[[hist.p.24h]]», «[[hist.p.7d]]» o «[[hist.p.all]]»). Il pulsante «[[hist.clear]]» cancella tutti i messaggi salvati, dopo una conferma; il log dei QSO non cambia.', 'Filters: the “[[hist.search]]” field, the drop-downs “[[hist.band]]”, “[[hist.mode]]” and “[[hist.period]]” (“[[hist.p.1h]]”, “[[hist.p.24h]]”, “[[hist.p.7d]]” or “[[hist.p.all]]”). The “[[hist.clear]]” button deletes all the saved messages, after a confirmation; the QSO log does not change.', 'Filter: das Feld „[[hist.search]]“, die Auswahllisten „[[hist.band]]“, „[[hist.mode]]“ und „[[hist.period]]“ („[[hist.p.1h]]“, „[[hist.p.24h]]“, „[[hist.p.7d]]“ oder „[[hist.p.all]]“). Die Schaltfläche „[[hist.clear]]“ löscht alle gespeicherten Nachrichten, nach einer Bestätigung; das QSO-Log ändert sich nicht.', 'Filtres : le champ « [[hist.search]] », les listes « [[hist.band]] », « [[hist.mode]] » et « [[hist.period]] » (« [[hist.p.1h]] », « [[hist.p.24h]] », « [[hist.p.7d]] » ou « [[hist.p.all]] »). Le bouton « [[hist.clear]] » supprime tous les messages enregistrés, après une confirmation ; le log des QSO ne change pas.', 'Filtros: el campo «[[hist.search]]», las listas «[[hist.band]]», «[[hist.mode]]» y «[[hist.period]]» («[[hist.p.1h]]», «[[hist.p.24h]]», «[[hist.p.7d]]» o «[[hist.p.all]]»). El botón «[[hist.clear]]» borra todos los mensajes guardados, tras una confirmación; el log de los QSO no cambia.', 'Filtros: o campo «[[hist.search]]», as listas «[[hist.band]]», «[[hist.mode]]» e «[[hist.period]]» («[[hist.p.1h]]», «[[hist.p.24h]]», «[[hist.p.7d]]» ou «[[hist.p.all]]»). O botão «[[hist.clear]]» apaga todas as mensagens guardadas, depois de uma confirmação; o log dos QSO não muda.'],
      ['Colonne: «[[hist.col.when]]», «[[hist.col.band]]», «[[hist.col.mode]]», «[[hist.col.snr]]», «[[hist.col.freq]]» (frequenza audio in Hz), «[[hist.col.text]]» (con il segno LoTW se la stazione lo usa) e «[[hist.col.country]]». Un clic su una riga con un nominativo lo mette nel campo di ricerca («[[hist.pick]]»).', 'Columns: “[[hist.col.when]]”, “[[hist.col.band]]”, “[[hist.col.mode]]”, “[[hist.col.snr]]”, “[[hist.col.freq]]” (audio frequency in Hz), “[[hist.col.text]]” (with the LoTW mark if the station uses it) and “[[hist.col.country]]”. A click on a row with a callsign puts it in the search field (“[[hist.pick]]”).', 'Spalten: „[[hist.col.when]]“, „[[hist.col.band]]“, „[[hist.col.mode]]“, „[[hist.col.snr]]“, „[[hist.col.freq]]“ (Audiofrequenz in Hz), „[[hist.col.text]]“ (mit dem LoTW-Zeichen, wenn die Station es nutzt) und „[[hist.col.country]]“. Ein Klick auf eine Zeile mit einem Rufzeichen setzt es in das Suchfeld („[[hist.pick]]“).', 'Colonnes : « [[hist.col.when]] », « [[hist.col.band]] », « [[hist.col.mode]] », « [[hist.col.snr]] », « [[hist.col.freq]] » (fréquence audio en Hz), « [[hist.col.text]] » (avec le signe LoTW si la station l’utilise) et « [[hist.col.country]] ». Un clic sur une ligne avec un indicatif le met dans le champ de recherche (« [[hist.pick]] »).', 'Columnas: «[[hist.col.when]]», «[[hist.col.band]]», «[[hist.col.mode]]», «[[hist.col.snr]]», «[[hist.col.freq]]» (frecuencia de audio en Hz), «[[hist.col.text]]» (con la marca LoTW si la estación lo usa) y «[[hist.col.country]]». Un clic en una fila con un indicativo lo pone en el campo de búsqueda («[[hist.pick]]»).', 'Colunas: «[[hist.col.when]]», «[[hist.col.band]]», «[[hist.col.mode]]», «[[hist.col.snr]]», «[[hist.col.freq]]» (frequência de áudio em Hz), «[[hist.col.text]]» (com o sinal LoTW se a estação o usa) e «[[hist.col.country]]». Um clique numa linha com um indicativo põe-no no campo de pesquisa («[[hist.pick]]»).'],
      ['In fondo: quanti messaggi vedi su quanti ce ne sono, il pulsante «[[hist.more]]» per caricare altre righe e il totale dei messaggi e delle stazioni con la data del primo.', 'At the bottom: how many messages you see out of how many there are, the “[[hist.more]]” button to load more rows and the total of messages and stations with the date of the first one.', 'Unten: wie viele Nachrichten du von wie vielen siehst, die Schaltfläche „[[hist.more]]“, um weitere Zeilen zu laden, und die Gesamtzahl der Nachrichten und der Stationen mit dem Datum der ersten.', 'En bas : combien de messages tu vois sur combien il y en a, le bouton « [[hist.more]] » pour charger d’autres lignes et le total des messages et des stations avec la date du premier.', 'Al final: cuántos mensajes ves de cuántos hay, el botón «[[hist.more]]» para cargar más filas y el total de los mensajes y de las estaciones con la fecha del primero.', 'No fundo: quantas mensagens vês em quantas existem, o botão «[[hist.more]]» para carregar mais linhas e o total das mensagens e das estações com a data da primeira.'],
    ],
  },
  {
    id: 'p-dxmapbar',
    title: ['Mappa DX: la barra dei comandi e l’ingranaggio', 'DX Map: the command bar and the gear', 'DX-Karte: Befehlsleiste und Zahnrad', 'Carte DX : la barre de commandes et l’engrenage', 'Mapa DX: la barra de comandos y el engranaje', 'Mapa DX: a barra de comandos e a roda dentada'],
    text: ['La pagina [[nav.dxmap]] è un planisfero con le stazioni in onda, i tuoi quadrati e le linee. Sopra la mappa c’è una barra con tutti i comandi; ogni voce ha il suo suggerimento. La stessa mappa sta nella linguetta «[[log.tab.map]]» del pannello Log, con una riga sola di comandi (vedi «La mappa nel pannello Log»).', 'The [[nav.dxmap]] page is a world map with the stations on the air, your squares and the lines. Above the map there is a bar with all the commands; each item has its hint. The same map is in the “[[log.tab.map]]” tab of the Log panel, with a single row of commands (see “The map in the Log panel”).', 'Die Seite [[nav.dxmap]] ist ein Globus mit den aktiven Stationen, deinen Feldern und den Linien. Über der Karte sitzt eine Leiste mit allen Befehlen; jeder Eintrag hat seinen Hinweis. Dieselbe Karte liegt im Reiter „[[log.tab.map]]“ des Log-Feldes, mit nur einer Befehlszeile (siehe „Die Karte im Log-Bereich“).', 'La page [[nav.dxmap]] est un planisphère avec les stations en l’air, tes carrés et les lignes. Au-dessus de la carte il y a une barre avec toutes les commandes ; chaque entrée a son info-bulle. La même carte est dans l’onglet « [[log.tab.map]] » du panneau Journal, avec une seule ligne de commandes (voir « La carte dans le panneau Journal »).', 'La página [[nav.dxmap]] es un planisferio con las estaciones en el aire, tus cuadrículas y las líneas. Sobre el mapa hay una barra con todos los comandos; cada opción tiene su sugerencia. El mismo mapa está en la pestaña «[[log.tab.map]]» del panel Log, con una sola fila de comandos (mira «El mapa en el panel Log»).', 'A página [[nav.dxmap]] é um planisfério com as estações no ar, as tuas quadrículas e as linhas. Por cima do mapa há uma barra com todos os comandos; cada entrada tem a sua sugestão. O mesmo mapa está no separador «[[log.tab.map]]» do painel Log, com uma só linha de comandos (vê «O mapa no painel Log»).'],
    steps: [
      ['La tendina di sinistra ([[map.style]]) cambia lo sfondo della mappa; il cursore ☼ ([[dxmap.brightness]]) la schiarisce o la scurisce.', 'The left drop-down ([[map.style]]) changes the map background; the ☼ slider ([[dxmap.brightness]]) lightens or darkens it.', 'Die Auswahlliste links ([[map.style]]) ändert den Hintergrund der Karte; der Regler ☼ ([[dxmap.brightness]]) macht sie heller oder dunkler.', 'La liste de gauche ([[map.style]]) change le fond de la carte ; le curseur de luminosité ([[dxmap.brightness]]) l’éclaircit ou l’assombrit.', 'La lista desplegable de la izquierda ([[map.style]]) cambia el fondo del mapa; el cursor ☼ ([[dxmap.brightness]]) lo aclara o lo oscurece.', 'A lista da esquerda ([[map.style]]) muda o fundo do mapa; o cursor ☼ ([[dxmap.brightness]]) clareia-o ou escurece-o.'],
      ['Caselle: «[[dxmap.greyline]]» (la linea del giorno e della notte), «[[dxmap.arcs]]» (una linea dalla tua stazione a ogni stazione in onda), «[[dxmap.heat]]» (la mappa di calore di chi ti ha ricevuto, da PSK Reporter), «[[dxmap.links]]» (una linea tra due stazioni quando una chiama l’altra, dorata se chiamano te), «[[dxmap.onlyHeardMe]]» (solo le linee verso chi ti ha ricevuto), «[[dxmap.callLabels]]» (nominativi sempre scritti; spento si vedono passando il mouse), «[[dxmap.squares]]» (i quadrati lavorati: giallo = lavorato, verde = confermato).', 'Check boxes: “[[dxmap.greyline]]” (the day and night line), “[[dxmap.arcs]]” (a line from your station to every station on the air), “[[dxmap.heat]]” (the heat map of who has received you, from PSK Reporter), “[[dxmap.links]]” (a line between two stations when one calls the other, golden if they call you), “[[dxmap.onlyHeardMe]]” (only the lines to those who received you), “[[dxmap.callLabels]]” (callsigns always written; when off they show on hover), “[[dxmap.squares]]” (the worked squares: yellow = worked, green = confirmed).', 'Kästchen: „[[dxmap.greyline]]“ (die Linie von Tag und Nacht), „[[dxmap.arcs]]“ (eine Linie von deiner Station zu jeder aktiven Station), „[[dxmap.heat]]“ (die Heatmap derer, die dich empfangen haben, von PSK Reporter), „[[dxmap.links]]“ (eine Linie zwischen zwei Stationen, wenn eine die andere ruft, golden, wenn sie dich rufen), „[[dxmap.onlyHeardMe]]“ (nur die Linien zu denen, die dich empfangen haben), „[[dxmap.callLabels]]“ (Rufzeichen immer angeschrieben; aus siehst du sie, wenn du die Maus darüberhältst), „[[dxmap.squares]]“ (die gearbeiteten Felder: gelb = gearbeitet, grün = bestätigt).', 'Cases : « [[dxmap.greyline]] » (la ligne du jour et de la nuit), « [[dxmap.arcs]] » (une ligne de ta station à chaque station en l’air), « [[dxmap.heat]] » (la carte de chaleur de ceux qui t’ont reçu, depuis PSK Reporter), « [[dxmap.links]] » (une ligne entre deux stations quand l’une appelle l’autre, dorée si elles t’appellent), « [[dxmap.onlyHeardMe]] » (seulement les lignes vers ceux qui t’ont reçu), « [[dxmap.callLabels]] » (indicatifs toujours écrits ; éteint, ils se voient en passant la souris), « [[dxmap.squares]] » (les carrés contactés : jaune = contacté, vert = confirmé).', 'Casillas: «[[dxmap.greyline]]» (la línea del día y de la noche), «[[dxmap.arcs]]» (una línea desde tu estación hasta cada estación en el aire), «[[dxmap.heat]]» (el mapa de calor de quien te ha recibido, de PSK Reporter), «[[dxmap.links]]» (una línea entre dos estaciones cuando una llama a la otra, dorada si te llaman a ti), «[[dxmap.onlyHeardMe]]» (solo las líneas hacia quien te ha recibido), «[[dxmap.callLabels]]» (indicativos siempre escritos; apagado se ven al pasar el ratón), «[[dxmap.squares]]» (los cuadrados trabajados: amarillo = trabajado, verde = confirmado).', 'Caixas: «[[dxmap.greyline]]» (a linha do dia e da noite), «[[dxmap.arcs]]» (uma linha da tua estação a cada estação no ar), «[[dxmap.heat]]» (o mapa de calor de quem te recebeu, do PSK Reporter), «[[dxmap.links]]» (uma linha entre duas estações quando uma chama a outra, dourada se chamam a ti), «[[dxmap.onlyHeardMe]]» (só as linhas para quem te recebeu), «[[dxmap.callLabels]]» (indicativos sempre escritos; desligado veem-se passando o rato), «[[dxmap.squares]]» (as quadrículas trabalhadas: amarelo = trabalhada, verde = confirmada).'],
      ['Le due tendine seguenti scelgono la banda («[[dxmap.bandNow]]» segue la radio, oppure «[[dxmap.allBands]]» o una banda) e il modo dei quadrati («[[dxmap.allModes]]»; attiva solo con «[[dxmap.squares]]» acceso). A destra «n in onda» conta le stazioni in onda.', 'The next two drop-downs choose the band (“[[dxmap.bandNow]]” follows the radio, or “[[dxmap.allBands]]” or one band) and the mode of the squares (“[[dxmap.allModes]]”; active only with “[[dxmap.squares]]” on). On the right “n on air” counts the stations on the air.', 'Die beiden folgenden Auswahllisten wählen das Band („[[dxmap.bandNow]]“ folgt dem Funkgerät, oder „[[dxmap.allBands]]“ oder ein Band) und die Betriebsart der Felder („[[dxmap.allModes]]“; nur aktiv, wenn „[[dxmap.squares]]“ eingeschaltet ist). Rechts zählt „n auf Sendung“ die aktiven Stationen.', 'Les deux listes suivantes choisissent la bande (« [[dxmap.bandNow]] » suit la radio, ou « [[dxmap.allBands]] » ou une bande) et le mode des carrés (« [[dxmap.allModes]] » ; active seulement avec « [[dxmap.squares]] » allumé). À droite, « n en l’air » compte les stations en l’air.', 'Las dos listas siguientes eligen la banda («[[dxmap.bandNow]]» sigue a la radio, o «[[dxmap.allBands]]» o una banda) y el modo de los cuadrados («[[dxmap.allModes]]»; activa solo con «[[dxmap.squares]]» encendido). A la derecha «n en el aire» cuenta las estaciones en el aire.', 'As duas listas seguintes escolhem a banda («[[dxmap.bandNow]]» segue o rádio, ou «[[dxmap.allBands]]» ou uma banda) e o modo das quadrículas («[[dxmap.allModes]]»; ativa só com «[[dxmap.squares]]» ligado). À direita «n no ar» conta as estações no ar.'],
      ['L’ingranaggio ⚙ («[[dxmap.more]]») apre le altre impostazioni: «[[dxmap.spotMax]]» (da 5 minuti a 6 ore: quanto vecchi sono gli spot di PSK Reporter mostrati), «[[dxmap.background]]» (colore), «[[dxmap.autoNight]]» con lo stile di notte e «[[dxmap.nightDark]]» (quanto scura), «[[dxmap.twilight]]», «[[dxmap.moon]]», «[[dxmap.animated]]» (linee animate), per la propagazione «[[dxmap.spotPaths]]» e il suo colore e «[[dxmap.dots]]», per «Chi chiama chi» il colore, «[[dxmap.linkMeColor]]», lo spessore e la velocità, e «[[dxmap.decay]]» (da 2 a 60 minuti: dopo quanto una stazione sbiadisce e sparisce).', 'The gear ⚙ (“[[dxmap.more]]”) opens the other settings: “[[dxmap.spotMax]]” (from 5 minutes to 6 hours: how old the PSK Reporter spots shown are), “[[dxmap.background]]” (colour), “[[dxmap.autoNight]]” with the night style and “[[dxmap.nightDark]]” (how dark), “[[dxmap.twilight]]”, “[[dxmap.moon]]”, “[[dxmap.animated]]” (animated lines), for propagation “[[dxmap.spotPaths]]” and its colour and “[[dxmap.dots]]”, for “Who calls whom” the colour, “[[dxmap.linkMeColor]]”, the thickness and the speed, and “[[dxmap.decay]]” (from 2 to 60 minutes: how long before a station fades and disappears).', 'Das Zahnrad ⚙ („[[dxmap.more]]“) öffnet die weiteren Einstellungen: „[[dxmap.spotMax]]“ (von 5 Minuten bis 6 Stunden: wie alt die gezeigten PSK-Reporter-Spots sind), „[[dxmap.background]]“ (Farbe), „[[dxmap.autoNight]]“ mit dem Nachtstil und „[[dxmap.nightDark]]“ (wie dunkel), „[[dxmap.twilight]]“, „[[dxmap.moon]]“, „[[dxmap.animated]]“ (animierte Linien), für die Ausbreitung „[[dxmap.spotPaths]]“ und ihre Farbe und „[[dxmap.dots]]“, für „Wer ruft wen“ die Farbe, „[[dxmap.linkMeColor]]“, die Dicke und die Geschwindigkeit, und „[[dxmap.decay]]“ (von 2 bis 60 Minuten: nach welcher Zeit eine Station verblasst und verschwindet).', 'L’engrenage (« [[dxmap.more]] ») ouvre les autres réglages : « [[dxmap.spotMax]] » (de 5 minutes à 6 heures : l’ancienneté des spots de PSK Reporter affichés), « [[dxmap.background]] » (couleur), « [[dxmap.autoNight]] » avec le style de nuit et « [[dxmap.nightDark]] » (à quel point il est sombre), « [[dxmap.twilight]] », « [[dxmap.moon]] », « [[dxmap.animated]] » (lignes animées), pour la propagation « [[dxmap.spotPaths]] » et sa couleur et « [[dxmap.dots]] », pour « Qui appelle qui » la couleur, « [[dxmap.linkMeColor]] », l’épaisseur et la vitesse, et « [[dxmap.decay]] » (de 2 à 60 minutes : au bout de combien de temps une station s’estompe et disparaît).', 'El engranaje ⚙ («[[dxmap.more]]») abre los demás ajustes: «[[dxmap.spotMax]]» (de 5 minutos a 6 horas: qué antigüedad tienen los spots de PSK Reporter mostrados), «[[dxmap.background]]» (color), «[[dxmap.autoNight]]» con el estilo de noche y «[[dxmap.nightDark]]» (cuánto de oscura), «[[dxmap.twilight]]», «[[dxmap.moon]]», «[[dxmap.animated]]» (líneas animadas), para la propagación «[[dxmap.spotPaths]]» y su color y «[[dxmap.dots]]», para «Quién llama a quién» el color, «[[dxmap.linkMeColor]]», el grosor y la velocidad, y «[[dxmap.decay]]» (de 2 a 60 minutos: después de cuánto una estación se desvanece y desaparece).', 'A roda dentada ⚙ («[[dxmap.more]]») abre as outras definições: «[[dxmap.spotMax]]» (de 5 minutos a 6 horas: que idade têm os spots do PSK Reporter mostrados), «[[dxmap.background]]» (cor), «[[dxmap.autoNight]]» com o estilo de noite e «[[dxmap.nightDark]]» (quão escura), «[[dxmap.twilight]]», «[[dxmap.moon]]», «[[dxmap.animated]]» (linhas animadas), para a propagação «[[dxmap.spotPaths]]» e a sua cor e «[[dxmap.dots]]», para «Quem chama quem» a cor, «[[dxmap.linkMeColor]]», a espessura e a velocidade, e «[[dxmap.decay]]» (de 2 a 60 minutos: passado quanto tempo uma estação esmorece e desaparece).'],
      ['Sulla mappa: rotella o i pulsanti + e − per ingrandire, tieni premuto e trascina per spostarti. Un clic su un punto dà quadrato, distanza, paese e zone CQ e ITU. Un clic su una stazione in onda, o sul suo nominativo, la chiama: Aurora lascia il QSO in corso e le risponde, come nella coda.', 'On the map: wheel or the + and − buttons to zoom, hold down and drag to move. A click on a point gives square, distance, country and CQ and ITU zones. A click on a station on the air, or on its callsign, calls it: Aurora leaves the current QSO and replies to it, as with the queue.', 'Auf der Karte: Mausrad oder die Schaltflächen + und − zum Vergrößern, gedrückt halten und ziehen, um dich zu bewegen. Ein Klick auf einen Punkt gibt Feld, Entfernung, Land und CQ- und ITU-Zonen. Ein Klick auf eine aktive Station oder auf ihr Rufzeichen ruft sie: Aurora verlässt das laufende QSO und antwortet ihr, wie bei der Warteschlange.', 'Sur la carte : molette ou boutons + et − pour zoomer, garde appuyé et glisse pour te déplacer. Un clic sur un point donne carré, distance, pays et zones CQ et ITU. Un clic sur une station en l’air, ou sur son indicatif, l’appelle : Aurora laisse le QSO en cours et lui répond, comme dans la file.', 'En el mapa: rueda del ratón o los botones + y − para acercar, mantén pulsado y arrastra para moverte. Un clic en un punto da cuadrícula, distancia, país y zonas CQ e ITU. Un clic en una estación en el aire, o en su indicativo, la llama: Aurora deja el QSO en curso y le responde, como en la cola.', 'No mapa: roda do rato ou os botões + e − para ampliar, mantém premido e arrasta para te deslocares. Um clique num ponto dá quadrícula, distância, país e zonas CQ e ITU. Um clique numa estação no ar, ou no seu indicativo, chama-a: a Aurora deixa o QSO em curso e responde-lhe, como na fila.'],
      ['In basso a sinistra la legenda: QSO (quadrato lavorato dal log), QSL (confermato), QSX (traffico in onda, non con te), CQ, CQDX e QRZ (chi chiama te). In trasmissione una linea rossa va alla stazione chiamata.', 'At the bottom left the legend: QSO (square worked from the log), QSL (confirmed), QSX (traffic on the air, not with you), CQ, CQDX and QRZ (who calls you). While transmitting a red line goes to the station you are calling.', 'Unten links die Legende: QSO (aus dem Log gearbeitetes Feld), QSL (bestätigt), QSX (Verkehr auf Sendung, nicht mit dir), CQ, CQDX und QRZ (wer dich ruft). Beim Senden führt eine rote Linie zur gerufenen Station.', 'En bas à gauche la légende : QSO (carré contacté d’après le log), QSL (confirmé), QSX (trafic en l’air, pas avec toi), CQ, CQDX et QRZ (ceux qui t’appellent). En émission, une ligne rouge va vers la station appelée.', 'Abajo a la izquierda la leyenda: QSO (cuadrado trabajado desde el log), QSL (confirmado), QSX (tráfico en el aire, no contigo), CQ, CQDX y QRZ (quien te llama a ti). En transmisión una línea roja va a la estación llamada.', 'Em baixo à esquerda a legenda: QSO (quadrícula trabalhada a partir do log), QSL (confirmada), QSX (tráfego no ar, não contigo), CQ, CQDX e QRZ (quem te chama). Em transmissão uma linha vermelha vai à estação chamada.'],
      ['Il pulsante ⧉ in alto a destra porta la mappa in una finestra a parte (vedi «Finestre a parte e disposizione»).', 'The ⧉ button at the top right moves the map to a separate window (see “Separate windows and layout”).', 'Die Schaltfläche ⧉ oben rechts bringt die Karte in ein eigenes Fenster (siehe „Eigene Fenster und Anordnung“).', 'Le bouton ⧉ en haut à droite amène la carte dans une fenêtre à part (voir « Fenêtres détachées et disposition »).', 'El botón ⧉ de arriba a la derecha lleva el mapa a una ventana aparte (mira «Ventanas aparte y disposición»).', 'O botão ⧉ em cima à direita leva o mapa para uma janela à parte (vê «Janelas à parte e disposição»).'],
    ],
  },
  {
    id: 'p-prop',
    title: ['Propagazione: ogni riquadro', 'Propagation: every panel', 'Ausbreitung: jedes Feld', 'Propagation : chaque encadré', 'Propagación: cada recuadro', 'Propagação: cada quadro'],
    text: ['La pagina [[nav.propagation]] (titolo «[[prop.title]]») ha a sinistra le condizioni del sole e delle bande, a destra la mappa e l’elenco di chi ti ha ricevuto. Servono i servizi online; spenti la pagina lo dice con il pulsante «[[prop.settings]]» (si accendono in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). In alto, il pulsante «[[prop.refresh]]» chiede subito i dati nuovi invece di aspettare i 10 secondi.', 'The [[nav.propagation]] page (title “[[prop.title]]”) has on the left the conditions of the sun and of the bands, on the right the map and the list of who has received you. It needs the online services; when they are off the page says so with the “[[prop.settings]]” button (they are turned on in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). At the top, the “[[prop.refresh]]” button asks for new data right away instead of waiting the 10 seconds.', 'Die Seite [[nav.propagation]] (Titel „[[prop.title]]“) hat links die Bedingungen von Sonne und Bändern, rechts die Karte und die Liste derer, die dich empfangen haben. Du brauchst die Online-Dienste; sind sie aus, sagt es die Seite mit der Schaltfläche „[[prop.settings]]“ (sie werden unter [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] eingeschaltet). Oben fordert die Schaltfläche „[[prop.refresh]]“ sofort neue Daten an, statt die 10 Sekunden abzuwarten.', 'La page [[nav.propagation]] (titre « [[prop.title]] ») a à gauche les conditions du soleil et des bandes, à droite la carte et la liste de ceux qui t’ont reçu. Il faut les services en ligne ; éteints, la page le dit avec le bouton « [[prop.settings]] » (ils s’allument dans [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). En haut, le bouton « [[prop.refresh]] » demande tout de suite les nouvelles données au lieu d’attendre les 10 secondes.', 'La página [[nav.propagation]] (título «[[prop.title]]») tiene a la izquierda las condiciones del sol y de las bandas, a la derecha el mapa y la lista de quien te ha recibido. Hacen falta los servicios en línea; apagados, la página lo dice con el botón «[[prop.settings]]» (se encienden en [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). Arriba, el botón «[[prop.refresh]]» pide enseguida los datos nuevos en lugar de esperar los 10 segundos.', 'A página [[nav.propagation]] (título «[[prop.title]]») tem à esquerda as condições do sol e das bandas, à direita o mapa e a lista de quem te recebeu. São precisos os serviços online; desligados a página di-lo com o botão «[[prop.settings]]» (ligam-se em [[nav.settings]] › [[sw.fam.log]] › [[tab.online]]). Em cima, o botão «[[prop.refresh]]» pede logo os dados novos em vez de esperar os 10 segundos.'],
    steps: [
      ['Riquadro «[[prop.solar]]»: tre indicatori — «[[prop.sfi]]» (il flusso solare a 10,7 cm: sopra 100 le bande alte si aprono, sotto 70 sono chiuse), «[[prop.a]]» (più basso = propagazione più calma) e «[[prop.k]]» (da 5 in su c’è una tempesta geomagnetica) — con il colore del giudizio; poi «[[prop.xray]]», «[[prop.spots]]», «[[prop.wind]]», «[[prop.geomag]]», «[[prop.noise]]» e, se c’è, «[[prop.aurora]]». In fondo l’ora dell’ultimo aggiornamento e la fonte dei dati (N0NBH, hamqsl.com).', '“[[prop.solar]]” box: three indicators — “[[prop.sfi]]” (the 10.7 cm solar flux: above 100 the high bands open, below 70 they are closed), “[[prop.a]]” (lower = calmer propagation) and “[[prop.k]]” (from 5 up there is a geomagnetic storm) — with the colour of the verdict; then “[[prop.xray]]”, “[[prop.spots]]”, “[[prop.wind]]”, “[[prop.geomag]]”, “[[prop.noise]]” and, if present, “[[prop.aurora]]”. At the bottom the time of the last update and the data source (N0NBH, hamqsl.com).', 'Feld „[[prop.solar]]“: drei Anzeigen — „[[prop.sfi]]“ (der Sonnenfluss bei 10,7 cm: über 100 öffnen sich die hohen Bänder, unter 70 sind sie zu), „[[prop.a]]“ (niedriger = ruhigere Ausbreitung) und „[[prop.k]]“ (ab 5 gibt es einen geomagnetischen Sturm) — mit der Farbe der Beurteilung; dann „[[prop.xray]]“, „[[prop.spots]]“, „[[prop.wind]]“, „[[prop.geomag]]“, „[[prop.noise]]“ und, falls vorhanden, „[[prop.aurora]]“. Unten die Zeit der letzten Aktualisierung und die Datenquelle (N0NBH, hamqsl.com).', 'Encadré « [[prop.solar]] » : trois indicateurs — « [[prop.sfi]] » (le flux solaire à 10,7 cm : au-dessus de 100 les bandes hautes s’ouvrent, en dessous de 70 elles sont fermées), « [[prop.a]] » (plus bas = propagation plus calme) et « [[prop.k]] » (à partir de 5 il y a une tempête géomagnétique) — avec la couleur du jugement ; puis « [[prop.xray]] », « [[prop.spots]] », « [[prop.wind]] », « [[prop.geomag]] », « [[prop.noise]] » et, s’il y en a, « [[prop.aurora]] ». En bas l’heure de la dernière mise à jour et la source des données (N0NBH, hamqsl.com).', 'Recuadro «[[prop.solar]]»: tres indicadores — «[[prop.sfi]]» (el flujo solar a 10,7 cm: por encima de 100 las bandas altas se abren, por debajo de 70 están cerradas), «[[prop.a]]» (más bajo = propagación más tranquila) y «[[prop.k]]» (de 5 en adelante hay una tormenta geomagnética) — con el color del juicio; luego «[[prop.xray]]», «[[prop.spots]]», «[[prop.wind]]», «[[prop.geomag]]», «[[prop.noise]]» y, si lo hay, «[[prop.aurora]]». Al final la hora de la última actualización y la fuente de los datos (N0NBH, hamqsl.com).', 'Quadro «[[prop.solar]]»: três indicadores — «[[prop.sfi]]» (o fluxo solar a 10,7 cm: acima de 100 as bandas altas abrem-se, abaixo de 70 estão fechadas), «[[prop.a]]» (mais baixo = propagação mais calma) e «[[prop.k]]» (de 5 para cima há uma tempestade geomagnética) — com a cor do juízo; depois «[[prop.xray]]», «[[prop.spots]]», «[[prop.wind]]», «[[prop.geomag]]», «[[prop.noise]]» e, se houver, «[[prop.aurora]]». No fim a hora da última atualização e a fonte dos dados (N0NBH, hamqsl.com).'],
      ['«[[prop.bands]]»: una tabella con le bande raggruppate (80-40 m, 30-20 m, 17-15 m, 12-10 m) e due colonne, giorno (sole) e notte (luna). Ogni casella ha tre barrette (una = scarsa, due = discreta, tre = buona) e la parola «[[prop.cond.Good]]», «[[prop.cond.Fair]]» o «[[prop.cond.Poor]]». La colonna in cui ti trovi adesso è segnata «[[prop.here]]»; la riga del gruppo di bande su cui è la radio è evidenziata e dice «[[prop.tuned]]». Gli stessi dati stanno nel blocco «[[bands.title]]» della pagina Stazione.', '“[[prop.bands]]”: a table with the bands grouped (80-40 m, 30-20 m, 17-15 m, 12-10 m) and two columns, day (sun) and night (moon). Each box has three small bars (one = poor, two = fair, three = good) and the word “[[prop.cond.Good]]”, “[[prop.cond.Fair]]” or “[[prop.cond.Poor]]”. The column you are in now is marked “[[prop.here]]”; the row of the band group the radio is on is highlighted and says “[[prop.tuned]]”. The same data is in the “[[bands.title]]” block of the Station page.', '„[[prop.bands]]“: eine Tabelle mit den gruppierten Bändern (80-40 m, 30-20 m, 17-15 m, 12-10 m) und zwei Spalten, Tag (Sonne) und Nacht (Mond). Jedes Kästchen hat drei Balken (einer = schwach, zwei = mäßig, drei = gut) und das Wort „[[prop.cond.Good]]“, „[[prop.cond.Fair]]“ oder „[[prop.cond.Poor]]“. Die Spalte, in der du gerade bist, ist mit „[[prop.here]]“ markiert; die Zeile der Bandgruppe, auf der das Funkgerät steht, ist hervorgehoben und sagt „[[prop.tuned]]“. Dieselben Daten stehen im Block „[[bands.title]]“ der Seite Station.', '« [[prop.bands]] » : un tableau avec les bandes regroupées (80-40 m, 30-20 m, 17-15 m, 12-10 m) et deux colonnes, jour (soleil) et nuit (lune). Chaque case a trois petites barres (une = faible, deux = moyenne, trois = bonne) et le mot « [[prop.cond.Good]] », « [[prop.cond.Fair]] » ou « [[prop.cond.Poor]] ». La colonne où tu te trouves maintenant est marquée « [[prop.here]] » ; la ligne du groupe de bandes sur lequel est la radio est surlignée et dit « [[prop.tuned]] ». Les mêmes données sont dans le bloc « [[bands.title]] » de la page Station.', '«[[prop.bands]]»: una tabla con las bandas agrupadas (80-40 m, 30-20 m, 17-15 m, 12-10 m) y dos columnas, día (sol) y noche (luna). Cada casilla tiene tres barritas (una = escasa, dos = discreta, tres = buena) y la palabra «[[prop.cond.Good]]», «[[prop.cond.Fair]]» o «[[prop.cond.Poor]]». La columna en la que estás ahora está marcada «[[prop.here]]»; la fila del grupo de bandas en que está la radio aparece resaltada y dice «[[prop.tuned]]». Los mismos datos están en el bloque «[[bands.title]]» de la página Estación.', '«[[prop.bands]]»: uma tabela com as bandas agrupadas (80-40 m, 30-20 m, 17-15 m, 12-10 m) e duas colunas, dia (sol) e noite (lua). Cada casa tem três barrinhas (uma = fraca, duas = razoável, três = boa) e a palavra «[[prop.cond.Good]]», «[[prop.cond.Fair]]» ou «[[prop.cond.Poor]]». A coluna em que estás agora está assinalada «[[prop.here]]»; a linha do grupo de bandas em que está o rádio está realçada e diz «[[prop.tuned]]». Os mesmos dados estão no bloco «[[bands.title]]» da página Estação.'],
      ['Numeri sulla ricezione: quante stazioni ti hanno ricevuto nelle ultime ore, la più lontana, il rapporto migliore, e le barre «[[prop.stat.byBand]]» con il colore di ogni banda.', 'Numbers about reception: how many stations have received you in the last hours, the farthest one, the best report, and the “[[prop.stat.byBand]]” bars with the colour of each band.', 'Zahlen zum Empfang: wie viele Stationen dich in den letzten Stunden empfangen haben, die weiteste, der beste Rapport, und die Balken „[[prop.stat.byBand]]“ mit der Farbe jedes Bandes.', 'Chiffres sur la réception : combien de stations t’ont reçu ces dernières heures, la plus lointaine, le meilleur report, et les barres « [[prop.stat.byBand]] » avec la couleur de chaque bande.', 'Números sobre la recepción: cuántas estaciones te han recibido en las últimas horas, la más lejana, el mejor informe, y las barras «[[prop.stat.byBand]]» con el color de cada banda.', 'Números sobre a receção: quantas estações te receberam nas últimas horas, a mais distante, o melhor relatório, e as barras «[[prop.stat.byBand]]» com a cor de cada banda.'],
      ['Riquadro «[[prop.psk]]»: la mappa con una linea e un punto per ogni stazione che ti ha ricevuto (PSK Reporter) e la tabella con «[[prop.col.when]]», «[[prop.col.who]]», «[[prop.col.band]]», «[[prop.col.snr]]» e «[[prop.col.distance]]». Senza ricezioni dice che nessuna stazione ti ha ricevuto nelle ultime ore. Le nuove ricezioni arrivano in pochi secondi.', '“[[prop.psk]]” box: the map with a line and a dot for every station that has received you (PSK Reporter) and the table with “[[prop.col.when]]”, “[[prop.col.who]]”, “[[prop.col.band]]”, “[[prop.col.snr]]” and “[[prop.col.distance]]”. With no receptions it says that no station has received you in the last hours. New receptions arrive within a few seconds.', 'Feld „[[prop.psk]]“: die Karte mit einer Linie und einem Punkt für jede Station, die dich empfangen hat (PSK Reporter), und die Tabelle mit „[[prop.col.when]]“, „[[prop.col.who]]“, „[[prop.col.band]]“, „[[prop.col.snr]]“ und „[[prop.col.distance]]“. Ohne Empfänge sagt sie, dass dich in den letzten Stunden keine Station empfangen hat. Neue Empfänge kommen binnen weniger Sekunden.', 'Encadré « [[prop.psk]] » : la carte avec une ligne et un point pour chaque station qui t’a reçu (PSK Reporter) et le tableau avec « [[prop.col.when]] », « [[prop.col.who]] », « [[prop.col.band]] », « [[prop.col.snr]] » et « [[prop.col.distance]] ». Sans réceptions, elle dit qu’aucune station ne t’a reçu ces dernières heures. Les nouvelles réceptions arrivent en quelques secondes.', 'Recuadro «[[prop.psk]]»: el mapa con una línea y un punto por cada estación que te ha recibido (PSK Reporter) y la tabla con «[[prop.col.when]]», «[[prop.col.who]]», «[[prop.col.band]]», «[[prop.col.snr]]» y «[[prop.col.distance]]». Sin recepciones dice que ninguna estación te ha recibido en las últimas horas. Las nuevas recepciones llegan en pocos segundos.', 'Quadro «[[prop.psk]]»: o mapa com uma linha e um ponto por cada estação que te recebeu (PSK Reporter) e a tabela com «[[prop.col.when]]», «[[prop.col.who]]», «[[prop.col.band]]», «[[prop.col.snr]]» e «[[prop.col.distance]]». Sem receções diz que nenhuma estação te recebeu nas últimas horas. As receções novas chegam em poucos segundos.'],
    ],
  },
  {
    id: 'p-stats',
    title: ['Statistiche e scheda DXCC', 'Statistics and the DXCC card', 'Statistik und DXCC-Karte', 'Statistiques et onglet DXCC', 'Estadísticas y ficha DXCC', 'Estatísticas e separador DXCC'],
    text: ['La pagina [[nav.stats]] riassume il log. Se Aurora non trova il log dei QSO dice «[[stats.unavailable]]».', 'The [[nav.stats]] page summarizes the log. If Aurora can’t find the QSO log, it says “[[stats.unavailable]]”.', 'Die Seite [[nav.stats]] fasst das Log zusammen. Findet Aurora das QSO-Log nicht, sagt sie „[[stats.unavailable]]“.', 'La page [[nav.stats]] résume le log. Si Aurora ne trouve pas le log des QSO, elle dit « [[stats.unavailable]] ».', 'La página [[nav.stats]] resume el log. Si Aurora no encuentra el log de los QSO dice «[[stats.unavailable]]».', 'A página [[nav.stats]] resume o log. Se a Aurora não encontrar o log dos QSO diz «[[stats.unavailable]]».'],
    steps: [
      ['In alto sette riquadri con i numeri (passando il mouse leggi come sono calcolati): «[[stats.qsos]]», «[[stats.calls]]», «[[stats.dxcc]]», «[[stats.cq]]» e «[[stats.itu]]» (con la barra di avanzamento e il totale), «[[stats.grids]]» e «[[stats.prefixes]]».', 'At the top seven boxes with the numbers (hover over them to read how they are calculated): “[[stats.qsos]]”, “[[stats.calls]]”, “[[stats.dxcc]]”, “[[stats.cq]]” and “[[stats.itu]]” (with the progress bar and the total), “[[stats.grids]]” and “[[stats.prefixes]]”.', 'Oben sieben Felder mit den Zahlen (mit der Maus darüber liest du, wie sie berechnet werden): „[[stats.qsos]]“, „[[stats.calls]]“, „[[stats.dxcc]]“, „[[stats.cq]]“ und „[[stats.itu]]“ (mit Fortschrittsbalken und Gesamtzahl), „[[stats.grids]]“ und „[[stats.prefixes]]“.', 'En haut sept encadrés avec les chiffres (en passant la souris tu lis comment ils sont calculés) : « [[stats.qsos]] », « [[stats.calls]] », « [[stats.dxcc]] », « [[stats.cq]] » et « [[stats.itu]] » (avec la barre de progression et le total), « [[stats.grids]] » et « [[stats.prefixes]] ».', 'Arriba siete recuadros con los números (al pasar el ratón lees cómo se calculan): «[[stats.qsos]]», «[[stats.calls]]», «[[stats.dxcc]]», «[[stats.cq]]» y «[[stats.itu]]» (con la barra de avance y el total), «[[stats.grids]]» y «[[stats.prefixes]]».', 'Em cima sete quadros com os números (passando o rato lês como são calculados): «[[stats.qsos]]», «[[stats.calls]]», «[[stats.dxcc]]», «[[stats.cq]]» e «[[stats.itu]]» (com a barra de progresso e o total), «[[stats.grids]]» e «[[stats.prefixes]]».'],
      ['Riquadro «[[stats.byBand]]»: per ogni banda i paesi lavorati e i QSO, con una barra per vedere a colpo d’occhio dove hai lavorato di più.', '“[[stats.byBand]]” box: for each band the countries worked and the QSOs, with a bar to see at a glance where you have worked most.', 'Feld „[[stats.byBand]]“: für jedes Band die gearbeiteten Länder und die QSOs, mit einem Balken, um auf einen Blick zu sehen, wo du am meisten gearbeitet hast.', 'Encadré « [[stats.byBand]] » : pour chaque bande les pays contactés et les QSO, avec une barre pour voir d’un coup d’œil où tu as le plus contacté.', 'Recuadro «[[stats.byBand]]»: para cada banda los países trabajados y los QSO, con una barra para ver de un vistazo dónde has trabajado más.', 'Quadro «[[stats.byBand]]»: para cada banda os países trabalhados e os QSO, com uma barra para ver de relance onde trabalhaste mais.'],
      ['Riquadro «[[dxcc.title]]»: la scheda DXCC (vedi «La scheda DXCC») con le etichette della stazione che stai chiamando, la tabella per modo e banda e, dentro «[[dxcc.countries.title]]» (si apre con un clic), l’elenco dei paesi con il campo «[[dxcc.countries.filter]]» e la tendina per scegliere quale riga della tabella (FT8, FT4, DIG o tutti i modi) mostrare per ogni paese.', '“[[dxcc.title]]” box: the DXCC card (see “The DXCC card”) with the labels of the station you are calling, the table by mode and band and, inside “[[dxcc.countries.title]]” (it opens with a click), the list of countries with the “[[dxcc.countries.filter]]” field and the drop-down to choose which row of the table (FT8, FT4, DIG or all modes) to show for each country.', 'Feld „[[dxcc.title]]“: die DXCC-Karte (siehe „Die DXCC-Karte“) mit den Etiketten der Station, die du rufst, der Tabelle nach Betriebsart und Band und, in „[[dxcc.countries.title]]“ (öffnet sich mit einem Klick), der Liste der Länder mit dem Feld „[[dxcc.countries.filter]]“ und der Auswahlliste, welche Zeile der Tabelle (FT8, FT4, DIG oder alle Betriebsarten) für jedes Land gezeigt wird.', 'Encadré « [[dxcc.title]] » : l’onglet DXCC (voir « L’onglet DXCC ») avec les étiquettes de la station que tu appelles, le tableau par mode et bande et, dans « [[dxcc.countries.title]] » (s’ouvre d’un clic), la liste des pays avec le champ « [[dxcc.countries.filter]] » et la liste pour choisir quelle ligne du tableau (FT8, FT4, DIG ou tous les modes) montrer pour chaque pays.', 'Recuadro «[[dxcc.title]]»: la ficha DXCC (mira «La ficha DXCC») con las etiquetas de la estación que estás llamando, la tabla por modo y banda y, dentro de «[[dxcc.countries.title]]» (se abre con un clic), la lista de los países con el campo «[[dxcc.countries.filter]]» y la lista desplegable para elegir qué fila de la tabla (FT8, FT4, DIG o todos los modos) mostrar para cada país.', 'Quadro «[[dxcc.title]]»: o separador DXCC (vê «O separador DXCC») com as etiquetas da estação que estás a chamar, a tabela por modo e banda e, dentro de «[[dxcc.countries.title]]» (abre-se com um clique), a lista dos países com o campo «[[dxcc.countries.filter]]» e a lista para escolher que linha da tabela (FT8, FT4, DIG ou todos os modos) mostrar para cada país.'],
      ['«[[stats.missing]]»: si apre con un clic e mostra i paesi che non hai ancora lavorato, un’etichetta per paese.', '“[[stats.missing]]”: it opens with a click and shows the countries you haven’t worked yet, one label per country.', '„[[stats.missing]]“: öffnet sich mit einem Klick und zeigt die Länder, die du noch nicht gearbeitet hast, ein Etikett pro Land.', '« [[stats.missing]] » : s’ouvre d’un clic et montre les pays que tu n’as pas encore contactés, une étiquette par pays.', '«[[stats.missing]]»: se abre con un clic y muestra los países que todavía no has trabajado, una etiqueta por país.', '«[[stats.missing]]»: abre-se com um clique e mostra os países que ainda não trabalhaste, uma etiqueta por país.'],
      ['Riquadro «[[logio.title]]» (aperto di fabbrica): «[[logio.export]]» apre la pagina [[nav.log]] per esportare; «[[logio.import]]» aggiunge al log i QSO di un tuo file ADIF (fino a 256 MB; i QSO già presenti non si duplicano; solo dal PC o dalla rete di casa). Alla fine dice quanti QSO ha aggiunto, quanti erano già presenti e quanti ha scartato.', '“[[logio.title]]” box (open by default): “[[logio.export]]” opens the [[nav.log]] page to export; “[[logio.import]]” adds to the log the QSOs of an ADIF file of yours (up to 256 MB; QSOs already present are not duplicated; only from the PC or from the home network). At the end it says how many QSOs it added, how many were already there and how many it discarded.', 'Feld „[[logio.title]]“ (ab Werk offen): „[[logio.export]]“ öffnet die Seite [[nav.log]] zum Exportieren; „[[logio.import]]“ fügt dem Log die QSOs einer eigenen ADIF-Datei hinzu (bis 256 MB; schon vorhandene QSOs werden nicht doppelt; nur vom PC oder aus dem Heimnetz). Am Ende sagt es, wie viele QSOs es hinzugefügt hat, wie viele schon vorhanden waren und wie viele es verworfen hat.', 'Encadré « [[logio.title]] » (ouvert par défaut) : « [[logio.export]] » ouvre la page [[nav.log]] pour exporter ; « [[logio.import]] » ajoute au log les QSO d’un de tes fichiers ADIF (jusqu’à 256 Mo ; les QSO déjà présents ne sont pas dupliqués ; seulement depuis le PC ou le réseau de la maison). À la fin elle dit combien de QSO elle a ajoutés, combien étaient déjà présents et combien elle a écartés.', 'Recuadro «[[logio.title]]» (abierto de serie): «[[logio.export]]» abre la página [[nav.log]] para exportar; «[[logio.import]]» añade al log los QSO de un archivo ADIF tuyo (hasta 256 MB; los QSO ya presentes no se duplican; solo desde el PC o desde la red de casa). Al final dice cuántos QSO ha añadido, cuántos ya estaban y cuántos ha descartado.', 'Quadro «[[logio.title]]» (aberto de origem): «[[logio.export]]» abre a página [[nav.log]] para exportar; «[[logio.import]]» junta ao log os QSO de um ficheiro ADIF teu (até 256 MB; os QSO já presentes não se duplicam; só a partir do PC ou da rede de casa). No fim diz quantos QSO juntou, quantos já existiam e quantos descartou.'],
    ],
  },
  {
    id: 'p-news',
    title: ['La pagina Novità', 'The News page', 'Die Seite Neuigkeiten', 'La page Nouveautés', 'La página Novedades', 'A página Novidades'],
    text: ['Si apre da [[nav.news]] nel menu dell’ingranaggio. Elenca le ultime funzioni aggiunte, modificate o corrette, dalla più recente, con la data e l’ora del rilascio nell’ora del tuo dispositivo.', 'It opens from [[nav.news]] in the gear menu. It lists the latest features added, changed or fixed, starting from the most recent, with the date and time of the release in your device’s time.', 'Sie öffnet sich über [[nav.news]] im Menü des Zahnrads. Sie listet die zuletzt hinzugefügten, geänderten oder korrigierten Funktionen auf, die neueste zuerst, mit Datum und Uhrzeit der Veröffentlichung in der Zeit deines Geräts.', 'Elle s’ouvre depuis [[nav.news]] dans le menu de l’engrenage. Elle liste les dernières fonctions ajoutées, modifiées ou corrigées, de la plus récente, avec la date et l’heure de la publication à l’heure de ton appareil.', 'Se abre desde [[nav.news]] en el menú del engranaje. Lista las últimas funciones añadidas, modificadas o corregidas, de la más reciente, con la fecha y la hora de la publicación en la hora de tu dispositivo.', 'Abre-se a partir de [[nav.news]] no menu da roda dentada. Lista as últimas funções acrescentadas, alteradas ou corrigidas, a partir da mais recente, com a data e a hora da publicação na hora do teu dispositivo.'],
    steps: [
      ['In alto tre pulsanti — [[news.kind.new]], [[news.kind.changed]] e [[news.kind.fixed]] — mostrano o nascondono ogni tipo di novità (acceso = colorato). Servono per cercare per esempio solo le correzioni.', 'At the top three buttons — [[news.kind.new]], [[news.kind.changed]] and [[news.kind.fixed]] — show or hide each type of news item (on = coloured). They are useful to search, for example, only the fixes.', 'Oben schalten drei Schaltflächen — [[news.kind.new]], [[news.kind.changed]] und [[news.kind.fixed]] — jede Art von Neuigkeit ein oder aus (an = farbig). Sie helfen, zum Beispiel nur nach den Korrekturen zu suchen.', 'En haut trois boutons — [[news.kind.new]], [[news.kind.changed]] et [[news.kind.fixed]] — montrent ou cachent chaque type de nouveauté (allumé = coloré). Ils servent à chercher par exemple seulement les corrections.', 'Arriba tres botones — [[news.kind.new]], [[news.kind.changed]] y [[news.kind.fixed]] — muestran u ocultan cada tipo de novedad (encendido = coloreado). Sirven para buscar, por ejemplo, solo las correcciones.', 'Em cima três botões — [[news.kind.new]], [[news.kind.changed]] e [[news.kind.fixed]] — mostram ou escondem cada tipo de novidade (aceso = colorido). Servem para procurar, por exemplo, só as correções.'],
      ['Ogni riga ha l’icona del tipo, il numero di versione, il titolo e la data; un clic sulla riga apre il testo. La riga della versione che stai usando è già aperta ed è segnata «[[news.current]]».', 'Each row has the type icon, the version number, the title and the date; a click on the row opens the text. The row of the version you are using is already open and is marked “[[news.current]]”.', 'Jede Zeile hat das Symbol der Art, die Versionsnummer, den Titel und das Datum; ein Klick auf die Zeile öffnet den Text. Die Zeile der Version, die du benutzt, ist schon offen und mit „[[news.current]]“ markiert.', 'Chaque ligne a l’icône du type, le numéro de version, le titre et la date ; un clic sur la ligne ouvre le texte. La ligne de la version que tu utilises est déjà ouverte et marquée « [[news.current]] ».', 'Cada fila tiene el icono del tipo, el número de versión, el título y la fecha; un clic en la fila abre el texto. La fila de la versión que estás usando ya está abierta y está marcada «[[news.current]]».', 'Cada linha tem o ícone do tipo, o número da versão, o título e a data; um clique na linha abre o texto. A linha da versão que estás a usar já está aberta e está assinalada «[[news.current]]».'],
      ['Il testo è nella lingua di Aurora. Per cosa è cambiato dopo un aggiornamento vedi anche «Aggiornamenti».', 'The text is in Aurora’s language. For what changed after an update see also “Updates”.', 'Der Text ist in der Sprache von Aurora. Was sich nach einem Update geändert hat, siehe auch „Updates“.', 'Le texte est dans la langue d’Aurora. Pour ce qui a changé après une mise à jour, voir aussi « Mises à jour ».', 'El texto está en el idioma de Aurora. Para saber qué ha cambiado tras una actualización mira también «Actualizaciones».', 'O texto está no idioma da Aurora. Para o que mudou depois de uma atualização vê também «Atualizações».'],
    ],
  },
  {
    id: 'p-guide',
    title: ['La Guida: come cercare', 'The Guide: how to search', 'Die Hilfe: so suchst du', 'Le Guide : comment chercher', 'La Guía: cómo buscar', 'O Guia: como pesquisar'],
    text: ['La Guida si apre da [[nav.wiki]] nel menu dell’ingranaggio. A sinistra c’è l’indice dei capitoli, a destra il testo.', 'The Guide opens from [[nav.wiki]] in the gear menu. On the left is the index of the chapters, on the right the text.', 'Die Hilfe öffnet sich über [[nav.wiki]] im Menü des Zahnrads. Links steht das Inhaltsverzeichnis der Kapitel, rechts der Text.', 'Le Guide s’ouvre depuis [[nav.wiki]] dans le menu de l’engrenage. À gauche il y a l’index des chapitres, à droite le texte.', 'La Guía se abre desde [[nav.wiki]] en el menú del engranaje. A la izquierda está el índice de los capítulos, a la derecha el texto.', 'O Guia abre-se a partir de [[nav.wiki]] no menu da roda dentada. À esquerda está o índice dos capítulos, à direita o texto.'],
    steps: [
      ['Il campo «[[guide.search]]» sta in cima all’indice: scrivi una parola e restano solo le voci che la contengono (nel titolo, nel testo, nei passi, nei consigli e nei «[[guide.fix]]»), nella lingua che hai scelto. Se non trova niente dice «[[guide.none]]».', 'The “[[guide.search]]” field is at the top of the index: type a word and only the entries that contain it remain (in the title, the text, the steps, the tips and the “[[guide.fix]]” items), in the language you have chosen. If it finds nothing it says “[[guide.none]]”.', 'Das Feld „[[guide.search]]“ steht ganz oben im Inhaltsverzeichnis: Schreibe ein Wort, und es bleiben nur die Einträge, die es enthalten (im Titel, im Text, in den Schritten, in den Tipps und in den „[[guide.fix]]“), in der Sprache, die du gewählt hast. Findet es nichts, sagt es „[[guide.none]]“.', 'Le champ « [[guide.search]] » est en haut de l’index : écris un mot et il ne reste que les entrées qui le contiennent (dans le titre, le texte, les étapes, les conseils et les « [[guide.fix]] »), dans la langue que tu as choisie. S’il ne trouve rien, il dit « [[guide.none]] ».', 'El campo «[[guide.search]]» está en lo alto del índice: escribe una palabra y quedan solo las entradas que la contienen (en el título, en el texto, en los pasos, en los consejos y en los «[[guide.fix]]»), en el idioma que has elegido. Si no encuentra nada dice «[[guide.none]]».', 'O campo «[[guide.search]]» está no topo do índice: escreve uma palavra e ficam só as entradas que a contêm (no título, no texto, nos passos, nas dicas e nos «[[guide.fix]]»), no idioma que escolheste. Se não encontrar nada diz «[[guide.none]]».'],
      ['Un clic su un capitolo nell’indice scorre fino a lì. Le voci hanno il nome vero dei pulsanti e delle caselle (lo stesso che vedi a schermo): cercando il nome di una casella trovi la voce che la spiega.', 'A click on a chapter in the index scrolls to it. The entries use the real name of the buttons and boxes (the same one you see on screen): searching for the name of a box you find the entry that explains it.', 'Ein Klick auf ein Kapitel im Inhaltsverzeichnis scrollt dorthin. Die Einträge haben den echten Namen der Schaltflächen und Kästchen (denselben, den du auf dem Bildschirm siehst): Suchst du nach dem Namen eines Kästchens, findest du den Eintrag, der es erklärt.', 'Un clic sur un chapitre dans l’index fait défiler jusque-là. Les entrées ont le vrai nom des boutons et des cases (le même que tu vois à l’écran) : en cherchant le nom d’une case, tu trouves l’entrée qui l’explique.', 'Un clic en un capítulo del índice se desplaza hasta allí. Las entradas tienen el nombre verdadero de los botones y de las casillas (el mismo que ves en pantalla): buscando el nombre de una casilla encuentras la entrada que la explica.', 'Um clique num capítulo do índice desce até lá. As entradas têm o nome verdadeiro dos botões e das caixas (o mesmo que vês no ecrã): procurando o nome de uma caixa encontras a entrada que a explica.'],
      ['Alcune pagine delle Impostazioni hanno un collegamento alla loro voce; l’indirizzo «#/guida/nome-della-voce» apre la Guida già su quella voce.', 'Some pages of the Settings have a link to their entry; the address “#/guida/name-of-the-entry” opens the Guide directly on that entry.', 'Einige Seiten der Einstellungen haben einen Link zu ihrem Eintrag; die Adresse „#/guida/nome-della-voce“ öffnet die Hilfe gleich bei diesem Eintrag.', 'Certaines pages des Réglages ont un lien vers leur entrée ; l’adresse « #/guida/nom-de-l-entree » ouvre le Guide déjà sur cette entrée.', 'Algunas páginas de los Ajustes tienen un enlace a su entrada; la dirección «#/guida/nombre-de-la-entrada» abre la Guía ya en esa entrada.', 'Algumas páginas das Definições têm uma ligação à sua entrada; o endereço «#/guida/nome-da-entrada» abre o Guia já nessa entrada.'],
    ],
  },
  {
    id: 'p-keys',
    title: ['Tasti rapidi e gesti', 'Shortcuts and gestures', 'Tastenkürzel und Gesten', 'Raccourcis clavier et gestes', 'Teclas rápidas y gestos', 'Teclas de atalho e gestos'],
    text: ['Un riepilogo di tutti i tasti e i clic speciali della pagina Stazione e delle pagine vicine.', 'A summary of all the special keys and clicks of the Station page and of the neighbouring pages.', 'Eine Übersicht über alle Tasten und besonderen Klicks der Seite Station und der Nachbarseiten.', 'Un récapitulatif de toutes les touches et de tous les clics spéciaux de la page Station et des pages voisines.', 'Un resumen de todas las teclas y los clics especiales de la página Estación y de las páginas vecinas.', 'Um resumo de todas as teclas e cliques especiais da página Estação e das páginas vizinhas.'],
    steps: [
      ['Esc: ferma subito la trasmissione e spegne [[ctl.enable_tx]] (non tocca AutoTX né AutoSeq). Funziona solo se è acceso «[[gen.escStop]]» in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Due Esc ravvicinati (entro 0,7 s) liberano anche la stazione da chiamare, come «[[ctl.clear_dx]]».', 'Esc: stops the transmission at once and turns off [[ctl.enable_tx]] (it does not touch AutoTX or AutoSeq). It works only if “[[gen.escStop]]” is on in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Two Esc in quick succession (within 0.7 s) also free the station to call, like “[[ctl.clear_dx]]”.', 'Esc: stoppt sofort das Senden und schaltet [[ctl.enable_tx]] aus (AutoTX und AutoSeq bleiben unberührt). Es funktioniert nur, wenn „[[gen.escStop]]“ unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] eingeschaltet ist. Zweimal Esc kurz hintereinander (innerhalb von 0,7 s) gibt auch die zu rufende Station frei, wie „[[ctl.clear_dx]]“.', 'Échap : arrête tout de suite l’émission et éteint [[ctl.enable_tx]] (ne touche ni à AutoTX ni à AutoSeq). Ne fonctionne que si « [[gen.escStop]] » est activé dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Deux Échap rapprochés (en 0,7 s) libèrent aussi la station à appeler, comme « [[ctl.clear_dx]] ».', 'Esc: detiene enseguida la transmisión y apaga [[ctl.enable_tx]] (no toca AutoTX ni AutoSeq). Funciona solo si está encendido «[[gen.escStop]]» en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Dos Esc seguidos (en menos de 0,7 s) liberan también la estación que hay que llamar, como «[[ctl.clear_dx]]».', 'Esc: pára logo a transmissão e desliga [[ctl.enable_tx]] (não toca em AutoTX nem em AutoSeq). Funciona só se «[[gen.escStop]]» estiver ligado em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Dois Esc seguidos (em menos de 0,7 s) libertam também a estação a chamar, como «[[ctl.clear_dx]]».'],
      ['Doppio clic su un messaggio: rispondi (serve «[[gen.dblReply]]»). Tasto destro su un messaggio: in coda. Tasto destro su un nominativo: menu «Apri su QRZ.com». Doppio clic su «RX» nel pannello Trasmissione: libera il DX. Doppio clic su un QSO nel pannello Log: correggi o cancella.', 'Double-click on a message: you reply (“[[gen.dblReply]]” is needed). Right-click on a message: into the queue. Right-click on a callsign: “Open on QRZ.com” menu. Double-click on “RX” in the Transmit panel: frees the DX. Double-click on a QSO in the Log panel: correct or delete.', 'Doppelklick auf eine Nachricht: Du antwortest (dafür ist „[[gen.dblReply]]“ nötig). Rechtsklick auf eine Nachricht: in die Warteschlange. Rechtsklick auf ein Rufzeichen: Menü „Auf QRZ.com öffnen“. Doppelklick auf „RX“ im Feld Senden: gibt den DX frei. Doppelklick auf ein QSO im Log-Feld: korrigieren oder löschen.', 'Double-clic sur un message : tu réponds (il faut « [[gen.dblReply]] »). Clic droit sur un message : en file. Clic droit sur un indicatif : menu « Ouvrir sur QRZ.com ». Double-clic sur « RX » dans le panneau Émission : libère le DX. Double-clic sur un QSO dans le panneau Journal : corriger ou supprimer.', 'Doble clic en un mensaje: respondes (hace falta «[[gen.dblReply]]»). Clic derecho en un mensaje: a la cola. Clic derecho en un indicativo: menú «Abrir en QRZ.com». Doble clic en «RX» en el panel Transmisión: libera el DX. Doble clic en un QSO del panel Log: corriges o borras.', 'Duplo clique numa mensagem: respondes (é preciso «[[gen.dblReply]]»). Botão direito numa mensagem: na fila. Botão direito num indicativo: menu «Abrir no QRZ.com». Duplo clique em «RX» no painel Transmissão: liberta o DX. Duplo clique num QSO no painel Log: corriges ou apagas.'],
      ['Cascata: tasto sinistro = frequenza Rx, tasto destro o Maiusc + clic = frequenza Tx; Tab per portarsi su una barra e frecce sinistra/destra per spostarla (10 Hz; Maiusc = 50 Hz).', 'Waterfall: left button = Rx frequency, right button or Shift + click = Tx frequency; Tab to move onto a bar and left/right arrows to move it (10 Hz; Shift = 50 Hz).', 'Wasserfall: linke Taste = Rx-Frequenz, rechte Taste oder Umschalt + Klick = Tx-Frequenz; mit Tab gehst du auf einen Balken und mit den Pfeilen links/rechts verschiebst du ihn (10 Hz; Umschalt = 50 Hz).', 'Cascade : clic gauche = fréquence Rx, clic droit ou Maj + clic = fréquence Tx ; Tab pour aller sur une barre et flèches gauche/droite pour la déplacer (10 Hz ; Maj = 50 Hz).', 'Cascada: botón izquierdo = frecuencia Rx, botón derecho o Mayús + clic = frecuencia Tx; Tab para ir a una barra y flechas izquierda/derecha para moverla (10 Hz; Mayús = 50 Hz).', 'Cascata: botão esquerdo = frequência Rx, botão direito ou Shift + clique = frequência Tx; Tab para chegar a uma barra e setas esquerda/direita para a mover (10 Hz; Shift = 50 Hz).'],
      ['Tabelle con colonne (Finestra RX, DX Cluster): trascina il titolo per spostare la colonna (oppure Alt + frecce), trascina il bordo destro per cambiare la larghezza (oppure Alt + Maiusc + frecce), tasto destro sul titolo per ripristinare.', 'Tables with columns (RX window, DX Cluster): drag the heading to move the column (or Alt + arrows), drag the right edge to change the width (or Alt + Shift + arrows), right-click on the heading to reset.', 'Tabellen mit Spalten (RX-Fenster, DX-Cluster): Ziehe den Titel, um die Spalte zu verschieben (oder Alt + Pfeiltasten), ziehe den rechten Rand, um die Breite zu ändern (oder Alt + Umschalt + Pfeiltasten), Rechtsklick auf den Titel zum Zurücksetzen.', 'Tableaux avec colonnes (Fenêtre RX, DX Cluster) : glisse le titre pour déplacer la colonne (ou Alt + flèches), glisse le bord droit pour changer la largeur (ou Alt + Maj + flèches), clic droit sur le titre pour réinitialiser.', 'Tablas con columnas (Ventana RX, DX Cluster): arrastra el título para mover la columna (o Alt + flechas), arrastra el borde derecho para cambiar la anchura (o Alt + Mayús + flechas), clic derecho en el título para restablecer.', 'Tabelas com colunas (Janela RX, DX Cluster): arrasta o título para mover a coluna (ou Alt + setas), arrasta a margem direita para mudar a largura (ou Alt + Shift + setas), botão direito no título para repor.'],
      ['Contest: F1 avvia Auto CQ, F2 scambio, F3 R + scambio, F4 chiusura (vedi «Contest: tastiera e comandi»). Finestra «Registrare il QSO»: Invio registra. Menu a tendina e finestre: Esc chiude. Lingua: frecce, Invio, Esc, Home, Fine.', 'Contest: F1 starts Auto CQ, F2 exchange, F3 R + exchange, F4 closing (see “Contest: keyboard and commands”). “Log the QSO” window: Enter logs. Drop-down menus and windows: Esc closes. Language: arrows, Enter, Esc, Home, End.', 'Contest: F1 startet Auto CQ, F2 Austausch, F3 R + Austausch, F4 Abschluss (siehe „Contest: Tastatur und Befehle“). Fenster „QSO loggen“: Enter speichert. Auswahlmenüs und Fenster: Esc schließt. Sprache: Pfeiltasten, Enter, Esc, Pos1, Ende.', 'Contest : F1 lance Auto CQ, F2 échange, F3 R + échange, F4 clôture (voir « Contest : clavier et commandes »). Fenêtre « Enregistrer le QSO » : Entrée enregistre. Listes déroulantes et fenêtres : Échap ferme. Langue : flèches, Entrée, Échap, Début, Fin.', 'Concurso: F1 inicia Auto CQ, F2 intercambio, F3 R + intercambio, F4 cierre (mira «Concurso: teclado y comandos»). Ventana «Registrar el QSO»: Intro registra. Menús desplegables y ventanas: Esc cierra. Idioma: flechas, Intro, Esc, Inicio, Fin.', 'Concurso: F1 inicia o Auto CQ, F2 troca, F3 R + troca, F4 fecho (vê «Concurso: teclado e comandos»). Janela «Registar o QSO»: Enter regista. Listas e janelas: Esc fecha. Idioma: setas, Enter, Esc, Home, End.'],
      ['Telefono: un tocco su un messaggio risponde; due tocchi ravvicinati su STOP fermano la trasmissione e liberano anche il DX.', 'Phone: a tap on a message replies; two quick taps on STOP stop the transmission and also free the DX.', 'Telefon: Ein Tippen auf eine Nachricht antwortet; zweimal kurz hintereinander auf STOP tippen stoppt das Senden und gibt auch den DX frei.', 'Téléphone : un toucher sur un message répond ; deux touchers rapprochés sur STOP arrêtent l’émission et libèrent aussi le DX.', 'Teléfono: un toque en un mensaje responde; dos toques seguidos en STOP detienen la transmisión y liberan también el DX.', 'Telemóvel: um toque numa mensagem responde; dois toques seguidos em STOP param a transmissão e libertam também o DX.'],
    ],
  },
  {
    id: 'p-fox',
    title: ['Pagina Fox: ogni comando', 'Fox page: every command', 'Fox-Seite: jeder Befehl', 'Page Fox : chaque commande', 'Página Fox: cada comando', 'Página Fox: cada comando'],
    text: ['La pagina [[nav.fox]] (titolo «[[fox.title]]») è per chi trasmette da una DXpedition e serve molte stazioni insieme. Per chiamare una DXpedition non serve: si usa Hound nella Stazione (vedi «Fare la Fox (pagina Fox)»). In alto a sinistra: il tuo nominativo, il modo e lo stato; sotto, le opzioni e la barra dei comandi.', 'The [[nav.fox]] page (title “[[fox.title]]”) is for those who transmit from a DXpedition and serve many stations together. To call a DXpedition you don’t need it: you use Hound on the Station (see “Being the Fox (Fox page)”). At the top left: your callsign, the mode and the status; below, the options and the command bar.', 'Die Seite [[nav.fox]] (Titel „[[fox.title]]“) ist für alle, die von einer DXpedition aus senden und viele Stationen gleichzeitig bedienen. Um eine DXpedition zu rufen, brauchst du sie nicht: Dafür nimmst du Hound auf der Station (siehe „Selbst Fox sein (Fox-Seite)“). Oben links: dein Rufzeichen, die Betriebsart und der Zustand; darunter die Optionen und die Befehlsleiste.', 'La page [[nav.fox]] (titre « [[fox.title]] ») est pour qui émet depuis une DXpédition et sert beaucoup de stations à la fois. Pour appeler une DXpédition elle ne sert pas : on utilise Hound dans la Station (voir « Être le Fox (page Fox) »). En haut à gauche : ton indicatif, le mode et l’état ; dessous, les options et la barre des commandes.', 'La página [[nav.fox]] (título «[[fox.title]]») es para quien transmite desde una DXpedición y atiende a muchas estaciones a la vez. Para llamar a una DXpedición no hace falta: se usa Hound en la Estación (mira «Ser el Fox (página Fox)»). Arriba a la izquierda: tu indicativo, el modo y el estado; debajo, las opciones y la barra de comandos.', 'A página [[nav.fox]] (título «[[fox.title]]») é para quem transmite a partir de uma DXpedição e serve muitas estações em conjunto. Para chamar uma DXpedição não é preciso: usa-se Hound na Estação (vê «Ser o Fox (página Fox)»). Em cima à esquerda: o teu indicativo, o modo e o estado; por baixo, as opções e a barra de comandos.'],
    steps: [
      ['Pillola di stato: [[fox.state.off]] (Fox spenta), [[fox.state.waiting]] (Fox accesa ma Abilita Tx spento), [[fox.state.ready]] (pronta, in attesa del prossimo periodo) o [[fox.state.onair]] (in onda).', 'Status pill: [[fox.state.off]] (Fox off), [[fox.state.waiting]] (Fox on but Enable Tx off), [[fox.state.ready]] (ready, waiting for the next period) or [[fox.state.onair]] (on the air).', 'Statusanzeige: [[fox.state.off]] (Fox aus), [[fox.state.waiting]] (Fox an, aber „Tx an“ aus), [[fox.state.ready]] (bereit, wartet auf den nächsten Durchgang) oder [[fox.state.onair]] (auf Sendung).', 'Pastille d’état : [[fox.state.off]] (Fox éteinte), [[fox.state.waiting]] (Fox allumée mais Activer Tx éteint), [[fox.state.ready]] (prête, en attente de la prochaine période) ou [[fox.state.onair]] (en l’air).', 'Píldora de estado: [[fox.state.off]] (Fox apagada), [[fox.state.waiting]] (Fox encendida pero Habilitar Tx apagado), [[fox.state.ready]] (lista, esperando el próximo periodo) o [[fox.state.onair]] (en el aire).', 'Pílula de estado: [[fox.state.off]] (Fox desligado), [[fox.state.waiting]] (Fox ligado mas Ativar Tx desligado), [[fox.state.ready]] (pronto, à espera do próximo período) ou [[fox.state.onair]] (no ar).'],
      ['A fianco otto contatori: «[[fox.logged]]» (QSO a log in questa sessione), «[[fox.inProgress]]», «[[fox.callers]]», «[[fox.queue]]», «[[fox.stat.rate]]» (QSO all’ora sugli ultimi 10), «[[fox.stat.hour]]» (QSO di ogni 5 minuti nell’ultima ora), «[[fox.periods]]» e «[[fox.continents]]» (QSO per continente). Passa il mouse per la spiegazione.', 'Beside it eight counters: “[[fox.logged]]” (QSOs logged in this session), “[[fox.inProgress]]”, “[[fox.callers]]”, “[[fox.queue]]”, “[[fox.stat.rate]]” (QSOs per hour over the last 10), “[[fox.stat.hour]]” (QSOs for each 5 minutes in the last hour), “[[fox.periods]]” and “[[fox.continents]]” (QSOs per continent). Hover over them for the explanation.', 'Daneben acht Zähler: „[[fox.logged]]“ (QSOs im Log in dieser Sitzung), „[[fox.inProgress]]“, „[[fox.callers]]“, „[[fox.queue]]“, „[[fox.stat.rate]]“ (QSOs pro Stunde aus den letzten 10), „[[fox.stat.hour]]“ (QSOs je 5 Minuten in der letzten Stunde), „[[fox.periods]]“ und „[[fox.continents]]“ (QSOs pro Kontinent). Halte die Maus darüber für die Erklärung.', 'À côté huit compteurs : « [[fox.logged]] » (QSO enregistrés dans cette session), « [[fox.inProgress]] », « [[fox.callers]] », « [[fox.queue]] », « [[fox.stat.rate]] » (QSO à l’heure sur les 10 derniers), « [[fox.stat.hour]] » (QSO de chaque tranche de 5 minutes dans la dernière heure), « [[fox.periods]] » et « [[fox.continents]] » (QSO par continent). Passe la souris pour l’explication.', 'Al lado ocho contadores: «[[fox.logged]]» (QSO al log en esta sesión), «[[fox.inProgress]]», «[[fox.callers]]», «[[fox.queue]]», «[[fox.stat.rate]]» (QSO por hora sobre los últimos 10), «[[fox.stat.hour]]» (QSO de cada 5 minutos en la última hora), «[[fox.periods]]» y «[[fox.continents]]» (QSO por continente). Pasa el ratón para ver la explicación.', 'Ao lado oito contadores: «[[fox.logged]]» (QSO no log nesta sessão), «[[fox.inProgress]]», «[[fox.callers]]», «[[fox.queue]]», «[[fox.stat.rate]]» (QSO por hora nos últimos 10), «[[fox.stat.hour]]» (QSO de cada 5 minutos na última hora), «[[fox.periods]]» e «[[fox.continents]]» (QSO por continente). Passa o rato para a explicação.'],
      ['Opzioni: «[[fox.slots]]» da 1 a 5 (quante stazioni servi nello stesso periodo: più posti = più veloce ma la potenza si divide); «[[fox.cq]]» (CQ a tutti o solo a un continente o ai DX); gli interruttori «UltraFOX» (un solo segnale largo da 750 a 2260 Hz con fino a 9 stazioni), «[[fox.moreCqs]]» (manda il CQ anche nei periodi con posti occupati) e «[[fox.autoQueue]]» (mette in coda da sola chi chiama, partendo dal segnale migliore); «[[fox.reset]]» svuota chi chiama, la coda e i QSO in corso e azzera i contatori.', 'Options: “[[fox.slots]]” from 1 to 5 (how many stations you serve in the same period: more slots = faster but the power is split); “[[fox.cq]]” (CQ to everyone or only to one continent or to the DX); the switches “UltraFOX” (a single wide signal from 750 to 2260 Hz with up to 9 stations), “[[fox.moreCqs]]” (also sends the CQ in periods with occupied slots) and “[[fox.autoQueue]]” (queues the callers by itself, starting from the best signal); “[[fox.reset]]” empties the callers, the queue and the QSOs in progress and zeroes the counters.', 'Optionen: „[[fox.slots]]“ von 1 bis 5 (wie viele Stationen du im selben Durchgang bedienst: mehr Slots = schneller, aber die Leistung teilt sich); „[[fox.cq]]“ (CQ an alle oder nur an einen Kontinent oder an die DX); die Schalter „UltraFOX“ (ein einziges breites Signal von 750 bis 2260 Hz mit bis zu 9 Stationen), „[[fox.moreCqs]]“ (sendet das CQ auch in Durchgängen mit belegten Slots) und „[[fox.autoQueue]]“ (reiht die Rufer von selbst ein, beginnend beim besten Signal); „[[fox.reset]]“ leert die Rufer, die Warteschlange und die laufenden QSOs und setzt die Zähler zurück.', 'Options : « [[fox.slots]] » de 1 à 5 (combien de stations tu sers dans la même période : plus de places = plus rapide mais la puissance se divise) ; « [[fox.cq]] » (CQ à tous ou seulement à un continent ou aux DX) ; les interrupteurs « UltraFOX » (un seul signal large de 750 à 2260 Hz avec jusqu’à 9 stations), « [[fox.moreCqs]] » (envoie le CQ aussi dans les périodes avec des places occupées) et « [[fox.autoQueue]] » (met en file toute seule ceux qui appellent, en partant du meilleur signal) ; « [[fox.reset]] » vide ceux qui appellent, la file et les QSO en cours et remet les compteurs à zéro.', 'Opciones: «[[fox.slots]]» de 1 a 5 (a cuántas estaciones atiendes en el mismo periodo: más puestos = más rápido pero la potencia se reparte); «[[fox.cq]]» (CQ a todos o solo a un continente o a los DX); los interruptores «UltraFOX» (una sola señal ancha de 750 a 2260 Hz con hasta 9 estaciones), «[[fox.moreCqs]]» (manda el CQ también en los periodos con puestos ocupados) y «[[fox.autoQueue]]» (pone en cola sola a quien llama, empezando por la mejor señal); «[[fox.reset]]» vacía quien llama, la cola y los QSO en curso y pone a cero los contadores.', 'Opções: «[[fox.slots]]» de 1 a 5 (quantas estações serves no mesmo período: mais lugares = mais rápido mas a potência divide-se); «[[fox.cq]]» (CQ a todos ou só a um continente ou aos DX); os interruptores «UltraFOX» (um só sinal largo de 750 a 2260 Hz com até 9 estações), «[[fox.moreCqs]]» (envia o CQ também nos períodos com lugares ocupados) e «[[fox.autoQueue]]» (põe na fila sozinho quem chama, começando pelo melhor sinal); «[[fox.reset]]» esvazia quem chama, a fila e os QSO em curso e põe os contadores a zero.'],
      ['Barra dei comandi: «[[fox.off]]» / «[[fox.on]]» (interruttore del modo Fox: da acceso chiama CQ nei periodi pari, sotto 1000 Hz; si blocca se un contest vieta Fox/Hound), «[[fox.enableTx]]» (senza, la Fox ascolta ma non trasmette nulla), il pulsante «[[stop.button]]», i comandi di ricezione (come in «La riga dei comandi di ricezione») e «[[ctl.split]]». Un riquadro sotto la barra avvisa se la frequenza è protetta (la Fox non trasmette a meno di 3 kHz dalle frequenze FT8 standard) o se manca Abilita Tx («[[fox.needTx]]»).', 'Command bar: “[[fox.off]]” / “[[fox.on]]” (switch of Fox mode: when on it calls CQ in the even periods, below 1000 Hz; it is locked if a contest forbids Fox/Hound), “[[fox.enableTx]]” (without it, the Fox listens but transmits nothing), the “[[stop.button]]” button, the receive controls (as in “The receive controls row”) and “[[ctl.split]]”. A box under the bar warns if the frequency is protected (the Fox does not transmit within 3 kHz of the standard FT8 frequencies) or if Enable Tx is missing (“[[fox.needTx]]”).', 'Befehlsleiste: „[[fox.off]]“ / „[[fox.on]]“ (Schalter der Betriebsart Fox: eingeschaltet ruft sie CQ in den geraden Durchgängen, unter 1000 Hz; sie sperrt sich, wenn ein Contest Fox/Hound verbietet), „[[fox.enableTx]]“ (ohne sie hört die Fox zu, sendet aber nichts), die Schaltfläche „[[stop.button]]“, die Empfangsbefehle (wie in „Die Empfangsbefehlsleiste“) und „[[ctl.split]]“. Ein Feld unter der Leiste warnt, wenn die Frequenz geschützt ist (die Fox sendet nicht näher als 3 kHz an den FT8-Standardfrequenzen) oder wenn „Tx an“ fehlt („[[fox.needTx]]“).', 'Barre des commandes : « [[fox.off]] » / « [[fox.on]] » (interrupteur du mode Fox : allumé, il appelle CQ dans les périodes paires, sous 1000 Hz ; il se bloque si un contest interdit Fox/Hound), « [[fox.enableTx]] » (sans lui, la Fox écoute mais n’émet rien), le bouton « [[stop.button]] », les commandes de réception (comme dans « La rangée des commandes de réception ») et « [[ctl.split]] ». Un encadré sous la barre avertit si la fréquence est protégée (la Fox n’émet pas à moins de 3 kHz des fréquences FT8 standard) ou s’il manque Activer Tx (« [[fox.needTx]] »).', 'Barra de comandos: «[[fox.off]]» / «[[fox.on]]» (interruptor del modo Fox: encendido llama CQ en los periodos pares, por debajo de 1000 Hz; se bloquea si un concurso prohíbe Fox/Hound), «[[fox.enableTx]]» (sin él, la Fox escucha pero no transmite nada), el botón «[[stop.button]]», los comandos de recepción (como en «La fila de comandos de recepción») y «[[ctl.split]]». Un recuadro bajo la barra avisa si la frecuencia está protegida (la Fox no transmite a menos de 3 kHz de las frecuencias FT8 estándar) o si falta Habilitar Tx («[[fox.needTx]]»).', 'Barra de comandos: «[[fox.off]]» / «[[fox.on]]» (interruptor do modo Fox: ligado, chama CQ nos períodos pares, abaixo de 1000 Hz; bloqueia-se se um concurso proibir Fox/Hound), «[[fox.enableTx]]» (sem ele, o Fox escuta mas não transmite nada), o botão «[[stop.button]]», os comandos de receção (como em «A linha de comandos de receção») e «[[ctl.split]]». Um quadro por baixo da barra avisa se a frequência está protegida (o Fox não transmite a menos de 3 kHz das frequências FT8 padrão) ou se falta Ativar Tx («[[fox.needTx]]»).'],
      ['A destra della barra il riquadro OTP: «[[fox.otpOn]]» / «[[fox.otpOff]]», il «[[fox.otpSeed]]» (16 caratteri A-Z e 2-7, salvato sul PC; vuoto = resta quello salvato), «[[fox.otpEvery]]» (ogni quanti periodi manda il codice), «[[fox.otpSave]]» e «[[fox.otpRemove]]». Serve a dimostrare agli Hound che sei la vera spedizione.', 'To the right of the bar the OTP box: “[[fox.otpOn]]” / “[[fox.otpOff]]”, the “[[fox.otpSeed]]” (16 characters A-Z and 2-7, saved on the PC; empty = the saved one stays), “[[fox.otpEvery]]” (how many periods between codes), “[[fox.otpSave]]” and “[[fox.otpRemove]]”. It is used to prove to the Hounds that you are the real expedition.', 'Rechts von der Leiste das OTP-Feld: „[[fox.otpOn]]“ / „[[fox.otpOff]]“, der „[[fox.otpSeed]]“ (16 Zeichen A-Z und 2-7, auf dem PC gespeichert; leer = der gespeicherte bleibt), „[[fox.otpEvery]]“ (nach wie vielen Durchgängen der Code gesendet wird), „[[fox.otpSave]]“ und „[[fox.otpRemove]]“. Damit beweist du den Hounds, dass du die echte Expedition bist.', 'À droite de la barre, l’encadré OTP : « [[fox.otpOn]] » / « [[fox.otpOff]] », la « [[fox.otpSeed]] » (16 caractères A-Z et 2-7, enregistrée sur le PC ; vide = reste celle enregistrée), « [[fox.otpEvery]] » (toutes les combien de périodes il envoie le code), « [[fox.otpSave]] » et « [[fox.otpRemove]] ». Il sert à prouver aux Hound que tu es la vraie expédition.', 'A la derecha de la barra el recuadro OTP: «[[fox.otpOn]]» / «[[fox.otpOff]]», la «[[fox.otpSeed]]» (16 caracteres A-Z y 2-7, guardada en el PC; vacía = se queda la guardada), «[[fox.otpEvery]]» (cada cuántos periodos manda el código), «[[fox.otpSave]]» y «[[fox.otpRemove]]». Sirve para demostrar a los Hound que eres la expedición de verdad.', 'À direita da barra o quadro OTP: «[[fox.otpOn]]» / «[[fox.otpOff]]», a «[[fox.otpSeed]]» (16 carateres A-Z e 2-7, guardada no PC; vazia = fica a que está guardada), «[[fox.otpEvery]]» (de quantos em quantos períodos envia o código), «[[fox.otpSave]]» e «[[fox.otpRemove]]». Serve para provar aos Hound que és a verdadeira expedição.'],
      ['«[[fox.callers]]» (a sinistra): chi ha risposto al tuo CQ. Campi: «[[fox.filter]]», «[[fox.sort]]» e «[[fox.sort2]]» (SNR, nominativo, locatore, distanza, età, Hz, valore esterno), «[[fox.snrMin]]» e «[[fox.snrMax]]», «[[fox.onlyNew]]» (nasconde chi è già a log su questa banda), «[[fox.addBest]]» (mette in coda le prime 5 dell’elenco). Doppio clic su una riga o «[[fox.add]]» mette la stazione in fondo alla coda; «[[fox.top]]» la mette in cima (sarà la prossima servita). La scritta «[[fox.dupe]]» dice che è già a log.', '“[[fox.callers]]” (on the left): who answered your CQ. Fields: “[[fox.filter]]”, “[[fox.sort]]” and “[[fox.sort2]]” (SNR, callsign, locator, distance, age, Hz, external value), “[[fox.snrMin]]” and “[[fox.snrMax]]”, “[[fox.onlyNew]]” (hides those already in the log on this band), “[[fox.addBest]]” (queues the first 5 of the list). A double-click on a row or “[[fox.add]]” puts the station at the end of the queue; “[[fox.top]]” puts it at the top (it will be served next). The “[[fox.dupe]]” label says it is already in the log.', '„[[fox.callers]]“ (links): wer auf deinen CQ geantwortet hat. Felder: „[[fox.filter]]“, „[[fox.sort]]“ und „[[fox.sort2]]“ (SNR, Rufzeichen, Locator, Entfernung, Alter, Hz, externer Wert), „[[fox.snrMin]]“ und „[[fox.snrMax]]“, „[[fox.onlyNew]]“ (blendet aus, wer auf diesem Band schon im Log ist), „[[fox.addBest]]“ (reiht die ersten 5 der Liste ein). Doppelklick auf eine Zeile oder „[[fox.add]]“ setzt die Station ans Ende der Warteschlange; „[[fox.top]]“ setzt sie an den Anfang (sie wird als Nächste bedient). Die Angabe „[[fox.dupe]]“ sagt, dass sie schon im Log ist.', '« [[fox.callers]] » (à gauche) : ceux qui ont répondu à ton CQ. Champs : « [[fox.filter]] », « [[fox.sort]] » et « [[fox.sort2]] » (SNR, indicatif, locator, distance, âge, Hz, valeur externe), « [[fox.snrMin]] » et « [[fox.snrMax]] », « [[fox.onlyNew]] » (cache ceux qui sont déjà au log sur cette bande), « [[fox.addBest]] » (met en file les 5 premières de la liste). Double-clic sur une ligne ou « [[fox.add]] » met la station au bout de la file ; « [[fox.top]] » la met en tête (elle sera la prochaine servie). Le texte « [[fox.dupe]] » dit qu’elle est déjà au log.', '«[[fox.callers]]» (a la izquierda): quien ha respondido a tu CQ. Campos: «[[fox.filter]]», «[[fox.sort]]» y «[[fox.sort2]]» (SNR, indicativo, localizador, distancia, edad, Hz, valor externo), «[[fox.snrMin]]» y «[[fox.snrMax]]», «[[fox.onlyNew]]» (oculta a quien ya está en el log en esta banda), «[[fox.addBest]]» (pone en cola las 5 primeras de la lista). Doble clic en una fila o «[[fox.add]]» pone la estación al final de la cola; «[[fox.top]]» la pone arriba (será la próxima atendida). El texto «[[fox.dupe]]» dice que ya está en el log.', '«[[fox.callers]]» (à esquerda): quem respondeu ao teu CQ. Campos: «[[fox.filter]]», «[[fox.sort]]» e «[[fox.sort2]]» (SNR, indicativo, locator, distância, idade, Hz, valor externo), «[[fox.snrMin]]» e «[[fox.snrMax]]», «[[fox.onlyNew]]» (esconde quem já está no log nesta banda), «[[fox.addBest]]» (põe na fila as primeiras 5 da lista). Duplo clique numa linha ou «[[fox.add]]» põe a estação no fim da fila; «[[fox.top]]» põe-na no topo (será a próxima servida). O texto «[[fox.dupe]]» diz que já está no log.'],
      ['Riquadri al centro: «[[fox.inProgress]]» (rapporto inviato, in attesa della conferma, con i tentativi; «[[fox.drop]]» chiude un QSO che non risponde e libera il posto), «[[fox.onAir]]» (i messaggi che la Fox sta trasmettendo, uno per posto), «[[fox.queue]]» (aspettano un posto libero; «[[fox.remove]]» toglie una stazione dalla coda) e «[[fox.log]]» (gli ultimi 500 QSO chiusi in questa sessione, con i pulsanti ADIF, Cabrillo e Club Log per salvarlo o mandarlo).', 'Boxes in the middle: “[[fox.inProgress]]” (report sent, waiting for confirmation, with the attempts; “[[fox.drop]]” closes a QSO that doesn’t answer and frees the slot), “[[fox.onAir]]” (the messages the Fox is transmitting, one per slot), “[[fox.queue]]” (waiting for a free slot; “[[fox.remove]]” removes a station from the queue) and “[[fox.log]]” (the last 500 QSOs closed in this session, with the ADIF, Cabrillo and Club Log buttons to save or send it).', 'Felder in der Mitte: „[[fox.inProgress]]“ (Rapport gesendet, wartet auf die Bestätigung, mit den Versuchen; „[[fox.drop]]“ schließt ein QSO, das nicht antwortet, und gibt den Slot frei), „[[fox.onAir]]“ (die Nachrichten, die die Fox gerade sendet, eine pro Slot), „[[fox.queue]]“ (sie warten auf einen freien Slot; „[[fox.remove]]“ nimmt eine Station aus der Warteschlange) und „[[fox.log]]“ (die letzten 500 in dieser Sitzung abgeschlossenen QSOs, mit den Schaltflächen ADIF, Cabrillo und Club Log, um es zu speichern oder zu senden).', 'Encadrés au centre : « [[fox.inProgress]] » (report envoyé, en attente de la confirmation, avec les tentatives ; « [[fox.drop]] » ferme un QSO qui ne répond pas et libère la place), « [[fox.onAir]] » (les messages que la Fox émet, un par place), « [[fox.queue]] » (attendent une place libre ; « [[fox.remove]] » enlève une station de la file) et « [[fox.log]] » (les 500 derniers QSO clos dans cette session, avec les boutons ADIF, Cabrillo et Club Log pour l’enregistrer ou l’envoyer).', 'Recuadros del centro: «[[fox.inProgress]]» (informe enviado, esperando la confirmación, con los intentos; «[[fox.drop]]» cierra un QSO que no responde y libera el puesto), «[[fox.onAir]]» (los mensajes que la Fox está transmitiendo, uno por puesto), «[[fox.queue]]» (esperan un puesto libre; «[[fox.remove]]» quita una estación de la cola) y «[[fox.log]]» (los últimos 500 QSO cerrados en esta sesión, con los botones ADIF, Cabrillo y Club Log para guardarlo o enviarlo).', 'Quadros ao centro: «[[fox.inProgress]]» (relatório enviado, à espera da confirmação, com as tentativas; «[[fox.drop]]» fecha um QSO que não responde e liberta o lugar), «[[fox.onAir]]» (as mensagens que o Fox está a transmitir, uma por lugar), «[[fox.queue]]» (esperam um lugar livre; «[[fox.remove]]» tira uma estação da fila) e «[[fox.log]]» (os últimos 500 QSO fechados nesta sessão, com os botões ADIF, Cabrillo e Club Log para o guardar ou enviar).'],
      ['Sotto «[[fox.callers]]» c’è la cascata («[[fox.waterfall]]»): clic = frequenza Rx, tasto destro o Maiusc + clic = frequenza Tx; l’altezza si cambia trascinando la maniglia. A destra «[[fox.received]]» elenca gli ultimi messaggi decodificati, con quelli rivolti a te in evidenza. La riga «Tentativi … attesa … cicli …» riassume i parametri.', 'Under “[[fox.callers]]” is the waterfall (“[[fox.waterfall]]”): click = Rx frequency, right-click or Shift + click = Tx frequency; the height is changed by dragging the handle. On the right “[[fox.received]]” lists the latest decoded messages, with those addressed to you highlighted. The line “Attempts … wait … cycles …” summarizes the parameters.', 'Unter „[[fox.callers]]“ liegt der Wasserfall („[[fox.waterfall]]“): Klick = Rx-Frequenz, Rechtsklick oder Umschalt + Klick = Tx-Frequenz; die Höhe änderst du, indem du den Griff ziehst. Rechts listet „[[fox.received]]“ die letzten dekodierten Nachrichten auf, die an dich gerichteten hervorgehoben. Die Zeile „Versuche … · Warten … Zyklen …“ fasst die Parameter zusammen.', 'Sous « [[fox.callers]] » il y a la cascade (« [[fox.waterfall]] ») : clic = fréquence Rx, clic droit ou Maj + clic = fréquence Tx ; la hauteur se change en glissant la poignée. À droite « [[fox.received]] » liste les derniers messages décodés, avec ceux qui te sont adressés en évidence. La ligne « Tentatives … attente … cycles … » résume les paramètres.', 'Bajo «[[fox.callers]]» está la cascada («[[fox.waterfall]]»): clic = frecuencia Rx, botón derecho o Mayús + clic = frecuencia Tx; la altura se cambia arrastrando el asa. A la derecha «[[fox.received]]» lista los últimos mensajes decodificados, con los dirigidos a ti destacados. La fila «Intentos … espera … ciclos …» resume los parámetros.', 'Por baixo de «[[fox.callers]]» está a cascata («[[fox.waterfall]]»): clique = frequência Rx, botão direito ou Shift + clique = frequência Tx; a altura muda-se arrastando a pega. À direita «[[fox.received]]» lista as últimas mensagens descodificadas, com as dirigidas a ti em destaque. A linha «Tentativas … espera … ciclos …» resume os parâmetros.'],
    ],
    tip: ['Usa il modo Fox solo se sei davvero la spedizione e lo annunci: in banda normale disturba.', 'Use Fox mode only if you really are the expedition and you announce it: on a normal band it causes interference.', 'Nutze die Betriebsart Fox nur, wenn du wirklich die Expedition bist und es ankündigst: Auf einem normalen Band stört sie.', 'Utilise le mode Fox seulement si tu es vraiment l’expédition et que tu l’annonces : en bande normale, il dérange.', 'Usa el modo Fox solo si eres de verdad la expedición y lo anuncias: en una banda normal molesta.', 'Usa o modo Fox só se fores mesmo a expedição e o anunciares: na banda normal incomoda.'],
  },
  {
    id: 'p-contest',
    title: ['Contest: la barra e le schede', 'Contest: the bar and the tabs', 'Contest: Leiste und Karteireiter', 'Contest : la barre et les onglets', 'Concurso: la barra y las fichas', 'Concurso: a barra e os separadores'],
    text: ['La pagina [[nav.contest]] ha in alto la barra del contest e, quando un contest è acceso, tre schede: «[[contest.tab.race]]», «[[contest.training]]» e «[[contest.analysis]]». Come si prepara un contest è in «Contest».', 'The [[nav.contest]] page has the contest bar at the top and, when a contest is on, three tabs: “[[contest.tab.race]]”, “[[contest.training]]” and “[[contest.analysis]]”. How to set up a contest is in “Contests”.', 'Die Seite [[nav.contest]] hat oben die Contest-Leiste und, wenn ein Contest eingeschaltet ist, drei Reiter: „[[contest.tab.race]]“, „[[contest.training]]“ und „[[contest.analysis]]“. Wie man einen Contest vorbereitet, steht unter „Conteste“.', 'La page [[nav.contest]] a en haut la barre du contest et, quand un contest est actif, trois onglets : « [[contest.tab.race]] », « [[contest.training]] » et « [[contest.analysis]] ». La façon de préparer un contest est dans « Concours ».', 'La página [[nav.contest]] tiene arriba la barra del concurso y, cuando un concurso está encendido, tres fichas: «[[contest.tab.race]]», «[[contest.training]]» y «[[contest.analysis]]». Cómo se prepara un concurso está en «Concursos».', 'A página [[nav.contest]] tem em cima a barra do concurso e, quando um concurso está ligado, três separadores: «[[contest.tab.race]]», «[[contest.training]]» e «[[contest.analysis]]». Como se prepara um concurso está em «Concursos».'],
    steps: [
      ['L’interruttore «[[contest.toggleOff]]» / «[[contest.toggleOn]]» accende il contest scelto (Aurora prepara messaggi, scambio, Fox e Hound spenti, AutoSeq e Hold Tx Freq) o lo spegne e ripristina le impostazioni di prima.', 'The “[[contest.toggleOff]]” / “[[contest.toggleOn]]” switch turns on the chosen contest (Aurora prepares messages, exchange, Fox and Hound off, AutoSeq and Hold Tx Freq) or turns it off and restores the previous settings.', 'Der Schalter „[[contest.toggleOff]]“ / „[[contest.toggleOn]]“ schaltet den gewählten Contest ein (Aurora bereitet Nachrichten, Austausch vor, Fox und Hound aus, AutoSeq und Hold Tx Freq) oder schaltet ihn aus und stellt die früheren Einstellungen wieder her.', 'L’interrupteur « [[contest.toggleOff]] » / « [[contest.toggleOn]] » active le contest choisi (Aurora prépare messages, échange, Fox et Hound éteints, AutoSeq et Hold Tx Freq) ou l’éteint et rétablit les réglages d’avant.', 'El interruptor «[[contest.toggleOff]]» / «[[contest.toggleOn]]» enciende el concurso elegido (Aurora prepara mensajes, intercambio, Fox y Hound apagados, AutoSeq y Hold Tx Freq) o lo apaga y restablece los ajustes de antes.', 'O interruptor «[[contest.toggleOff]]» / «[[contest.toggleOn]]» liga o concurso escolhido (a Aurora prepara mensagens, troca, Fox e Hound desligados, AutoSeq e Hold Tx Freq) ou desliga-o e repõe as definições de antes.'],
      ['La tendina «[[contest.choose]]» elenca i contest per gruppo e per data di inizio; scegline uno e, se un contest è già acceso, passa a quello. Accanto, «[[contest.how]]» apre una scheda con cosa si trasmette (con un esempio), gli orari in UTC e in ora locale, la durata, le ore massime, la pausa minima e il link al regolamento ufficiale.', 'The “[[contest.choose]]” drop-down lists the contests by group and by start date; choose one and, if a contest is already on, it switches to that one. Next to it, “[[contest.how]]” opens a card with what is sent (with an example), the times in UTC and in local time, the duration, the maximum hours, the minimum break and the link to the official rules.', 'Die Auswahlliste „[[contest.choose]]“ listet die Conteste nach Gruppe und Startdatum auf; wähle einen, und wenn schon ein Contest eingeschaltet ist, wechselst du zu diesem. Daneben öffnet „[[contest.how]]“ eine Karte mit dem, was gesendet wird (mit einem Beispiel), den Zeiten in UTC und in Ortszeit, der Dauer, den Höchststunden, der Mindestpause und dem Link zum offiziellen Regelwerk.', 'La liste « [[contest.choose]] » énumère les contests par groupe et par date de début ; choisis-en un et, si un contest est déjà actif, elle passe à celui-là. À côté, « [[contest.how]] » ouvre une fiche avec ce qu’on émet (avec un exemple), les horaires en UTC et en heure locale, la durée, les heures maximales, la pause minimale et le lien vers le règlement officiel.', 'La lista desplegable «[[contest.choose]]» enumera los concursos por grupo y por fecha de inicio; elige uno y, si ya hay un concurso encendido, pasa a ese. Al lado, «[[contest.how]]» abre una ficha con qué se transmite (con un ejemplo), los horarios en UTC y en hora local, la duración, las horas máximas, la pausa mínima y el enlace al reglamento oficial.', 'A lista «[[contest.choose]]» mostra os concursos por grupo e por data de início; escolhe um e, se já houver um concurso ligado, passa para esse. Ao lado, «[[contest.how]]» abre um cartão com o que se transmite (com um exemplo), os horários em UTC e em hora local, a duração, as horas máximas, a pausa mínima e a ligação ao regulamento oficial.'],
      ['Con il contest acceso la barra mostra: la fase («Inizia tra …», il tempo che manca alla fine, «[[contest.phase.finito]]» o «[[contest.phase.sempre]]»), «[[contest.qso]]», «[[contest.mult]]», «[[contest.score]]», «[[contest.rate10]]» e «[[contest.rate60]]» (QSO all’ora), «[[contest.forecast]]» (il punteggio se continui a questo ritmo), «[[contest.sent]]», la tessera della categoria (clic: scegli categoria, operatori, potenza, assistenza o trasmettitori del Field Day) e «[[contest.hours]]». Se la banda o il modo non sono ammessi compare un avviso rosso.', 'With the contest on, the bar shows: the phase (“Starts in …”, the time left to the end, “[[contest.phase.finito]]” or “[[contest.phase.sempre]]”), “[[contest.qso]]”, “[[contest.mult]]”, “[[contest.score]]”, “[[contest.rate10]]” and “[[contest.rate60]]” (QSOs per hour), “[[contest.forecast]]” (the score if you keep this pace), “[[contest.sent]]”, the category tile (click: choose category, operators, power, assistance or Field Day transmitters) and “[[contest.hours]]”. If the band or the mode is not allowed, a red warning appears.', 'Bei eingeschaltetem Contest zeigt die Leiste: die Phase („Beginnt in …“, die Zeit bis zum Ende, „[[contest.phase.finito]]“ oder „[[contest.phase.sempre]]“), „[[contest.qso]]“, „[[contest.mult]]“, „[[contest.score]]“, „[[contest.rate10]]“ und „[[contest.rate60]]“ (QSOs pro Stunde), „[[contest.forecast]]“ (die Punktzahl, wenn du in diesem Tempo weitermachst), „[[contest.sent]]“, die Karte der Kategorie (Klick: Kategorie, Operatoren, Leistung, Unterstützung oder Sender des Field Day wählen) und „[[contest.hours]]“. Sind Band oder Betriebsart nicht erlaubt, erscheint ein roter Hinweis.', 'Avec le contest actif, la barre montre : la phase (« Commence dans … », le temps qui reste avant la fin, « [[contest.phase.finito]] » ou « [[contest.phase.sempre]] »), « [[contest.qso]] », « [[contest.mult]] », « [[contest.score]] », « [[contest.rate10]] » et « [[contest.rate60]] » (QSO à l’heure), « [[contest.forecast]] » (le score si tu continues à ce rythme), « [[contest.sent]] », la pastille de la catégorie (clic : choisis catégorie, opérateurs, puissance, assistance ou émetteurs du Field Day) et « [[contest.hours]] ». Si la bande ou le mode ne sont pas admis, une alerte rouge apparaît.', 'Con el concurso encendido la barra muestra: la fase («Empieza en …», el tiempo que falta para el final, «[[contest.phase.finito]]» o «[[contest.phase.sempre]]»), «[[contest.qso]]», «[[contest.mult]]», «[[contest.score]]», «[[contest.rate10]]» y «[[contest.rate60]]» (QSO por hora), «[[contest.forecast]]» (la puntuación si sigues a este ritmo), «[[contest.sent]]», la ficha de la categoría (clic: elige categoría, operadores, potencia, asistencia o transmisores del Field Day) y «[[contest.hours]]». Si la banda o el modo no están admitidos aparece un aviso rojo.', 'Com o concurso ligado a barra mostra: a fase («Começa em …», o tempo que falta para o fim, «[[contest.phase.finito]]» ou «[[contest.phase.sempre]]»), «[[contest.qso]]», «[[contest.mult]]», «[[contest.score]]», «[[contest.rate10]]» e «[[contest.rate60]]» (QSO por hora), «[[contest.forecast]]» (a pontuação se continuares a este ritmo), «[[contest.sent]]», o cartão da categoria (clique: escolhe categoria, operadores, potência, assistência ou transmissores do Field Day) e «[[contest.hours]]». Se a banda ou o modo não forem permitidos aparece um aviso vermelho.'],
      ['Con il contest spento la barra dice «[[contest.none]]» e il pulsante «[[contest.calendar]]» apre l’elenco dei contest dei prossimi mesi, con «[[contest.cal.prepare]]» per attivarne uno al volo (le date segnate «[[contest.cal.check]]» vanno verificate sul regolamento).', 'With the contest off, the bar says “[[contest.none]]” and the “[[contest.calendar]]” button opens the list of contests of the coming months, with “[[contest.cal.prepare]]” to activate one on the fly (dates marked “[[contest.cal.check]]” must be checked against the rules).', 'Bei ausgeschaltetem Contest sagt die Leiste „[[contest.none]]“, und die Schaltfläche „[[contest.calendar]]“ öffnet die Liste der Conteste der nächsten Monate, mit „[[contest.cal.prepare]]“, um einen im Handumdrehen zu aktivieren (die mit „[[contest.cal.check]]“ markierten Daten müssen im Regelwerk geprüft werden).', 'Avec le contest éteint, la barre dit « [[contest.none]] » et le bouton « [[contest.calendar]] » ouvre la liste des contests des prochains mois, avec « [[contest.cal.prepare]] » pour en activer un au vol (les dates marquées « [[contest.cal.check]] » sont à vérifier sur le règlement).', 'Con el concurso apagado la barra dice «[[contest.none]]» y el botón «[[contest.calendar]]» abre la lista de los concursos de los próximos meses, con «[[contest.cal.prepare]]» para activar uno al vuelo (las fechas marcadas «[[contest.cal.check]]» hay que verificarlas en el reglamento).', 'Com o concurso desligado a barra diz «[[contest.none]]» e o botão «[[contest.calendar]]» abre a lista dos concursos dos próximos meses, com «[[contest.cal.prepare]]» para ativar um de imediato (as datas assinaladas «[[contest.cal.check]]» têm de ser verificadas no regulamento).'],
      ['Sulla riga delle schede, a destra, c’è la tendina delle frequenze con le sole bande ammesse, e il quadratino RX/TX: «RX» verde in ascolto (un clic libera il QSO in corso, come «Canc DX»), «TX» rosso in trasmissione (un clic ferma subito).', 'On the row of tabs, on the right, there is the frequency drop-down with only the allowed bands, and the little RX/TX box: green “RX” when listening (a click frees the current QSO, like “Clear DX”), red “TX” when transmitting (a click stops it at once).', 'In der Reiterzeile, rechts, steht die Frequenzliste mit nur den erlaubten Bändern, und das Quadrat RX/TX: grünes „RX“ beim Hören (ein Klick gibt das laufende QSO frei, wie „DX löschen“), rotes „TX“ beim Senden (ein Klick stoppt sofort).', 'Sur la ligne des onglets, à droite, il y a la liste des fréquences avec seulement les bandes admises, et le petit carré RX/TX : « RX » vert en écoute (un clic libère le QSO en cours, comme « Effacer DX »), « TX » rouge en émission (un clic arrête tout de suite).', 'En la fila de las fichas, a la derecha, está la lista de las frecuencias con solo las bandas admitidas, y el cuadradito RX/TX: «RX» verde en escucha (un clic libera el QSO en curso, como «Borrar DX»), «TX» rojo en transmisión (un clic detiene enseguida).', 'Na linha dos separadores, à direita, está a lista das frequências só com as bandas permitidas, e o quadradinho RX/TX: «RX» verde a ouvir (um clique liberta o QSO em curso, como «Limpar DX»), «TX» vermelho em transmissão (um clique pára logo).'],
      ['Scheda «[[contest.training]]»: un simulatore (vedi «Contest: calendario, allenamento e analisi»). Scheda «[[contest.analysis]]»: il bilancio dopo la gara.', '“[[contest.training]]” tab: a simulator (see “Contest: calendar, training and analysis”). “[[contest.analysis]]” tab: the review after the contest.', 'Reiter „[[contest.training]]“: ein Simulator (siehe „Contest: Kalender, Training und Auswertung“). Reiter „[[contest.analysis]]“: die Bilanz nach dem Wettbewerb.', 'Onglet « [[contest.training]] » : un simulateur (voir « Contest : calendrier, entraînement et analyse »). Onglet « [[contest.analysis]] » : le bilan après la course.', 'Ficha «[[contest.training]]»: un simulador (mira «Concurso: calendario, entrenamiento y análisis»). Ficha «[[contest.analysis]]»: el balance tras la competición.', 'Separador «[[contest.training]]»: um simulador (vê «Concurso: calendário, treino e análise»). Separador «[[contest.analysis]]»: o balanço depois da prova.'],
    ],
  },
  {
    id: 'p-contest2',
    title: ['Contest: la scheda In gara, riquadro per riquadro', 'Contest: the Racing tab, panel by panel', 'Contest: der Reiter Im Contest, Feld für Feld', 'Contest : l’onglet En course, encadré par encadré', 'Concurso: la ficha En competición, recuadro a recuadro', 'Concurso: o separador Em prova, quadro a quadro'],
    text: ['La scheda «[[contest.tab.race]]» è la pagina di lavoro durante il contest. Le scorciatoie F1–F4 sono in «Contest: tastiera e comandi».', 'The “[[contest.tab.race]]” tab is the working page during the contest. The F1–F4 shortcuts are in “Contest: keyboard and commands”.', 'Der Reiter „[[contest.tab.race]]“ ist die Arbeitsseite während des Contests. Die Kürzel F1–F4 stehen unter „Contest: Tastatur und Befehle“.', 'L’onglet « [[contest.tab.race]] » est la page de travail pendant le contest. Les raccourcis F1–F4 sont dans « Contest : clavier et commandes ».', 'La ficha «[[contest.tab.race]]» es la página de trabajo durante el concurso. Los atajos F1–F4 están en «Concurso: teclado y comandos».', 'O separador «[[contest.tab.race]]» é a página de trabalho durante o concurso. Os atalhos F1–F4 estão em «Concurso: teclado e comandos».'],
    steps: [
      ['«[[contest.decodes]]» (o «[[contest.decodes.time]]»): le decodifiche degli ultimi periodi. Colonne: «[[contest.col.utc]]», «[[contest.col.msg]]», «[[contest.col.country]]», «[[contest.col.new]]» (cosa vale per te) e «[[contest.col.value]]»; i titoli si spostano e si allargano trascinandoli. Doppio clic su una riga: chiami quella stazione (se è un doppio, Aurora chiede prima conferma); la stella ★ è la stazione consigliata. Righe: barrata = doppio, gialla = «[[contest.nonContest]]», «[[contest.outOfRules]]» = fuori regola.', '“[[contest.decodes]]” (or “[[contest.decodes.time]]”): the decodes of the last periods. Columns: “[[contest.col.utc]]”, “[[contest.col.msg]]”, “[[contest.col.country]]”, “[[contest.col.new]]” (what counts for you) and “[[contest.col.value]]”; the headings can be moved and widened by dragging them. Double-click on a row: you call that station (if it is a dupe, Aurora asks for confirmation first); the star ★ is the recommended station. Rows: struck through = dupe, yellow = “[[contest.nonContest]]”, “[[contest.outOfRules]]” = out of the rules.', '„[[contest.decodes]]“ (oder „[[contest.decodes.time]]“): die Dekodierungen der letzten Durchgänge. Spalten: „[[contest.col.utc]]“, „[[contest.col.msg]]“, „[[contest.col.country]]“, „[[contest.col.new]]“ (was für dich zählt) und „[[contest.col.value]]“; die Titel verschiebst und verbreiterst du durch Ziehen. Doppelklick auf eine Zeile: Du rufst diese Station (ist sie ein Doppel, fragt Aurora vorher nach); der Stern ★ ist die empfohlene Station. Zeilen: durchgestrichen = Doppel, gelb = „[[contest.nonContest]]“, „[[contest.outOfRules]]“ = gegen die Regeln.', '« [[contest.decodes]] » (ou « [[contest.decodes.time]] ») : les décodages des dernières périodes. Colonnes : « [[contest.col.utc]] », « [[contest.col.msg]] », « [[contest.col.country]] », « [[contest.col.new]] » (ce qui vaut pour toi) et « [[contest.col.value]] » ; les titres se déplacent et s’élargissent en les glissant. Double-clic sur une ligne : tu appelles cette station (si c’est un doublon, Aurora demande d’abord confirmation) ; l’étoile ★ est la station conseillée. Lignes : barrée = doublon, jaune = « [[contest.nonContest]] », « [[contest.outOfRules]] » = hors règlement.', '«[[contest.decodes]]» (o «[[contest.decodes.time]]»): las decodificaciones de los últimos periodos. Columnas: «[[contest.col.utc]]», «[[contest.col.msg]]», «[[contest.col.country]]», «[[contest.col.new]]» (qué vale para ti) y «[[contest.col.value]]»; los títulos se mueven y se ensanchan arrastrándolos. Doble clic en una fila: llamas a esa estación (si es un doble, Aurora pide antes confirmación); la estrella ★ es la estación aconsejada. Filas: tachada = doble, amarilla = «[[contest.nonContest]]», «[[contest.outOfRules]]» = fuera de reglamento.', '«[[contest.decodes]]» (ou «[[contest.decodes.time]]»): as descodificações dos últimos períodos. Colunas: «[[contest.col.utc]]», «[[contest.col.msg]]», «[[contest.col.country]]», «[[contest.col.new]]» (o que vale para ti) e «[[contest.col.value]]»; os títulos movem-se e alargam-se arrastando-os. Duplo clique numa linha: chamas essa estação (se for um duplicado, a Aurora pede primeiro confirmação); a estrela ★ é a estação aconselhada. Linhas: riscada = duplicado, amarela = «[[contest.nonContest]]», «[[contest.outOfRules]]» = fora do regulamento.'],
      ['Sopra l’elenco: «[[contest.order]]» con «[[contest.order.value]]» (punti e moltiplicatori nuovi in alto, solo gli ultimi due periodi) e «[[contest.order.time]]» (tutte, in ordine di tempo); «[[contest.onlyCq]]» (nasconde i QSO fra altre stazioni); un filtro per locatore, che si toglie con la ✕.', 'Above the list: “[[contest.order]]” with “[[contest.order.value]]” (new points and multipliers on top, only the last two periods) and “[[contest.order.time]]” (all of them, in time order); “[[contest.onlyCq]]” (hides the QSOs between other stations); a filter by locator, which you remove with the ✕.', 'Über der Liste: „[[contest.order]]“ mit „[[contest.order.value]]“ (Punkte und neue Multiplikatoren oben, nur die letzten zwei Durchgänge) und „[[contest.order.time]]“ (alle, nach Zeit geordnet); „[[contest.onlyCq]]“ (blendet die QSOs zwischen anderen Stationen aus); ein Filter nach Locator, der mit dem ✕ aufgehoben wird.', 'Au-dessus de la liste : « [[contest.order]] » avec « [[contest.order.value]] » (points et multiplicateurs nouveaux en haut, seulement les deux dernières périodes) et « [[contest.order.time]] » (toutes, par ordre de temps) ; « [[contest.onlyCq]] » (cache les QSO entre autres stations) ; un filtre par locator, qui s’enlève avec la ✕.', 'Sobre la lista: «[[contest.order]]» con «[[contest.order.value]]» (puntos y multiplicadores nuevos arriba, solo los dos últimos periodos) y «[[contest.order.time]]» (todas, en orden de tiempo); «[[contest.onlyCq]]» (oculta los QSO entre otras estaciones); un filtro por localizador, que se quita con la ✕.', 'Por cima da lista: «[[contest.order]]» com «[[contest.order.value]]» (pontos e multiplicadores novos em cima, só os dois últimos períodos) e «[[contest.order.time]]» (todas, por ordem de tempo); «[[contest.onlyCq]]» (esconde os QSO entre outras estações); um filtro por locator, que se tira com o ✕.'],
      ['«[[contest.qsoNow]]»: la stazione con cui sei in QSO e la sua sequenza automatica ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): un clic su una riga sceglie quel messaggio, «[[contest.onAir]]» dice quale sta uscendo. Se la stazione non fa il contest (risponde con il rapporto in dB) compaiono «[[contest.normal.rpt]]», «[[contest.normal.rrpt]]» e «RR73» per chiudere con i messaggi normali: il QSO va nel log normale e non conta per la gara.', '“[[contest.qsoNow]]”: the station you are in QSO with and its automatic sequence ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): a click on a row chooses that message, “[[contest.onAir]]” says which one is going out. If the station is not in the contest (it answers with the report in dB), “[[contest.normal.rpt]]”, “[[contest.normal.rrpt]]” and “RR73” appear to close with the normal messages: the QSO goes into the normal log and does not count for the contest.', '„[[contest.qsoNow]]“: die Station, mit der du im QSO bist, und ihre automatische Sequenz ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): Ein Klick auf eine Zeile wählt diese Nachricht, „[[contest.onAir]]“ sagt, welche gerade herausgeht. Macht die Station den Contest nicht mit (antwortet mit dem Rapport in dB), erscheinen „[[contest.normal.rpt]]“, „[[contest.normal.rrpt]]“ und „RR73“, um mit den normalen Nachrichten abzuschließen: Das QSO kommt ins normale Log und zählt nicht für den Wettbewerb.', '« [[contest.qsoNow]] » : la station avec laquelle tu es en QSO et sa séquence automatique ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]) : un clic sur une ligne choisit ce message, « [[contest.onAir]] » dit lequel est en train de sortir. Si la station ne fait pas le contest (elle répond avec le report en dB), « [[contest.normal.rpt]] », « [[contest.normal.rrpt]] » et « RR73 » apparaissent pour clore avec les messages normaux : le QSO va dans le log normal et ne compte pas pour la course.', '«[[contest.qsoNow]]»: la estación con la que estás en QSO y su secuencia automática ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): un clic en una fila elige ese mensaje, «[[contest.onAir]]» dice cuál está saliendo. Si la estación no hace el concurso (responde con el informe en dB) aparecen «[[contest.normal.rpt]]», «[[contest.normal.rrpt]]» y «RR73» para cerrar con los mensajes normales: el QSO va al log normal y no cuenta para la competición.', '«[[contest.qsoNow]]»: a estação com que estás em QSO e a sua sequência automática ( [[contest.step.exch]], [[contest.step.rexch]], [[contest.step.close]], [[contest.step.cq]]): um clique numa linha escolhe essa mensagem, «[[contest.onAir]]» diz qual está a sair. Se a estação não está no concurso (responde com o relatório em dB) aparecem «[[contest.normal.rpt]]», «[[contest.normal.rrpt]]» e «RR73» para fechar com as mensagens normais: o QSO vai para o log normal e não conta para a prova.'],
      ['Pulsanti sotto: «[[contest.autoseq]]» (i messaggi avanzano da soli), «[[contest.enableTx]]», «[[contest.autoCq]]» (F1: il CQ del contest a ogni periodo finché qualcuno risponde), «[[contest.rr73]]» (rimanda la chiusura se il corrispondente ripete lo scambio), «[[stop.button]]». «[[contest.next]]» dice chi chiamare dopo, in ordine di valore.', 'Buttons below: “[[contest.autoseq]]” (the messages advance by themselves), “[[contest.enableTx]]”, “[[contest.autoCq]]” (F1: the contest CQ at every period until someone answers), “[[contest.rr73]]” (resends the closing if the other station repeats the exchange), “[[stop.button]]”. “[[contest.next]]” says whom to call next, in order of value.', 'Schaltflächen darunter: „[[contest.autoseq]]“ (die Nachrichten laufen von selbst weiter), „[[contest.enableTx]]“, „[[contest.autoCq]]“ (F1: das Contest-CQ in jedem Durchgang, bis jemand antwortet), „[[contest.rr73]]“ (sendet den Abschluss erneut, wenn die Gegenstation den Austausch wiederholt), „[[stop.button]]“. „[[contest.next]]“ sagt, wen du als Nächsten rufst, nach Wert geordnet.', 'Boutons dessous : « [[contest.autoseq]] » (les messages avancent tout seuls), « [[contest.enableTx]] », « [[contest.autoCq]] » (F1 : le CQ du contest à chaque période tant que personne ne répond), « [[contest.rr73]] » (renvoie la clôture si le correspondant répète l’échange), « [[stop.button]] ». « [[contest.next]] » dit qui appeler ensuite, par ordre de valeur.', 'Botones de abajo: «[[contest.autoseq]]» (los mensajes avanzan solos), «[[contest.enableTx]]», «[[contest.autoCq]]» (F1: el CQ del concurso en cada periodo hasta que alguien responde), «[[contest.rr73]]» (reenvía el cierre si el corresponsal repite el intercambio), «[[stop.button]]». «[[contest.next]]» dice a quién llamar después, en orden de valor.', 'Botões por baixo: «[[contest.autoseq]]» (as mensagens avançam sozinhas), «[[contest.enableTx]]», «[[contest.autoCq]]» (F1: o CQ do concurso a cada período até alguém responder), «[[contest.rr73]]» (reenvia o fecho se o correspondente repetir a troca), «[[stop.button]]». «[[contest.next]]» diz quem chamar a seguir, por ordem de valor.'],
      ['«[[contest.tips]]»: il ritmo delle ultime 12 ore e gli avvisi («[[contest.alert.ok]]» quando è tutto in regola; poi inizio, fine, QSO incerti, avvio umano obbligatorio, ore di attività). Con più bande c’è anche la tabella dei QSO, punti e moltiplicatori per banda.', '“[[contest.tips]]”: the rate of the last 12 hours and the warnings (“[[contest.alert.ok]]” when everything is in order; then start, end, uncertain QSOs, mandatory human start-up, hours of activity). With several bands there is also the table of QSOs, points and multipliers per band.', '„[[contest.tips]]“: das Tempo der letzten 12 Stunden und die Hinweise („[[contest.alert.ok]]“, wenn alles in Ordnung ist; dann Beginn, Ende, unsichere QSOs, Pflicht zum menschlichen Start, Aktivitätsstunden). Bei mehreren Bändern gibt es auch die Tabelle der QSOs, Punkte und Multiplikatoren pro Band.', '« [[contest.tips]] » : le rythme des 12 dernières heures et les alertes (« [[contest.alert.ok]] » quand tout est en règle ; puis début, fin, QSO incertains, démarrage humain obligatoire, heures d’activité). Avec plusieurs bandes, il y a aussi le tableau des QSO, points et multiplicateurs par bande.', '«[[contest.tips]]»: el ritmo de las últimas 12 horas y los avisos («[[contest.alert.ok]]» cuando todo está en regla; luego inicio, final, QSO inciertos, arranque humano obligatorio, horas de actividad). Con varias bandas también está la tabla de los QSO, puntos y multiplicadores por banda.', '«[[contest.tips]]»: o ritmo das últimas 12 horas e os avisos («[[contest.alert.ok]]» quando está tudo em ordem; depois início, fim, QSO incertos, arranque humano obrigatório, horas de atividade). Com mais bandas há também a tabela dos QSO, pontos e multiplicadores por banda.'],
      ['Riga dei pulsanti: «[[contest.rules]]» (il regolamento in breve e il link ufficiale), «[[contest.calendar]]», «[[contest.export]]» (il file per lo sponsor, vedi sotto), «[[contest.settings]]» (le impostazioni del contest, modificabili e salvate per contest), «[[contest.training]]», «[[contest.analysis]]» e «[[contest.end]]» (spegne il contest e torna alle impostazioni di prima).', 'Row of buttons: “[[contest.rules]]” (the rules in brief and the official link), “[[contest.calendar]]”, “[[contest.export]]” (the file for the sponsor, see below), “[[contest.settings]]” (the contest settings, editable and saved per contest), “[[contest.training]]”, “[[contest.analysis]]” and “[[contest.end]]” (turns the contest off and goes back to the previous settings).', 'Zeile der Schaltflächen: „[[contest.rules]]“ (das Regelwerk in Kürze und der offizielle Link), „[[contest.calendar]]“, „[[contest.export]]“ (die Datei für den Sponsor, siehe unten), „[[contest.settings]]“ (die Einstellungen des Contests, änderbar und pro Contest gespeichert), „[[contest.training]]“, „[[contest.analysis]]“ und „[[contest.end]]“ (schaltet den Contest aus und kehrt zu den früheren Einstellungen zurück).', 'Rangée de boutons : « [[contest.rules]] » (le règlement en bref et le lien officiel), « [[contest.calendar]] », « [[contest.export]] » (le fichier pour le sponsor, voir plus bas), « [[contest.settings]] » (les réglages du contest, modifiables et enregistrés par contest), « [[contest.training]] », « [[contest.analysis]] » et « [[contest.end]] » (éteint le contest et revient aux réglages d’avant).', 'Fila de botones: «[[contest.rules]]» (el reglamento en breve y el enlace oficial), «[[contest.calendar]]», «[[contest.export]]» (el archivo para el patrocinador, mira más abajo), «[[contest.settings]]» (los ajustes del concurso, modificables y guardados por concurso), «[[contest.training]]», «[[contest.analysis]]» y «[[contest.end]]» (apaga el concurso y vuelve a los ajustes de antes).', 'Linha dos botões: «[[contest.rules]]» (o regulamento em resumo e a ligação oficial), «[[contest.calendar]]», «[[contest.export]]» (o ficheiro para o patrocinador, vê abaixo), «[[contest.settings]]» (as definições do concurso, editáveis e guardadas por concurso), «[[contest.training]]», «[[contest.analysis]]» e «[[contest.end]]» (desliga o concurso e volta às definições de antes).'],
      ['«[[contest.export]]»: scegli il «[[contest.exp.format]]» (Cabrillo 3.0, EDI o ADIF secondo il regolamento); l’elenco «[[contest.exp.problems]]» dice cosa sistemare prima dell’invio (oppure «[[contest.exp.ok]]»); «[[contest.exp.save]]» salva il file e «[[contest.exp.send]]» apre la pagina dello sponsor. Aurora non invia niente da sola.', '“[[contest.export]]”: choose the “[[contest.exp.format]]” (Cabrillo 3.0, EDI or ADIF according to the rules); the “[[contest.exp.problems]]” list says what to fix before sending (or “[[contest.exp.ok]]”); “[[contest.exp.save]]” saves the file and “[[contest.exp.send]]” opens the sponsor’s page. Aurora does not send anything by itself.', '„[[contest.export]]“: Wähle das „[[contest.exp.format]]“ (Cabrillo 3.0, EDI oder ADIF je nach Regelwerk); die Liste „[[contest.exp.problems]]“ sagt, was vor dem Versand zu korrigieren ist (oder „[[contest.exp.ok]]“); „[[contest.exp.save]]“ speichert die Datei und „[[contest.exp.send]]“ öffnet die Seite des Sponsors. Aurora sendet von selbst nichts.', '« [[contest.export]] » : choisis le « [[contest.exp.format]] » (Cabrillo 3.0, EDI ou ADIF selon le règlement) ; la liste « [[contest.exp.problems]] » dit ce qu’il faut arranger avant l’envoi (ou « [[contest.exp.ok]] ») ; « [[contest.exp.save]] » enregistre le fichier et « [[contest.exp.send]] » ouvre la page du sponsor. Aurora n’envoie rien toute seule.', '«[[contest.export]]»: elige el «[[contest.exp.format]]» (Cabrillo 3.0, EDI o ADIF según el reglamento); la lista «[[contest.exp.problems]]» dice qué arreglar antes del envío (o «[[contest.exp.ok]]»); «[[contest.exp.save]]» guarda el archivo y «[[contest.exp.send]]» abre la página del patrocinador. Aurora no envía nada sola.', '«[[contest.export]]»: escolhe o «[[contest.exp.format]]» (Cabrillo 3.0, EDI ou ADIF segundo o regulamento); a lista «[[contest.exp.problems]]» diz o que acertar antes do envio (ou «[[contest.exp.ok]]»); «[[contest.exp.save]]» guarda o ficheiro e «[[contest.exp.send]]» abre a página do patrocinador. A Aurora não envia nada sozinha.'],
    ],
  },
  {
    id: 'p-contest3',
    title: ['Contest: calendario, allenamento e analisi', 'Contest: calendar, training and analysis', 'Contest: Kalender, Training und Auswertung', 'Contest : calendrier, entraînement et analyse', 'Concurso: calendario, entrenamiento y análisis', 'Concurso: calendário, treino e análise'],
    text: ['Altri riquadri della pagina [[nav.contest]]: il consiglio di banda, la mappa dei moltiplicatori e il log del contest stanno nella scheda «[[contest.tab.race]]», sotto le decodifiche; l’allenamento e l’analisi hanno una scheda ciascuno.', 'Other boxes of the [[nav.contest]] page: the band advice, the multiplier map and the contest log are in the “[[contest.tab.race]]” tab, under the decodes; training and analysis have a tab each.', 'Weitere Felder der Seite [[nav.contest]]: der Bandtipp, die Karte der Multiplikatoren und das Contest-Log stehen im Reiter „[[contest.tab.race]]“, unter den Dekodierungen; Training und Auswertung haben je einen Reiter.', 'Autres encadrés de la page [[nav.contest]] : le conseil de bande, la carte des multiplicateurs et le log du contest sont dans l’onglet « [[contest.tab.race]] », sous les décodages ; l’entraînement et l’analyse ont un onglet chacun.', 'Otros recuadros de la página [[nav.contest]]: el consejo de banda, el mapa de los multiplicadores y el log del concurso están en la ficha «[[contest.tab.race]]», bajo las decodificaciones; el entrenamiento y el análisis tienen una ficha cada uno.', 'Outros quadros da página [[nav.contest]]: o conselho de banda, o mapa dos multiplicadores e o log do concurso estão no separador «[[contest.tab.race]]», por baixo das descodificações; o treino e a análise têm um separador cada.'],
    steps: [
      ['«[[contest.adv]]» (ogni 15 secondi dalle decodifiche): per ogni banda del regolamento le stazioni sentite negli ultimi 15 minuti, i moltiplicatori nuovi in ascolto e il rate stimato. Dice «Resta su banda · modo» o «Vai su banda · modo» con il motivo, e un clic porta la radio sulla banda e sul modo consigliati; «[[contest.adv.ignore]]» lo scarta. Segna anche quanti cambi di banda hai fatto sul massimo ammesso.', '“[[contest.adv]]” (every 15 seconds from the decodes): for each band of the rules, the stations heard in the last 15 minutes, the new multipliers being heard and the estimated rate. It says “Stay on band · mode” or “Go to band · mode” with the reason, and a click moves the radio to the advised band and mode; “[[contest.adv.ignore]]” dismisses it. It also shows how many band changes you have made out of the maximum allowed.', '„[[contest.adv]]“ (alle 15 Sekunden aus den Dekodierungen): für jedes Band des Regelwerks die in den letzten 15 Minuten gehörten Stationen, die neuen Multiplikatoren, die man hört, und die geschätzte Rate. Es sagt „Bleib auf Band · Betriebsart“ oder „Wechsle auf Band · Betriebsart“ mit dem Grund, und ein Klick stellt das Funkgerät auf das empfohlene Band und die empfohlene Betriebsart; „[[contest.adv.ignore]]“ verwirft es. Es zeigt auch, wie viele Bandwechsel du vom erlaubten Höchstwert schon gemacht hast.', '« [[contest.adv]] » (toutes les 15 secondes d’après les décodages) : pour chaque bande du règlement, les stations entendues ces 15 dernières minutes, les multiplicateurs nouveaux à l’écoute et le rate estimé. Il dit « Reste sur bande · mode » ou « Va sur bande · mode » avec le motif, et un clic place la radio sur la bande et le mode conseillés ; « [[contest.adv.ignore]] » l’écarte. Il indique aussi combien de changements de bande tu as faits sur le maximum admis.', '«[[contest.adv]]» (cada 15 segundos a partir de las decodificaciones): para cada banda del reglamento las estaciones oídas en los últimos 15 minutos, los multiplicadores nuevos en escucha y el rate estimado. Dice «Quédate en banda · modo» o «Ve a banda · modo» con el motivo, y un clic lleva la radio a la banda y al modo aconsejados; «[[contest.adv.ignore]]» lo descarta. Marca también cuántos cambios de banda has hecho sobre el máximo admitido.', '«[[contest.adv]]» (a cada 15 segundos a partir das descodificações): para cada banda do regulamento as estações ouvidas nos últimos 15 minutos, os multiplicadores novos à escuta e o rate estimado. Diz «Fica em banda · modo» ou «Vai para banda · modo» com o motivo, e um clique leva o rádio para a banda e o modo aconselhados; «[[contest.adv.ignore]]» descarta-o. Assinala também quantas mudanças de banda fizeste sobre o máximo permitido.'],
      ['«[[contest.map]]»: per la banda scelta nelle linguette i moltiplicatori già lavorati, quelli nuovi che si sentono adesso (arancio) e quelli sentiti ma già presi (dalle decodifiche degli ultimi 15 minuti). Un clic su un riquadro o su un nominativo chiama la stazione. Se il contest non ha moltiplicatori dice «[[contest.noMult]]».', '“[[contest.map]]”: for the band chosen in the tabs, the multipliers already worked, the new ones you can hear now (orange) and those heard but already taken (from the decodes of the last 15 minutes). A click on a box or on a callsign calls the station. If the contest has no multipliers it says “[[contest.noMult]]”.', '„[[contest.map]]“: für das in den Reitern gewählte Band die schon gearbeiteten Multiplikatoren, die neuen, die man jetzt hört (orange), und die gehörten, aber schon erledigten (aus den Dekodierungen der letzten 15 Minuten). Ein Klick auf ein Feld oder auf ein Rufzeichen ruft die Station. Hat der Contest keine Multiplikatoren, sagt es „[[contest.noMult]]“.', '« [[contest.map]] » : pour la bande choisie dans les onglets, les multiplicateurs déjà contactés, les nouveaux qu’on entend maintenant (orange) et ceux entendus mais déjà pris (d’après les décodages des 15 dernières minutes). Un clic sur un carré ou sur un indicatif appelle la station. Si le contest n’a pas de multiplicateurs, il dit « [[contest.noMult]] ».', '«[[contest.map]]»: para la banda elegida en las pestañitas, los multiplicadores ya trabajados, los nuevos que se oyen ahora (naranja) y los oídos pero ya conseguidos (de las decodificaciones de los últimos 15 minutos). Un clic en un recuadro o en un indicativo llama a la estación. Si el concurso no tiene multiplicadores dice «[[contest.noMult]]».', '«[[contest.map]]»: para a banda escolhida nos separadores os multiplicadores já trabalhados, os novos que se ouvem agora (laranja) e os ouvidos mas já feitos (das descodificações dos últimos 15 minutos). Um clique num quadro ou num indicativo chama a estação. Se o concurso não tiver multiplicadores diz «[[contest.noMult]]».'],
      ['«[[contest.log]]»: il log di questo contest (i QSO vanno anche nel log normale), con il numero di QSO e di incerti. Un clic sullo scambio ricevuto lo corregge («[[contest.edited]]»); tasto destro su una riga: valido, incerto o «[[contest.notInContest]]» (0 punti, fuori dal Cabrillo). «[[contest.resetLog]]» ricomincia il log da zero, dopo una conferma (il vecchio resta come copia nella cartella dei dati).', '“[[contest.log]]”: the log of this contest (the QSOs also go into the normal log), with the number of QSOs and of uncertain ones. A click on the received exchange corrects it (“[[contest.edited]]”); right-click on a row: valid, uncertain or “[[contest.notInContest]]” (0 points, left out of the Cabrillo). “[[contest.resetLog]]” starts the log again from zero, after a confirmation (the old one stays as a copy in the data folder).', '„[[contest.log]]“: das Log dieses Contests (die QSOs kommen auch ins normale Log), mit der Zahl der QSOs und der unsicheren. Ein Klick auf den empfangenen Austausch korrigiert ihn („[[contest.edited]]“); Rechtsklick auf eine Zeile: gültig, unsicher oder „[[contest.notInContest]]“ (0 Punkte, nicht im Cabrillo). „[[contest.resetLog]]“ beginnt das Log bei null, nach einer Bestätigung (das alte bleibt als Kopie im Datenordner).', '« [[contest.log]] » : le log de ce contest (les QSO vont aussi dans le log normal), avec le nombre de QSO et d’incertains. Un clic sur l’échange reçu le corrige (« [[contest.edited]] ») ; clic droit sur une ligne : valide, incertain ou « [[contest.notInContest]] » (0 point, hors du Cabrillo). « [[contest.resetLog]] » recommence le log à zéro, après une confirmation (l’ancien reste en copie dans le dossier des données).', '«[[contest.log]]»: el log de este concurso (los QSO van también al log normal), con el número de QSO y de inciertos. Un clic en el intercambio recibido lo corrige («[[contest.edited]]»); clic derecho en una fila: válido, incierto o «[[contest.notInContest]]» (0 puntos, fuera del Cabrillo). «[[contest.resetLog]]» empieza el log desde cero, tras una confirmación (el viejo queda como copia en la carpeta de datos).', '«[[contest.log]]»: o log deste concurso (os QSO vão também para o log normal), com o número de QSO e de incertos. Um clique na troca recebida corrige-a («[[contest.edited]]»); botão direito numa linha: válido, incerto ou «[[contest.notInContest]]» (0 pontos, fora do Cabrillo). «[[contest.resetLog]]» recomeça o log do zero, depois de uma confirmação (o antigo fica como cópia na pasta dos dados).'],
      ['Scheda «[[contest.training]]»: scegli il contest, il «[[contest.sim.pileup]]» ([[contest.sim.light]], [[contest.sim.medium]] o [[contest.sim.heavy]]) e la «[[contest.sim.duration]]», poi «[[contest.sim.start]]»; «[[contest.sim.stop]]» ferma. Le chiamate finte compaiono come le decodifiche in gara: doppio clic per rispondere, RR73 per chiudere. Non usa la radio e non scrive nel log; il bilancio mostra rate, doppi, scambi errati e «[[contest.sim.nil]]» evitati con il reinvio di RR73. Un’etichetta «[[contest.sim.badge]]» ricorda che è una prova.', '“[[contest.training]]” tab: choose the contest, the “[[contest.sim.pileup]]” ([[contest.sim.light]], [[contest.sim.medium]] or [[contest.sim.heavy]]) and the “[[contest.sim.duration]]”, then “[[contest.sim.start]]”; “[[contest.sim.stop]]” stops. The fake calls appear like the decodes in the contest: double-click to reply, RR73 to close. It does not use the radio and does not write to the log; the summary shows rate, dupes, wrong exchanges and the “[[contest.sim.nil]]” avoided by resending RR73. A “[[contest.sim.badge]]” label reminds you that it is a drill.', 'Reiter „[[contest.training]]“: Wähle den Contest, den „[[contest.sim.pileup]]“ ([[contest.sim.light]], [[contest.sim.medium]] oder [[contest.sim.heavy]]) und die „[[contest.sim.duration]]“, dann „[[contest.sim.start]]“; „[[contest.sim.stop]]“ stoppt. Die falschen Rufe erscheinen wie die Dekodierungen im Contest: Doppelklick zum Antworten, RR73 zum Abschließen. Er benutzt das Funkgerät nicht und schreibt nicht ins Log; die Bilanz zeigt Rate, Doppel, falsche Austausche und durch das erneute Senden von RR73 vermiedene „[[contest.sim.nil]]“. Ein Etikett „[[contest.sim.badge]]“ erinnert daran, dass es eine Übung ist.', 'Onglet « [[contest.training]] » : choisis le contest, le « [[contest.sim.pileup]] » ([[contest.sim.light]], [[contest.sim.medium]] ou [[contest.sim.heavy]]) et la « [[contest.sim.duration]] », puis « [[contest.sim.start]] » ; « [[contest.sim.stop]] » arrête. Les faux appels apparaissent comme les décodages en course : double-clic pour répondre, RR73 pour clore. Il n’utilise pas la radio et n’écrit pas dans le log ; le bilan montre rate, doublons, échanges erronés et « [[contest.sim.nil]] » évités grâce au renvoi de RR73. Une étiquette « [[contest.sim.badge]] » rappelle que c’est un essai.', 'Ficha «[[contest.training]]»: elige el concurso, el «[[contest.sim.pileup]]» ([[contest.sim.light]], [[contest.sim.medium]] o [[contest.sim.heavy]]) y la «[[contest.sim.duration]]», luego «[[contest.sim.start]]»; «[[contest.sim.stop]]» detiene. Las llamadas falsas aparecen como las decodificaciones en competición: doble clic para responder, RR73 para cerrar. No usa la radio y no escribe en el log; el balance muestra rate, dobles, intercambios erróneos y «[[contest.sim.nil]]» evitados con el reenvío de RR73. Una etiqueta «[[contest.sim.badge]]» recuerda que es una prueba.', 'Separador «[[contest.training]]»: escolhe o concurso, o «[[contest.sim.pileup]]» ([[contest.sim.light]], [[contest.sim.medium]] ou [[contest.sim.heavy]]) e a «[[contest.sim.duration]]», depois «[[contest.sim.start]]»; «[[contest.sim.stop]]» pára. As chamadas falsas aparecem como as descodificações em prova: duplo clique para responder, RR73 para fechar. Não usa o rádio e não escreve no log; o balanço mostra rate, duplicados, trocas erradas e «[[contest.sim.nil]]» evitados com o reenvio de RR73. Uma etiqueta «[[contest.sim.badge]]» lembra que é um ensaio.'],
      ['Scheda «[[contest.analysis]]»: scegli l’«[[contest.an.edition]]» (o il contest attivo) e leggi QSO, moltiplicatori, punteggio, QSO incerti e ore attive; il grafico dà i QSO ora per ora (verde = la migliore, arancio = la peggiore), poi «[[contest.an.band]]», «[[contest.an.best]]» e «[[contest.an.lost]]» (buchi di oltre 15 minuti senza QSO), con un consiglio.', '“[[contest.analysis]]” tab: choose the “[[contest.an.edition]]” (or the active contest) and read QSOs, multipliers, score, uncertain QSOs and active hours; the chart gives the QSOs hour by hour (green = the best, orange = the worst), then “[[contest.an.band]]”, “[[contest.an.best]]” and “[[contest.an.lost]]” (gaps of more than 15 minutes without a QSO), with a piece of advice.', 'Reiter „[[contest.analysis]]“: Wähle die „[[contest.an.edition]]“ (oder den aktiven Contest) und lies QSOs, Multiplikatoren, Punktzahl, unsichere QSOs und aktive Stunden; die Grafik zeigt die QSOs Stunde für Stunde (grün = die beste, orange = die schlechteste), dann „[[contest.an.band]]“, „[[contest.an.best]]“ und „[[contest.an.lost]]“ (Lücken von über 15 Minuten ohne QSO), mit einem Rat.', 'Onglet « [[contest.analysis]] » : choisis l’« [[contest.an.edition]] » (ou le contest actif) et lis QSO, multiplicateurs, score, QSO incertains et heures actives ; le graphique donne les QSO heure par heure (vert = la meilleure, orange = la pire), puis « [[contest.an.band]] », « [[contest.an.best]] » et « [[contest.an.lost]] » (trous de plus de 15 minutes sans QSO), avec un conseil.', 'Ficha «[[contest.analysis]]»: elige la «[[contest.an.edition]]» (o el concurso activo) y lee QSO, multiplicadores, puntuación, QSO inciertos y horas activas; el gráfico da los QSO hora por hora (verde = la mejor, naranja = la peor), luego «[[contest.an.band]]», «[[contest.an.best]]» y «[[contest.an.lost]]» (huecos de más de 15 minutos sin QSO), con un consejo.', 'Separador «[[contest.analysis]]»: escolhe a «[[contest.an.edition]]» (ou o concurso ativo) e lê QSO, multiplicadores, pontuação, QSO incertos e horas ativas; o gráfico dá os QSO hora a hora (verde = a melhor, laranja = a pior), depois «[[contest.an.band]]», «[[contest.an.best]]» e «[[contest.an.lost]]» (buracos de mais de 15 minutos sem QSO), com um conselho.'],
      ['«[[contest.settings]]» apre le impostazioni del contest, con la tendina dei messaggi (l’attività), la parola del CQ, lo scambio fisso, il primo numero progressivo, il modo, la potenza, i punti bonus, Hold Tx Freq e RRR, e i dati del Cabrillo (nominativo in gara, locatore, antenna, club, nome, email, indirizzo, soapbox, categoria di tempo e categoria aggiuntiva). I valori sono quelli che Aurora ha preparato per il contest; si salvano con «[[contest.set.save]]». Le stesse voci stanno in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].', '“[[contest.settings]]” opens the contest settings, with the message drop-down (the activity), the CQ word, the fixed exchange, the first serial number, the mode, the power, the bonus points, Hold Tx Freq and RRR, and the Cabrillo data (contest callsign, locator, antenna, club, name, email, address, soapbox, time category and extra category). The values are the ones Aurora has prepared for the contest; they are saved with “[[contest.set.save]]”. The same items are in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].', '„[[contest.settings]]“ öffnet die Einstellungen des Contests, mit der Auswahlliste der Nachrichten (die Aktivität), dem CQ-Wort, dem festen Austausch, der ersten laufenden Nummer, der Betriebsart, der Leistung, den Bonuspunkten, Hold Tx Freq und RRR, und den Cabrillo-Daten (Rufzeichen im Contest, Locator, Antenne, Club, Name, E-Mail, Adresse, Soapbox, Zeitkategorie und zusätzliche Kategorie). Die Werte sind die, die Aurora für den Contest vorbereitet hat; sie werden mit „[[contest.set.save]]“ gespeichert. Dieselben Einträge stehen unter [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].', '« [[contest.settings]] » ouvre les réglages du contest, avec la liste des messages (l’activité), le mot du CQ, l’échange fixe, le premier numéro de série, le mode, la puissance, les points bonus, Hold Tx Freq et RRR, et les données du Cabrillo (indicatif en course, locator, antenne, club, nom, e-mail, adresse, soapbox, catégorie de temps et catégorie supplémentaire). Les valeurs sont celles qu’Aurora a préparées pour le contest ; elles s’enregistrent avec « [[contest.set.save]] ». Les mêmes entrées sont dans [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].', '«[[contest.settings]]» abre los ajustes del concurso, con la lista desplegable de los mensajes (la actividad), la palabra del CQ, el intercambio fijo, el primer número progresivo, el modo, la potencia, los puntos de bonificación, Hold Tx Freq y RRR, y los datos del Cabrillo (indicativo en competición, localizador, antena, club, nombre, correo electrónico, dirección, soapbox, categoría de tiempo y categoría adicional). Los valores son los que Aurora ha preparado para el concurso; se guardan con «[[contest.set.save]]». Las mismas opciones están en [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].', '«[[contest.settings]]» abre as definições do concurso, com a lista das mensagens (a atividade), a palavra do CQ, a troca fixa, o primeiro número de série, o modo, a potência, os pontos de bónus, Hold Tx Freq e RRR, e os dados do Cabrillo (indicativo em prova, locator, antena, clube, nome, email, endereço, soapbox, categoria de tempo e categoria adicional). Os valores são os que a Aurora preparou para o concurso; guardam-se com «[[contest.set.save]]». As mesmas entradas estão em [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].'],
    ],
  },
  {
    id: 'p-qmap',
    title: ['QMAP: ogni comando', 'QMAP: every command', 'QMAP: jeder Befehl', 'QMAP : chaque commande', 'QMAP: cada comando', 'QMAP: cada comando'],
    text: ['La pagina [[nav.qmap]] (titolo «[[qmap.title]]») mostra tutti i Q65 di una fetta di banda ascoltata da un ricevitore SDR. Vedi anche «QMAP: tutti i Q65 di una fetta di banda». Senza SDR dice «[[qmap.needSdr]]».', 'The [[nav.qmap]] page (title “[[qmap.title]]”) shows all the Q65 signals in a slice of the band listened to by an SDR receiver. See also “QMAP: every Q65 in a slice of the band”. Without an SDR it says “[[qmap.needSdr]]”.', 'Die Seite [[nav.qmap]] (Titel „[[qmap.title]]“) zeigt alle Q65 eines Bandausschnitts, den ein SDR-Empfänger hört. Siehe auch „QMAP: alle Q65 in einem Bandausschnitt“. Ohne SDR sagt sie „[[qmap.needSdr]]“.', 'La page [[nav.qmap]] (titre « [[qmap.title]] ») montre tous les Q65 d’une tranche de bande écoutée par un récepteur SDR. Voir aussi « QMAP : tous les Q65 d’une tranche de bande ». Sans SDR, elle dit « [[qmap.needSdr]] ».', 'La página [[nav.qmap]] (título «[[qmap.title]]») muestra todos los Q65 de una franja de banda escuchada por un receptor SDR. Mira también «QMAP: todos los Q65 de una franja de banda». Sin SDR dice «[[qmap.needSdr]]».', 'A página [[nav.qmap]] (título «[[qmap.title]]») mostra todos os Q65 de uma faixa da banda escutada por um recetor SDR. Vê também «QMAP: todos os Q65 de uma faixa da banda». Sem SDR diz «[[qmap.needSdr]]».'],
    steps: [
      ['«[[qmap.source]]»: [[qmap.source.off]], [[qmap.source.tci]] (con «[[qmap.tci]]», per esempio 127.0.0.1:40001, e il «[[qmap.rate]]») oppure [[qmap.source.file]] (con il «[[qmap.file]]» e il pulsante «[[qmap.decodeFile]]»). La sorgente si cambia solo dal PC dove gira Aurora.', '“[[qmap.source]]”: [[qmap.source.off]], [[qmap.source.tci]] (with “[[qmap.tci]]”, for example 127.0.0.1:40001, and the “[[qmap.rate]]”) or [[qmap.source.file]] (with the “[[qmap.file]]” and the “[[qmap.decodeFile]]” button). The source can be changed only from the PC where Aurora runs.', '„[[qmap.source]]“: [[qmap.source.off]], [[qmap.source.tci]] (mit „[[qmap.tci]]“, zum Beispiel 127.0.0.1:40001, und der „[[qmap.rate]]“) oder [[qmap.source.file]] (mit der „[[qmap.file]]“ und der Schaltfläche „[[qmap.decodeFile]]“). Die Quelle änderst du nur am PC, auf dem Aurora läuft.', '« [[qmap.source]] » : [[qmap.source.off]], [[qmap.source.tci]] (avec « [[qmap.tci]] », par exemple 127.0.0.1:40001, et le « [[qmap.rate]] ») ou [[qmap.source.file]] (avec le « [[qmap.file]] » et le bouton « [[qmap.decodeFile]] »). La source ne se change que depuis le PC où tourne Aurora.', '«[[qmap.source]]»: [[qmap.source.off]], [[qmap.source.tci]] (con «[[qmap.tci]]», por ejemplo 127.0.0.1:40001, y la «[[qmap.rate]]») o [[qmap.source.file]] (con el «[[qmap.file]]» y el botón «[[qmap.decodeFile]]»). La fuente se cambia solo desde el PC donde corre Aurora.', '«[[qmap.source]]»: [[qmap.source.off]], [[qmap.source.tci]] (com «[[qmap.tci]]», por exemplo 127.0.0.1:40001, e o «[[qmap.rate]]») ou [[qmap.source.file]] (com o «[[qmap.file]]» e o botão «[[qmap.decodeFile]]»). A origem muda-se só a partir do PC onde corre a Aurora.'],
      ['«[[qmap.center]]» (in kHz): la frequenza al centro della fetta, se la sorgente non la dice (il TCI la manda da solo; nei file si legge dal nome, per esempio …_144100kHz.wav). Senza centro il clic «[[qmap.qso]]» non può sapere dove andare.', '“[[qmap.center]]” (in kHz): the frequency at the centre of the slice, if the source doesn’t say it (TCI sends it by itself; for files it is read from the name, for example …_144100kHz.wav). Without a centre the “[[qmap.qso]]” click cannot know where to go.', '„[[qmap.center]]“ (in kHz): die Frequenz in der Mitte des Ausschnitts, wenn die Quelle sie nicht nennt (TCI sendet sie von selbst; bei Dateien liest man sie aus dem Namen, zum Beispiel …_144100kHz.wav). Ohne Mitte weiß der Klick „[[qmap.qso]]“ nicht, wohin er soll.', '« [[qmap.center]] » (en kHz) : la fréquence au centre de la tranche, si la source ne la dit pas (le TCI l’envoie tout seul ; pour les fichiers elle se lit dans le nom, par exemple …_144100kHz.wav). Sans centre, le clic « [[qmap.qso]] » ne peut pas savoir où aller.', '«[[qmap.center]]» (en kHz): la frecuencia en el centro de la franja, si la fuente no la dice (el TCI la manda solo; en los archivos se lee del nombre, por ejemplo …_144100kHz.wav). Sin centro el clic «[[qmap.qso]]» no puede saber adónde ir.', '«[[qmap.center]]» (em kHz): a frequência ao centro da faixa, se a origem não a disser (o TCI envia-a sozinho; nos ficheiros lê-se do nome, por exemplo …_144100kHz.wav). Sem centro o clique «[[qmap.qso]]» não pode saber para onde ir.'],
      ['«[[qmap.period]]» e «[[qmap.submodes]]»: periodo e sottomodi da cercare. «[[qmap.fading]]»: il modello di evanescenza per l’EME. «[[qmap.also30]]» (con periodo 60 s cerca anche i Q65-30). «[[qmap.average]]» somma i periodi per i segnali più deboli; «[[qmap.clearAverage]]» svuota la media. «[[qmap.save]]» applica tutto.', '“[[qmap.period]]” and “[[qmap.submodes]]”: period and submodes to search for. “[[qmap.fading]]”: the fading model for EME. “[[qmap.also30]]” (with a 60 s period it also searches for Q65-30). “[[qmap.average]]” adds up the periods for weaker signals; “[[qmap.clearAverage]]” empties the average. “[[qmap.save]]” applies everything.', '„[[qmap.period]]“ und „[[qmap.submodes]]“: Durchgang und Untermodi, nach denen gesucht wird. „[[qmap.fading]]“: das Fading-Modell für EME. „[[qmap.also30]]“ (bei Durchgang 60 s sucht es auch Q65-30). „[[qmap.average]]“ addiert die Durchgänge für schwächere Signale; „[[qmap.clearAverage]]“ leert die Mittelung. „[[qmap.save]]“ wendet alles an.', '« [[qmap.period]] » et « [[qmap.submodes]] » : période et sous-modes à chercher. « [[qmap.fading]] » : le modèle d’évanouissement pour l’EME. « [[qmap.also30]] » (avec une période de 60 s, cherche aussi les Q65-30). « [[qmap.average]] » additionne les périodes pour les signaux plus faibles ; « [[qmap.clearAverage]] » vide la moyenne. « [[qmap.save]] » applique tout.', '«[[qmap.period]]» y «[[qmap.submodes]]»: periodo y submodos que hay que buscar. «[[qmap.fading]]»: el modelo de desvanecimiento para el EME. «[[qmap.also30]]» (con periodo 60 s busca también los Q65-30). «[[qmap.average]]» suma los periodos para las señales más débiles; «[[qmap.clearAverage]]» vacía el promedio. «[[qmap.save]]» aplica todo.', '«[[qmap.period]]» e «[[qmap.submodes]]»: período e submodos a procurar. «[[qmap.fading]]»: o modelo de desvanecimento para o EME. «[[qmap.also30]]» (com período de 60 s procura também os Q65-30). «[[qmap.average]]» soma os períodos para os sinais mais fracos; «[[qmap.clearAverage]]» esvazia a média. «[[qmap.save]]» aplica tudo.'],
      ['«[[qmap.spectrum]]»: lo spettro della fetta con i segnali trovati; sotto, quanti candidati e messaggi ha trovato e quanti secondi di dati usa. La riga della Luna dice azimut, elevazione ed eco Doppler dal tuo locatore.', '“[[qmap.spectrum]]”: the spectrum of the slice with the signals found; below, how many candidates and messages it has found and how many seconds of data it uses. The Moon row gives azimuth, elevation and Doppler echo from your locator.', '„[[qmap.spectrum]]“: das Spektrum des Ausschnitts mit den gefundenen Signalen; darunter, wie viele Kandidaten und Nachrichten es gefunden hat und wie viele Sekunden Daten es benutzt. Die Zeile des Mondes nennt Azimut, Elevation und Doppler-Echo von deinem Locator aus.', '« [[qmap.spectrum]] » : le spectre de la tranche avec les signaux trouvés ; dessous, combien de candidats et de messages il a trouvés et combien de secondes de données il utilise. La ligne de la Lune dit azimut, élévation et écho Doppler depuis ton locator.', '«[[qmap.spectrum]]»: el espectro de la franja con las señales encontradas; debajo, cuántos candidatos y mensajes ha encontrado y cuántos segundos de datos usa. La fila de la Luna dice acimut, elevación y eco Doppler desde tu localizador.', '«[[qmap.spectrum]]»: o espetro da faixa com os sinais encontrados; por baixo, quantos candidatos e mensagens encontrou e quantos segundos de dados usa. A linha da Lua diz azimute, elevação e eco Doppler a partir do teu locator.'],
      ['Tabella dei messaggi: «[[qmap.col.freq]]», «[[qmap.col.sked]]» (la frequenza dove trasmette chi corregge da sé il proprio Doppler), «[[qmap.col.mode]]» e «[[qmap.col.msg]]». Il pulsante «[[qmap.qso]]» porta la radio su quel segnale in Q65 con il periodo e il sottomodo giusti; se non è tutto a posto dice cosa manca (il centro della fetta, o che la radio non si è spostata). Senza messaggi: «[[qmap.empty]]».', 'Message table: “[[qmap.col.freq]]”, “[[qmap.col.sked]]” (the frequency where the station that corrects its own Doppler transmits), “[[qmap.col.mode]]” and “[[qmap.col.msg]]”. The “[[qmap.qso]]” button moves the radio to that signal in Q65 with the right period and submode; if everything is not in order it says what is missing (the centre of the slice, or that the radio did not move). With no messages: “[[qmap.empty]]”.', 'Tabelle der Nachrichten: „[[qmap.col.freq]]“, „[[qmap.col.sked]]“ (die Frequenz, auf der sendet, wer sein eigenes Doppler selbst korrigiert), „[[qmap.col.mode]]“ und „[[qmap.col.msg]]“. Die Schaltfläche „[[qmap.qso]]“ stellt das Funkgerät auf dieses Signal in Q65 mit dem richtigen Durchgang und Untermodus; ist nicht alles in Ordnung, sagt sie, was fehlt (die Mitte des Ausschnitts, oder dass das Funkgerät sich nicht bewegt hat). Ohne Nachrichten: „[[qmap.empty]]“.', 'Tableau des messages : « [[qmap.col.freq]] », « [[qmap.col.sked]] » (la fréquence où émet celui qui corrige lui-même son Doppler), « [[qmap.col.mode]] » et « [[qmap.col.msg]] ». Le bouton « [[qmap.qso]] » place la radio sur ce signal en Q65 avec la période et le sous-mode justes ; si tout n’est pas en ordre, il dit ce qui manque (le centre de la tranche, ou que la radio ne s’est pas déplacée). Sans messages : « [[qmap.empty]] ».', 'Tabla de los mensajes: «[[qmap.col.freq]]», «[[qmap.col.sked]]» (la frecuencia donde transmite quien corrige por sí mismo su Doppler), «[[qmap.col.mode]]» y «[[qmap.col.msg]]». El botón «[[qmap.qso]]» lleva la radio a esa señal en Q65 con el periodo y el submodo correctos; si no está todo en orden dice qué falta (el centro de la franja, o que la radio no se ha movido). Sin mensajes: «[[qmap.empty]]».', 'Tabela das mensagens: «[[qmap.col.freq]]», «[[qmap.col.sked]]» (a frequência onde transmite quem corrige sozinho o seu Doppler), «[[qmap.col.mode]]» e «[[qmap.col.msg]]». O botão «[[qmap.qso]]» leva o rádio para esse sinal em Q65 com o período e o submodo certos; se nem tudo estiver em ordem diz o que falta (o centro da faixa, ou que o rádio não se moveu). Sem mensagens: «[[qmap.empty]]».'],
    ],
  },
  {
    id: 'p-rotor',
    title: ['Rotore: la pagina e la scheda', 'Rotator: the page and the card', 'Rotor: Seite und Karteireiter', 'Rotor : la page et l’onglet', 'Rotor: la página y la ficha', 'Rotor: a página e o separador'],
    text: ['La pagina [[nav.rotator]] (titolo «[[rot.title]]») mostra la rosa dei venti e i comandi del rotore. La stessa scheda può stare anche sopra la Stazione, nei modi FT8, FT4, JT65, Q65 e così via. La configurazione del rotore è in «Il rotore d’antenna».', 'The [[nav.rotator]] page (title “[[rot.title]]”) shows the compass rose and the rotator controls. The same card can also sit above the Station, in the FT8, FT4, JT65, Q65 modes and so on. The rotator setup is in “The antenna rotator”.', 'Die Seite [[nav.rotator]] (Titel „[[rot.title]]“) zeigt die Windrose und die Befehle des Rotors. Dieselbe Karte kann auch über der Station stehen, in den Betriebsarten FT8, FT4, JT65, Q65 und so weiter. Die Einrichtung des Rotors steht unter „Der Antennenrotor“.', 'La page [[nav.rotator]] (titre « [[rot.title]] ») montre la rose des vents et les commandes du rotor. Le même onglet peut aussi se trouver au-dessus de la Station, dans les modes FT8, FT4, JT65, Q65 et ainsi de suite. La configuration du rotor est dans « Le rotor d’antenne ».', 'La página [[nav.rotator]] (título «[[rot.title]]») muestra la rosa de los vientos y los comandos del rotor. La misma ficha puede estar también sobre la Estación, en los modos FT8, FT4, JT65, Q65 y así sucesivamente. La configuración del rotor está en «El rotor de antena».', 'A página [[nav.rotator]] (título «[[rot.title]]») mostra a rosa dos ventos e os comandos do rotor. O mesmo separador pode estar também por cima da Estação, nos modos FT8, FT4, JT65, Q65 e assim por diante. A configuração do rotor está em «O rotor de antena».'],
    steps: [
      ['La rosa: l’ago pieno è l’antenna, quello tratteggiato la destinazione; il segno verde è la stazione DX (percorso corto), quello arancio la via lunga. Se il rotore ha un campo più largo di 360° una fascia gialla sulla bussola segna la sovrapposizione, dove si arriva da due angoli (si sceglie il più vicino). Clicca sulla rosa per mandare l’antenna in quella direzione («[[rot.clickHint]]»).', 'The rose: the solid needle is the antenna, the dashed one the destination; the green mark is the DX station (short path), the orange one the long path. If the rotator has a range wider than 360°, a yellow band on the compass marks the overlap, where you can arrive from two angles (the nearest is chosen). Click on the rose to send the antenna in that direction (“[[rot.clickHint]]”).', 'Die Rose: Die ausgefüllte Nadel ist die Antenne, die gestrichelte das Ziel; das grüne Zeichen ist die DX-Station (kurzer Weg), das orange der lange Weg. Hat der Rotor einen Bereich größer als 360°, markiert ein gelbes Band auf dem Kompass die Überlappung, wo man aus zwei Winkeln ankommt (der nähere wird gewählt). Klicke auf die Rose, um die Antenne in diese Richtung zu schicken („[[rot.clickHint]]“).', 'La rose : l’aiguille pleine est l’antenne, celle en pointillé la destination ; le repère vert est la station DX (trajet court), l’orange le trajet long. Si le rotor a un champ plus large que 360°, une bande jaune sur la boussole marque le recouvrement, où l’on arrive par deux angles (on choisit le plus proche). Clique sur la rose pour envoyer l’antenne dans cette direction (« [[rot.clickHint]] »).', 'La rosa: la aguja llena es la antena, la discontinua el destino; la marca verde es la estación DX (camino corto), la naranja el camino largo. Si el rotor tiene un campo más ancho de 360° una banda amarilla en la brújula marca el solapamiento, donde se llega desde dos ángulos (se elige el más cercano). Haz clic en la rosa para mandar la antena en esa dirección («[[rot.clickHint]]»).', 'A rosa: o ponteiro cheio é a antena, o tracejado o destino; o sinal verde é a estação DX (percurso curto), o laranja o percurso longo. Se o rotor tiver um campo mais largo do que 360° uma faixa amarela na bússola assinala a sobreposição, onde se chega por dois ângulos (escolhe-se o mais próximo). Clica na rosa para mandar a antena nessa direção («[[rot.clickHint]]»).'],
      ['Stato: «[[rot.state.connected]]», «[[rot.state.moving]]», «[[rot.state.off]]» o «[[rot.state.error]]». Con il rotore spento la scheda dice «[[rot.offText]]» e il pulsante «[[rot.openSettings]]» porta alla configurazione.', 'Status: “[[rot.state.connected]]”, “[[rot.state.moving]]”, “[[rot.state.off]]” or “[[rot.state.error]]”. With the rotator off the card says “[[rot.offText]]” and the “[[rot.openSettings]]” button leads to the setup.', 'Zustand: „[[rot.state.connected]]“, „[[rot.state.moving]]“, „[[rot.state.off]]“ oder „[[rot.state.error]]“. Bei ausgeschaltetem Rotor sagt die Karte „[[rot.offText]]“, und die Schaltfläche „[[rot.openSettings]]“ führt zur Einrichtung.', 'État : « [[rot.state.connected]] », « [[rot.state.moving]] », « [[rot.state.off]] » ou « [[rot.state.error]] ». Avec le rotor éteint, l’onglet dit « [[rot.offText]] » et le bouton « [[rot.openSettings]] » mène à la configuration.', 'Estado: «[[rot.state.connected]]», «[[rot.state.moving]]», «[[rot.state.off]]» o «[[rot.state.error]]». Con el rotor apagado la ficha dice «[[rot.offText]]» y el botón «[[rot.openSettings]]» lleva a la configuración.', 'Estado: «[[rot.state.connected]]», «[[rot.state.moving]]», «[[rot.state.off]]» ou «[[rot.state.error]]». Com o rotor desligado o separador diz «[[rot.offText]]» e o botão «[[rot.openSettings]]» leva à configuração.'],
      ['«[[rot.heading]]» dà la direzione attuale, «[[rot.degrees]]» è il campo dove scrivi i gradi (Invio o «[[rot.go]]» vanno), «[[rot.stop]]» ferma subito. Il pulsante «[[rot.more]]» apre il resto: «[[rot.short]]» (verso la stazione DX) e «[[rot.long]]» (via lunga), i passi «[[rot.steps]]» −10° / −2° / +2° / +10°, e Park (la posizione di riposo, con il comando per portarcelo e quello per impostarla sull’attuale).', '“[[rot.heading]]” gives the current direction, “[[rot.degrees]]” is the field where you write the degrees (Enter or “[[rot.go]]” go), “[[rot.stop]]” stops at once. The “[[rot.more]]” button opens the rest: “[[rot.short]]” (towards the DX station) and “[[rot.long]]” (long path), the “[[rot.steps]]” −10° / −2° / +2° / +10°, and Park (the rest position, with the command to move there and the one to set it to the current one).', '„[[rot.heading]]“ gibt die aktuelle Richtung an, „[[rot.degrees]]“ ist das Feld, in das du die Grad schreibst (Enter oder „[[rot.go]]“ starten), „[[rot.stop]]“ stoppt sofort. Die Schaltfläche „[[rot.more]]“ öffnet den Rest: „[[rot.short]]“ (zur DX-Station) und „[[rot.long]]“ (langer Weg), die Schritte „[[rot.steps]]“ −10° / −2° / +2° / +10°, und Park (die Ruheposition, mit dem Befehl, sie anzufahren, und dem, sie auf die aktuelle zu setzen).', '« [[rot.heading]] » donne la direction actuelle, « [[rot.degrees]] » est le champ où tu écris les degrés (Entrée ou « [[rot.go]] » pour partir), « [[rot.stop]] » arrête tout de suite. Le bouton « [[rot.more]] » ouvre le reste : « [[rot.short]] » (vers la station DX) et « [[rot.long]] » (trajet long), les pas « [[rot.steps]] » −10° / −2° / +2° / +10°, et Park (la position de repos, avec la commande pour y aller et celle pour la régler sur la position actuelle).', '«[[rot.heading]]» da la dirección actual, «[[rot.degrees]]» es el campo donde escribes los grados (Intro o «[[rot.go]]» van), «[[rot.stop]]» detiene enseguida. El botón «[[rot.more]]» abre el resto: «[[rot.short]]» (hacia la estación DX) y «[[rot.long]]» (camino largo), los pasos «[[rot.steps]]» −10° / −2° / +2° / +10°, y Park (la posición de reposo, con el comando para llevarlo allí y el de ajustarla a la actual).', '«[[rot.heading]]» dá a direção atual, «[[rot.degrees]]» é o campo onde escreves os graus (Enter ou «[[rot.go]]» avançam), «[[rot.stop]]» pára logo. O botão «[[rot.more]]» abre o resto: «[[rot.short]]» (para a estação DX) e «[[rot.long]]» (percurso longo), os passos «[[rot.steps]]» −10° / −2° / +2° / +10°, e Park (a posição de repouso, com o comando para lá levar a antena e o de a definir na atual).'],
      ['Nella pagina [[nav.rotator]] il pulsante «[[rot.onStation.on]]» / «[[rot.onStation.off]]» toglie o mostra la scheda sopra la Stazione. La scheda ha una barra del titolo: il pulsante di ripiegamento la chiude o la riapre («[[rot.close]]» / «[[rot.open]]»); la X la nasconde («[[rot.hideStation]]»); se la scheda galleggia, si sposta dalla barra (doppio clic: torna al suo posto) e si ridimensiona dall’angolo («[[rot.resize]]»); con ⧉ va in una finestra a parte. Sul telefono e sul tablet la scheda sulla Stazione non c’è: si usa questa pagina.', 'On the [[nav.rotator]] page the “[[rot.onStation.on]]” / “[[rot.onStation.off]]” button removes or shows the card above the Station. The card has a title bar: the fold button closes or reopens it (“[[rot.close]]” / “[[rot.open]]”); the X hides it (“[[rot.hideStation]]”); if the card floats, it is moved from the bar (double-click: back to its place) and resized from the corner (“[[rot.resize]]”); with ⧉ it goes into a separate window. On the phone and the tablet the card on the Station is not there: you use this page.', 'Auf der Seite [[nav.rotator]] entfernt oder zeigt die Schaltfläche „[[rot.onStation.on]]“ / „[[rot.onStation.off]]“ die Karte über der Station. Die Karte hat eine Titelleiste: Die Einklapp-Schaltfläche schließt oder öffnet sie („[[rot.close]]“ / „[[rot.open]]“); das X blendet sie aus („[[rot.hideStation]]“); schwebt die Karte, verschiebst du sie an der Leiste (Doppelklick: zurück an ihren Platz) und änderst die Größe an der Ecke („[[rot.resize]]“); mit ⧉ geht sie in ein eigenes Fenster. Auf Telefon und Tablet gibt es die Karte auf der Station nicht: Dort nimmst du diese Seite.', 'Dans la page [[nav.rotator]], le bouton « [[rot.onStation.on]] » / « [[rot.onStation.off]] » enlève ou montre l’onglet au-dessus de la Station. L’onglet a une barre de titre : le bouton de repli le ferme ou le rouvre (« [[rot.close]] » / « [[rot.open]] ») ; la X le masque (« [[rot.hideStation]] ») ; si l’onglet flotte, il se déplace par la barre (double-clic : il revient à sa place) et se redimensionne par le coin (« [[rot.resize]] ») ; avec ⧉ il va dans une fenêtre à part. Sur le téléphone et la tablette, l’onglet sur la Station n’existe pas : on utilise cette page.', 'En la página [[nav.rotator]] el botón «[[rot.onStation.on]]» / «[[rot.onStation.off]]» quita o muestra la ficha sobre la Estación. La ficha tiene una barra del título: el botón de plegado la cierra o la reabre («[[rot.close]]» / «[[rot.open]]»); la X la oculta («[[rot.hideStation]]»); si la ficha flota, se mueve desde la barra (doble clic: vuelve a su sitio) y se redimensiona desde la esquina («[[rot.resize]]»); con ⧉ va a una ventana aparte. En el teléfono y en la tableta la ficha sobre la Estación no existe: se usa esta página.', 'Na página [[nav.rotator]] o botão «[[rot.onStation.on]]» / «[[rot.onStation.off]]» tira ou mostra o separador por cima da Estação. O separador tem uma barra do título: o botão de recolher fecha-o ou reabre-o («[[rot.close]]» / «[[rot.open]]»); o X esconde-o («[[rot.hideStation]]»); se o separador flutuar, move-se pela barra (duplo clique: volta ao seu lugar) e redimensiona-se pelo canto («[[rot.resize]]»); com ⧉ vai para uma janela à parte. No telemóvel e no tablet o separador na Estação não existe: usa-se esta página.'],
      ['Senza il tuo locatore o senza una stazione DX i pulsanti «[[rot.short]]» e «[[rot.long]]» non possono calcolare la direzione: la scheda lo dice («[[rot.noMyGrid]]», «[[rot.noDxAny]]»).', 'Without your locator or without a DX station the “[[rot.short]]” and “[[rot.long]]” buttons cannot calculate the direction: the card says so (“[[rot.noMyGrid]]”, “[[rot.noDxAny]]”).', 'Ohne dein Locator oder ohne eine DX-Station können die Schaltflächen „[[rot.short]]“ und „[[rot.long]]“ die Richtung nicht berechnen: Die Karte sagt es („[[rot.noMyGrid]]“, „[[rot.noDxAny]]“).', 'Sans ton locator ou sans station DX, les boutons « [[rot.short]] » et « [[rot.long]] » ne peuvent pas calculer la direction : l’onglet le dit (« [[rot.noMyGrid]] », « [[rot.noDxAny]] »).', 'Sin tu localizador o sin una estación DX los botones «[[rot.short]]» y «[[rot.long]]» no pueden calcular la dirección: la ficha lo dice («[[rot.noMyGrid]]», «[[rot.noDxAny]]»).', 'Sem o teu locator ou sem uma estação DX os botões «[[rot.short]]» e «[[rot.long]]» não podem calcular a direção: o separador di-lo («[[rot.noMyGrid]]», «[[rot.noDxAny]]»).'],
    ],
  },
  {
    id: 'p-sat',
    title: ['Satelliti: la pagina riquadro per riquadro', 'Satellites: the page, panel by panel', 'Satelliten: die Seite Feld für Feld', 'Satellites : la page encadré par encadré', 'Satélites: la página recuadro a recuadro', 'Satélites: a página quadro a quadro'],
    text: ['La pagina [[nav.sat]] (titolo «[[sat.title]]») ha la mappa in alto e, sotto, i riquadri. Come si prepara è in «Satelliti: passaggi, Doppler e rotore». Senza il tuo locatore la pagina dice «[[sat.noObserver]]».', 'The [[nav.sat]] page (title “[[sat.title]]”) has the map at the top and the boxes below. How to set it up is in “Satellites: passes, Doppler and rotator”. Without your locator the page says “[[sat.noObserver]]”.', 'Die Seite [[nav.sat]] (Titel „[[sat.title]]“) hat oben die Karte und darunter die Felder. Wie man sie vorbereitet, steht unter „Satelliten: Überflüge, Doppler und Rotor“. Ohne dein Locator sagt die Seite „[[sat.noObserver]]“.', 'La page [[nav.sat]] (titre « [[sat.title]] ») a la carte en haut et, dessous, les encadrés. La façon de la préparer est dans « Satellites : passages, Doppler et rotor ». Sans ton locator, la page dit « [[sat.noObserver]] ».', 'La página [[nav.sat]] (título «[[sat.title]]») tiene el mapa arriba y, debajo, los recuadros. Cómo se prepara está en «Satélites: pasos, Doppler y rotor». Sin tu localizador la página dice «[[sat.noObserver]]».', 'A página [[nav.sat]] (título «[[sat.title]]») tem o mapa em cima e, por baixo, os quadros. Como se prepara está em «Satélites: passagens, Doppler e rotor». Sem o teu locator a página diz «[[sat.noObserver]]».'],
    steps: [
      ['Barra della mappa: «[[sat.tle.refresh]]» (scarica i dati delle orbite; accanto leggi da quanto tempo li hai scaricati; se non ci sono, «[[sat.tle.none]]») e il pulsante «[[sat.set.title]]», che apre le impostazioni dei satelliti ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: server dei dati delle orbite, aggiornamento automatico, mappa, Doppler e rotore). La tendina «[[sat.map.pick]]» sceglie la mappa del mondo; «[[sat.map.add]]» ne aggiunge una (immagine equirettangolare 360° × 180°).', 'Map bar: “[[sat.tle.refresh]]” (downloads the orbit data; next to it you read how long ago you downloaded it; if there is none, “[[sat.tle.none]]”) and the “[[sat.set.title]]” button, which opens the satellite settings ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: orbit data server, automatic update, map, Doppler and rotator). The “[[sat.map.pick]]” drop-down chooses the world map; “[[sat.map.add]]” adds one (equirectangular image 360° × 180°).', 'Leiste der Karte: „[[sat.tle.refresh]]“ (lädt die Bahndaten herunter; daneben liest du, wie lange es her ist, dass du sie geladen hast; sind keine da, „[[sat.tle.none]]“) und die Schaltfläche „[[sat.set.title]]“, die die Satelliteneinstellungen öffnet ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: Server der Bahndaten, automatische Aktualisierung, Karte, Doppler und Rotor). Die Auswahlliste „[[sat.map.pick]]“ wählt die Weltkarte; „[[sat.map.add]]“ fügt eine hinzu (Bild in equirektangulärer Projektion 360° × 180°).', 'Barre de la carte : « [[sat.tle.refresh]] » (télécharge les données des orbites ; à côté tu lis depuis combien de temps tu les as téléchargées ; s’il n’y en a pas, « [[sat.tle.none]] ») et le bouton « [[sat.set.title]] », qui ouvre les réglages des satellites ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]] : serveur des données des orbites, mise à jour automatique, carte, Doppler et rotor). La liste « [[sat.map.pick]] » choisit la carte du monde ; « [[sat.map.add]] » en ajoute une (image équirectangulaire 360° × 180°).', 'Barra del mapa: «[[sat.tle.refresh]]» (descarga los datos de las órbitas; al lado lees hace cuánto tiempo los descargaste; si no hay, «[[sat.tle.none]]») y el botón «[[sat.set.title]]», que abre los ajustes de los satélites ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: servidor de los datos de las órbitas, actualización automática, mapa, Doppler y rotor). La lista «[[sat.map.pick]]» elige el mapa del mundo; «[[sat.map.add]]» añade uno (imagen equirrectangular 360° × 180°).', 'Barra do mapa: «[[sat.tle.refresh]]» (transfere os dados das órbitas; ao lado lês há quanto tempo os transferiste; se não existirem, «[[sat.tle.none]]») e o botão «[[sat.set.title]]», que abre as definições dos satélites ([[nav.settings]] › [[sw.fam.modes]] › [[nav.sat]]: servidor dos dados das órbitas, atualização automática, mapa, Doppler e rotor). A lista «[[sat.map.pick]]» escolhe o mapa do mundo; «[[sat.map.add]]» acrescenta um (imagem equirretangular 360° × 180°).'],
      ['Sulla mappa si vedono i satelliti spuntati con la loro traccia e l’impronta radio, il giorno e la notte, «[[sat.sun]]» e «[[sat.moon]]» e la tua stazione («[[sat.station]]»). Accanto un radar del cielo mostra dove sta il satellite scelto e dove punta il rotore (anello azzurro).', 'On the map you see the checked satellites with their track and radio footprint, day and night, “[[sat.sun]]” and “[[sat.moon]]” and your station (“[[sat.station]]”). Next to it a sky radar shows where the chosen satellite is and where the rotator points (light-blue ring).', 'Auf der Karte siehst du die angehakten Satelliten mit ihrer Spur und dem Funkfußabdruck, Tag und Nacht, „[[sat.sun]]“ und „[[sat.moon]]“ und deine Station („[[sat.station]]“). Daneben zeigt ein Himmelsradar, wo der gewählte Satellit steht und wohin der Rotor zeigt (hellblauer Ring).', 'Sur la carte on voit les satellites cochés avec leur trace et l’empreinte radio, le jour et la nuit, « [[sat.sun]] » et « [[sat.moon]] » et ta station (« [[sat.station]] »). À côté, un radar du ciel montre où est le satellite choisi et où pointe le rotor (anneau bleu clair).', 'En el mapa se ven los satélites marcados con su traza y la huella de radio, el día y la noche, «[[sat.sun]]» y «[[sat.moon]]» y tu estación («[[sat.station]]»). Al lado un radar del cielo muestra dónde está el satélite elegido y adónde apunta el rotor (anillo azul).', 'No mapa veem-se os satélites assinalados com o seu traço e a pegada rádio, o dia e a noite, «[[sat.sun]]» e «[[sat.moon]]» e a tua estação («[[sat.station]]»). Ao lado um radar do céu mostra onde está o satélite escolhido e para onde aponta o rotor (anel azul).'],
      ['«[[sat.pass.title]]»: i prossimi passaggi del satellite che segui, con «[[sat.pass.hours]]» (finestra di tempo) e «[[sat.pass.minEl]]» (quelli sotto non si mostrano), e le colonne «[[sat.pass.aos]]», «[[sat.pass.max]]», «[[sat.pass.los]]», «[[sat.pass.dur]]» e «[[sat.pass.az]]». Una riga dice «[[sat.pass.now]]» o «[[sat.pass.next]]».', '“[[sat.pass.title]]”: the next passes of the satellite you follow, with “[[sat.pass.hours]]” (time window) and “[[sat.pass.minEl]]” (those below are not shown), and the columns “[[sat.pass.aos]]”, “[[sat.pass.max]]”, “[[sat.pass.los]]”, “[[sat.pass.dur]]” and “[[sat.pass.az]]”. A row says “[[sat.pass.now]]” or “[[sat.pass.next]]”.', '„[[sat.pass.title]]“: die nächsten Überflüge des Satelliten, dem du folgst, mit „[[sat.pass.hours]]“ (Zeitfenster) und „[[sat.pass.minEl]]“ (darunter wird nichts gezeigt), und den Spalten „[[sat.pass.aos]]“, „[[sat.pass.max]]“, „[[sat.pass.los]]“, „[[sat.pass.dur]]“ und „[[sat.pass.az]]“. Eine Zeile sagt „[[sat.pass.now]]“ oder „[[sat.pass.next]]“.', '« [[sat.pass.title]] » : les prochains passages du satellite que tu suis, avec « [[sat.pass.hours]] » (fenêtre de temps) et « [[sat.pass.minEl]] » (ceux en dessous ne s’affichent pas), et les colonnes « [[sat.pass.aos]] », « [[sat.pass.max]] », « [[sat.pass.los]] », « [[sat.pass.dur]] » et « [[sat.pass.az]] ». Une ligne dit « [[sat.pass.now]] » ou « [[sat.pass.next]] ».', '«[[sat.pass.title]]»: los próximos pasos del satélite que sigues, con «[[sat.pass.hours]]» (ventana de tiempo) y «[[sat.pass.minEl]]» (los que quedan por debajo no se muestran), y las columnas «[[sat.pass.aos]]», «[[sat.pass.max]]», «[[sat.pass.los]]», «[[sat.pass.dur]]» y «[[sat.pass.az]]». Una fila dice «[[sat.pass.now]]» o «[[sat.pass.next]]».', '«[[sat.pass.title]]»: as próximas passagens do satélite que segues, com «[[sat.pass.hours]]» (janela de tempo) e «[[sat.pass.minEl]]» (as que ficam abaixo não se mostram), e as colunas «[[sat.pass.aos]]», «[[sat.pass.max]]», «[[sat.pass.los]]», «[[sat.pass.dur]]» e «[[sat.pass.az]]». Uma linha diz «[[sat.pass.now]]» ou «[[sat.pass.next]]».'],
      ['«[[sat.list.title]]»: il campo «[[sat.list.search]]» cerca per nome; un clic sul nome lo segui (compare in «[[sat.data.title]]»); la spunta lo fa comparire sulla mappa. I satelliti senza dati delle orbite sono segnati «[[sat.list.noTle]]».', '“[[sat.list.title]]”: the “[[sat.list.search]]” field searches by name; a click on the name follows it (it appears in “[[sat.data.title]]”); the check mark makes it appear on the map. Satellites without orbit data are marked “[[sat.list.noTle]]”.', '„[[sat.list.title]]“: Das Feld „[[sat.list.search]]“ sucht nach Namen; ein Klick auf den Namen, und du folgst ihm (er erscheint in „[[sat.data.title]]“); das Häkchen lässt ihn auf der Karte erscheinen. Satelliten ohne Bahndaten sind mit „[[sat.list.noTle]]“ markiert.', '« [[sat.list.title]] » : le champ « [[sat.list.search]] » cherche par nom ; un clic sur le nom et tu le suis (il apparaît dans « [[sat.data.title]] ») ; la case cochée le fait apparaître sur la carte. Les satellites sans données des orbites sont marqués « [[sat.list.noTle]] ».', '«[[sat.list.title]]»: el campo «[[sat.list.search]]» busca por nombre; un clic en el nombre lo sigues (aparece en «[[sat.data.title]]»); la marca lo hace aparecer en el mapa. Los satélites sin datos de órbitas están marcados «[[sat.list.noTle]]».', '«[[sat.list.title]]»: o campo «[[sat.list.search]]» procura por nome; um clique no nome segue-o (aparece em «[[sat.data.title]]»); o visto faz com que apareça no mapa. Os satélites sem dados das órbitas estão assinalados «[[sat.list.noTle]]».'],
      ['«[[sat.data.title]]»: posizione (longitudine, latitudine, quota), elevazione, azimut, distanza, velocità e velocità radiale, «[[sat.d.approaching]]» o «[[sat.d.receding]]», «[[sat.d.visible]]» o «[[sat.d.hidden]]»; sotto «[[sat.orbit.title]]» (inclinazione, eccentricità, periodo, giri al giorno, data dei dati). «[[sat.info.title]]»: transponder, salita e discesa, se invertente; le frequenze vanno controllate su AMSAT.', '“[[sat.data.title]]”: position (longitude, latitude, altitude), elevation, azimuth, distance, speed and radial speed, “[[sat.d.approaching]]” or “[[sat.d.receding]]”, “[[sat.d.visible]]” or “[[sat.d.hidden]]”; below “[[sat.orbit.title]]” (inclination, eccentricity, period, revolutions per day, date of the data). “[[sat.info.title]]”: transponder, uplink and downlink, whether inverting; the frequencies must be checked on AMSAT.', '„[[sat.data.title]]“: Position (Länge, Breite, Höhe), Elevation, Azimut, Entfernung, Geschwindigkeit und Radialgeschwindigkeit, „[[sat.d.approaching]]“ oder „[[sat.d.receding]]“, „[[sat.d.visible]]“ oder „[[sat.d.hidden]]“; darunter „[[sat.orbit.title]]“ (Neigung, Exzentrizität, Umlaufzeit, Umläufe pro Tag, Datum der Daten). „[[sat.info.title]]“: Transponder, Auf- und Abwärtsstrecke, ob invertierend; die Frequenzen sind bei AMSAT zu prüfen.', '« [[sat.data.title]] » : position (longitude, latitude, altitude), élévation, azimut, distance, vitesse et vitesse radiale, « [[sat.d.approaching]] » ou « [[sat.d.receding]] », « [[sat.d.visible]] » ou « [[sat.d.hidden]] » ; dessous « [[sat.orbit.title]] » (inclinaison, excentricité, période, tours par jour, date des données). « [[sat.info.title]] » : transpondeur, montée et descente, s’il est inverseur ; les fréquences sont à vérifier sur AMSAT.', '«[[sat.data.title]]»: posición (longitud, latitud, altitud), elevación, acimut, distancia, velocidad y velocidad radial, «[[sat.d.approaching]]» o «[[sat.d.receding]]», «[[sat.d.visible]]» o «[[sat.d.hidden]]»; debajo «[[sat.orbit.title]]» (inclinación, excentricidad, periodo, vueltas al día, fecha de los datos). «[[sat.info.title]]»: transpondedor, subida y bajada, si es inversor; las frecuencias hay que comprobarlas en AMSAT.', '«[[sat.data.title]]»: posição (longitude, latitude, altitude), elevação, azimute, distância, velocidade e velocidade radial, «[[sat.d.approaching]]» ou «[[sat.d.receding]]», «[[sat.d.visible]]» ou «[[sat.d.hidden]]»; por baixo «[[sat.orbit.title]]» (inclinação, excentricidade, período, voltas por dia, data dos dados). «[[sat.info.title]]»: transponder, subida e descida, se é inversor; as frequências têm de ser verificadas na AMSAT.'],
      ['«[[sat.ctl.title]]»: la tendina «[[sat.ctl.transponder]]», la «[[sat.ctl.downlink]]» (cursore), la «[[sat.ctl.txOffset]]», l’«[[sat.ctl.minEl]]» (0-60°), «[[sat.ctl.doppler]]» (con lo stato della radio e le frequenze di ricezione e trasmissione corrette), «[[sat.ctl.rotor]]» e «[[sat.ctl.prepoint]]». Sotto ogni interruttore una riga dice se la radio o il rotore sono collegati («[[sat.ctl.radioReady]]», «[[sat.ctl.rotorReady]]», altrimenti «[[sat.ctl.radioNot]]», «[[sat.ctl.rotorNot]]»).', '“[[sat.ctl.title]]”: the “[[sat.ctl.transponder]]” drop-down, the “[[sat.ctl.downlink]]” (slider), the “[[sat.ctl.txOffset]]”, the “[[sat.ctl.minEl]]” (0-60°), “[[sat.ctl.doppler]]” (with the radio status and the corrected receive and transmit frequencies), “[[sat.ctl.rotor]]” and “[[sat.ctl.prepoint]]”. Under each switch a line says whether the radio or the rotator is connected (“[[sat.ctl.radioReady]]”, “[[sat.ctl.rotorReady]]”, otherwise “[[sat.ctl.radioNot]]”, “[[sat.ctl.rotorNot]]”).', '„[[sat.ctl.title]]“: die Auswahlliste „[[sat.ctl.transponder]]“, die „[[sat.ctl.downlink]]“ (Regler), der „[[sat.ctl.txOffset]]“, die „[[sat.ctl.minEl]]“ (0-60°), „[[sat.ctl.doppler]]“ (mit dem Zustand des Funkgeräts und den korrigierten Empfangs- und Sendefrequenzen), „[[sat.ctl.rotor]]“ und „[[sat.ctl.prepoint]]“. Unter jedem Schalter sagt eine Zeile, ob Funkgerät oder Rotor verbunden sind („[[sat.ctl.radioReady]]“, „[[sat.ctl.rotorReady]]“, sonst „[[sat.ctl.radioNot]]“, „[[sat.ctl.rotorNot]]“).', '« [[sat.ctl.title]] » : la liste « [[sat.ctl.transponder]] », la « [[sat.ctl.downlink]] » (curseur), le « [[sat.ctl.txOffset]] », l’« [[sat.ctl.minEl]] » (0-60°), « [[sat.ctl.doppler]] » (avec l’état de la radio et les fréquences de réception et d’émission corrigées), « [[sat.ctl.rotor]] » et « [[sat.ctl.prepoint]] ». Sous chaque interrupteur, une ligne dit si la radio ou le rotor sont connectés (« [[sat.ctl.radioReady]] », « [[sat.ctl.rotorReady]] », sinon « [[sat.ctl.radioNot]] », « [[sat.ctl.rotorNot]] »).', '«[[sat.ctl.title]]»: la lista «[[sat.ctl.transponder]]», la «[[sat.ctl.downlink]]» (cursor), la «[[sat.ctl.txOffset]]», la «[[sat.ctl.minEl]]» (0-60°), «[[sat.ctl.doppler]]» (con el estado de la radio y las frecuencias de recepción y transmisión corregidas), «[[sat.ctl.rotor]]» y «[[sat.ctl.prepoint]]». Bajo cada interruptor una fila dice si la radio o el rotor están conectados («[[sat.ctl.radioReady]]», «[[sat.ctl.rotorReady]]», si no «[[sat.ctl.radioNot]]», «[[sat.ctl.rotorNot]]»).', '«[[sat.ctl.title]]»: a lista «[[sat.ctl.transponder]]», a «[[sat.ctl.downlink]]» (cursor), a «[[sat.ctl.txOffset]]», a «[[sat.ctl.minEl]]» (0-60°), «[[sat.ctl.doppler]]» (com o estado do rádio e as frequências de receção e transmissão corrigidas), «[[sat.ctl.rotor]]» e «[[sat.ctl.prepoint]]». Por baixo de cada interruptor uma linha diz se o rádio ou o rotor estão ligados («[[sat.ctl.radioReady]]», «[[sat.ctl.rotorReady]]», senão «[[sat.ctl.radioNot]]», «[[sat.ctl.rotorNot]]»).'],
    ],
  },
  {
    id: 'p-signals',
    title: ['Il pannello Segnali (CW e PSK)', 'The Signals panel (CW and PSK)', 'Das Feld Signale (CW und PSK)', 'Le panneau Signaux (CW et PSK)', 'El panel Señales (CW y PSK)', 'O painel Sinais (CW e PSK)'],
    text: ['Nelle pagine di CW e PSK, sopra la cascata, il pannello «[[digi.band.title]]» decodifica tutti i segnali della banda audio insieme e li mette in elenco, uno per riga. Si accende e si spegne dal menu Opzioni («[[digi.band.mi]]» in CW, «[[digi.band.miPsk]]» in PSK) e si mostra o nasconde dal menu Vista («[[digi.band.view]]»).', 'On the CW and PSK pages, above the waterfall, the “[[digi.band.title]]” panel decodes all the signals in the audio band together and lists them, one per row. It is turned on and off from the Options menu (“[[digi.band.mi]]” in CW, “[[digi.band.miPsk]]” in PSK) and shown or hidden from the View menu (“[[digi.band.view]]”).', 'Auf den Seiten von CW und PSK, über dem Wasserfall, dekodiert das Feld „[[digi.band.title]]“ alle Signale des Audiobereichs gleichzeitig und listet sie auf, eines pro Zeile. Es wird im Menü Optionen ein- und ausgeschaltet („[[digi.band.mi]]“ in CW, „[[digi.band.miPsk]]“ in PSK) und im Menü Ansicht gezeigt oder ausgeblendet („[[digi.band.view]]“).', 'Dans les pages CW et PSK, au-dessus de la cascade, le panneau « [[digi.band.title]] » décode ensemble tous les signaux de la bande audio et les met en liste, un par ligne. Il s’allume et s’éteint depuis le menu Options (« [[digi.band.mi]] » en CW, « [[digi.band.miPsk]] » en PSK) et se montre ou se cache depuis le menu Vue (« [[digi.band.view]] »).', 'En las páginas de CW y PSK, sobre la cascada, el panel «[[digi.band.title]]» decodifica todas las señales de la banda de audio a la vez y las pone en una lista, una por fila. Se enciende y se apaga desde el menú Opciones («[[digi.band.mi]]» en CW, «[[digi.band.miPsk]]» en PSK) y se muestra u oculta desde el menú Vista («[[digi.band.view]]»).', 'Nas páginas de CW e PSK, por cima da cascata, o painel «[[digi.band.title]]» descodifica todos os sinais da banda de áudio em conjunto e põe-nos em lista, um por linha. Liga-se e desliga-se no menu Opções («[[digi.band.mi]]» em CW, «[[digi.band.miPsk]]» em PSK) e mostra-se ou esconde-se no menu Vista («[[digi.band.view]]»).'],
    steps: [
      ['Intestazione: quanti segnali ci sono, quanti chiamano CQ (le loro righe sono evidenziate) e la nota che i caratteri in grigio sono incerti. Il pulsante «[[digi.band.clear]]» svuota l’elenco, lo storico e i nominativi sulla cascata; i segnali che ci sono ancora ricompaiono da soli.', 'Header: how many signals there are, how many call CQ (their rows are highlighted) and the note that grey characters are uncertain. The “[[digi.band.clear]]” button empties the list, the history and the callsigns on the waterfall; signals that are still there reappear by themselves.', 'Kopfzeile: wie viele Signale es gibt, wie viele CQ rufen (ihre Zeilen sind hervorgehoben) und der Hinweis, dass graue Zeichen unsicher sind. Die Schaltfläche „[[digi.band.clear]]“ leert die Liste, den Verlauf und die Rufzeichen im Wasserfall; Signale, die noch da sind, erscheinen von selbst wieder.', 'En-tête : combien de signaux il y a, combien appellent CQ (leurs lignes sont surlignées) et la note que les caractères en gris sont incertains. Le bouton « [[digi.band.clear]] » vide la liste, l’historique et les indicatifs sur la cascade ; les signaux qui sont encore là réapparaissent tout seuls.', 'Cabecera: cuántas señales hay, cuántas llaman CQ (sus filas aparecen resaltadas) y la nota de que los caracteres en gris son inciertos. El botón «[[digi.band.clear]]» vacía la lista, el historial y los indicativos de la cascada; las señales que aún están vuelven a aparecer solas.', 'Cabeçalho: quantos sinais há, quantos chamam CQ (as suas linhas ficam realçadas) e a nota de que os carateres a cinzento são incertos. O botão «[[digi.band.clear]]» esvazia a lista, o histórico e os indicativos na cascata; os sinais que ainda lá estão reaparecem sozinhos.'],
      ['Colonne: «[[digi.band.colFreq]]» (rispetto alla radio), WPM (solo in CW: la velocità), S/N in dB, «[[digi.band.colCall]]» e «[[digi.band.colText]]». Nella colonna del nominativo: bandiera, nominativo, l’etichetta CQ o DE; in corsivo e più chiaro finché non è verificato («[[digi.band.notVerified]]»: sentito una volta sola o con caratteri incerti), pieno quando è verificato («[[digi.band.verified]]»). Senza segnali l’elenco dice «[[digi.band.empty]]» (o «[[digi.band.emptyPsk]]»).', 'Columns: “[[digi.band.colFreq]]” (relative to the radio), WPM (CW only: the speed), S/N in dB, “[[digi.band.colCall]]” and “[[digi.band.colText]]”. In the callsign column: flag, callsign, the CQ or DE label; in italics and lighter until it is verified (“[[digi.band.notVerified]]”: heard only once or with uncertain characters), solid when it is verified (“[[digi.band.verified]]”). With no signals the list says “[[digi.band.empty]]” (or “[[digi.band.emptyPsk]]”).', 'Spalten: „[[digi.band.colFreq]]“ (bezogen auf das Funkgerät), WPM (nur in CW: die Geschwindigkeit), S/N in dB, „[[digi.band.colCall]]“ und „[[digi.band.colText]]“. In der Spalte des Rufzeichens: Flagge, Rufzeichen, das Etikett CQ oder DE; kursiv und heller, solange es nicht bestätigt ist („[[digi.band.notVerified]]“: nur einmal gehört oder mit unsicheren Zeichen), voll, wenn es bestätigt ist („[[digi.band.verified]]“). Ohne Signale sagt die Liste „[[digi.band.empty]]“ (oder „[[digi.band.emptyPsk]]“).', 'Colonnes : « [[digi.band.colFreq]] » (par rapport à la radio), WPM (seulement en CW : la vitesse), S/N en dB, « [[digi.band.colCall]] » et « [[digi.band.colText]] ». Dans la colonne de l’indicatif : drapeau, indicatif, l’étiquette CQ ou DE ; en italique et plus clair tant qu’il n’est pas vérifié (« [[digi.band.notVerified]] » : entendu une seule fois ou avec des caractères incertains), plein quand il est vérifié (« [[digi.band.verified]] »). Sans signaux, la liste dit « [[digi.band.empty]] » (ou « [[digi.band.emptyPsk]] »).', 'Columnas: «[[digi.band.colFreq]]» (respecto a la radio), WPM (solo en CW: la velocidad), S/N en dB, «[[digi.band.colCall]]» y «[[digi.band.colText]]». En la columna del indicativo: bandera, indicativo, la etiqueta CQ o DE; en cursiva y más claro mientras no está verificado («[[digi.band.notVerified]]»: oído una sola vez o con caracteres inciertos), lleno cuando está verificado («[[digi.band.verified]]»). Sin señales la lista dice «[[digi.band.empty]]» (o «[[digi.band.emptyPsk]]»).', 'Colunas: «[[digi.band.colFreq]]» (em relação ao rádio), WPM (só em CW: a velocidade), S/N em dB, «[[digi.band.colCall]]» e «[[digi.band.colText]]». Na coluna do indicativo: bandeira, indicativo, a etiqueta CQ ou DE; em itálico e mais claro enquanto não for verificado («[[digi.band.notVerified]]»: ouvido uma só vez ou com carateres incertos), cheio quando está verificado («[[digi.band.verified]]»). Sem sinais a lista diz «[[digi.band.empty]]» (ou «[[digi.band.emptyPsk]]»).'],
      ['Un clic su una riga porta la ricezione su quel segnale (la riga del segnale agganciato è evidenziata); il doppio clic apre lo «[[digi.band.history]]»: tutto il testo degli ultimi 60 secondi, con i pulsanti «[[digi.band.tune]]» (porta lì la ricezione), «[[digi.band.toQso]]» (mette il nominativo nel QSO) e «[[digi.band.close]]». Dopo 45 secondi di silenzio il canale si chiude («[[digi.band.historyGone]]»).', 'A click on a row moves reception to that signal (the row of the locked signal is highlighted); a double-click opens the “[[digi.band.history]]”: all the text of the last 60 seconds, with the buttons “[[digi.band.tune]]” (moves reception there), “[[digi.band.toQso]]” (puts the callsign in the QSO) and “[[digi.band.close]]”. After 45 seconds of silence the channel closes (“[[digi.band.historyGone]]”).', 'Ein Klick auf eine Zeile stellt den Empfang auf dieses Signal (die Zeile des aufgeschalteten Signals ist hervorgehoben); der Doppelklick öffnet den „[[digi.band.history]]“: den ganzen Text der letzten 60 Sekunden, mit den Schaltflächen „[[digi.band.tune]]“ (stellt den Empfang dorthin), „[[digi.band.toQso]]“ (setzt das Rufzeichen ins QSO) und „[[digi.band.close]]“. Nach 45 Sekunden Stille schließt sich der Kanal („[[digi.band.historyGone]]“).', 'Un clic sur une ligne place la réception sur ce signal (la ligne du signal accroché est surlignée) ; le double-clic ouvre l’« [[digi.band.history]] » : tout le texte des 60 dernières secondes, avec les boutons « [[digi.band.tune]] » (y place la réception), « [[digi.band.toQso]] » (met l’indicatif dans le QSO) et « [[digi.band.close]] ». Après 45 secondes de silence, le canal se ferme (« [[digi.band.historyGone]] »).', 'Un clic en una fila lleva la recepción a esa señal (la fila de la señal enganchada aparece resaltada); el doble clic abre el «[[digi.band.history]]»: todo el texto de los últimos 60 segundos, con los botones «[[digi.band.tune]]» (lleva allí la recepción), «[[digi.band.toQso]]» (pone el indicativo en el QSO) y «[[digi.band.close]]». Tras 45 segundos de silencio el canal se cierra («[[digi.band.historyGone]]»).', 'Um clique numa linha leva a receção para esse sinal (a linha do sinal agarrado fica realçada); o duplo clique abre o «[[digi.band.history]]»: todo o texto dos últimos 60 segundos, com os botões «[[digi.band.tune]]» (leva lá a receção), «[[digi.band.toQso]]» (põe o indicativo no QSO) e «[[digi.band.close]]». Depois de 45 segundos de silêncio o canal fecha-se («[[digi.band.historyGone]]»).'],
      ['La tendina «[[digi.band.validation]]» decide quanto essere severi con i nominativi: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] o [[digi.band.valMaximum]]. Più è severa, più volte un nominativo dalla forma rara deve essere sentito prima di valere. Il «?» spiega le regole.', 'The “[[digi.band.validation]]” drop-down decides how strict to be with callsigns: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] or [[digi.band.valMaximum]]. The stricter it is, the more times a callsign of an unusual shape must be heard before it counts. The “?” explains the rules.', 'Die Auswahlliste „[[digi.band.validation]]“ bestimmt, wie streng mit den Rufzeichen umgegangen wird: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] oder [[digi.band.valMaximum]]. Je strenger, desto öfter muss ein Rufzeichen mit seltener Form gehört werden, bevor es gilt. Das „?“ erklärt die Regeln.', 'La liste « [[digi.band.validation]] » décide du degré de sévérité envers les indicatifs : [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] ou [[digi.band.valMaximum]]. Plus elle est sévère, plus un indicatif de forme rare doit être entendu de fois avant de valoir. Le « ? » explique les règles.', 'La lista desplegable «[[digi.band.validation]]» decide cuán estricto ser con los indicativos: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] o [[digi.band.valMaximum]]. Cuanto más estricta, más veces debe oírse un indicativo de forma rara antes de valer. El «?» explica las reglas.', 'A lista «[[digi.band.validation]]» decide quão rigoroso ser com os indicativos: [[digi.band.valMinimal]], [[digi.band.valNormal]], [[digi.band.valStrict]] ou [[digi.band.valMaximum]]. Quanto mais rigorosa, mais vezes um indicativo de forma rara tem de ser ouvido antes de valer. O «?» explica as regras.'],
      ['La maniglia sul bordo alto del pannello si trascina per cambiare l’altezza dell’elenco; l’altezza resta ricordata. Le opzioni «[[digi.band.spots]]», «[[digi.band.spotsCqOnly]]» e «[[digi.band.wfCalls]]» si accendono dai menu Opzioni e Vista (i nominativi verificati diventano spot locali del DX Cluster di Aurora, sul tuo PC, niente va in rete).', 'The handle on the top edge of the panel is dragged to change the height of the list; the height is remembered. The options “[[digi.band.spots]]”, “[[digi.band.spotsCqOnly]]” and “[[digi.band.wfCalls]]” are turned on from the Options and View menus (verified callsigns become local spots of Aurora’s DX Cluster, on your PC, nothing goes onto the network).', 'Den Griff am oberen Rand des Feldes ziehst du, um die Höhe der Liste zu ändern; die Höhe bleibt gespeichert. Die Optionen „[[digi.band.spots]]“, „[[digi.band.spotsCqOnly]]“ und „[[digi.band.wfCalls]]“ schaltest du in den Menüs Optionen und Ansicht ein (die bestätigten Rufzeichen werden zu lokalen Spots des DX-Clusters von Aurora, auf deinem PC, nichts geht ins Netz).', 'La poignée sur le bord haut du panneau se glisse pour changer la hauteur de la liste ; la hauteur reste mémorisée. Les options « [[digi.band.spots]] », « [[digi.band.spotsCqOnly]] » et « [[digi.band.wfCalls]] » s’allument depuis les menus Options et Vue (les indicatifs vérifiés deviennent des spots locaux du DX Cluster d’Aurora, sur ton PC, rien ne part sur le réseau).', 'El asa del borde superior del panel se arrastra para cambiar la altura de la lista; la altura se recuerda. Las opciones «[[digi.band.spots]]», «[[digi.band.spotsCqOnly]]» y «[[digi.band.wfCalls]]» se encienden desde los menús Opciones y Vista (los indicativos verificados se convierten en spots locales del DX Cluster de Aurora, en tu PC, nada va a la red).', 'A pega na margem de cima do painel arrasta-se para mudar a altura da lista; a altura fica guardada. As opções «[[digi.band.spots]]», «[[digi.band.spotsCqOnly]]» e «[[digi.band.wfCalls]]» ligam-se nos menus Opções e Vista (os indicativos verificados passam a ser spots locais do DX Cluster da Aurora, no teu PC, nada vai para a rede).'],
    ],
    tip: ['Più dettagli sul CW nella voce «Ricevere e trasmettere in CW».', 'More details about CW are in the entry “Receiving and sending CW”.', 'Mehr Einzelheiten zu CW stehen im Eintrag „CW empfangen und senden“.', 'Plus de détails sur le CW dans l’entrée « Recevoir et émettre en CW ».', 'Más detalles sobre el CW en la entrada «Recibir y transmitir en CW».', 'Mais detalhes sobre o CW na entrada «Receber e transmitir em CW».'],
  },
  {
    id: 'p-phone',
    title: ['Il telecomando: ogni pulsante', 'The remote control: every button', 'Die Fernbedienung: jede Schaltfläche', 'La télécommande : chaque bouton', 'El mando a distancia: cada botón', 'O telecomando: cada botão'],
    text: ['Sotto i 768 px di larghezza (telefono) la pagina Stazione diventa un telecomando compatto; sul tablet in orizzontale sono due colonne. Funziona uguale sul telefono associato e in una finestra stretta del PC. Come si associa è in «Associare telefono o tablet».', 'Below 768 px of width (phone) the Station page becomes a compact remote control; on a tablet in landscape it has two columns. It works the same on the paired phone and in a narrow window on the PC. How to pair is in “Pairing a phone or tablet”.', 'Unter 768 px Breite (Telefon) wird die Seite Station zu einer kompakten Fernbedienung; auf dem Tablet quer sind es zwei Spalten. Sie funktioniert gleich auf dem gekoppelten Telefon und in einem schmalen Fenster am PC. Wie man koppelt, steht unter „Telefon oder Tablet koppeln“.', 'Sous 768 px de largeur (téléphone), la page Station devient une télécommande compacte ; sur la tablette à l’horizontale, il y a deux colonnes. Elle fonctionne pareil sur le téléphone associé et dans une fenêtre étroite du PC. La façon de l’associer est dans « Associer téléphone ou tablette ».', 'Por debajo de los 768 px de anchura (teléfono) la página Estación se convierte en un mando a distancia compacto; en la tableta en horizontal son dos columnas. Funciona igual en el teléfono vinculado y en una ventana estrecha del PC. Cómo se vincula está en «Vincular teléfono o tableta».', 'Abaixo de 768 px de largura (telemóvel) a página Estação torna-se um telecomando compacto; no tablet na horizontal são duas colunas. Funciona igual no telemóvel associado e numa janela estreita do PC. Como se associa está em «Associar telemóvel ou tablet».'],
    steps: [
      ['Barra in alto: la pastiglia RX (verde) o TX (rossa); la tendina della banda e quella del modo (grigie se la radio non è comandata; se stai trasmettendo Aurora chiede conferma prima di cambiarle); il pulsante con i watt (la potenza vera che la radio sta mandando): un tocco apre − e + che alzano o abbassano la potenza della radio del 5%; i secondi del periodo; il pulsante ⟳ che ricarica la pagina dal PC («[[phone.refresh]]»); l’icona del tema. Sotto, una barra mostra l’avanzamento del periodo.', 'Top bar: the RX (green) or TX (red) badge; the band drop-down and the mode one (grey if the radio is not controlled; if you are transmitting, Aurora asks for confirmation before changing them); the button with the watts (the real power the radio is sending): a tap opens − and + which raise or lower the radio power by 5%; the seconds of the period; the ⟳ button that reloads the page from the PC (“[[phone.refresh]]”); the theme icon. Below, a bar shows the progress of the period.', 'Leiste oben: die Pille RX (grün) oder TX (rot); die Auswahlliste des Bandes und die der Betriebsart (grau, wenn das Funkgerät nicht gesteuert wird; sendest du gerade, fragt Aurora vor dem Wechsel nach); die Schaltfläche mit den Watt (die echte Leistung, die das Funkgerät gerade sendet): Ein Tippen öffnet − und +, die die Leistung des Funkgeräts um 5 % erhöhen oder senken; die Sekunden des Durchgangs; die Schaltfläche ⟳, die die Seite vom PC neu lädt („[[phone.refresh]]“); das Design-Symbol. Darunter zeigt ein Balken den Fortschritt des Durchgangs.', 'Barre du haut : la pastille RX (verte) ou TX (rouge) ; la liste de la bande et celle du mode (grises si la radio n’est pas pilotée ; si tu émets, Aurora demande confirmation avant de les changer) ; le bouton avec les watts (la vraie puissance que la radio envoie) : un toucher ouvre − et + qui montent ou baissent la puissance de la radio de 5 % ; les secondes de la période ; le bouton ⟳ qui recharge la page depuis le PC (« [[phone.refresh]] ») ; l’icône du thème. Dessous, une barre montre l’avancement de la période.', 'Barra de arriba: la pastilla RX (verde) o TX (roja); la lista de la banda y la del modo (grises si la radio no está controlada; si estás transmitiendo Aurora pide confirmación antes de cambiarlas); el botón con los vatios (la potencia real que la radio está mandando): un toque abre − y + que suben o bajan la potencia de la radio un 5%; los segundos del periodo; el botón ⟳ que recarga la página desde el PC («[[phone.refresh]]»); el icono del tema. Debajo, una barra muestra el avance del periodo.', 'Barra de cima: a pastilha RX (verde) ou TX (vermelha); a lista da banda e a do modo (cinzentas se o rádio não é comandado; se estás a transmitir a Aurora pede confirmação antes de as mudar); o botão com os watts (a potência verdadeira que o rádio está a enviar): um toque abre − e + que aumentam ou diminuem a potência do rádio em 5%; os segundos do período; o botão ⟳ que recarrega a página a partir do PC («[[phone.refresh]]»); o ícone do tema. Por baixo, uma barra mostra o avanço do período.'],
      ['«[[panel.all]]»: i messaggi della banda. Un solo tocco su una riga risponde a quella stazione. Sotto, due riquadri che si aprono e chiudono con un tocco sul titolo: «[[panel.cluster]]» (gli spot della banda; un tocco sintonizza; non c’è se il cluster è spento) e «[[phone.log]]» (gli ultimi 3 QSO).', '“[[panel.all]]”: the messages of the band. A single tap on a row replies to that station. Below, two boxes that open and close with a tap on the title: “[[panel.cluster]]” (the spots of the band; a tap tunes; it is not there if the cluster is off) and “[[phone.log]]” (the last 3 QSOs).', '„[[panel.all]]“: die Nachrichten des Bandes. Ein einziges Tippen auf eine Zeile antwortet dieser Station. Darunter zwei Felder, die sich mit einem Tippen auf den Titel öffnen und schließen: „[[panel.cluster]]“ (die Spots des Bandes; ein Tippen stimmt ab; fehlt, wenn der Cluster aus ist) und „[[phone.log]]“ (die letzten 3 QSOs).', '« [[panel.all]] » : les messages de la bande. Un seul toucher sur une ligne répond à cette station. Dessous, deux encadrés qui s’ouvrent et se ferment par un toucher sur le titre : « [[panel.cluster]] » (les spots de la bande ; un toucher accorde ; n’existe pas si le cluster est éteint) et « [[phone.log]] » (les 3 derniers QSO).', '«[[panel.all]]»: los mensajes de la banda. Un solo toque en una fila responde a esa estación. Debajo, dos recuadros que se abren y cierran con un toque en el título: «[[panel.cluster]]» (los spots de la banda; un toque sintoniza; no está si el cluster está apagado) y «[[phone.log]]» (los últimos 3 QSO).', '«[[panel.all]]»: as mensagens da banda. Um só toque numa linha responde a essa estação. Por baixo, dois quadros que se abrem e fecham com um toque no título: «[[panel.cluster]]» (os spots da banda; um toque sintoniza; não existe se o cluster estiver desligado) e «[[phone.log]]» (os últimos 3 QSO).'],
      ['Il riquadro dei messaggi Tx: titolo «[[phone.txMessages]]» con la frequenza Tx (diventa rosso «[[phone.transmitting]]» mentre trasmetti), la riga del DX («[[phone.dx]]» o «[[phone.calling]]» con bandiera e distanza) e il pulsante «[[ctl.split]]», poi i sei messaggi con il loro tipo ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): un tocco sceglie il prossimo da trasmettere. Sotto, la cascata.', 'The Tx messages box: title “[[phone.txMessages]]” with the Tx frequency (it turns red “[[phone.transmitting]]” while you transmit), the DX row (“[[phone.dx]]” or “[[phone.calling]]” with flag and distance) and the “[[ctl.split]]” button, then the six messages with their type ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): a tap chooses the next one to transmit. Below, the waterfall.', 'Das Feld der Tx-Nachrichten: Titel „[[phone.txMessages]]“ mit der Tx-Frequenz (wird rot „[[phone.transmitting]]“, während du sendest), die Zeile des DX („[[phone.dx]]“ oder „[[phone.calling]]“ mit Flagge und Entfernung) und die Schaltfläche „[[ctl.split]]“, dann die sechs Nachrichten mit ihrem Typ ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): Ein Tippen wählt die nächste zu sendende. Darunter der Wasserfall.', 'L’encadré des messages Tx : titre « [[phone.txMessages]] » avec la fréquence Tx (elle devient rouge « [[phone.transmitting]] » pendant que tu émets), la ligne du DX (« [[phone.dx]] » ou « [[phone.calling]] » avec drapeau et distance) et le bouton « [[ctl.split]] », puis les six messages avec leur type ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ) : un toucher choisit le prochain à émettre. Dessous, la cascade.', 'El recuadro de los mensajes Tx: título «[[phone.txMessages]]» con la frecuencia Tx (se pone roja «[[phone.transmitting]]» mientras transmites), la fila del DX («[[phone.dx]]» o «[[phone.calling]]» con bandera y distancia) y el botón «[[ctl.split]]», luego los seis mensajes con su tipo ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): un toque elige el próximo que se va a transmitir. Debajo, la cascada.', 'O quadro das mensagens Tx: título «[[phone.txMessages]]» com a frequência Tx (fica vermelho «[[phone.transmitting]]» enquanto transmites), a linha do DX («[[phone.dx]]» ou «[[phone.calling]]» com bandeira e distância) e o botão «[[ctl.split]]», depois as seis mensagens com o seu tipo ([[phone.kind.grid]], [[phone.kind.report]], [[phone.kind.rreport]], RR73, 73, CQ): um toque escolhe a próxima a transmitir. Por baixo, a cascata.'],
      ['Barra in fondo: «[[phone.cq]]» (chiama CQ), «[[ctl.enable_tx]]» (diventa «[[phone.txOn]]») e «[[phone.stop]]» (diventa «[[stop.button]]» mentre trasmetti); due tocchi ravvicinati sullo stop fermano anche la stazione scelta. Restano sempre a portata di dito.', 'Bar at the bottom: “[[phone.cq]]” (calls CQ), “[[ctl.enable_tx]]” (it becomes “[[phone.txOn]]”) and “[[phone.stop]]” (it becomes “[[stop.button]]” while you transmit); two quick taps on stop also free the chosen station. They always stay within reach of your finger.', 'Leiste unten: „[[phone.cq]]“ (ruft CQ), „[[ctl.enable_tx]]“ (wird zu „[[phone.txOn]]“) und „[[phone.stop]]“ (wird zu „[[stop.button]]“, während du sendest); zweimal kurz hintereinander auf Stopp tippen gibt auch die gewählte Station frei. Sie bleiben immer in Reichweite des Fingers.', 'Barre du bas : « [[phone.cq]] » (appelle CQ), « [[ctl.enable_tx]] » (devient « [[phone.txOn]] ») et « [[phone.stop]] » (devient « [[stop.button]] » pendant que tu émets) ; deux touchers rapprochés sur stop arrêtent aussi la station choisie. Ils restent toujours à portée de doigt.', 'Barra del fondo: «[[phone.cq]]» (llama CQ), «[[ctl.enable_tx]]» (se convierte en «[[phone.txOn]]») y «[[phone.stop]]» (se convierte en «[[stop.button]]» mientras transmites); dos toques seguidos en el stop detienen también la estación elegida. Se quedan siempre al alcance del dedo.', 'Barra do fundo: «[[phone.cq]]» (chama CQ), «[[ctl.enable_tx]]» (passa a «[[phone.txOn]]») e «[[phone.stop]]» (passa a «[[stop.button]]» enquanto transmites); dois toques seguidos no stop libertam também a estação escolhida. Ficam sempre ao alcance do dedo.'],
      ['Dal telefono le Impostazioni non ci sono: si cambiano solo dal PC.', 'On the phone the Settings are not there: they are changed only from the PC.', 'Auf dem Telefon gibt es die Einstellungen nicht: Sie werden nur am PC geändert.', 'Depuis le téléphone, les Réglages n’existent pas : ils se changent seulement depuis le PC.', 'Desde el teléfono los Ajustes no están: se cambian solo desde el PC.', 'No telemóvel as Definições não existem: mudam-se só a partir do PC.'],
    ],
    tip: ['Se il telefono mostra dati fermi: tocca ⟳. Altrimenti guarda «Il telefono non si aggiorna».', 'If the phone shows frozen data: tap ⟳. Otherwise see “The phone does not update”.', 'Zeigt das Telefon stehende Daten: Tippe auf ⟳. Sonst sieh unter „Das Telefon aktualisiert nicht“ nach.', 'Si le téléphone montre des données figées : touche ⟳. Sinon, regarde « Le téléphone ne se met pas à jour ».', 'Si el teléfono muestra datos parados: toca ⟳. Si no, mira «El teléfono no se actualiza».', 'Se o telemóvel mostrar dados parados: toca em ⟳. Senão vê «O telemóvel não atualiza».'],
  },
  {
    id: 'p-pair',
    title: ['La pagina «Associa questo dispositivo»', 'The “Pair this device” page', 'Die Seite „Dieses Gerät koppeln“', 'La page « Associer cet appareil »', 'La página «Vincular este dispositivo»', 'A página «Associar este dispositivo»'],
    text: ['È la pagina che il telefono vede la prima volta, o quando l’associazione è stata tolta. Si arriva qui dal QR del PC (link «#/associa?codice=…») o scrivendo l’indirizzo di Aurora.', 'It is the page the phone sees the first time, or when the pairing has been removed. You get here from the QR code on the PC (link “#/associa?codice=…”) or by typing the Aurora address.', 'Das ist die Seite, die das Telefon beim ersten Mal sieht oder wenn die Kopplung entfernt wurde. Man kommt hierher über den QR-Code am PC (Link „#/associa?codice=…“) oder indem man die Adresse von Aurora schreibt.', 'C’est la page que le téléphone voit la première fois, ou quand l’association a été retirée. On arrive ici depuis le QR du PC (lien « #/associa?codice=… ») ou en écrivant l’adresse d’Aurora.', 'Es la página que el teléfono ve la primera vez, o cuando se ha quitado la vinculación. Se llega aquí desde el QR del PC (enlace «#/associa?codice=…») o escribiendo la dirección de Aurora.', 'É a página que o telemóvel vê da primeira vez, ou quando a associação foi retirada. Chega-se aqui pelo QR do PC (ligação «#/associa?codice=…») ou escrevendo o endereço da Aurora.'],
    steps: [
      ['«[[pair.code]]»: le 8 cifre mostrate sul PC (valgono 2 minuti). Con il QR il campo si riempie e l’associazione parte da sola. Senza fotocamera scrivi il codice a mano.', '“[[pair.code]]”: the 8 digits shown on the PC (valid for 2 minutes). With the QR code the field fills in and the pairing starts by itself. Without a camera, type the code by hand.', '„[[pair.code]]“: die 8 Ziffern, die am PC angezeigt werden (sie gelten 2 Minuten). Mit dem QR-Code füllt sich das Feld, und die Kopplung startet von selbst. Ohne Kamera schreibst du den Code von Hand.', '« [[pair.code]] » : les 8 chiffres affichés sur le PC (valables 2 minutes). Avec le QR, le champ se remplit et l’association démarre toute seule. Sans appareil photo, écris le code à la main.', '«[[pair.code]]»: las 8 cifras que se muestran en el PC (valen 2 minutos). Con el QR el campo se rellena y la vinculación arranca sola. Sin cámara escribe el código a mano.', '«[[pair.code]]»: os 8 algarismos mostrados no PC (valem 2 minutos). Com o QR o campo preenche-se e a associação arranca sozinha. Sem câmara escreve o código à mão.'],
      ['«[[pair.name]]»: un nome per riconoscere il dispositivo nell’elenco dei dispositivi associati (da 1 a 64 caratteri). Poi «[[pair.button]]».', '“[[pair.name]]”: a name to recognize the device in the list of paired devices (from 1 to 64 characters). Then “[[pair.button]]”.', '„[[pair.name]]“: ein Name, um das Gerät in der Liste der gekoppelten Geräte zu erkennen (1 bis 64 Zeichen). Dann „[[pair.button]]“.', '« [[pair.name]] » : un nom pour reconnaître l’appareil dans la liste des appareils associés (de 1 à 64 caractères). Puis « [[pair.button]] ».', '«[[pair.name]]»: un nombre para reconocer el dispositivo en la lista de los dispositivos vinculados (de 1 a 64 caracteres). Después «[[pair.button]]».', '«[[pair.name]]»: um nome para reconheceres o dispositivo na lista dos dispositivos associados (de 1 a 64 carateres). Depois «[[pair.button]]».'],
      ['Messaggi: codice sbagliato («[[pair.badCode]]»), scaduto («[[pair.expired]]»), troppo corto («[[pair.short]]»), senza nome («[[pair.nameRequired]]»), troppi tentativi (aspetta il numero di secondi indicato). Se Aurora non risponde: «[[app.noCore]]», con il pulsante per riprovare e, se trova un altro indirizzo già usato, per passarci.', 'Messages: wrong code (“[[pair.badCode]]”), expired (“[[pair.expired]]”), too short (“[[pair.short]]”), no name (“[[pair.nameRequired]]”), too many attempts (wait the number of seconds shown). If Aurora does not answer: “[[app.noCore]]”, with the button to try again and, if it finds another address already used, to switch to it.', 'Meldungen: falscher Code („[[pair.badCode]]“), abgelaufen („[[pair.expired]]“), zu kurz („[[pair.short]]“), ohne Namen („[[pair.nameRequired]]“), zu viele Versuche (warte die angegebene Zahl von Sekunden). Antwortet Aurora nicht: „[[app.noCore]]“, mit der Schaltfläche, es erneut zu versuchen und, wenn es eine andere schon benutzte Adresse findet, dorthin zu wechseln.', 'Messages : code faux (« [[pair.badCode]] »), expiré (« [[pair.expired]] »), trop court (« [[pair.short]] »), sans nom (« [[pair.nameRequired]] »), trop d’essais (attends le nombre de secondes indiqué). Si Aurora ne répond pas : « [[app.noCore]] », avec le bouton pour réessayer et, s’il trouve une autre adresse déjà utilisée, pour y passer.', 'Mensajes: código erróneo («[[pair.badCode]]»), caducado («[[pair.expired]]»), demasiado corto («[[pair.short]]»), sin nombre («[[pair.nameRequired]]»), demasiados intentos (espera el número de segundos indicado). Si Aurora no responde: «[[app.noCore]]», con el botón para reintentar y, si encuentra otra dirección ya usada, para pasar a ella.', 'Mensagens: código errado («[[pair.badCode]]»), expirado («[[pair.expired]]»), curto demais («[[pair.short]]»), sem nome («[[pair.nameRequired]]»), demasiadas tentativas (espera o número de segundos indicado). Se a Aurora não responder: «[[app.noCore]]», com o botão para tentar de novo e, se encontrar outro endereço já usado, para passar para ele.'],
    ],
  },
];
